INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52899, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "足のいちばんうしろの部分。", "primary_collocate": null, "pronunciation": "かかと", "ipa": "kakato", "syllable_count": 3, "sentences": [{"text": "靴が大きくて、歩くたびに踵が浮いてしまう。", "target_word": "踵", "complexity_tier": "T3", "furigana": "靴[くつ]が大[おお]きくて、歩[ある]くたびに踵[かかと]が浮[う]いてしまう。", "sentence_source": "generated"}, {"text": "爪先立ちをやめて、踵を床につけた。", "target_word": "踵", "complexity_tier": "T3", "furigana": "爪先立[つまさきだ]ちをやめて、踵[かかと]を床[ゆか]につけた。", "sentence_source": "generated"}, {"text": "走っていて、踵を石にぶつけて痛めた。", "target_word": "踵", "complexity_tier": "T3", "furigana": "走[はし]っていて、踵[かかと]を石[いし]にぶつけて痛[いた]めた。", "sentence_source": "generated"}, {"text": "踵を上げ下げする運動で、ふくらはぎを鍛える。", "target_word": "踵", "complexity_tier": "T3", "furigana": "踵[かかと]を上[あ]げ下[お]ろしする運動[うんどう]で、ふくらはぎを鍛[きた]える。", "sentence_source": "generated"}, {"text": "彼は踵をそろえて、きちんと立った。", "target_word": "踵", "complexity_tier": "T3", "furigana": "彼[かれ]は踵[かかと]をそろえて、きちんと立[た]った。", "sentence_source": "generated"}, {"text": "転んで、踵の骨にひびが入った。", "target_word": "踵", "complexity_tier": "T3", "furigana": "転[ころ]んで、踵[かかと]の骨[ほね]にひびが入[はい]った。", "sentence_source": "generated"}, {"text": "雪道で滑らないよう、踵に体重をのせて歩いた。", "target_word": "踵", "complexity_tier": "T3", "furigana": "雪道[ゆきみち]で滑[すべ]らないよう、踵[かかと]に体重[たいじゅう]をのせて歩[ある]いた。", "sentence_source": "generated"}, {"text": "踵を軸にして、くるりと体を回した。", "target_word": "踵", "complexity_tier": "T3", "furigana": "踵[かかと]を軸[じく]にして、くるりと体[からだ]を回[まわ]した。", "sentence_source": "generated"}, {"text": "ベッドの端から、踵がはみ出している。", "target_word": "踵", "complexity_tier": "T3", "furigana": "ベッドの端[はし]から、踵[かかと]がはみ出[だ]している。", "sentence_source": "generated"}, {"text": "暗い部屋で、踵を家具の角にぶつけた。", "target_word": "踵", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]で、踵[かかと]を家具[かぐ]の角[かど]にぶつけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "踵", "label": "名詞"}], "register": "neutral", "sense_fingerprint": "足の一番後ろの部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52899, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踵", "is_correct": true, "explanation": "正解。靴が大きいと浮く、足のいちばん後ろの部分を指す。"}, {"text": "肩", "is_correct": false, "explanation": "体の上部の部位で、靴が浮く文には合わない。「肩が浮く」は不自然。"}, {"text": "耳", "is_correct": false, "explanation": "頭の横の器官で、靴が大きくて浮く場面とは関係がない。"}, {"text": "頬", "is_correct": false, "explanation": "顔の部位で、靴が浮く文の主語にはならない。"}], "explanations": {"踵": "正解。靴が大きいと浮く、足のいちばん後ろの部分を指す。", "肩": "体の上部の部位で、靴が浮く文には合わない。「肩が浮く」は不自然。", "耳": "頭の横の器官で、靴が大きくて浮く場面とは関係がない。", "頬": "顔の部位で、靴が浮く文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "踵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "踵を寄せて、難しい顔をした。", "explanation": "ここは〈眉〉の場面。難しい顔をするとき寄せるのは眉で、踵を寄せるとは言わない。"}, {"text": "友達と踵を並べて座った。", "explanation": "ここは〈膝〉の場面。膝を並べて座るのは自然だが、踵を並べて座るとは言わない。"}, {"text": "踵で紙を折って、鶴を作った。", "explanation": "ここは〈指〉の場面。紙を折るのは指で、踵では折らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52899, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "踵", "is_correct": true, "explanation": "正解。雪道で体重をのせる、足の後ろ側の部位を指す。"}, {"text": "瞼", "is_correct": false, "explanation": "目を覆う部位で、体重をのせて歩く文には合わない。"}, {"text": "唇", "is_correct": false, "explanation": "口の周りの部位で、体重をのせて歩く場面とは関係がない。"}, {"text": "額", "is_correct": false, "explanation": "顔の部位で、体重をのせて歩く動作とは合わない。"}], "explanations": {"踵": "正解。雪道で体重をのせる、足の後ろ側の部位を指す。", "瞼": "目を覆う部位で、体重をのせて歩く文には合わない。", "唇": "口の周りの部位で、体重をのせて歩く場面とは関係がない。", "額": "顔の部位で、体重をのせて歩く動作とは合わない。"}, "sentence_index": 6, "correct_answer": "踵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "踵を机について、頬杖をついた。", "explanation": "ここは〈肘〉の場面。机について頬杖をつくのは肘で、踵を机につけるとは言わない。"}, {"text": "踵を打って、子どもたちを呼んだ。", "explanation": "ここは〈手〉の場面。人を呼ぶために打つのは手で、踵で打つとは言わない。"}, {"text": "踵に大きな箱を背負って歩いた。", "explanation": "ここは〈背中〉の場面。箱を背負うのは背中で、踵に背負うとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52899, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坂道を下りるときは、踵が地面につけて歩く。", "corrected_sentence": "坂道を下りるときは、踵を地面につけて歩く。", "error_description": "目的語を示す「を」が正しいのに「が」を使っている。「踵を地面につける」が正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52899, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "転んで、踵を強く打ったた。", "corrected_sentence": "転んで、踵を強く打った。", "error_description": "「た」が重なっている。「打った」が正しく、「打ったた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52900, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「踵に」の「に」で、靴ずれができた場所を示す。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、靴ずれができる場所を示せない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では、「踵を靴ずれができた」となり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では、靴ずれができる場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「踵に」の「に」で、靴ずれができた場所を示す。", "から": "起点の「から」では、靴ずれができる場所を示せない。", "を": "目的語の「を」では、「踵を靴ずれができた」となり文が成り立たない。", "へ": "方向の「へ」では、靴ずれができる場所を示せない。"}, "error_tags": {"から": "起点", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
