INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52900, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "足の裏の後ろ側の、かたい部分。かかと。", "primary_collocate": null, "pronunciation": "かかと", "ipa": "kakato", "syllable_count": 3, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "踵", "complexity_tier": "T4", "furigana": "靴紐[くつひも]を固[かた]く結[むす]び、踵[かかと]で床[ゆか]を鳴[な]らせば、鈍[にぶ]い音[おと]が魂[たましい]の鼓動[こどう]と共鳴[きょうめい]する。", "sentence_source": "mined"}, {"text": "新しい靴で、踵に靴ずれができてしまった。", "target_word": "踵", "complexity_tier": "T3", "furigana": "新[あたら]しい靴[くつ]で、踵[かかと]に靴[くつ]ずれができてしまった。", "sentence_source": "generated"}, {"text": "冬になると、踵がかたくなってひび割れる。", "target_word": "踵", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、踵[かかと]がかたくなってひび割[わ]れる。", "sentence_source": "generated"}, {"text": "寒い朝、踵のひび割れにクリームを塗った。", "target_word": "踵", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]、踵[かかと]のひび割[わ]れにクリームを塗[ぬ]った。", "sentence_source": "generated"}, {"text": "踵の角質を、軽石で丁寧に削った。", "target_word": "踵", "complexity_tier": "T3", "furigana": "踵[かかと]の角質[かくしつ]を、軽石[かるいし]で丁寧[ていねい]に削[けず]った。", "sentence_source": "generated"}, {"text": "彼女は踵で軽く床を蹴って、ダンスの拍子をとった。", "target_word": "踵", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は踵[かかと]で軽[かる]く床[ゆか]を蹴[け]って、ダンスの拍子[ひょうし]をとった。", "sentence_source": "generated"}, {"text": "毎日たくさん歩くので、踵の皮がかたくなった。", "target_word": "踵", "complexity_tier": "T3", "furigana": "毎日[まいにち]たくさん歩[ある]くので、踵[かかと]の皮[かわ]がかたくなった。", "sentence_source": "generated"}, {"text": "スリッパの中で、踵の皮が厚くなってきた。", "target_word": "踵", "complexity_tier": "T3", "furigana": "スリッパの中[なか]で、踵[かかと]の皮[かわ]が厚[あつ]くなってきた。", "sentence_source": "generated"}, {"text": "お風呂上がりに、踵を保湿するのが習慣だ。", "target_word": "踵", "complexity_tier": "T3", "furigana": "お風呂[ふろ]上[あ]がりに、踵[かかと]を保湿[ほしつ]するのが習慣[しゅうかん]だ。", "sentence_source": "generated"}, {"text": "踵の皮膚がかたくなり、歩くと少し痛い。", "target_word": "踵", "complexity_tier": "T3", "furigana": "踵[かかと]の皮膚[ひふ]がかたくなり、歩[ある]くと少[すこ]し痛[いた]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "踵", "label": "名詞"}], "register": "neutral", "sense_fingerprint": "足の裏の後ろ側のかたい部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52900, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踵", "is_correct": true, "explanation": "正解。靴紐を結んで床を鳴らす、足の裏の後ろ側の部位を指す。"}, {"text": "眉", "is_correct": false, "explanation": "顔の部位で、床を踏み鳴らす場面では使えない。「眉で床を鳴らす」は不自然。"}, {"text": "耳", "is_correct": false, "explanation": "頭の横の器官で、床を鳴らすことはできない。文の動作と合わない。"}, {"text": "鼻", "is_correct": false, "explanation": "顔の中央の器官で、床を鳴らす動作には使えない。"}], "explanations": {"踵": "正解。靴紐を結んで床を鳴らす、足の裏の後ろ側の部位を指す。", "眉": "顔の部位で、床を踏み鳴らす場面では使えない。「眉で床を鳴らす」は不自然。", "耳": "頭の横の器官で、床を鳴らすことはできない。文の動作と合わない。", "鼻": "顔の中央の器官で、床を鳴らす動作には使えない。"}, "sentence_index": 0, "correct_answer": "踵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "踵を噛んで、涙をこらえた。", "explanation": "ここは〈唇〉の場面。涙をこらえるときに噛むのは唇で、踵を噛むとは言わない。"}, {"text": "彼は机に踵をついて、考え込んだ。", "explanation": "ここは〈肘〉の場面。考え込むときに机につくのは肘で、踵をつくとは言わない。"}, {"text": "踵を鍵盤に置いた。", "explanation": "ここは〈指〉の場面。鍵盤は指で押さえて弾く物なので、踵を置いて弾くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52900, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "踵", "is_correct": true, "explanation": "正解。歩くことで皮がかたくなる、足の後ろ側の部位を指す。"}, {"text": "額", "is_correct": false, "explanation": "顔の部位で、歩くことで皮がかたくなる場面とは関係がない。"}, {"text": "唇", "is_correct": false, "explanation": "口の周りの部位で、歩く動作とは関係がなく、皮がかたくなる文に合わない。"}, {"text": "瞼", "is_correct": false, "explanation": "目を覆う部位で、歩くことで皮が厚くなる文とは合わない。"}], "explanations": {"踵": "正解。歩くことで皮がかたくなる、足の後ろ側の部位を指す。", "額": "顔の部位で、歩くことで皮がかたくなる場面とは関係がない。", "唇": "口の周りの部位で、歩く動作とは関係がなく、皮がかたくなる文に合わない。", "瞼": "目を覆う部位で、歩くことで皮が厚くなる文とは合わない。"}, "sentence_index": 6, "correct_answer": "踵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "踵を打って、拍手した。", "explanation": "ここは〈手〉の場面。拍手は手を打つ動作で、踵を打って音を出すとは言わない。"}, {"text": "踵の上に本を広げて読んだ。", "explanation": "ここは〈膝〉の場面。本を広げて置くのは膝の上で、踵の上に置くとは言わない。"}, {"text": "踵に重い荷物をのせて運んだ。", "explanation": "ここは〈肩〉の場面。荷物を担ぐ部位は肩で、踵にのせて運ぶとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52900, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いサンダルで、踵を豆ができてしまった。", "corrected_sentence": "古いサンダルで、踵に豆ができてしまった。", "error_description": "目的語の「を」は「できる」に合わない。場所を示す「に」を使い、「踵に豆ができてしまった」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52900, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日立ち仕事なので、踵をかたくなってきた。", "corrected_sentence": "毎日立ち仕事なので、踵がかたくなってきた。", "error_description": "主語を示す「が」が正しいのに「を」を使っている。「かたくなる」は自動詞なので「踵が」の形をとり、「踵を」は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52901, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩く", "is_correct": true, "explanation": "正解。しっかり締まっている状態の反対で、ゆるんでいる様子を表す対義語。"}, {"text": "高く", "is_correct": false, "explanation": "位置を表す語で、締まりの反対語ではない。"}, {"text": "早く", "is_correct": false, "explanation": "速さを表す語で、締まりの反対語にはならない。"}, {"text": "細く", "is_correct": false, "explanation": "太さを表す語で、締まりの強さの反対語ではない。"}], "correct_answer": "緩く", "explanations": {"緩く": "正解。しっかり締まっている状態の反対で、ゆるんでいる様子を表す対義語。", "高く": "位置を表す語で、締まりの反対語ではない。", "早く": "速さを表す語で、締まりの反対語にはならない。", "細く": "太さを表す語で、締まりの強さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52901, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩く", "is_correct": true, "explanation": "正解。しっかり締まっている状態の反対で、ゆるんでいる様子を表す対義語。"}, {"text": "寒く", "is_correct": false, "explanation": "温度を表す語で、締まりの反対語ではない。"}, {"text": "黒く", "is_correct": false, "explanation": "色を表す語で、締まりの反対語ではない。"}, {"text": "浅く", "is_correct": false, "explanation": "深さを表す語で、締まりの反対語にはならない。"}], "correct_answer": "緩く", "explanations": {"緩く": "正解。しっかり締まっている状態の反対で、ゆるんでいる様子を表す対義語。", "寒く": "温度を表す語で、締まりの反対語ではない。", "黒く": "色を表す語で、締まりの反対語ではない。", "浅く": "深さを表す語で、締まりの反対語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52901, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "しっかりと、ゆるまないようにすること。", "primary_collocate": null, "pronunciation": "かたい", "ipa": "katai", "syllable_count": 3, "sentences": [{"text": "ネジを固く締めないと、棚がぐらぐらする。", "target_word": "固く", "complexity_tier": "T3", "furigana": "ネジを固[かた]く締[し]めないと、棚[たな]がぐらぐらする。", "sentence_source": "generated"}, {"text": "風で飛ばないように、帽子のひもを固く結んだ。", "target_word": "固く", "complexity_tier": "T3", "furigana": "風[かぜ]で飛[と]ばないように、帽子[ぼうし]のひもを固[かた]く結[むす]んだ。", "sentence_source": "generated"}, {"text": "彼女は目を固く閉じて、願い事をした。", "target_word": "固く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は目[め]を固[かた]く閉[と]じて、願[ねが]い事[ごと]をした。", "sentence_source": "generated"}, {"text": "引っ越しの箱は、テープで固く留めた。", "target_word": "固く", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの箱[はこ]は、テープで固[かた]く留[と]めた。", "sentence_source": "generated"}, {"text": "風が強いので、窓を固く閉めておいた。", "target_word": "固く", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いので、窓[まど]を固[かた]く閉[し]めておいた。", "sentence_source": "generated"}, {"text": "荷造りのひもを固く縛っておけば、途中でゆるまない。", "target_word": "固く", "complexity_tier": "T3", "furigana": "荷造[にづく]りのひもを固[かた]く縛[しば]っておけば、途中[とちゅう]でゆるまない。", "sentence_source": "generated"}, {"text": "運動会の前に、靴のひもを固く結び直した。", "target_word": "固く", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の前[まえ]に、靴[くつ]のひもを固[かた]く結[むす]び直[なお]した。", "sentence_source": "generated"}, {"text": "手すりを固く握って、階段をゆっくり下りた。", "target_word": "固く", "complexity_tier": "T3", "furigana": "手[て]すりを固[かた]く握[にぎ]って、階段[かいだん]をゆっくり下[お]りた。", "sentence_source": "generated"}, {"text": "ふたを固く閉めたので、中身はこぼれなかった。", "target_word": "固く", "complexity_tier": "T3", "furigana": "ふたを固[かた]く閉[し]めたので、中身[なかみ]はこぼれなかった。", "sentence_source": "generated"}, {"text": "木の板を釘で固く打ちつけて、扉を直した。", "target_word": "固く", "complexity_tier": "T3", "furigana": "木[き]の板[いた]を釘[くぎ]で固[かた]く打[う]ちつけて、扉[とびら]を直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固い", "label": "終止形・連体形"}, {"form": "固く", "label": "連用形"}, {"form": "固かった", "label": "過去形"}, {"form": "固くない", "label": "否定形"}, {"form": "固ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "締める・結ぶ・閉じるなどの動作を、ゆるまないように しっかり行うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: ゆるま (Zipf 1.5)']::text[], '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52901, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固く", "is_correct": true, "explanation": "正解。「ネジを固く締める」の連用形で、ゆるまないように締める様子を表す。"}, {"text": "遠く", "is_correct": false, "explanation": "距離を表す語で、締める動作の仕方として意味が通らない。"}, {"text": "赤く", "is_correct": false, "explanation": "色の描写にしかならず、締める強さを表せない。"}, {"text": "白く", "is_correct": false, "explanation": "色を表す語で、締める動作を修飾できない。"}], "explanations": {"固く": "正解。「ネジを固く締める」の連用形で、ゆるまないように締める様子を表す。", "遠く": "距離を表す語で、締める動作の仕方として意味が通らない。", "赤く": "色の描写にしかならず、締める強さを表せない。", "白く": "色を表す語で、締める動作を修飾できない。"}, "sentence_index": 0, "correct_answer": "固く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は固く息を吸って、ゆっくり目を開けた。", "explanation": "ここは〈深く〉の意味。固くは締めて緩まないようにする意味で、息を吸う仕方には使わない。"}, {"text": "彼は固く走って、列車に間に合った。", "explanation": "ここは〈速く〉の意味。固くは締めて緩まないようにする意味で、走る速さには使わない。"}, {"text": "彼は夜固く帰宅した。", "explanation": "ここは〈遅く〉の意味。固くは締めて緩まないようにする意味で、帰る時刻には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52901, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固く", "is_correct": true, "explanation": "正解。「靴のひもを固く結び直した」で、しっかり結ぶ様子を表す。"}, {"text": "寒く", "is_correct": false, "explanation": "温度を表す語で、結ぶ動作を修飾できない。"}, {"text": "黒く", "is_correct": false, "explanation": "色の描写にしかならず、結び方の様子を表せない。"}, {"text": "暗く", "is_correct": false, "explanation": "明るさを表す語で、結び直す動作の仕方として意味が通らない。"}], "explanations": {"固く": "正解。「靴のひもを固く結び直した」で、しっかり結ぶ様子を表す。", "寒く": "温度を表す語で、結ぶ動作を修飾できない。", "黒く": "色の描写にしかならず、結び方の様子を表せない。", "暗く": "明るさを表す語で、結び直す動作の仕方として意味が通らない。"}, "sentence_index": 6, "correct_answer": "固く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は部屋を固く掃除した。", "explanation": "ここは〈きれいに〉の意味。固くは緩まないように締める意味で、掃除の仕方には使わない。"}, {"text": "彼は廊下を固く歩いた。", "explanation": "ここは〈静かに〉の意味。固くは締めて緩まない状態を表すので、歩き方の静かさには使わない。"}, {"text": "その机は固く古くなっていた。", "explanation": "ここは〈古く〉の意味。固くは締めて緩まない状態を表すので、古びていく様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52901, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ビンのふたを固い締めて、持ち運んだ。", "corrected_sentence": "ビンのふたを固く締めて、持ち運んだ。", "error_description": "「締めて」の前は連用形「固く」が必要。「固い」は動詞を修飾できない形なので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "固く", "is_correct": true, "explanation": "正解。「固く結んだ」の連用形で、結ぶ動作を修飾している。"}, {"text": "固い", "is_correct": false, "explanation": "終止形・連体形で、動詞「結んだ」を修飾する形になっていない。"}, {"text": "固かった", "is_correct": false, "explanation": "過去形で、「〜ないように結んだ」という目的の文と意味が合わない。"}, {"text": "固くない", "is_correct": false, "explanation": "否定形で、ゆるまないように結ぶという意味が反転してしまう。"}], "correct_form": "固く", "base_form": "固い", "form_label": "連用形", "sentence_index": 1, "explanations": {"固く": "正解。「固く結んだ」の連用形で、結ぶ動作を修飾している。", "固い": "終止形・連体形で、動詞「結んだ」を修飾する形になっていない。", "固かった": "過去形で、「〜ないように結んだ」という目的の文と意味が合わない。", "固くない": "否定形で、ゆるまないように結ぶという意味が反転してしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52901, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボルトを固く温めてから、機械を動かした。", "corrected_sentence": "ボルトを固く締めてから、機械を動かした。", "error_description": "「固く」が修飾する動詞が不適切。ゆるまないようにするのは「締める」なので、「温めて」は誤りの語。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "固く", "is_correct": true, "explanation": "正解。「手すりを固く握って」の連用形で、握る動作を修飾している。"}, {"text": "固ければ", "is_correct": false, "explanation": "仮定形で「〜ならば」の意味になり、動詞「握って」を修飾できない。"}, {"text": "固くて", "is_correct": false, "explanation": "て形で、後ろに続けて動作を修飾する形にならない。"}, {"text": "固くなかった", "is_correct": false, "explanation": "過去の否定形で、握る動作の仕方を表す形として意味が合わない。"}], "correct_form": "固く", "base_form": "固い", "form_label": "連用形", "sentence_index": 7, "explanations": {"固く": "正解。「手すりを固く握って」の連用形で、握る動作を修飾している。", "固ければ": "仮定形で「〜ならば」の意味になり、動詞「握って」を修飾できない。", "固くて": "て形で、後ろに続けて動作を修飾する形にならない。", "固くなかった": "過去の否定形で、握る動作の仕方を表す形として意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52902, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩く", "is_correct": true, "explanation": "正解。すきまなく締まる状態の反対で、ゆるんでいる様子を表す対義語。"}, {"text": "高く", "is_correct": false, "explanation": "位置や程度を表す語で、締まり具合の反対語ではない。"}, {"text": "早く", "is_correct": false, "explanation": "速さを表す語で、締まりの反対語にはならない。"}, {"text": "細く", "is_correct": false, "explanation": "太さを表す語で、締まりの強さの反対語ではない。"}], "correct_answer": "緩く", "explanations": {"緩く": "正解。すきまなく締まる状態の反対で、ゆるんでいる様子を表す対義語。", "高く": "位置や程度を表す語で、締まり具合の反対語ではない。", "早く": "速さを表す語で、締まりの反対語にはならない。", "細く": "太さを表す語で、締まりの強さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52902, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩く", "is_correct": true, "explanation": "正解。締まって動かない状態の反対で、ゆるんでいる様子を表す対義語。"}, {"text": "寒く", "is_correct": false, "explanation": "温度を表す語で、締まりの反対語ではない。"}, {"text": "黒く", "is_correct": false, "explanation": "色を表す語で、締まりの反対語ではない。"}, {"text": "浅く", "is_correct": false, "explanation": "深さを表す語で、締まりの反対語にはならない。"}], "correct_answer": "緩く", "explanations": {"緩く": "正解。締まって動かない状態の反対で、ゆるんでいる様子を表す対義語。", "寒く": "温度を表す語で、締まりの反対語ではない。", "黒く": "色を表す語で、締まりの反対語ではない。", "浅く": "深さを表す語で、締まりの反対語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52902, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物と物の間にすきまがなく、しっかりと結びついているさま。また、強くて動かないさま。", "primary_collocate": null, "pronunciation": "かたい", "ipa": "katai", "syllable_count": 3, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "固く", "complexity_tier": "T4", "furigana": "靴紐[くつひも]を固[かた]く結[むす]び、踵[かかと]で床[ゆか]を鳴[な]らせば、鈍[にぶ]い音[おと]が魂[たましい]の鼓動[こどう]と共鳴[きょうめい]する。", "sentence_source": "mined"}, {"text": "結び目が固くて、なかなかほどけない。", "target_word": "固く", "complexity_tier": "T3", "furigana": "結[むす]び目[め]が固[かた]くて、なかなかほどけない。", "sentence_source": "generated"}, {"text": "雨が降らず、畑の土が固くなってしまった。", "target_word": "固く", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らず、畑[はたけ]の土[つち]が固[かた]くなってしまった。", "sentence_source": "generated"}, {"text": "瓶のふたが固くて、手では開かなかった。", "target_word": "固く", "complexity_tier": "T3", "furigana": "瓶[びん]のふたが固[かた]くて、手[て]では開[あ]かなかった。", "sentence_source": "generated"}, {"text": "冬の朝、池の水は固く凍っていた。", "target_word": "固く", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]、池[いけ]の水[みず]は固[かた]く凍[こお]っていた。", "sentence_source": "generated"}, {"text": "子どもは母の手を固く握って離さなかった。", "target_word": "固く", "complexity_tier": "T3", "furigana": "子[こ]どもは母[はは]の手[て]を固[かた]く握[にぎ]って離[はな]さなかった。", "sentence_source": "generated"}, {"text": "古い扉は固く閉ざされたまま、誰も開けられない。", "target_word": "固く", "complexity_tier": "T3", "furigana": "古[ふる]い扉[とびら]は固[かた]く閉[と]ざされたまま、誰[だれ]も開[あ]けられない。", "sentence_source": "generated"}, {"text": "固い地面にくいを打ち込むのは大変だ。", "target_word": "固い", "complexity_tier": "T3", "furigana": "固[かた]い地面[じめん]にくいを打[う]ち込[こ]むのは大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "荷物が動かないように、ロープで固く縛った。", "target_word": "固く", "complexity_tier": "T3", "furigana": "荷物[にもつ]が動[うご]かないように、ロープで固[かた]く縛[しば]った。", "sentence_source": "generated"}, {"text": "雪の下の氷は固く、スコップが入らなかった。", "target_word": "固く", "complexity_tier": "T3", "furigana": "雪[ゆき]の下[した]の氷[こおり]は固[かた]く、スコップが入[はい]らなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固い", "label": "終止形・連体形"}, {"form": "固く", "label": "連用形"}, {"form": "固かった", "label": "過去形"}, {"form": "固くない", "label": "否定形"}, {"form": "固ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "隙間なくしっかり結びつき、簡単には動かない・ほどけない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 踵 (Zipf 3.15), 鳴らせ (Zipf 3.25), 鈍い (Zipf 3.23), 共鳴 (Zipf 3.38)']::text[], '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52902, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固く", "is_correct": true, "explanation": "正解。「靴紐を固く結ぶ」の連用形で、ほどけないようにしっかり結ぶ様子を表す。"}, {"text": "遠く", "is_correct": false, "explanation": "「遠く結ぶ」は距離を表し、紐の結び方として意味が通らない。"}, {"text": "赤く", "is_correct": false, "explanation": "色を表す語で、結ぶ動作の強さや様子を表せず不自然。"}, {"text": "白く", "is_correct": false, "explanation": "色の描写にしかならず、結ぶ動作を修飾できない。"}], "explanations": {"固く": "正解。「靴紐を固く結ぶ」の連用形で、ほどけないようにしっかり結ぶ様子を表す。", "遠く": "「遠く結ぶ」は距離を表し、紐の結び方として意味が通らない。", "赤く": "色を表す語で、結ぶ動作の強さや様子を表せず不自然。", "白く": "色の描写にしかならず、結ぶ動作を修飾できない。"}, "sentence_index": 0, "correct_answer": "固く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その夜は固い風が吹いて、窓がきしんだ。", "explanation": "ここは〈強い〉の意味。固いは物同士がすきまなく結びつき動かない状態を表すので、吹く風には使えない。"}, {"text": "寒い日、彼は固いお茶を飲んで体を温めた。", "explanation": "ここは〈熱い〉の意味。固いはしっかり結びついて動かない状態を指すので、お茶の温度には使えない。"}, {"text": "母の味噌汁は固くて、いつも少し塩辛い。", "explanation": "ここは〈濃い〉の意味。固いは物の状態を表し、汁物の味の濃さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52902, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固く", "is_correct": true, "explanation": "正解。「扉は固く閉ざされた」と、しっかり閉まって開かない様子を表す。"}, {"text": "寒く", "is_correct": false, "explanation": "温度を表す語で、扉を閉ざす様子を表せず意味が通らない。"}, {"text": "黒く", "is_correct": false, "explanation": "色の描写にしかならず、閉ざすという動作の仕方を表せない。"}, {"text": "浅く", "is_correct": false, "explanation": "深さを表す語で、扉を閉ざす様子に合わない。"}], "explanations": {"固く": "正解。「扉は固く閉ざされた」と、しっかり閉まって開かない様子を表す。", "寒く": "温度を表す語で、扉を閉ざす様子を表せず意味が通らない。", "黒く": "色の描写にしかならず、閉ざすという動作の仕方を表せない。", "浅く": "深さを表す語で、扉を閉ざす様子に合わない。"}, "sentence_index": 6, "correct_answer": "固く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓を開けると、部屋は固い日差しで満ちた。", "explanation": "ここは〈明るい〉の意味。固いは物がすきまなく結びつく状態を表すので、光の様子には使わない。"}, {"text": "疲れた夜、彼は固い風呂でゆっくり休んだ。", "explanation": "ここは〈ぬるい〉の意味。固いは物の結びつきを表すので、湯の温度には使えない。"}, {"text": "固い夏休みが終わってしまった。", "explanation": "ここは〈短い〉の意味。固いは物の状態を指し、期間の長さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52902, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚のネジを固い締めて、動かないようにした。", "corrected_sentence": "棚のネジを固く締めて、動かないようにした。", "error_description": "「締めて」の前は連用形「固く」が必要。「固い」は終止形・連体形で、動詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "固く", "is_correct": true, "explanation": "正解。「固くて」の「固く」部分で、連用形。"}, {"text": "固い", "is_correct": false, "explanation": "終止形・連体形で、「固いて」となり、て形の接続に続かない。"}, {"text": "固かった", "is_correct": false, "explanation": "過去形で、「なかなかほどけない」という現在の状態と時制が合わない。"}, {"text": "固くない", "is_correct": false, "explanation": "否定形で、「固くない」と続くと意味が反転し、結び目の状態と合わない。"}], "correct_form": "固く", "base_form": "固い", "form_label": "連用形", "sentence_index": 1, "explanations": {"固く": "正解。「固くて」の「固く」部分で、連用形。", "固い": "終止形・連体形で、「固いて」となり、て形の接続に続かない。", "固かった": "過去形で、「なかなかほどけない」という現在の状態と時制が合わない。", "固くない": "否定形で、「固くない」と続くと意味が反転し、結び目の状態と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52902, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土の塊が固く溶けて、掘るのに苦労した。", "corrected_sentence": "土の塊が固く乾いて、掘るのに苦労した。", "error_description": "「固く」が修飾する動詞が不適切。固くなるのは「乾く」なので「乾いて」が正しく、「溶けて」は固さと結びつかず不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "固い", "is_correct": true, "explanation": "正解。連体形で、後ろの名詞「地面」を直接修飾している。"}, {"text": "固ければ", "is_correct": false, "explanation": "仮定形で「〜ならば」の意味になり、名詞を修飾できない。"}, {"text": "固くて", "is_correct": false, "explanation": "て形で、名詞「地面」を修飾できない。"}, {"text": "固く", "is_correct": false, "explanation": "連用形で、名詞「地面」を直接修飾できない。"}], "correct_form": "固い", "base_form": "固い", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"固い": "正解。連体形で、後ろの名詞「地面」を直接修飾している。", "固ければ": "仮定形で「〜ならば」の意味になり、名詞を修飾できない。", "固くて": "て形で、名詞「地面」を修飾できない。", "固く": "連用形で、名詞「地面」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
