INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52903, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52903, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "足で床などをたたいて音を出すこと。", "primary_collocate": null, "pronunciation": "ならす", "ipa": "narasɯ", "syllable_count": 3, "sentences": [{"text": "緊張すると、弟は足で床を鳴らす癖がある。", "target_word": "鳴らす", "complexity_tier": "T3", "furigana": "緊張[きんちょう]すると、弟[おとうと]は足[あし]で床[ゆか]を鳴[な]らす癖[くせ]がある。", "sentence_source": "generated"}, {"text": "兵士たちは靴を鳴らして、一列に並んだ。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは靴[くつ]を鳴[な]らして、一列[いちれつ]に並[なら]んだ。", "sentence_source": "generated"}, {"text": "ダンスの先生は、床を鳴らしてテンポを教えてくれた。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "ダンスの先生[せんせい]は、床[ゆか]を鳴[な]らしてテンポを教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "祭りの夜、男たちは足で地面を鳴らして踊った。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]、男[おとこ]たちは足[あし]で地面[じめん]を鳴[な]らして踊[おど]った。", "sentence_source": "generated"}, {"text": "寒くて、私は足を鳴らしながらバスを待った。", "target_word": "鳴らし", "complexity_tier": "T3", "furigana": "寒[さむ]くて、私[わたし]は足[あし]を鳴[な]らしながらバスを待[ま]った。", "sentence_source": "generated"}, {"text": "彼女は怒って、わざと床を鳴らして歩いた。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は怒[おこ]って、わざと床[ゆか]を鳴[な]らして歩[ある]いた。", "sentence_source": "generated"}, {"text": "舞台の上で、タップダンサーが靴を軽やかに鳴らした。", "target_word": "鳴らした", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の上[うえ]で、タップダンサーが靴[くつ]を軽[かる]やかに鳴[な]らした。", "sentence_source": "generated"}, {"text": "赤ちゃんが寝ているので、床を鳴らさないで歩いてください。", "target_word": "鳴らさない", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが寝[ね]ているので、床[ゆか]を鳴[な]らさないで歩[ある]いてください。", "sentence_source": "generated"}, {"text": "合図に合わせて、みんなで足を三回鳴らした。", "target_word": "鳴らした", "complexity_tier": "T3", "furigana": "合図[あいず]に合[あ]わせて、みんなで足[あし]を三回[さんかい]鳴[な]らした。", "sentence_source": "generated"}, {"text": "勝った選手を迎えようと、観客は足を鳴らして喜んだ。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "勝[か]った選手[せんしゅ]を迎[むか]えようと、観客[かんきゃく]は足[あし]を鳴[な]らして喜[よろこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳴らす", "label": "終止形"}, {"form": "鳴らし", "label": "連用形"}, {"form": "鳴らして", "label": "て形"}, {"form": "鳴らした", "label": "過去形"}, {"form": "鳴らさない", "label": "否定形"}, {"form": "鳴らせ", "label": "仮定形（鳴らせば）"}], "register": "neutral", "sense_fingerprint": "足で床や地面をたたくように踏んで音を出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52903, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鳴らす", "is_correct": true, "explanation": "正解。終止形で、名詞「癖」を修飾して「床を鳴らす癖」となる。"}, {"text": "鳴らして", "is_correct": false, "explanation": "て形で、名詞「癖」を修飾できず文が成り立たない。"}, {"text": "鳴らせ", "is_correct": false, "explanation": "命令・仮定の形で、「癖」を修飾する形にならない。"}, {"text": "鳴らしながら", "is_correct": false, "explanation": "同時動作の形で、「癖がある」と続けると意味が通らない。"}], "explanations": {"鳴らす": "正解。終止形で、名詞「癖」を修飾して「床を鳴らす癖」となる。", "鳴らして": "て形で、名詞「癖」を修飾できず文が成り立たない。", "鳴らせ": "命令・仮定の形で、「癖」を修飾する形にならない。", "鳴らしながら": "同時動作の形で、「癖がある」と続けると意味が通らない。"}, "sentence_index": 0, "correct_answer": "鳴らす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中に雷を鳴らして、空が光った。", "explanation": "ここは〈鳴る〉の意味。鳴らすは人や物に音を出させる語で、雷が鳴る場合は自動詞の〈鳴る〉を使う。"}, {"text": "彼は声を鳴らして、みんなに合図した。", "explanation": "ここは〈声を上げる〉の意味。鳴らすは物を打ち当てたり振動させたりして音を出す語で、人の声には使わない。"}, {"text": "犬は尻尾を鳴らして、飼い主に駆け寄った。", "explanation": "ここは〈振る〉の意味。鳴らすは音を出す語で、尻尾を動かす場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52903, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鳴らした", "is_correct": true, "explanation": "正解。過去形で、舞台上での動作として「靴を軽やかに鳴らした」と完結する。"}, {"text": "鳴らさない", "is_correct": false, "explanation": "否定形で、舞台での動作を否定する意味になり、文の内容と合わない。"}, {"text": "鳴らされ", "is_correct": false, "explanation": "受身の語幹で、「靴を」の目的語と文が合わない。"}, {"text": "鳴らさず", "is_correct": false, "explanation": "否定の連用形で、動作を行わなかった意味になり文が成り立たない。"}], "explanations": {"鳴らした": "正解。過去形で、舞台上での動作として「靴を軽やかに鳴らした」と完結する。", "鳴らさない": "否定形で、舞台での動作を否定する意味になり、文の内容と合わない。", "鳴らされ": "受身の語幹で、「靴を」の目的語と文が合わない。", "鳴らさず": "否定の連用形で、動作を行わなかった意味になり文が成り立たない。"}, "sentence_index": 6, "correct_answer": "鳴らした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブルドーザーで地面を鳴らして、平らにした。", "explanation": "ここは〈ならす〉（平らにする）の意味。鳴らすは音を出す語なので、地面を平らにする意味では使わない。"}, {"text": "朝早く、庭の鳥が一斉に鳴らした。", "explanation": "ここは〈鳴く〉の意味。鳥や動物が声を出すときは自動詞の〈鳴く〉を使い、鳴らすは使わない。"}, {"text": "彼は耳を鳴らして、遠くの話し声を聞いた。", "explanation": "ここは〈耳を澄ます〉の意味。鳴らすは物や体を振動させて音を出す語で、聞く態度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52903, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "観客は足に床を鳴らして、選手を応援した。", "corrected_sentence": "観客は足で床を鳴らして、選手を応援した。", "error_description": "足を使って音を出す手段は「で」で示す。「に」では足に床があるような関係になり、動作として不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "鳴らして", "is_correct": true, "explanation": "正解。て形で、後ろの「並んだ」へ続けられる。"}, {"text": "鳴らす", "is_correct": false, "explanation": "終止形で、「一列に並んだ」と続かない。"}, {"text": "鳴らせ", "is_correct": false, "explanation": "命令形で、「靴を鳴らせ、一列に並んだ」と過去の叙述が続かない。"}, {"text": "鳴らした", "is_correct": false, "explanation": "過去形で動作が完結し、「一列に並んだ」と続けられない。"}], "correct_form": "鳴らして", "base_form": "鳴らす", "form_label": "て形", "sentence_index": 1, "explanations": {"鳴らして": "正解。て形で、後ろの「並んだ」へ続けられる。", "鳴らす": "終止形で、「一列に並んだ」と続かない。", "鳴らせ": "命令形で、「靴を鳴らせ、一列に並んだ」と過去の叙述が続かない。", "鳴らした": "過去形で動作が完結し、「一列に並んだ」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52903, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "合図で、観客は一斉に足を鳴らすて応援した。", "corrected_sentence": "合図で、観客は一斉に足を鳴らして応援した。", "error_description": "「鳴らして」のて形が崩れている。「鳴らす」の接続は「鳴らして」が正しく、「鳴らすて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "鳴らさない", "is_correct": true, "explanation": "正解。否定形で「床を鳴らさないで歩いてください」の依頼の意味を作る。"}, {"text": "鳴らさせ", "is_correct": false, "explanation": "使役の語幹で、「〜ないで」の依頼文と形が合わない。"}, {"text": "鳴らされ", "is_correct": false, "explanation": "受身の語幹で、依頼文の主語と動作の関係が合わない。"}, {"text": "鳴らさず", "is_correct": false, "explanation": "否定の連用形で、「歩いてください」と続けると意味が不自然になる。"}], "correct_form": "鳴らさない", "base_form": "鳴らす", "form_label": "否定形", "sentence_index": 7, "explanations": {"鳴らさない": "正解。否定形で「床を鳴らさないで歩いてください」の依頼の意味を作る。", "鳴らさせ": "使役の語幹で、「〜ないで」の依頼文と形が合わない。", "鳴らされ": "受身の語幹で、依頼文の主語と動作の関係が合わない。", "鳴らさず": "否定の連用形で、「歩いてください」と続けると意味が不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52904, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52904, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52904, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を打ち当てたり、振動させたりして音を出す。特に、足で床や地面を強く踏んで音を立てる。", "primary_collocate": null, "pronunciation": "ならす", "ipa": "narasɯ", "syllable_count": 3, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "鳴らせ", "complexity_tier": "T4", "furigana": "靴紐[くつひも]を固[かた]く結[むす]び、踵[かかと]で床[ゆか]を鳴[な]らせば、鈍[にぶ]い音[おと]が魂[たましい]の鼓動[こどう]と共鳴[きょうめい]する。", "sentence_source": "mined"}, {"text": "怒った父は、足を鳴らして部屋を出ていった。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "怒[おこ]った父[ちち]は、足[あし]を鳴[な]らして部屋[へや]を出[で]ていった。", "sentence_source": "generated"}, {"text": "ダンサーはかかとを鳴らして、リズムをとった。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "ダンサーはかかとを鳴[な]らして、リズムをとった。", "sentence_source": "generated"}, {"text": "子どもたちは嬉しくて、足を鳴らして喜んだ。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "子[こ]どもたちは嬉[うれ]しくて、足[あし]を鳴[な]らして喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "彼は靴のかかとを鳴らして、気をつけの姿勢をとった。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "彼[かれ]は靴[くつ]のかかとを鳴[な]らして、気[き]をつけの姿勢[しせい]をとった。", "sentence_source": "generated"}, {"text": "ステージの上で、フラメンコの踊り手が床を力強く鳴らした。", "target_word": "鳴らした", "complexity_tier": "T3", "furigana": "ステージの上[うえ]で、フラメンコの踊[おど]り手[て]が床[ゆか]を力強[ちからづよ]く鳴[な]らした。", "sentence_source": "generated"}, {"text": "夜は下の階に響くので、床を鳴らさないでください。", "target_word": "鳴らさない", "complexity_tier": "T3", "furigana": "夜[よる]は下[した]の階[かい]に響[ひび]くので、床[ゆか]を鳴[な]らさないでください。", "sentence_source": "generated"}, {"text": "応援団は太鼓に合わせて、足を鳴らして声を出した。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "応援団[おうえんだん]は太鼓[たいこ]に合[あ]わせて、足[あし]を鳴[な]らして声[こえ]を出[だ]した。", "sentence_source": "generated"}, {"text": "雪道で長靴を鳴らしながら、学校へ向かった。", "target_word": "鳴らし", "complexity_tier": "T3", "furigana": "雪道[ゆきみち]で長靴[ながぐつ]を鳴[な]らしながら、学校[がっこう]へ向[む]かった。", "sentence_source": "generated"}, {"text": "先生は教室の床を足で鳴らして、みんなを静かにさせた。", "target_word": "鳴らして", "complexity_tier": "T3", "furigana": "先生[せんせい]は教室[きょうしつ]の床[ゆか]を足[あし]で鳴[な]らして、みんなを静[しず]かにさせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳴らす", "label": "終止形"}, {"form": "鳴らし", "label": "連用形"}, {"form": "鳴らして", "label": "て形"}, {"form": "鳴らした", "label": "過去形"}, {"form": "鳴らさない", "label": "否定形"}, {"form": "鳴らせ", "label": "仮定形（鳴らせば）"}], "register": "neutral", "sense_fingerprint": "足やかかとで床・地面を強く踏み、音を立てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52904, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鳴らせ", "is_correct": true, "explanation": "正解。仮定形「鳴らせば」で、「床を鳴らせば」と条件を続けられる。"}, {"text": "鳴らさない", "is_correct": false, "explanation": "否定形で「〜ば」の条件文に続かず、文が成り立たない。"}, {"text": "鳴らした", "is_correct": false, "explanation": "過去形で、「〜ば」の仮定の文に続けられない。"}, {"text": "鳴らして", "is_correct": false, "explanation": "て形で、「〜ば」に続けることができない。"}], "explanations": {"鳴らせ": "正解。仮定形「鳴らせば」で、「床を鳴らせば」と条件を続けられる。", "鳴らさない": "否定形で「〜ば」の条件文に続かず、文が成り立たない。", "鳴らした": "過去形で、「〜ば」の仮定の文に続けられない。", "鳴らして": "て形で、「〜ば」に続けることができない。"}, "sentence_index": 0, "correct_answer": "鳴らせ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中に雷を鳴らして、空が光った。", "explanation": "ここは〈鳴る〉の意味。鳴らすは人や物に音を出させる語で、雷が鳴る場合は自動詞の〈鳴る〉を使う。"}, {"text": "彼は声を鳴らして、みんなに合図した。", "explanation": "ここは〈声を上げる〉の意味。鳴らすは物を打ち当てたり振動させたりして音を出す語で、人の声には使わない。"}, {"text": "犬は尻尾を鳴らして、飼い主に駆け寄った。", "explanation": "ここは〈振る〉の意味。鳴らすは音を出す語で、尻尾を動かす場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52904, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鳴らさない", "is_correct": true, "explanation": "正解。「床を鳴らさないでください」の形で、禁止の意味を表す。"}, {"text": "鳴らさせ", "is_correct": false, "explanation": "使役の語幹で、「床を〜でください」の形に入らない。"}, {"text": "鳴らされ", "is_correct": false, "explanation": "受身の語幹で、「でください」に続けて意味が成り立たない。"}, {"text": "鳴らしながら", "is_correct": false, "explanation": "同時動作を表す形で、「でください」の依頼文には入らない。"}], "explanations": {"鳴らさない": "正解。「床を鳴らさないでください」の形で、禁止の意味を表す。", "鳴らさせ": "使役の語幹で、「床を〜でください」の形に入らない。", "鳴らされ": "受身の語幹で、「でください」に続けて意味が成り立たない。", "鳴らしながら": "同時動作を表す形で、「でください」の依頼文には入らない。"}, "sentence_index": 6, "correct_answer": "鳴らさない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブルドーザーで地面を鳴らして、平らにした。", "explanation": "ここは〈ならす〉（平らにする）の意味。鳴らすは音を出す語なので、地面を平らにする意味では使わない。"}, {"text": "朝早く、庭の鳥が一斉に鳴らした。", "explanation": "ここは〈鳴く〉の意味。鳥や動物が声を出すときは自動詞の〈鳴く〉を使い、鳴らすは使わない。"}, {"text": "彼は耳を鳴らして、遠くの話し声を聞いた。", "explanation": "ここは〈耳を澄ます〉の意味。鳴らすは物や体を振動させて音を出す語で、聞く態度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52904, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い朝、彼は足が鳴らして体を温めた。", "corrected_sentence": "寒い朝、彼は足を鳴らして体を温めた。", "error_description": "「鳴らして」の目的語には「を」が必要。「が」では足が自分で音を出す形になり、不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "鳴らして", "is_correct": true, "explanation": "正解。て形で、後ろの「部屋を出ていった」に続けられる。"}, {"text": "鳴らす", "is_correct": false, "explanation": "終止形で、「部屋を出ていった」と続く形にならない。"}, {"text": "鳴らせ", "is_correct": false, "explanation": "命令形で、「足を鳴らせ部屋を出ていった」と続かない。"}, {"text": "鳴らした", "is_correct": false, "explanation": "過去形で動作が完結してしまい、「部屋を出ていった」と続けられない。"}], "correct_form": "鳴らして", "base_form": "鳴らす", "form_label": "て形", "sentence_index": 1, "explanations": {"鳴らして": "正解。て形で、後ろの「部屋を出ていった」に続けられる。", "鳴らす": "終止形で、「部屋を出ていった」と続く形にならない。", "鳴らせ": "命令形で、「足を鳴らせ部屋を出ていった」と続かない。", "鳴らした": "過去形で動作が完結してしまい、「部屋を出ていった」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52904, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは床を足で鳴らすして、遊び回った。", "corrected_sentence": "子どもたちは床を足で鳴らして、遊び回った。", "error_description": "「鳴らす」のて形は「鳴らして」。「鳴らすして」は接続の形が誤りで、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "鳴らして", "is_correct": true, "explanation": "正解。て形で、「声を出した」へ続く形になっている。"}, {"text": "鳴らさせ", "is_correct": false, "explanation": "使役の語幹で、「足を〜て声を出した」と続けると意味が変わる。"}, {"text": "鳴らされ", "is_correct": false, "explanation": "受身の語幹で、主語が足に移り文の意味が合わない。"}, {"text": "鳴らせ", "is_correct": false, "explanation": "命令形で、「足を鳴らせ声を出した」と続かない。"}], "correct_form": "鳴らして", "base_form": "鳴らす", "form_label": "て形", "sentence_index": 7, "explanations": {"鳴らして": "正解。て形で、「声を出した」へ続く形になっている。", "鳴らさせ": "使役の語幹で、「足を〜て声を出した」と続けると意味が変わる。", "鳴らされ": "受身の語幹で、主語が足に移り文の意味が合わない。", "鳴らせ": "命令形で、「足を鳴らせ声を出した」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52905, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『鼓動が大きくなる』で、大きくなるのは鼓動なので主語の『が』が入る。"}, {"text": "を", "is_correct": false, "explanation": "『大きくなる』は目的語を取らないので、『を』は入らない。"}, {"text": "に", "is_correct": false, "explanation": "『鼓動に大きくなる』では、変化の主体を示す形にならない。"}, {"text": "と", "is_correct": false, "explanation": "『鼓動と大きくなる』は並列の形で、変化の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "『鼓動が大きくなる』で、大きくなるのは鼓動なので主語の『が』が入る。", "を": "『大きくなる』は目的語を取らないので、『を』は入らない。", "に": "『鼓動に大きくなる』では、変化の主体を示す形にならない。", "と": "『鼓動と大きくなる』は並列の形で、変化の主語にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "帰着・対象", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52905, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『鼓動が乱れた』で、乱れたのは鼓動なので主語の『が』が入る。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、乱れるという状態の形にならない。"}, {"text": "で", "is_correct": false, "explanation": "『鼓動で乱れた』では手段の形になり、文意に合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示すので、乱れるという変化の形にならない。"}], "correct_answer": "が", "explanations": {"が": "『鼓動が乱れた』で、乱れたのは鼓動なので主語の『が』が入る。", "へ": "『へ』は方向を示すので、乱れるという状態の形にならない。", "で": "『鼓動で乱れた』では手段の形になり、文意に合わない。", "より": "『より』は比較を示すので、乱れるという変化の形にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "で": "場所・手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52905, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "心臓がドキドキする動きのことです。", "primary_collocate": null, "pronunciation": "こどう", "ipa": "kodoː", "syllable_count": 3, "sentences": [{"text": "階段を駆け上がると、鼓動が速くなった。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "階段[かいだん]を駆[か]け上[あ]がると、鼓動[こどう]が速[はや]くなった。", "sentence_source": "generated"}, {"text": "好きな人の前では、鼓動が大きくなる。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "好[す]きな人[ひと]の前[まえ]では、鼓動[こどう]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "手首に指を当てて、鼓動を数えた。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "手首[てくび]に指[ゆび]を当[あ]てて、鼓動[こどう]を数[かぞ]えた。", "sentence_source": "generated"}, {"text": "怖い映画を見て、鼓動が激しくて眠れなかった。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "怖[こわ]い映画[えいが]を見[み]て、鼓動[こどう]が激[はげ]しくて眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "合格発表の前は、鼓動の音が耳に聞こえるようだった。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "合格発表[ごうかくはっぴょう]の前[まえ]は、鼓動[こどう]の音[おと]が耳[みみ]に聞[き]こえるようだった。", "sentence_source": "generated"}, {"text": "検査で、機械が胎児の鼓動を音にして聞かせてくれた。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "検査[けんさ]で、機械[きかい]が胎児[たいじ]の鼓動[こどう]を音[おと]にして聞[き]かせてくれた。", "sentence_source": "generated"}, {"text": "眠る前、枕に耳をつけると自分の鼓動が聞こえる。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "眠[ねむ]る前[まえ]、枕[まくら]に耳[みみ]をつけると自分[じぶん]の鼓動[こどう]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "緊張で鼓動が乱れたので、水を飲んで休んだ。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "緊張[きんちょう]で鼓動[こどう]が乱[みだ]れたので、水[みず]を飲[の]んで休[やす]んだ。", "sentence_source": "generated"}, {"text": "犬を抱くと、小さな鼓動が手に伝わってきた。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "犬[いぬ]を抱[だ]くと、小[ちい]さな鼓動[こどう]が手[て]に伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "運動をやめて数分すると、鼓動は元に戻った。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "運動[うんどう]をやめて数分[すうふん]すると、鼓動[こどう]は元[もと]に戻[もど]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鼓動", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "心臓がドキドキと打つ体の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52905, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼓動", "is_correct": true, "explanation": "階段を駆け上がって速くなるのは心臓の鼓動で、この文脈に合う。"}, {"text": "指紋", "is_correct": false, "explanation": "指紋は指先の模様で、速くなる動きではない。"}, {"text": "木目", "is_correct": false, "explanation": "木目は木材の模様で、速くなるものではない。"}, {"text": "年輪", "is_correct": false, "explanation": "年輪は木の成長の跡で、速くなるという文脈に合わない。"}], "explanations": {"鼓動": "階段を駆け上がって速くなるのは心臓の鼓動で、この文脈に合う。", "指紋": "指紋は指先の模様で、速くなる動きではない。", "木目": "木目は木材の模様で、速くなるものではない。", "年輪": "年輪は木の成長の跡で、速くなるという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "鼓動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "救急隊員は手首の鼓動を取って、血圧を測り始めた。", "explanation": "ここは〈脈〉の意味。脈は手首で取るものなので『脈を取る』と言うが、鼓動は数えたり聞いたりするもので、取るとは言わない。"}, {"text": "鼓動が乾いて、色が濃くなった。", "explanation": "〈絵の具〉の意味。鼓動は乾いたり色が濃くなったりしない。"}, {"text": "鼓動が冷たくて、手を離した。", "explanation": "〈ドアノブ〉の意味。鼓動に温度はなく、冷たいとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52905, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鼓動", "is_correct": true, "explanation": "枕に耳をつけて聞こえるのは、自分の心臓の鼓動。"}, {"text": "切符", "is_correct": false, "explanation": "切符は紙の乗車券で、耳をつけて聞こえるものではない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は洗う道具で、耳に聞こえる音を出さない。"}, {"text": "洗濯物", "is_correct": false, "explanation": "洗濯物は布の集まりで、耳をつけて聞こえるものではない。"}], "explanations": {"鼓動": "枕に耳をつけて聞こえるのは、自分の心臓の鼓動。", "切符": "切符は紙の乗車券で、耳をつけて聞こえるものではない。", "石鹸": "石鹸は洗う道具で、耳に聞こえる音を出さない。", "洗濯物": "洗濯物は布の集まりで、耳をつけて聞こえるものではない。"}, "sentence_index": 6, "correct_answer": "鼓動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "やかんの鼓動が沸いて、湯気が立った。", "explanation": "ここは〈ぽこぽこと鳴る音〉の意味。鼓動は心臓の拍動で、やかんの鳴る音を表すのには使えない。"}, {"text": "大雨で鼓動が濁った。", "explanation": "〈川〉の意味。鼓動は濁ったり澄んだりするものではない。"}, {"text": "パンが焼けて、鼓動が香ばしい匂いがした。", "explanation": "ここは〈香料〉の意味。鼓動は香りを放つものではなく、香料のように匂いを出すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52905, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坂道を歩いて、鼓動を速くなった。", "corrected_sentence": "坂道を歩いて、鼓動が速くなった。", "error_description": "『速くなる』は主語の『が』を取る。『鼓動を』は目的語の誤りで、『鼓動が速くなった』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52905, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緊張で鼓動が濡れたので、深呼吸して休んだ。", "corrected_sentence": "緊張で鼓動が乱れたので、深呼吸して休んだ。", "error_description": "『濡れた』は『乱れた』の誤り。鼓動は乱れる（不規則になる）もので、濡れるものではない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52906, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『鼓動が速かった』では、速かったのは鼓動なので主語の『が』が入る。"}, {"text": "を", "is_correct": false, "explanation": "『速い』は目的語を取らないので、『鼓動を速かった』は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『鼓動に速かった』では、状態の主体を示す形にならない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示すので、鼓動の状態を述べる文には入らない。"}], "correct_answer": "が", "explanations": {"が": "『鼓動が速かった』では、速かったのは鼓動なので主語の『が』が入る。", "を": "『速い』は目的語を取らないので、『鼓動を速かった』は成り立たない。", "に": "『鼓動に速かった』では、状態の主体を示す形にならない。", "で": "『で』は場所や手段を示すので、鼓動の状態を述べる文には入らない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "対象・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52906, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『町の鼓動が感じられる』で、感じられるものは鼓動なので主語の『が』が入る。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すので、感じられる対象の形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、『鼓動へ感じられる』は不自然。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示すので、感じられる対象の形にならない。"}], "correct_answer": "が", "explanations": {"が": "『町の鼓動が感じられる』で、感じられるものは鼓動なので主語の『が』が入る。", "と": "『と』は並列や相手を示すので、感じられる対象の形にならない。", "へ": "『へ』は方向を示すので、『鼓動へ感じられる』は不自然。", "より": "『より』は比較を示すので、感じられる対象の形にならない。"}, "error_tags": {"が": "主語", "と": "並列・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52906, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "心臓の拍動。また、心臓が打つように感じられる動きや響き。", "primary_collocate": null, "pronunciation": "こどう", "ipa": "kodoː", "syllable_count": 3, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "鼓動", "complexity_tier": "T4", "furigana": "靴紐[くつひも]を固[かた]く結[むす]び、踵[かかと]で床[ゆか]を鳴[な]らせば、鈍[にぶ]い音[おと]が魂[たましい]の鼓動[こどう]と共鳴[きょうめい]する。", "sentence_source": "mined"}, {"text": "走ったあと、胸に手を当てると鼓動が速かった。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "走[はし]ったあと、胸[むね]に手[て]を当[あ]てると鼓動[こどう]が速[はや]かった。", "sentence_source": "generated"}, {"text": "静かな部屋では、自分の鼓動まで聞こえてくる。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "静[しず]かな部屋[へや]では、自分[じぶん]の鼓動[こどう]まで聞[き]こえてくる。", "sentence_source": "generated"}, {"text": "医者は聴診器で赤ちゃんの鼓動を確かめた。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "医者[いしゃ]は聴診器[ちょうしんき]で赤[あか]ちゃんの鼓動[こどう]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "発表の前、緊張して鼓動が激しくなった。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の前[まえ]、緊張[きんちょう]して鼓動[こどう]が激[はげ]しくなった。", "sentence_source": "generated"}, {"text": "太鼓の低い音は、まるで大地の鼓動のように響いた。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "太鼓[たいこ]の低[ひく]い音[おと]は、まるで大地[だいち]の鼓動[こどう]のように響[ひび]いた。", "sentence_source": "generated"}, {"text": "彼に名前を呼ばれて、胸の鼓動が高まった。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "彼[かれ]に名前[なまえ]を呼[よ]ばれて、胸[むね]の鼓動[こどう]が高[たか]まった。", "sentence_source": "generated"}, {"text": "朝の市場には、町の鼓動が感じられる。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "朝[あさ]の市場[いちば]には、町[まち]の鼓動[こどう]が感[かん]じられる。", "sentence_source": "generated"}, {"text": "母のおなかに耳を当てて、小さな鼓動を聞いた。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "母[はは]のおなかに耳[みみ]を当[あ]てて、小[ちい]さな鼓動[こどう]を聞[き]いた。", "sentence_source": "generated"}, {"text": "静かに深呼吸すると、鼓動がだんだん落ち着いてきた。", "target_word": "鼓動", "complexity_tier": "T3", "furigana": "静[しず]かに深呼吸[しんこきゅう]すると、鼓動[こどう]がだんだん落[お]ち着[つ]いてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鼓動", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "心臓の拍動、またそれになぞらえた脈打つような動きや響き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52906, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼓動", "is_correct": true, "explanation": "心臓の拍動を指し、靴紐や床の音が魂の拍動と共鳴するという文脈に合う。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸で、踵で床を鳴らす音と共鳴するものではない。"}, {"text": "指紋", "is_correct": false, "explanation": "指紋は指先の皮膚の模様で、音や響きと結びつかない。"}, {"text": "車輪", "is_correct": false, "explanation": "車輪は回る部品で、魂と共鳴するという文脈に合わない。"}], "explanations": {"鼓動": "心臓の拍動を指し、靴紐や床の音が魂の拍動と共鳴するという文脈に合う。", "寝息": "寝息は眠っている人の呼吸で、踵で床を鳴らす音と共鳴するものではない。", "指紋": "指紋は指先の皮膚の模様で、音や響きと結びつかない。", "車輪": "車輪は回る部品で、魂と共鳴するという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "鼓動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱が下がって、鼓動がようやく平熱に戻った。", "explanation": "ここは〈体温〉の意味。鼓動は心臓の拍動なので、平熱という温度の状態には戻らない。"}, {"text": "この布は鼓動がなめらかだ。", "explanation": "〈手触り〉の意味。鼓動は布の感触を表さず、なめらかさとは結びつかない。"}, {"text": "寒い朝、鼓動が白く見えた。", "explanation": "〈息〉の意味。息は白く見えるが、鼓動には色や見た目の性質がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52906, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鼓動", "is_correct": true, "explanation": "名前を呼ばれて胸の中で高まるものは心臓の拍動で、鼓動が入る。"}, {"text": "冷や汗", "is_correct": false, "explanation": "冷や汗は皮膚に出る汗で、胸の中で高まるものではない。"}, {"text": "切り傷", "is_correct": false, "explanation": "切り傷は皮膚の傷で、高まるという動きを表さない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の色で、胸の中で高まる対象にはならない。"}], "explanations": {"鼓動": "名前を呼ばれて胸の中で高まるものは心臓の拍動で、鼓動が入る。", "冷や汗": "冷や汗は皮膚に出る汗で、胸の中で高まるものではない。", "切り傷": "切り傷は皮膚の傷で、高まるという動きを表さない。", "夕焼け": "夕焼けは空の色で、胸の中で高まる対象にはならない。"}, "sentence_index": 6, "correct_answer": "鼓動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨がやむと、鼓動がだんだん晴れてきた。", "explanation": "〈空〉の意味。空は晴れるが、鼓動は晴れたり曇ったりしない。"}, {"text": "春になると、鼓動が一斉に咲いた。", "explanation": "〈桜〉の意味。桜は一斉に咲くが、鼓動は花のように咲くものではない。"}, {"text": "風が吹いて、鼓動が乾いた。", "explanation": "〈洗濯物〉の意味。洗濯物は乾くが、鼓動は乾いたり濡れたりしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52906, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合の後、胸に手を当てると鼓動を速かった。", "corrected_sentence": "試合の後、胸に手を当てると鼓動が速かった。", "error_description": "『速い』は主語に『が』を取る形容詞。『鼓動を』の『を』は誤りで、『鼓動が速かった』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52906, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験の前、鼓動が激しく割れた。", "corrected_sentence": "試験の前、鼓動が激しく打った。", "error_description": "『割れた』は『打った』の誤り。鼓動は『激しく打つ』と言い、ガラスのように割れるものではない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52907, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鋭い", "is_correct": true, "explanation": "音が澄んで鋭く響く様子を表し、鈍い音と対になる対義語。"}, {"text": "温かい", "is_correct": false, "explanation": "温度の形容で、鈍いの対義語ではない。"}, {"text": "明るい", "is_correct": false, "explanation": "光の明るさを表し、鈍いの対義語ではない。"}, {"text": "丸い", "is_correct": false, "explanation": "形の形容で、鈍いの対義語ではない。"}], "correct_answer": "鋭い", "explanations": {"鋭い": "音が澄んで鋭く響く様子を表し、鈍い音と対になる対義語。", "温かい": "温度の形容で、鈍いの対義語ではない。", "明るい": "光の明るさを表し、鈍いの対義語ではない。", "丸い": "形の形容で、鈍いの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52907, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鋭い", "is_correct": true, "explanation": "音が澄んで鋭く響く様子を表し、鈍い音と対になる対義語。"}, {"text": "狭い", "is_correct": false, "explanation": "広さを表す形容詞で、鈍いの対義語ではない。"}, {"text": "浅い", "is_correct": false, "explanation": "深さを表す形容詞で、鈍いの対義語にはならない。"}, {"text": "黒い", "is_correct": false, "explanation": "色の形容で、鈍いの対義語ではない。"}], "correct_answer": "鋭い", "explanations": {"鋭い": "音が澄んで鋭く響く様子を表し、鈍い音と対になる対義語。", "狭い": "広さを表す形容詞で、鈍いの対義語ではない。", "浅い": "深さを表す形容詞で、鈍いの対義語にはならない。", "黒い": "色の形容で、鈍いの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52907, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "音がはっきりしなくて、重くて低い感じのこと。", "primary_collocate": null, "pronunciation": "にぶい", "ipa": "ɲibɯi", "syllable_count": 3, "sentences": [{"text": "重い荷物を床に置くと、ドスンと鈍い音がした。", "target_word": "鈍い", "complexity_tier": "T2", "furigana": "重[おも]い荷物[にもつ]を床[ゆか]に置[お]くと、ドスンと鈍[にぶ]い音[おと]がした。", "sentence_source": "generated"}, {"text": "雷の鈍い音が、遠くの山のほうから聞こえてきた。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "雷[かみなり]の鈍[にぶ]い音[おと]が、遠[とお]くの山[やま]のほうから聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "雪の中では、足音さえ鈍く聞こえる。", "target_word": "鈍く", "complexity_tier": "T3", "furigana": "雪[ゆき]の中[なか]では、足音[あしおと]さえ鈍[にぶ]く聞[き]こえる。", "sentence_source": "generated"}, {"text": "木のドアをたたくと、鈍い音が廊下に響いた。", "target_word": "鈍い", "complexity_tier": "T2", "furigana": "木[き]のドアをたたくと、鈍[にぶ]い音[おと]が廊下[ろうか]に響[ひび]いた。", "sentence_source": "generated"}, {"text": "夜中に、壁の向こうから鈍い音が何度も聞こえて、目が覚めた。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "夜中[よなか]に、壁[かべ]の向[む]こうから鈍[にぶ]い音[おと]が何度[なんど]も聞[き]こえて、目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "この太鼓は皮がゆるんでいて、鈍い音しか出ません。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "この太鼓[たいこ]は皮[かわ]がゆるんでいて、鈍[にぶ]い音[おと]しか出[で]ません。", "sentence_source": "generated"}, {"text": "ひびの入ったコップは、たたくと鈍い音がして、澄んだ音は出ない。", "target_word": "鈍い", "complexity_tier": "T4", "furigana": "ひびの入[はい]ったコップは、たたくと鈍[にぶ]い音[おと]がして、澄[す]んだ音[おと]は出[で]ない。", "sentence_source": "generated"}, {"text": "倉庫の奥から、重い物が倒れる鈍い音が聞こえた。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "倉庫[そうこ]の奥[おく]から、重[おも]い物[もの]が倒[たお]れる鈍[にぶ]い音[おと]が聞[き]こえた。", "sentence_source": "generated"}, {"text": "ボールが体に当たる鈍い音がして、観客は思わず息をのんだ。", "target_word": "鈍い", "complexity_tier": "T4", "furigana": "ボールが体[からだ]に当[あ]たる鈍[にぶ]い音[おと]がして、観客[かんきゃく]は思[おも]わず息[いき]をのんだ。", "sentence_source": "generated"}, {"text": "工事現場から、機械が地面を打つ鈍い音が一日中続いている。", "target_word": "鈍い", "complexity_tier": "T4", "furigana": "工事現場[こうじげんば]から、機械[きかい]が地面[じめん]を打[う]つ鈍[にぶ]い音[おと]が一日中[いちにちじゅう]続[つづ]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈍く", "label": "連用形"}, {"form": "鈍かった", "label": "過去形"}, {"form": "鈍くない", "label": "否定形"}, {"form": "鈍ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "音が澄まず、重く低くこもって聞こえる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52907, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鈍い", "is_correct": true, "explanation": "重く低くこもった音を表し、ドスンという音の説明に合う。"}, {"text": "赤い", "is_correct": false, "explanation": "赤いは色の形容で、音には使わない。"}, {"text": "甘い", "is_correct": false, "explanation": "甘いは味の形容で、音を表さない。"}, {"text": "苦い", "is_correct": false, "explanation": "苦いは味の形容で、音には使わない。"}], "explanations": {"鈍い": "重く低くこもった音を表し、ドスンという音の説明に合う。", "赤い": "赤いは色の形容で、音には使わない。", "甘い": "甘いは味の形容で、音を表さない。", "苦い": "苦いは味の形容で、音には使わない。"}, "sentence_index": 0, "correct_answer": "鈍い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このジュースは鈍くておいしい。", "explanation": "〈甘い〉の意味。鈍いは味の甘さを表さない。"}, {"text": "この水は鈍くて、底まで見える。", "explanation": "〈透明〉の意味。鈍いは水の透き通り具合を表さない。"}, {"text": "この屋根は鈍くて、雪が積もりにくい。", "explanation": "〈高い〉の意味。鈍いは屋根の高さを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52907, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鈍い", "is_correct": true, "explanation": "澄まずこもった音を表し、澄んだ音と対比させる文に合う。"}, {"text": "青い", "is_correct": false, "explanation": "青いは色の形容で、音には使わない。"}, {"text": "酸っぱい", "is_correct": false, "explanation": "酸っぱいは味の形容で、音を表さない。"}, {"text": "四角い", "is_correct": false, "explanation": "四角いは形の形容で、音には使えない。"}], "explanations": {"鈍い": "澄まずこもった音を表し、澄んだ音と対比させる文に合う。", "青い": "青いは色の形容で、音には使わない。", "酸っぱい": "酸っぱいは味の形容で、音を表さない。", "四角い": "四角いは形の形容で、音には使えない。"}, "sentence_index": 6, "correct_answer": "鈍い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真冬の空気は鈍くて、息が白くなる。", "explanation": "〈冷たい〉の意味。鈍いは温度や肌で感じる冷たさを表さない。"}, {"text": "このパンは鈍くて食べやすい。", "explanation": "〈柔らかい〉の意味。鈍いは噛んだときの柔らかさを表さない。"}, {"text": "ストーブが鈍くて、部屋がすぐ暖まる。", "explanation": "〈熱い〉の意味。鈍いはストーブの温度の高さを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52907, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い箱を床に置くと、ドスンと鈍いくない音がした。", "corrected_sentence": "重い箱を床に置くと、ドスンと鈍い音がした。", "error_description": "『鈍い』に『くない』を重ねるのは誤りで、名詞を修飾するのは『鈍い音』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "鈍い", "is_correct": true, "explanation": "基本形で、名詞『音』を直接修飾する形。"}, {"text": "鈍く", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。"}, {"text": "鈍くて", "is_correct": false, "explanation": "て形なので、名詞『音』を直接修飾できない。"}, {"text": "鈍ければ", "is_correct": false, "explanation": "仮定形で、音が鈍いという事実を仮定に変えてしまう。"}], "correct_form": "鈍い", "base_form": "鈍い", "form_label": "基本形", "sentence_index": 1, "explanations": {"鈍い": "基本形で、名詞『音』を直接修飾する形。", "鈍く": "連用形で、名詞を直接修飾できない。", "鈍くて": "て形なので、名詞『音』を直接修飾できない。", "鈍ければ": "仮定形で、音が鈍いという事実を仮定に変えてしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52907, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地下室の扉を閉めると、鈍くな音が聞こえた。", "corrected_sentence": "地下室の扉を閉めると、鈍い音が聞こえた。", "error_description": "『鈍い』は形容詞で、名詞『音』の前では基本形『鈍い』を使う。『鈍くな』は活用の誤りで、『鈍い音』が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "鈍い", "is_correct": true, "explanation": "基本形で、名詞『音』を直接修飾する形。"}, {"text": "鈍さ", "is_correct": false, "explanation": "名詞形で、名詞『音』を直接修飾できない。"}, {"text": "鈍かろう", "is_correct": false, "explanation": "推量形で、名詞『音』を直接修飾できない。"}, {"text": "鈍そう", "is_correct": false, "explanation": "様子を表す形で、音を直接修飾する形にならない。"}], "correct_form": "鈍い", "base_form": "鈍い", "form_label": "基本形", "sentence_index": 7, "explanations": {"鈍い": "基本形で、名詞『音』を直接修飾する形。", "鈍さ": "名詞形で、名詞『音』を直接修飾できない。", "鈍かろう": "推量形で、名詞『音』を直接修飾できない。", "鈍そう": "様子を表す形で、音を直接修飾する形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52908, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鋭い", "is_correct": true, "explanation": "〈鈍い〉の対義語。勘や感覚の鋭さを表し、「勘が鈍い」の反対になる。"}, {"text": "赤い", "is_correct": false, "explanation": "色の形容詞で、感覚の鋭さとは関係がなく、〈鈍い〉の対義語ではない。"}, {"text": "甘い", "is_correct": false, "explanation": "味や考えの甘さを表す語で、〈鈍い〉の対義語として辞書には載らない。"}, {"text": "短い", "is_correct": false, "explanation": "長さを表す語で、感覚や頭の働きの対義語ではない。"}], "correct_answer": "鋭い", "explanations": {"鋭い": "〈鈍い〉の対義語。勘や感覚の鋭さを表し、「勘が鈍い」の反対になる。", "赤い": "色の形容詞で、感覚の鋭さとは関係がなく、〈鈍い〉の対義語ではない。", "甘い": "味や考えの甘さを表す語で、〈鈍い〉の対義語として辞書には載らない。", "短い": "長さを表す語で、感覚や頭の働きの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52908, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鋭い", "is_correct": true, "explanation": "〈鈍い〉の対義語。鋭い音は澄んで鋭く響く音で、こもった鈍い音の反対になる。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す語で、音の響きの対義語ではない。"}, {"text": "濃い", "is_correct": false, "explanation": "色や味の濃さを表す語で、〈鈍い〉の対義語ではない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "柔らかさを表す語で、音や感覚の対義語として辞書には載らない。"}], "correct_answer": "鋭い", "explanations": {"鋭い": "〈鈍い〉の対義語。鋭い音は澄んで鋭く響く音で、こもった鈍い音の反対になる。", "細い": "太さを表す語で、音の響きの対義語ではない。", "濃い": "色や味の濃さを表す語で、〈鈍い〉の対義語ではない。", "柔らかい": "柔らかさを表す語で、音や感覚の対義語として辞書には載らない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52908, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "（音などが）澄んでおらず、こもった感じで、重く響く様子。また、刃物の切れ味が悪いことや、頭の回転が遅いことなどにも使う。", "primary_collocate": null, "pronunciation": "にぶい", "ipa": "nibɯi", "syllable_count": 3, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "鈍い", "complexity_tier": "T5", "furigana": "靴紐(くつひも)を固(かた)く結(むす)び、踵(かかと)で床(ゆか)を鳴(な)らせば、鈍(にぶ)い音(おと)が魂(たましい)の鼓動(こどう)と共鳴(きょうめい)する。", "sentence_source": "mined"}, {"text": "包丁が鈍いので、トマトがうまく切れず、つぶれてしまった。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "包丁(ほうちょう)が鈍(にぶ)いので、トマトがうまく切(き)れず、つぶれてしまった。", "sentence_source": "generated"}, {"text": "遠くの空から、雷の鈍い音が低く響いてきた。", "target_word": "鈍い", "complexity_tier": "T4", "furigana": "遠(とお)くの空(そら)から、雷(かみなり)の鈍(にぶ)い音(おと)が低(ひく)く響(ひび)いてきた。", "sentence_source": "generated"}, {"text": "彼は勘が鈍いので、皆が怒っていることにも気づかなかった。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "彼(かれ)は勘(かん)が鈍(にぶ)いので、皆(みな)が怒(おこ)っていることにも気(き)づかなかった。", "sentence_source": "generated"}, {"text": "寝不足の朝は頭の働きが鈍く、簡単な計算も間違えてしまう。", "target_word": "鈍く", "complexity_tier": "T3", "furigana": "寝不足(ねぶそく)の朝(あさ)は頭(あたま)の働(はたら)きが鈍(にぶ)く、簡単(かんたん)な計算(けいさん)も間違(まちが)えてしまう。", "sentence_source": "generated"}, {"text": "錆びたはさみは切れ味が鈍く、紙がぎざぎざに切れた。", "target_word": "鈍く", "complexity_tier": "T4", "furigana": "錆(さ)びたはさみは切(き)れ味(あじ)が鈍(にぶ)く、紙(かみ)がぎざぎざに切(き)れた。", "sentence_source": "generated"}, {"text": "鐘の音は雪に包まれたように鈍く、遠くまで届かなかった。", "target_word": "鈍く", "complexity_tier": "T4", "furigana": "鐘(かね)の音(おと)は雪(ゆき)に包(つつ)まれたように鈍(にぶ)く、遠(とお)くまで届(とど)かなかった。", "sentence_source": "generated"}, {"text": "動きが鈍い犬は、ボールをなかなか捕まえられなかった。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "動(うご)きが鈍(にぶ)い犬(いぬ)は、ボールをなかなか捕(つか)まえられなかった。", "sentence_source": "generated"}, {"text": "彼女は人の気持ちに鈍いと言われるのを気にしている。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は人(ひと)の気持(きも)ちに鈍(にぶ)いと言(い)われるのを気(き)にしている。", "sentence_source": "generated"}, {"text": "木の扉をたたくと、中が詰まっているような鈍い音がした。", "target_word": "鈍い", "complexity_tier": "T3", "furigana": "木(き)の扉(とびら)をたたくと、中(なか)が詰(つ)まっているような鈍(にぶ)い音(おと)がした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈍い", "label": "基本形"}, {"form": "鈍く", "label": "連用形"}, {"form": "鈍くない", "label": "否定形"}, {"form": "鈍かった", "label": "過去形"}, {"form": "鈍ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "音がこもる・切れ味が悪い・反応や頭の働きが遅いことを表す形容詞(にぶい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52908, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鈍い", "is_correct": true, "explanation": "基本形の連体形で、「鈍い音」としてこもって重く響く音を表し、文の描写に合う。"}, {"text": "赤い", "is_correct": false, "explanation": "色を表す形容詞で、音の響きは表せない。「赤い音が魂の鼓動と共鳴する」は意味をなさない。"}, {"text": "苦い", "is_correct": false, "explanation": "味を表す形容詞で、音には使わない。靴紐と床を鳴らす音の描写に合わない。"}, {"text": "寒い", "is_correct": false, "explanation": "温度の形容詞で、音の響きを表せない。「寒い音」は文の描写に合わない。"}], "explanations": {"鈍い": "基本形の連体形で、「鈍い音」としてこもって重く響く音を表し、文の描写に合う。", "赤い": "色を表す形容詞で、音の響きは表せない。「赤い音が魂の鼓動と共鳴する」は意味をなさない。", "苦い": "味を表す形容詞で、音には使わない。靴紐と床を鳴らす音の描写に合わない。", "寒い": "温度の形容詞で、音の響きを表せない。「寒い音」は文の描写に合わない。"}, "sentence_index": 0, "correct_answer": "鈍い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生の鈍い指摘で、生徒たちは答えに詰まった。", "explanation": "ここは〈鋭い〉の場面。的確さを言う指摘には鋭いを使い、鈍いは切れ味や反応の遅さを表すので合わない。"}, {"text": "電車が鈍くて、会議に間に合わなかった。", "explanation": "ここは〈遅い〉の場面。乗り物の速さには鈍いではなく遅いを使うので、この言葉はこうは使わない。"}, {"text": "その荷物は鈍くて、一人では持ち上げられなかった。", "explanation": "ここは〈重い〉の場面。重さには鈍いを使わず重いを使う。音のこもりの意味と取り違えやすい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52908, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鈍く", "is_correct": true, "explanation": "連用形。「鈍く、遠くまで届かなかった」と音のこもる様子を述べ、雪に包まれた描写に合う。"}, {"text": "大きく", "is_correct": false, "explanation": "大きい音なら遠くまで届くはずで、雪に包まれた描写や「届かなかった」と矛盾する。"}, {"text": "鋭く", "is_correct": false, "explanation": "鋭い音は雪に包まれた描写と反対で、「届かなかった」とも噛み合わない。"}, {"text": "軽く", "is_correct": false, "explanation": "軽い音の描写は「雪に包まれたように」と噛み合わず、届かなかった理由にもならない。"}], "explanations": {"鈍く": "連用形。「鈍く、遠くまで届かなかった」と音のこもる様子を述べ、雪に包まれた描写に合う。", "大きく": "大きい音なら遠くまで届くはずで、雪に包まれた描写や「届かなかった」と矛盾する。", "鋭く": "鋭い音は雪に包まれた描写と反対で、「届かなかった」とも噛み合わない。", "軽く": "軽い音の描写は「雪に包まれたように」と噛み合わず、届かなかった理由にもならない。"}, "sentence_index": 6, "correct_answer": "鈍く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷たいお湯で体を洗う代わりに、鈍いお湯で体を洗った。", "explanation": "ここは〈ぬるい〉の場面。温度の状態には鈍いを使わず、ぬるいを使うので、この言葉はこうは使わない。"}, {"text": "この香水は香りが鈍くて、すぐに消えてしまった。", "explanation": "ここは〈弱い〉の場面。香りの強さを言うには弱いや薄いを使い、鈍いは音の響きや切れ味、反応の遅さを表すので合わない。"}, {"text": "夜の冷え込みが鈍くて、コートはいらなかった。", "explanation": "ここは〈緩い〉の場面。冷え込みの弱さには緩いや穏やかを使い、鈍いは音の響きや切れ味、動きの遅さを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52908, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その包丁は鈍いて、野菜がうまく切れなかった。", "corrected_sentence": "その包丁は鈍くて、野菜がうまく切れなかった。", "error_description": "誤りは「鈍いて」。形容詞は語幹に「く」を付けた連用形「鈍く」から「て」で続けるので、正しくは「鈍くて」。「鈍い」の「い」を「く」に変える。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "鈍い", "is_correct": true, "explanation": "基本形。「鈍いので」の形で、理由を述べる文の述語として直接続く形。"}, {"text": "鈍く", "is_correct": false, "explanation": "連用形。「ので」には続かず、「鈍く〜なる」や「鈍くて」などの形で使う。"}, {"text": "鈍くて", "is_correct": false, "explanation": "て形で原因を表すため、「ので」と並べると理由が二重になり不自然。"}, {"text": "鈍ければ", "is_correct": false, "explanation": "仮定形で条件を表す。理由を述べる「ので」とは合わない。"}], "correct_form": "鈍い", "base_form": "鈍い", "form_label": "基本形", "sentence_index": 1, "explanations": {"鈍い": "基本形。「鈍いので」の形で、理由を述べる文の述語として直接続く形。", "鈍く": "連用形。「ので」には続かず、「鈍く〜なる」や「鈍くて」などの形で使う。", "鈍くて": "て形で原因を表すため、「ので」と並べると理由が二重になり不自然。", "鈍ければ": "仮定形で条件を表す。理由を述べる「ので」とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52908, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業が遅れたのは、彼の判断が鈍いかったからだ。", "corrected_sentence": "作業が遅れたのは、彼の判断が鈍かったからだ。", "error_description": "誤りは「鈍いかった」。形容詞の過去形は語幹に「かった」を付けて「鈍かった」になるので、「い」を残すのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "鈍い", "is_correct": true, "explanation": "基本形。「動きが鈍い犬」と、いつもの性質を連体修飾で表す形。"}, {"text": "鈍さ", "is_correct": false, "explanation": "名詞。「動きの鈍さ」とは言えても、「動きが鈍さ犬は」では名詞を修飾できず、文が成り立たない。"}, {"text": "鈍そう", "is_correct": false, "explanation": "様態の形。「鈍そうな犬」と「な」が要り、「動きが鈍そう犬は」では文が成り立たない。"}, {"text": "鈍かろう", "is_correct": false, "explanation": "推量の形で「〜だろう」の意味になり、名詞を修飾して文を成り立たせられない。"}], "correct_form": "鈍い", "base_form": "鈍い", "form_label": "基本形", "sentence_index": 7, "explanations": {"鈍い": "基本形。「動きが鈍い犬」と、いつもの性質を連体修飾で表す形。", "鈍さ": "名詞。「動きの鈍さ」とは言えても、「動きが鈍さ犬は」では名詞を修飾できず、文が成り立たない。", "鈍そう": "様態の形。「鈍そうな犬」と「な」が要り、「動きが鈍そう犬は」では文が成り立たない。", "鈍かろう": "推量の形で「〜だろう」の意味になり、名詞を修飾して文を成り立たせられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52909, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「座る」の着地点（場所）を示す。床の上に座る。"}, {"text": "を", "is_correct": false, "explanation": "「座る」は目的語を取らない動作なので、「を」は合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「床から座る」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、場所を示す必要がある文では「床と座る」は合わない。"}], "correct_answer": "に", "explanations": {"に": "「座る」の着地点（場所）を示す。床の上に座る。", "を": "「座る」は目的語を取らない動作なので、「を」は合わない。", "から": "起点を示すが、「床から座る」は意味が通らない。", "と": "並列や相手を示すが、場所を示す必要がある文では「床と座る」は合わない。"}, "error_tags": {"を": "目的語", "から": "起点", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52909, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「しく」の置き場所を示す。床の上にマットを敷く。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「床よりマットをしいて」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「床へマットをしく」は置く場所の意味に合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「床がマットをしく」は主語が逆になり文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「しく」の置き場所を示す。床の上にマットを敷く。", "より": "比較を示すが、「床よりマットをしいて」は文が成り立たない。", "へ": "方向を示すが、「床へマットをしく」は置く場所の意味に合わない。", "が": "主語を示すが、「床がマットをしく」は主語が逆になり文が成り立たない。"}, "error_tags": {"より": "比較", "へ": "方向", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52909, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゆか。へやのしたにある、たいらなところ。", "primary_collocate": null, "pronunciation": "ゆか", "ipa": "jɯka", "syllable_count": 2, "sentences": [{"text": "床にごみが落ちています。", "target_word": "床", "complexity_tier": "T2", "furigana": "床[ゆか]にごみが落[お]ちています。", "sentence_source": "generated"}, {"text": "子どもたちは床に座って絵本を読んでいる。", "target_word": "床", "complexity_tier": "T2", "furigana": "子[こ]どもたちは床[ゆか]に座[すわ]って絵本[えほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "床がぬれているから、気をつけてね。", "target_word": "床", "complexity_tier": "T2", "furigana": "床[ゆか]がぬれているから、気[き]をつけてね。", "sentence_source": "generated"}, {"text": "猫が床の上で寝ています。", "target_word": "床", "complexity_tier": "T2", "furigana": "猫[ねこ]が床[ゆか]の上[うえ]で寝[ね]ています。", "sentence_source": "generated"}, {"text": "部屋の床を毎日そうじします。", "target_word": "床", "complexity_tier": "T2", "furigana": "部屋[へや]の床[ゆか]を毎日[まいにち]そうじします。", "sentence_source": "generated"}, {"text": "床に落ちたペンを拾った。", "target_word": "床", "complexity_tier": "T2", "furigana": "床[ゆか]に落[お]ちたペンを拾[ひろ]った。", "sentence_source": "generated"}, {"text": "この部屋は床が冷たいので、スリッパをはきます。", "target_word": "床", "complexity_tier": "T3", "furigana": "この部屋[へや]は床[ゆか]が冷[つめ]たいので、スリッパをはきます。", "sentence_source": "generated"}, {"text": "床にマットをしいて、ヨガをした。", "target_word": "床", "complexity_tier": "T2", "furigana": "床[ゆか]にマットをしいて、ヨガをした。", "sentence_source": "generated"}, {"text": "ボールが床をころころ転がって、机の下に入った。", "target_word": "床", "complexity_tier": "T3", "furigana": "ボールが床[ゆか]をころころ転[ころ]がって、机[つくえ]の下[した]に入[はい]った。", "sentence_source": "generated"}, {"text": "床が白いので、汚れがよく目立つ。", "target_word": "床", "complexity_tier": "T3", "furigana": "床[ゆか]が白[しろ]いので、汚[よご]れがよく目立[めだ]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "床", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "へやの下にある、人が立ったり物を置いたりする平らな面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52909, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "床", "is_correct": true, "explanation": "ごみが落ちている場所として、へやの床が合う。"}, {"text": "光", "is_correct": false, "explanation": "光は物ではないので、ごみが落ちる場所にならない。"}, {"text": "音", "is_correct": false, "explanation": "音は落ちた物を受け止める場所にならず、文が成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "色はごみが落ちる場所にならず、文の意味に合わない。"}], "explanations": {"床": "ごみが落ちている場所として、へやの床が合う。", "光": "光は物ではないので、ごみが落ちる場所にならない。", "音": "音は落ちた物を受け止める場所にならず、文が成り立たない。", "色": "色はごみが落ちる場所にならず、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "浜辺で、子どもが床を掘って遊んだ。", "explanation": "ここは〈砂〉の意味（浜の砂）。床は室内のゆかで、浜辺で掘る砂の代わりにはならない。"}, {"text": "畑の床を耕して、麦をまいた。", "explanation": "ここは〈土〉の意味。畑は屋外の土を耕すもので、室内の〈床〉とは言わない。"}, {"text": "床に苗を植えて、庭を彩った。", "explanation": "ここは〈花壇〉の意味（苗を植える区画）。床は室内のゆかで、苗を植える場所にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52909, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "床", "is_correct": true, "explanation": "冷たくなるのは床で、スリッパが必要という文脈に合う。"}, {"text": "花", "is_correct": false, "explanation": "花は冷たくならず、スリッパの話とつながらない。"}, {"text": "声", "is_correct": false, "explanation": "「冷たい声」とは言えるが、この文は部屋と床の冷たさを述べており合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は冷たくなるものではなく、文が成り立たない。"}], "explanations": {"床": "冷たくなるのは床で、スリッパが必要という文脈に合う。", "花": "花は冷たくならず、スリッパの話とつながらない。", "声": "「冷たい声」とは言えるが、この文は部屋と床の冷たさを述べており合わない。", "味": "味は冷たくなるものではなく、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕焼けの床に、鳥が飛んでいた。", "explanation": "ここは〈空〉の意味（頭上に広がる空間）。床は室内のゆかで、鳥が飛ぶ場所にはならない。"}, {"text": "散髪は、いつもの床で頼んでいる。", "explanation": "ここは〈床屋〉の意味。「床」だけでは散髪の店を指さないので合わない。"}, {"text": "富士山の床が雪で白くなっている。", "explanation": "ここは〈山頂〉の意味（山の一番上）。床は室内のゆかで、山の頂上を指すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52909, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが床を上で跳ねている。", "corrected_sentence": "子どもが床の上で跳ねている。", "error_description": "正しくは「の」。「床の上」と場所を言うときは「の」を使う。「を」を付けると目的語になり、「床を上で」は文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52909, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床をマットをしいたら、足が痛くない。", "corrected_sentence": "床にマットをしいたら、足が痛くない。", "error_description": "正しくは「に」。「しく」は物を置く場所（床）を「に」で示す。「を」を付けると「床を」と「マットを」が重なり、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
