INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52911, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「進む」の主語、つまり変化の主体を示す。退廃が進む。"}, {"text": "を", "is_correct": false, "explanation": "「進む」は目的語を取らない動詞なので、「退廃を進む」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "方向を示すが、「退廃に進んで」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「退廃と進んで」では主語の役割を果たせず合わない。"}], "correct_answer": "が", "explanations": {"が": "「進む」の主語、つまり変化の主体を示す。退廃が進む。", "を": "「進む」は目的語を取らない動詞なので、「退廃を進む」は成り立たない。", "に": "方向を示すが、「退廃に進んで」は意味が通らない。", "と": "並列や相手を示すが、「退廃と進んで」では主語の役割を果たせず合わない。"}, "error_tags": {"を": "目的語", "に": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52911, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "元気がなくて、だんだん悪くなること。", "primary_collocate": null, "pronunciation": "たいはい", "ipa": "taihai", "syllable_count": 4, "sentences": [{"text": "町の商店街は人が減り、退廃が進んでいる。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "町[まち]の商店街[しょうてんがい]は人[ひと]が減[へ]り、退廃[たいはい]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "長い戦争のせいで、国の文化は退廃してしまった。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "長[なが]い戦争[せんそう]のせいで、国[くに]の文化[ぶんか]は退廃[たいはい]してしまった。", "sentence_source": "generated"}, {"text": "心の退廃を防ぐには、規則正しい生活が大切だ。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "心[こころ]の退廃[たいはい]を防[ふせ]ぐには、規則正[きそくただ]しい生活[せいかつ]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "指導者が怠けると、組織の退廃が始まる。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "指導者[しどうしゃ]が怠[なま]けると、組織[そしき]の退廃[たいはい]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "退廃した町を、住民たちが力を合わせて立て直した。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "退廃[たいはい]した町[まち]を、住民[じゅうみん]たちが力[ちから]を合[あ]わせて立[た]て直[なお]した。", "sentence_source": "generated"}, {"text": "学校の退廃を心配した先生が、生徒と話し合いをした。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "学校[がっこう]の退廃[たいはい]を心配[しんぱい]した先生[せんせい]が、生徒[せいと]と話[はな]し合[あ]いをした。", "sentence_source": "generated"}, {"text": "彼は仕事を失ってから、生活の退廃が目立つようになった。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "彼[かれ]は仕事[しごと]を失[うしな]ってから、生活[せいかつ]の退廃[たいはい]が目立[めだ]つようになった。", "sentence_source": "generated"}, {"text": "昔は栄えた港も、今では退廃が進んで人影がない。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "昔[むかし]は栄[さか]えた港[みなと]も、今[いま]では退廃[たいはい]が進[すす]んで人影[ひとかげ]がない。", "sentence_source": "generated"}, {"text": "道徳の退廃を嘆く声が、新聞の投書欄に増えている。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "道徳[どうとく]の退廃[たいはい]を嘆[なげ]く声[こえ]が、新聞[しんぶん]の投書欄[とうしょらん]に増[ふ]えている。", "sentence_source": "generated"}, {"text": "退廃を止めるには、まず一人ひとりが責任を持つことだ。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "退廃[たいはい]を止[と]めるには、まず一人[ひとり]ひとりが責任[せきにん]を持[も]つことだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "退廃する", "label": "サ変動詞"}, {"form": "退廃した", "label": "過去形"}, {"form": "退廃的", "label": "形状詞（派生）"}], "register": "formal", "sense_fingerprint": "活気や秩序が失われ、少しずつ悪い状態へ衰えていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52911, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退廃", "is_correct": true, "explanation": "活力が失われて悪くなっていく状態を表し、人が減っていく文脈に合う。"}, {"text": "繁栄", "is_correct": false, "explanation": "栄えることを表し、人が減って悪くなる文脈と逆で合わない。"}, {"text": "混雑", "is_correct": false, "explanation": "人が多く集まる状態を表し、人が減るという文の流れと矛盾する。"}, {"text": "活気", "is_correct": false, "explanation": "元気な勢いを表すが、「活気が進んでいる」は悪くなる流れと合わない。"}], "explanations": {"退廃": "活力が失われて悪くなっていく状態を表し、人が減っていく文脈に合う。", "繁栄": "栄えることを表し、人が減って悪くなる文脈と逆で合わない。", "混雑": "人が多く集まる状態を表し、人が減るという文の流れと矛盾する。", "活気": "元気な勢いを表すが、「活気が進んでいる」は悪くなる流れと合わない。"}, "sentence_index": 0, "correct_answer": "退廃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "定年になり、彼は会社を退廃した。", "explanation": "ここは〈退職〉の意味（会社を辞める）。退廃は衰えや堕落の意味で、辞める行為には使わない。"}, {"text": "観客は、途中で退廃して席を立った。", "explanation": "ここは〈退席〉の意味（その場を離れる）。退廃は衰えや堕落の意味で、席を立つ行動には使わない。"}, {"text": "侵入者を退廃させた。", "explanation": "ここは〈撃退〉の意味（追い払う）。退廃は堕落の意味で、敵を追い払う文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52911, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退廃", "is_correct": true, "explanation": "悪い方へ衰えていく状態を表し、仕事を失ってから生活が崩れていく文脈に合う。"}, {"text": "余裕", "is_correct": false, "explanation": "心身や生活にゆとりがあることを表し、仕事を失った文脈と合わない。"}, {"text": "豊かさ", "is_correct": false, "explanation": "満ち足りた状態を表し、「仕事を失ってから」の流れと矛盾する。"}, {"text": "充実", "is_correct": false, "explanation": "満たされて生き生きしている状態を表し、悪くなる文脈には合わない。"}], "explanations": {"退廃": "悪い方へ衰えていく状態を表し、仕事を失ってから生活が崩れていく文脈に合う。", "余裕": "心身や生活にゆとりがあることを表し、仕事を失った文脈と合わない。", "豊かさ": "満ち足りた状態を表し、「仕事を失ってから」の流れと矛盾する。", "充実": "満たされて生き生きしている状態を表し、悪くなる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "退廃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議があまりに退廃で、みんなあくびをしていた。", "explanation": "ここは〈退屈〉の意味（つまらない様子）。退廃は堕落や衰えの意味で、この文には合わない。"}, {"text": "一行は山道で退廃し、宿に引き返した。", "explanation": "ここは〈退却〉の意味（後ろへ引き返す）。退廃は衰えや堕落の意味で、退いて引き返す行動には使わない。"}, {"text": "彼は困難に直面し、すぐに仕事を退廃してしまった。", "explanation": "ここは〈放棄〉の意味（途中で投げ出す）。退廃は堕落の意味で、仕事を投げ出す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52911, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ルールが守られなくなり、クラブの退廃を進んだ。", "corrected_sentence": "ルールが守られなくなり、クラブの退廃が進んだ。", "error_description": "正しくは「が」。「進む」は自動詞なので、変化の主体を「が」で示す。「を」は目的語用で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52911, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の退廃を目立つようになった。", "corrected_sentence": "町の退廃が目立つようになった。", "error_description": "正しくは「が」。「目立つ」は自動詞なので、主語を「が」で示す。「を」は目的語用で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52912, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52912, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「退廃の象徴」の連体修飾。退廃を表すものという関係を示す。"}, {"text": "で", "is_correct": false, "explanation": "「退廃で象徴だ」は手段や場所の意味になり、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「退廃から象徴だ」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「退廃より象徴だと批判」は意味が合わない。"}], "correct_answer": "の", "explanations": {"の": "「退廃の象徴」の連体修飾。退廃を表すものという関係を示す。", "で": "「退廃で象徴だ」は手段や場所の意味になり、文が成り立たない。", "から": "起点を示すが、「退廃から象徴だ」は意味が通らない。", "より": "比較を示すが、「退廃より象徴だと批判」は意味が合わない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52912, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や文化の活力が失われ、堕落した状態。また、そうした状態に感じられる、衰えた中の美しさ。", "primary_collocate": null, "pronunciation": "たいはい", "ipa": "taihai", "syllable_count": 4, "sentences": [{"text": "その絵には、退廃の美しさが静かに漂っていた。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "その絵[え]には、退廃[たいはい]の美[うつく]しさが静[しず]かに漂[ただよ]っていた。", "sentence_source": "generated"}, {"text": "戦後の街には退廃の空気が漂い、人々は夜ごと酒場に集まった。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "戦後[せんご]の街[まち]には退廃[たいはい]の空気[くうき]が漂[ただよ]い、人々[ひとびと]は夜[よ]ごと酒場[さかば]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "その小説は、貴族社会の退廃を美しい文章で描いている。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "その小説[しょうせつ]は、貴族社会[きぞくしゃかい]の退廃[たいはい]を美[うつく]しい文章[ぶんしょう]で描[えが]いている。", "sentence_source": "generated"}, {"text": "退廃した都市の風景に、彼は不思議な魅力を感じた。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "退廃[たいはい]した都市[とし]の風景[ふうけい]に、彼[かれ]は不思議[ふしぎ]な魅力[みりょく]を感[かん]じた。", "sentence_source": "generated"}, {"text": "世紀末の芸術には、退廃の美を好む傾向があった。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "世紀末[せいきまつ]の芸術[げいじゅつ]には、退廃[たいはい]の美[び]を好[この]む傾向[けいこう]があった。", "sentence_source": "generated"}, {"text": "この映画は、退廃した世界で生きる若者たちの姿を描いている。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "この映画[えいが]は、退廃[たいはい]した世界[せかい]で生[い]きる若者[わかもの]たちの姿[すがた]を描[えが]いている。", "sentence_source": "generated"}, {"text": "廃墟のような古いホテルには、退廃の美しさがあった。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "廃墟[はいきょ]のような古[ふる]いホテルには、退廃[たいはい]の美[うつく]しさがあった。", "sentence_source": "generated"}, {"text": "評論家は、豪華だが空虚なパーティーを退廃の象徴だと批判した。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "評論家[ひょうろんか]は、豪華[ごうか]だが空虚[くうきょ]なパーティーを退廃[たいはい]の象徴[しょうちょう]だと批判[ひはん]した。", "sentence_source": "generated"}, {"text": "王朝の末期には政治の退廃が進み、民衆の不満が高まった。", "target_word": "退廃", "complexity_tier": "T4", "furigana": "王朝[おうちょう]の末期[まっき]には政治[せいじ]の退廃[たいはい]が進[すす]み、民衆[みんしゅう]の不満[ふまん]が高[たか]まった。", "sentence_source": "generated"}, {"text": "彼女の歌には、退廃の美しさと優しさが同居している。", "target_word": "退廃", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌[うた]には、退廃[たいはい]の美[うつく]しさと優[やさ]しさが同居[どうきょ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "退廃的", "label": "形状詞（派生）"}, {"form": "退廃する", "label": "サ変動詞"}], "register": "formal", "sense_fingerprint": "社会・文化の活力が衰えて堕落した状態、またその頽廃的な美", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e525fbb-df41-47a6-baf1-6b045386055a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52912, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退廃", "is_correct": true, "explanation": "堕落や衰えの中にある美しさを表し、「退廃の美しさ」として文の内容に合う。"}, {"text": "凶暴", "is_correct": false, "explanation": "荒々しく乱暴な様子を表し、退廃の美しさの文脈には合わない。"}, {"text": "陳腐", "is_correct": false, "explanation": "ありふれて古臭いことを表し、「美しさ」を修飾する意味として合わない。"}, {"text": "残虐", "is_correct": false, "explanation": "むごいことを表し、「退廃の美しさ」という語としては合わない。"}], "explanations": {"退廃": "堕落や衰えの中にある美しさを表し、「退廃の美しさ」として文の内容に合う。", "凶暴": "荒々しく乱暴な様子を表し、退廃の美しさの文脈には合わない。", "陳腐": "ありふれて古臭いことを表し、「美しさ」を修飾する意味として合わない。", "残虐": "むごいことを表し、「退廃の美しさ」という語としては合わない。"}, "sentence_index": 0, "correct_answer": "退廃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "危険を感じた住民は、町から退廃した。", "explanation": "ここは〈退避〉の意味（危険から離れて逃れる）。退廃は堕落や活力の喪失を指すので合わない。"}, {"text": "日に当たって、カーテンの色が退廃した。", "explanation": "ここは〈退色〉の意味（色があせる）。退廃は社会や文化の堕落の意味で、布の色あせには使わない。"}, {"text": "進化の過程で、この器官は退廃した。", "explanation": "ここは〈退化〉の意味（生物の器官が衰える）。退廃は社会や文化の堕落に使うので、器官には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52912, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退廃", "is_correct": true, "explanation": "堕落や衰えの中にある美しさを表し、「退廃の美しさがあった」と廃墟の文脈に合う。"}, {"text": "無垢", "is_correct": false, "explanation": "汚れのない純真さを表し、廃墟のような古いホテルの文脈と合わない。"}, {"text": "雄大", "is_correct": false, "explanation": "規模が大きく堂々とした様子を表し、廃墟の文脈では意味が合わない。"}, {"text": "清楚", "is_correct": false, "explanation": "清らかで控えめな様子を表し、廃墟の美しさを表す語としては合わない。"}], "explanations": {"退廃": "堕落や衰えの中にある美しさを表し、「退廃の美しさがあった」と廃墟の文脈に合う。", "無垢": "汚れのない純真さを表し、廃墟のような古いホテルの文脈と合わない。", "雄大": "規模が大きく堂々とした様子を表し、廃墟の文脈では意味が合わない。", "清楚": "清らかで控えめな様子を表し、廃墟の美しさを表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "退廃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は五時に退廃した。", "explanation": "ここは〈退勤〉の意味（仕事を終えて職場を出る）。退廃は堕落や衰えの意味で、時刻に仕事を終える文には合わない。"}, {"text": "夏の食品が退廃した。", "explanation": "ここは〈腐敗〉の意味（食品が傷む）。退廃は社会や文化の堕落に使い、食品の傷みには使わない。"}, {"text": "満員電車で、彼女は一歩退廃して道を譲った。", "explanation": "ここは〈退く〉の意味（後ろへ下がる）。退廃は堕落の意味で、移動の「下がる」にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52912, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "戦後の混乱が続き、人々の退廃を深まった。", "corrected_sentence": "戦後の混乱が続き、人々の退廃が深まった。", "error_description": "正しくは「が」。「深まる」は自動詞で目的語を取らないので、主語を「が」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52912, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この作家の詩には、退廃へ憧れがにじんでいる。", "corrected_sentence": "この作家の詩には、退廃への憧れがにじんでいる。", "error_description": "正しくは「への」。「憧れ」の対象を示すには「への」が必要。「へ」だけでは「退廃へ憧れ」が不自然で、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde8f80-9d6b-4421-ad17-775afed25479') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52913, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「生き方に共鳴し」で、共鳴する相手を「に」で示す。ここは「に」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。共鳴は「生き方を共鳴する」とは言わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。共鳴の相手には使わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。共鳴の相手を示すには合わない。"}], "correct_answer": "に", "explanations": {"に": "「生き方に共鳴し」で、共鳴する相手を「に」で示す。ここは「に」。", "を": "「を」は目的語を示す。共鳴は「生き方を共鳴する」とは言わない。", "へ": "「へ」は方向を示す。共鳴の相手には使わない。", "から": "「から」は起点を示す。共鳴の相手を示すには合わない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52913, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「考えに共鳴した」で、共鳴する相手を「に」で示す。ここは「に」。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「考えで共鳴した」は共鳴の相手を示せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「考えより共鳴した」は共鳴の相手にならず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「考えの共鳴した」は述語にならず、文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "「考えに共鳴した」で、共鳴する相手を「に」で示す。ここは「に」。", "で": "「で」は手段や場所を示す。「考えで共鳴した」は共鳴の相手を示せず、文が成り立たない。", "より": "「より」は比較を示す。「考えより共鳴した」は共鳴の相手にならず、不自然。", "の": "「の」は名詞をつなぐ。「考えの共鳴した」は述語にならず、文が成立しない。"}, "error_tags": {"で": "手段・場所", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52913, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心が、同じように感じて動くこと。", "primary_collocate": null, "pronunciation": "きょうめい", "ipa": "kʲoːmeː", "syllable_count": 4, "sentences": [{"text": "彼の演説を聞いて、多くの若者が強い共鳴を感じた。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "彼[かれ]の演説[えんぜつ]を聞[き]いて、多[おお]くの若者[わかもの]が強[つよ]い共鳴[きょうめい]を感[かん]じた。", "sentence_source": "generated"}, {"text": "主人公の孤独な生き方に共鳴し、読者から手紙が殺到した。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "主人公[しゅじんこう]の孤独[こどく]な生[い]き方[かた]に共鳴[きょうめい]し、読者[どくしゃ]から手紙[てがみ]が殺到[さっとう]した。", "sentence_source": "generated"}, {"text": "同じ苦労を経験した者同士だから、彼女の話には深く共鳴できた。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "同[おな]じ苦労[くろう]を経験[けいけん]した者同士[ものどうし]だから、彼女[かのじょ]の話[はなし]には深[ふか]く共鳴[きょうめい]できた。", "sentence_source": "generated"}, {"text": "彼の意見には賛成できないが、根底にある思いには共鳴する。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]には賛成[さんせい]できないが、根底[こんてい]にある思[おも]いには共鳴[きょうめい]する。", "sentence_source": "generated"}, {"text": "映画のラストシーンに共鳴して、会場のあちこちで涙を流す人がいた。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "映画[えいが]のラストシーンに共鳴[きょうめい]して、会場[かいじょう]のあちこちで涙[なみだ]を流[なが]す人[ひと]がいた。", "sentence_source": "generated"}, {"text": "小さな市民運動だったが、各地で共鳴する人が現れ、参加者は一万人を超えた。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "小[ちい]さな市民[しみん]運動[うんどう]だったが、各地[かくち]で共鳴[きょうめい]する人[ひと]が現[あらわ]れ、参加者[さんかしゃ]は一万人[いちまんにん]を超[こ]えた。", "sentence_source": "generated"}, {"text": "歌詞に描かれた別れの痛みに共鳴し、私は思わず涙ぐんだ。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "歌詞[かし]に描[えが]かれた別[わか]れの痛[いた]みに共鳴[きょうめい]し、私[わたし]は思[おも]わず涙[なみだ]ぐんだ。", "sentence_source": "generated"}, {"text": "教授の考えに共鳴した学生たちが、自主的に勉強会を開いた。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]の考[かんが]えに共鳴[きょうめい]した学生[がくせい]たちが、自主的[じしゅてき]に勉強会[べんきょうかい]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "彼女の歌は聴く人の心に共鳴を生み、静かな感動が広がった。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌[うた]は聴[き]く人[ひと]の心[こころ]に共鳴[きょうめい]を生[う]み、静[しず]かな感動[かんどう]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "気持ちを分かち合える友人と出会い、お互いの夢に共鳴し合った。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "気持[きも]ちを分[わ]かち合[あ]える友人[ゆうじん]と出会[であ]い、お互[たが]いの夢[ゆめ]に共鳴[きょうめい]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共鳴", "label": "基本形"}, {"form": "共鳴する", "label": "する形"}, {"form": "共鳴した", "label": "た形"}, {"form": "共鳴して", "label": "て形"}, {"form": "共鳴しない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "共鳴：他人の考えや気持ちに触れて、自分の心も同じように動くこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52913, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共鳴", "is_correct": true, "explanation": "「強い共鳴を感じた」は、演説に心が強く同調したことを表す。文脈に合う。"}, {"text": "手順", "is_correct": false, "explanation": "「手順」は作業の順序で、「強い手順を感じた」は不自然。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢」は人の歳で、感じるものとして「強い年齢を感じた」は不自然。"}, {"text": "税率", "is_correct": false, "explanation": "「税率」は税金の割合で、「強い税率を感じた」は意味をなさない。"}], "explanations": {"共鳴": "「強い共鳴を感じた」は、演説に心が強く同調したことを表す。文脈に合う。", "手順": "「手順」は作業の順序で、「強い手順を感じた」は不自然。", "年齢": "「年齢」は人の歳で、感じるものとして「強い年齢を感じた」は不自然。", "税率": "「税率」は税金の割合で、「強い税率を感じた」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "共鳴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は彼の成績に共鳴して、驚いた。", "explanation": "ここは「感心する」の意味。共鳴は自分の心も同じように動くことで、成績への感心には使わない。"}, {"text": "寒さに共鳴して、彼は窓を閉めた。", "explanation": "ここは「寒さに反応する」の意味。共鳴は他人と同じ気持ちになることで、自分の体感への反応には使わない。"}, {"text": "信号の色に共鳴して、車を止めた。", "explanation": "ここは「信号に従う」の意味。共鳴は心が同じように動くことで、規則に従う意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52913, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共鳴", "is_correct": true, "explanation": "「痛みに共鳴し」は、別れの痛みに心が同調したことを表す。文脈に合う。"}, {"text": "手続き", "is_correct": false, "explanation": "「手続き」は事務的な手順で、「痛みに手続きし」は意味をなさない。"}, {"text": "駐車", "is_correct": false, "explanation": "「駐車」は車を止めることで、「痛みに駐車し」は成り立たない。"}, {"text": "配送", "is_correct": false, "explanation": "「配送」は荷物を届けることで、感情の文脈には合わない。"}], "explanations": {"共鳴": "「痛みに共鳴し」は、別れの痛みに心が同調したことを表す。文脈に合う。", "手続き": "「手続き」は事務的な手順で、「痛みに手続きし」は意味をなさない。", "駐車": "「駐車」は車を止めることで、「痛みに駐車し」は成り立たない。", "配送": "「配送」は荷物を届けることで、感情の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "共鳴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の説に共鳴して、反論のデータを示した。", "explanation": "ここは「異を唱える」の意味。共鳴は相手の考えに同調することで、反対の立場を示す意味にはならない。"}, {"text": "届いた請求書に共鳴して、すぐ支払った。", "explanation": "ここは「事務的に処理する」の意味。共鳴は心が同じように感じて動くことで、請求書の処理には使わない。"}, {"text": "強い風に共鳴して、ドアが閉まった。", "explanation": "ここは「押されて動く」の意味。共鳴は心が同じように感じて動くことで、物が押されて動く意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52913, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の歌に共鳴され、私は涙が出た。", "corrected_sentence": "彼の歌に共鳴し、私は涙が出た。", "error_description": "「共鳴する」は受身にしない。「共鳴される」は誤りで、正しくは「共鳴し」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52913, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その詩に共鳴なかった、と妹は言った。", "corrected_sentence": "その詩に共鳴しなかった、と妹は言った。", "error_description": "否定形は「共鳴しなかった」。「し」が抜けていて、「共鳴なかった」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52914, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「共鳴」は「〜に共鳴する」で、響きかける相手を「に」で示す。演説に共鳴したのでここは「に」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示す。共鳴は「演説を共鳴する」とは言わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう方向を示す。共鳴の相手は方向ではないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や原因を示す。共鳴の相手を示すには合わない。"}], "correct_answer": "に", "explanations": {"に": "「共鳴」は「〜に共鳴する」で、響きかける相手を「に」で示す。演説に共鳴したのでここは「に」。", "を": "「を」は他動詞の目的語を示す。共鳴は「演説を共鳴する」とは言わない。", "へ": "「へ」は向かう方向を示す。共鳴の相手は方向ではないので合わない。", "から": "「から」は起点や原因を示す。共鳴の相手を示すには合わない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52914, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「弦の音と共鳴する」で、共鳴する相手を「と」で示す。ここは「と」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。共鳴は他動詞ではないので「弦の音を共鳴する」とは言えない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。「弦の音より共鳴する」は相手を示さず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「弦の音の共鳴する」は述語にならず、文が成立しない。"}], "correct_answer": "と", "explanations": {"と": "「弦の音と共鳴する」で、共鳴する相手を「と」で示す。ここは「と」。", "を": "「を」は目的語を示す。共鳴は他動詞ではないので「弦の音を共鳴する」とは言えない。", "より": "「より」は比較の基準を示す。「弦の音より共鳴する」は相手を示さず、文が成り立たない。", "の": "「の」は名詞をつなぐ。「弦の音の共鳴する」は述語にならず、文が成立しない。"}, "error_tags": {"を": "対象", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52914, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他人の感情や意見に強く同調し、自分も同じように感じること。また、物理的には、振動が他の物体に伝わって同じ振動を起こすこと。", "primary_collocate": null, "pronunciation": "きょうめい", "ipa": "kʲoːmeː", "syllable_count": 4, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "靴紐[くつひも]を固[かた]く結[むす]び、踵[かかと]で床[ゆか]を鳴[な]らせば、鈍[にぶ]い音[おと]が魂[たましい]の鼓動[こどう]と共鳴[きょうめい]する。", "sentence_source": "mined"}, {"text": "彼の演説に強く共鳴した若者たちが、署名活動に加わった。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "彼[かれ]の演説[えんぜつ]に強[つよ]く共鳴[きょうめい]した若者[わかもの]たちが、署名[しょめい]活動[かつどう]に加[くわ]わった。", "sentence_source": "generated"}, {"text": "二本の音叉を並べて片方を鳴らすと、もう一方も共鳴して音を出す。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "二本[にほん]の音叉[おんさ]を並[なら]べて片方[かたほう]を鳴[な]らすと、もう一方[いっぽう]も共鳴[きょうめい]して音[おと]を出[だ]す。", "sentence_source": "generated"}, {"text": "彼女の訴えは多くの人の共鳴を呼び、全国に支援の輪が広がった。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の訴[うった]えは多[おお]くの人[ひと]の共鳴[きょうめい]を呼[よ]び、全国[ぜんこく]に支援[しえん]の輪[わ]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "橋が大きく揺れたのは、風の振動と橋の揺れが共鳴したからだ。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "橋[はし]が大[おお]きく揺[ゆ]れたのは、風[かぜ]の振動[しんどう]と橋[はし]の揺[ゆ]れが共鳴[きょうめい]したからだ。", "sentence_source": "generated"}, {"text": "社長の理念に共鳴して、優秀な技術者が次々と入社した。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の理念[りねん]に共鳴[きょうめい]して、優秀[ゆうしゅう]な技術者[ぎじゅつしゃ]が次々[つぎつぎ]と入社[にゅうしゃ]した。", "sentence_source": "generated"}, {"text": "その詩の最後の一行に深い共鳴を覚え、私は何度も読み返した。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "その詩[し]の最後[さいご]の一行[いちぎょう]に深[ふか]い共鳴[きょうめい]を覚[おぼ]え、私[わたし]は何度[なんど]も読[よ]み返[かえ]した。", "sentence_source": "generated"}, {"text": "ギターの胴が弦の音と共鳴するので、小さな音でも豊かに響く。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "ギターの胴[どう]が弦[げん]の音[おと]と共鳴[きょうめい]するので、小[ちい]さな音[おと]でも豊[ゆた]かに響[ひび]く。", "sentence_source": "generated"}, {"text": "彼とは考え方が違い、どうしても共鳴できない部分が残った。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "彼[かれ]とは考[かんが]え方[かた]が違[ちが]い、どうしても共鳴[きょうめい]できない部分[ぶぶん]が残[のこ]った。", "sentence_source": "generated"}, {"text": "低い音が響くと、窓ガラスがそれに共鳴してびりびりと震えた。", "target_word": "共鳴", "complexity_tier": "T3", "furigana": "低[ひく]い音[おと]が響[ひび]くと、窓[まど]ガラスがそれに共鳴[きょうめい]してびりびりと震[ふる]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共鳴", "label": "基本形"}, {"form": "共鳴する", "label": "する形"}, {"form": "共鳴した", "label": "た形"}, {"form": "共鳴して", "label": "て形"}, {"form": "共鳴しない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "共鳴：他人の感情や意見への強い同調。物理では振動が他の物体に伝わり同じ振動を起こすこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52914, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共鳴", "is_correct": true, "explanation": "「鼓動と共鳴する」は、音が鼓動と響き合うことを表す。文脈に合う。"}, {"text": "沈黙", "is_correct": false, "explanation": "「沈黙する」は音や声が止むことで、鼓動と響き合う文脈と逆になる。"}, {"text": "乾燥", "is_correct": false, "explanation": "「乾燥する」は水分が失われることで、音と鼓動の関係には合わない。"}, {"text": "停滞", "is_correct": false, "explanation": "「停滞する」は進まなくなることで、響き合う動きとは合わない。"}], "explanations": {"共鳴": "「鼓動と共鳴する」は、音が鼓動と響き合うことを表す。文脈に合う。", "沈黙": "「沈黙する」は音や声が止むことで、鼓動と響き合う文脈と逆になる。", "乾燥": "「乾燥する」は水分が失われることで、音と鼓動の関係には合わない。", "停滞": "「停滞する」は進まなくなることで、響き合う動きとは合わない。"}, "sentence_index": 0, "correct_answer": "共鳴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "両社は技術を共鳴させて、新しい製品を開発した。", "explanation": "ここは「共同で作る」の意味。共鳴は感情や振動が同調することなので、協力して開発する意味には合わない。"}, {"text": "薬剤を共鳴させて、傷口を消毒した。", "explanation": "ここは「殺菌する」の意味。共鳴は感情や振動が同調することで、薬剤で殺菌する意味には合わない。"}, {"text": "薬に強く共鳴した患者がいた。", "explanation": "ここは「薬に反応する」の意味。共鳴は人の感情や物の振動の同調で、薬の作用には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52914, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共鳴", "is_correct": true, "explanation": "「深い共鳴を覚える」は、詩に強く心が同調したことを表す。文脈に合う。"}, {"text": "手続き", "is_correct": false, "explanation": "「手続き」は手順を踏む行為で、「深い手続きを覚える」は意味をなさない。"}, {"text": "税率", "is_correct": false, "explanation": "「税率」は税金の割合で、感情を覚える文脈には合わない。"}, {"text": "駐車", "is_correct": false, "explanation": "「駐車」は車を止めることで、「深い駐車を覚える」は不自然。"}], "explanations": {"共鳴": "「深い共鳴を覚える」は、詩に強く心が同調したことを表す。文脈に合う。", "手続き": "「手続き」は手順を踏む行為で、「深い手続きを覚える」は意味をなさない。", "税率": "「税率」は税金の割合で、感情を覚える文脈には合わない。", "駐車": "「駐車」は車を止めることで、「深い駐車を覚える」は不自然。"}, "sentence_index": 6, "correct_answer": "共鳴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は質問に共鳴して、丁寧に答えた。", "explanation": "ここは「回答する」の意味。共鳴は心が同じように動くことで、質問への返答は表さない。"}, {"text": "上司の命令に共鳴して、資料を作った。", "explanation": "ここは「命令に従う」の意味。共鳴は同じ気持ちになることで、指示への服従は表さない。"}, {"text": "彼の説に共鳴して、反論の資料を集めた。", "explanation": "ここは「異を唱える」の意味。共鳴は相手の考えに同調することで、反対の立場を示す意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52914, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の演説を強く共鳴した若者が、署名に加わった。", "corrected_sentence": "彼の演説に強く共鳴した若者が、署名に加わった。", "error_description": "「共鳴」は「〜に共鳴する」と「に」を取る。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52914, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その言葉に共鳴った、と彼女は言った。", "corrected_sentence": "その言葉に共鳴した、と彼女は言った。", "error_description": "過去形は「共鳴した」。「共鳴った」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52915, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「街路は一方通行」で、話題としての街路を「は」で示す。ここは「は」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「この街路を一方通行なので」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示す。「この街路に一方通行なので」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。一方通行の状態を述べる文脈には合わない。"}], "correct_answer": "は", "explanations": {"は": "「街路は一方通行」で、話題としての街路を「は」で示す。ここは「は」。", "を": "「を」は目的語を示す。「この街路を一方通行なので」は文として成り立たない。", "に": "「に」は場所や相手を示す。「この街路に一方通行なので」は不自然。", "へ": "「へ」は方向を示す。一方通行の状態を述べる文脈には合わない。"}, "error_tags": {"を": "対象", "に": "場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52915, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「広い街路が碁盤の目のように走っている」で、走る主体の街路を「が」で示す。ここは「が」。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「広い街路から碁盤の目のように走っている」は起点の意味になり、走る主体も示せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「広い街路の走っている」は主語と動詞が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「広い街路と走っている」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「広い街路が碁盤の目のように走っている」で、走る主体の街路を「が」で示す。ここは「が」。", "から": "「から」は起点を示す。「広い街路から碁盤の目のように走っている」は起点の意味になり、走る主体も示せず不自然。", "の": "「の」は名詞をつなぐ。「広い街路の走っている」は主語と動詞が成り立たない。", "と": "「と」は並列や相手を示す。「広い街路と走っている」は文が成り立たない。"}, "error_tags": {"から": "起点", "の": "連体", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52915, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "道のことを言う言葉で、車や人が通る場所です。", "primary_collocate": null, "pronunciation": "がいろ", "ipa": "ɡaiɾo", "syllable_count": 3, "sentences": [{"text": "駅前の街路は、朝の通勤の人で込み合っていた。", "target_word": "街路", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の街路[がいろ]は、朝[あさ]の通勤[つうきん]の人[ひと]で込[こ]み合[あ]っていた。", "sentence_source": "generated"}, {"text": "この街路は一方通行なので、反対側からは車が入れない。", "target_word": "街路", "complexity_tier": "T3", "furigana": "この街路[がいろ]は一方通行[いっぽうつうこう]なので、反対側[はんたいがわ]からは車[くるま]が入[はい]れない。", "sentence_source": "generated"}, {"text": "工事のため、街路の一部が来週まで通れなくなる。", "target_word": "街路", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、街路[がいろ]の一部[いちぶ]が来週[らいしゅう]まで通[とお]れなくなる。", "sentence_source": "generated"}, {"text": "子どもが飛び出さないように、街路の角に見守りの人が立っている。", "target_word": "街路", "complexity_tier": "T3", "furigana": "子[こ]どもが飛[と]び出[だ]さないように、街路[がいろ]の角[かど]に見守[みまも]りの人[ひと]が立[た]っている。", "sentence_source": "generated"}, {"text": "雪が積もって、街路は歩くのも大変なほど滑りやすくなった。", "target_word": "街路", "complexity_tier": "T3", "furigana": "雪[ゆき]が積[つ]もって、街路[がいろ]は歩[ある]くのも大変[たいへん]なほど滑[すべ]りやすくなった。", "sentence_source": "generated"}, {"text": "街路の左右にはパン屋や花屋が並び、散歩するだけで楽しい。", "target_word": "街路", "complexity_tier": "T3", "furigana": "街路[がいろ]の左右[さゆう]にはパン屋[や]や花屋[はなや]が並[なら]び、散歩[さんぽ]するだけで楽[たの]しい。", "sentence_source": "generated"}, {"text": "夏祭りの夜、街路は浴衣を着た人たちでにぎわった。", "target_word": "街路", "complexity_tier": "T3", "furigana": "夏祭[なつまつ]りの夜[よる]、街路[がいろ]は浴衣[ゆかた]を着[き]た人[ひと]たちでにぎわった。", "sentence_source": "generated"}, {"text": "地図で見ると、この街は広い街路が碁盤の目のように走っている。", "target_word": "街路", "complexity_tier": "T3", "furigana": "地図[ちず]で見[み]ると、この街[まち]は広[ひろ]い街路[がいろ]が碁盤[ごばん]の目[め]のように走[はし]っている。", "sentence_source": "generated"}, {"text": "狭い街路に車を止めると、救急車が通れなくなって危険だ。", "target_word": "街路", "complexity_tier": "T3", "furigana": "狭[せま]い街路[がいろ]に車[くるま]を止[と]めると、救急車[きゅうきゅうしゃ]が通[とお]れなくなって危険[きけん]だ。", "sentence_source": "generated"}, {"text": "道に迷ったので、街路の端に立って地図を広げた。", "target_word": "街路", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]ったので、街路[がいろ]の端[はし]に立[た]って地図[ちず]を広[ひろ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "街路", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "街路：車や人が通る、町なかの道。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52915, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街路", "is_correct": true, "explanation": "「駅前の街路は、朝の通勤の人で込み合う」で、人や車が通る町の道を表す。文脈に合う。"}, {"text": "税率", "is_correct": false, "explanation": "「税率」は税金の割合で、「駅前の税率は込み合う」は意味をなさない。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢」は人の歳で、「駅前の年齢は込み合う」は成り立たない。"}, {"text": "手順", "is_correct": false, "explanation": "「手順」は作業の順序で、「駅前の手順は込み合う」は不自然。"}], "explanations": {"街路": "「駅前の街路は、朝の通勤の人で込み合う」で、人や車が通る町の道を表す。文脈に合う。", "税率": "「税率」は税金の割合で、「駅前の税率は込み合う」は意味をなさない。", "年齢": "「年齢」は人の歳で、「駅前の年齢は込み合う」は成り立たない。", "手順": "「手順」は作業の順序で、「駅前の手順は込み合う」は不自然。"}, "sentence_index": 0, "correct_answer": "街路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室の街路を走らないように注意された。", "explanation": "ここは「廊下」の意味。廊下は建物の中の通路で、街路は町の中の屋外の道なので合わない。"}, {"text": "電車の街路で席を譲った。", "explanation": "ここは「車内」の意味。車内は乗り物の中の空間で、街路は屋外の道なので合わない。"}, {"text": "ホームの街路で電車を待った。", "explanation": "ここは「乗降場」の意味。街路は町の中の道なので、電車の乗降場には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52915, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街路", "is_correct": true, "explanation": "「夏祭りの夜、街路はにぎわった」で、町の道が人でにぎわったことを表す。文脈に合う。"}, {"text": "手続き", "is_correct": false, "explanation": "「手続き」は事務的な手順で、「夏祭りの夜、手続きはにぎわった」は成り立たない。"}, {"text": "駐車", "is_correct": false, "explanation": "「駐車」は車を止めることで、人が浴衣でにぎわう文脈には合わない。"}, {"text": "配送", "is_correct": false, "explanation": "「配送」は荷物を届けることで、「夏祭りの夜、配送はにぎわった」は不自然。"}], "explanations": {"街路": "「夏祭りの夜、街路はにぎわった」で、町の道が人でにぎわったことを表す。文脈に合う。", "手続き": "「手続き」は事務的な手順で、「夏祭りの夜、手続きはにぎわった」は成り立たない。", "駐車": "「駐車」は車を止めることで、人が浴衣でにぎわう文脈には合わない。", "配送": "「配送」は荷物を届けることで、「夏祭りの夜、配送はにぎわった」は不自然。"}, "sentence_index": 6, "correct_answer": "街路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地下の街路を歩いて、改札の出口を探した。", "explanation": "ここは「地下通路」の意味。街路は地上の町の道なので、地下の通路には合わない。"}, {"text": "家に入る前、玄関の街路で靴を脱いだ。", "explanation": "ここは「家の入り口の土間」の意味。街路は町の中の道なので、家の中の場所には合わない。"}, {"text": "夏の夜、街路の流れに釣り糸を垂らした。", "explanation": "ここは「川」の意味。街路は車や人が通る町の道なので、水の流れる場所には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52915, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前の街路を、朝の通勤の人で込み合う。", "corrected_sentence": "駅前の街路は、朝の通勤の人で込み合う。", "error_description": "「込み合う」は自動詞で、街路は主語になるので「は」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52915, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏祭りの夜、街路を浴衣姿の人たちでにぎわった。", "corrected_sentence": "夏祭りの夜、街路は浴衣姿の人たちでにぎわった。", "error_description": "「にぎわう」は自動詞で、街路は主語になるので「は」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52916, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「街路に」で、街灯の光が伸びる場所を「に」で示す。ここは「に」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語の目印。場所を示す文脈には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語の目印。街路を主語にすると、伸びるという動きの主体が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう方向を示す。伸びている状態の場所には合わない。"}], "correct_answer": "に", "explanations": {"に": "「街路に」で、街灯の光が伸びる場所を「に」で示す。ここは「に」。", "を": "「を」は目的語の目印。場所を示す文脈には合わない。", "が": "「が」は主語の目印。街路を主語にすると、伸びるという動きの主体が不自然になる。", "へ": "「へ」は向かう方向を示す。伸びている状態の場所には合わない。"}, "error_tags": {"を": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52916, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「街路がふさがれてしまった」で、ふさがれる主語を「が」で示す。ここは「が」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。受身の主語を「を」で示すことはできない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。ふさがれる主語には使わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や原因を示す。主語を示すには合わない。"}], "correct_answer": "が", "explanations": {"が": "「街路がふさがれてしまった」で、ふさがれる主語を「が」で示す。ここは「が」。", "を": "「を」は目的語を示す。受身の主語を「を」で示すことはできない。", "へ": "「へ」は方向を示す。ふさがれる主語には使わない。", "から": "「から」は起点や原因を示す。主語を示すには合わない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52916, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "町の中にある、建物と建物の間の道。道路。", "primary_collocate": null, "pronunciation": "がいろ", "ipa": "ɡaiɾo", "syllable_count": 3, "sentences": [{"text": "さあ、この退廃的な美しさを纏い、冷徹な街路へ歩み出そうではないか。", "target_word": "街路", "complexity_tier": "T3", "furigana": "さあ、この退廃的[たいはいてき]な美[うつく]しさを纏[まと]い、冷徹[れいてつ]な街路[がいろ]へ歩[あゆ]み出[だ]そうではないか。", "sentence_source": "mined"}, {"text": "雨上がりの街路には、街灯の光が長く伸びていた。", "target_word": "街路", "complexity_tier": "T3", "furigana": "雨上[あめあ]がりの街路[がいろ]には、街灯[がいとう]の光[ひかり]が長[なが]く伸[の]びていた。", "sentence_source": "generated"}, {"text": "古い街路は幅が狭く、大型の車は通り抜けられない。", "target_word": "街路", "complexity_tier": "T3", "furigana": "古[ふる]い街路[がいろ]は幅[はば]が狭[せま]く、大型[おおがた]の車[くるま]は通[とお]り抜[ぬ]けられない。", "sentence_source": "generated"}, {"text": "祭りの日には、街路の両側に屋台がずらりと並んだ。", "target_word": "街路", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]には、街路[がいろ]の両側[りょうがわ]に屋台[やたい]がずらりと並[なら]んだ。", "sentence_source": "generated"}, {"text": "夜が更けると、人通りの絶えた街路に靴音だけが響いた。", "target_word": "街路", "complexity_tier": "T3", "furigana": "夜[よる]が更[ふ]けると、人通[ひとどお]りの絶[た]えた街路[がいろ]に靴音[くつおと]だけが響[ひび]いた。", "sentence_source": "generated"}, {"text": "市は街路を広げて、歩行者が安心して歩けるようにした。", "target_word": "街路", "complexity_tier": "T3", "furigana": "市[し]は街路[がいろ]を広[ひろ]げて、歩行者[ほこうしゃ]が安心[あんしん]して歩[ある]けるようにした。", "sentence_source": "generated"}, {"text": "石畳の街路を抜けると、突然、視界が開けて広場に出た。", "target_word": "街路", "complexity_tier": "T3", "furigana": "石畳[いしだたみ]の街路[がいろ]を抜[ぬ]けると、突然[とつぜん]、視界[しかい]が開[ひら]けて広場[ひろば]に出[で]た。", "sentence_source": "generated"}, {"text": "地震のあと、倒れた看板や瓦礫で街路がふさがれてしまった。", "target_word": "街路", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、倒[たお]れた看板[かんばん]や瓦礫[がれき]で街路[がいろ]がふさがれてしまった。", "sentence_source": "generated"}, {"text": "港町の街路は、坂が多くて自転車では上れない。", "target_word": "街路", "complexity_tier": "T3", "furigana": "港町[みなとまち]の街路[がいろ]は、坂[さか]が多[おお]くて自転車[じてんしゃ]では上[のぼ]れない。", "sentence_source": "generated"}, {"text": "朝になると、掃除をする人たちが街路をほうきで掃いていた。", "target_word": "街路", "complexity_tier": "T3", "furigana": "朝[あさ]になると、掃除[そうじ]をする人[ひと]たちが街路[がいろ]をほうきで掃[は]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "街路", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "街路：町の建物と建物の間を通る道。道路。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52916, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街路", "is_correct": true, "explanation": "「冷徹な街路へ歩み出す」は、町の道へ踏み出すことを表す。文脈に合う。"}, {"text": "手順", "is_correct": false, "explanation": "「手順」は作業の順序で、「冷徹な手順へ歩み出す」は成り立たない。"}, {"text": "税率", "is_correct": false, "explanation": "「税率」は税金の割合で、「冷徹な税率へ」は意味をなさない。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢」は人の歳で、「冷徹な年齢へ歩み出す」は不自然。"}], "explanations": {"街路": "「冷徹な街路へ歩み出す」は、町の道へ踏み出すことを表す。文脈に合う。", "手順": "「手順」は作業の順序で、「冷徹な手順へ歩み出す」は成り立たない。", "税率": "「税率」は税金の割合で、「冷徹な税率へ」は意味をなさない。", "年齢": "「年齢」は人の歳で、「冷徹な年齢へ歩み出す」は不自然。"}, "sentence_index": 0, "correct_answer": "街路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "線路の街路を電車が走った。", "explanation": "ここは「線路」の意味。街路は町の中の道なので、電車の線路には合わない。"}, {"text": "ホテルの街路を歩いて、部屋に戻った。", "explanation": "ここは「廊下」の意味。廊下は建物の中の通路で、街路は建物の間の屋外の道なので合わない。"}, {"text": "屋上の街路に洗濯物を干した。", "explanation": "ここは「屋根の上の平らな場所」の意味。街路は地上の町の道なので、屋根の上には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52916, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街路", "is_correct": true, "explanation": "「石畳の街路を抜ける」は、石畳の道を通ることを表す。文脈に合う。"}, {"text": "手続き", "is_correct": false, "explanation": "「手続き」は事務的な手順で、「石畳の手続きを抜ける」は意味をなさない。"}, {"text": "駐車", "is_correct": false, "explanation": "「駐車」は車を止めることで、「石畳の駐車を抜ける」は成り立たない。"}, {"text": "配送", "is_correct": false, "explanation": "「配送」は荷物を届けることで、「石畳の配送を抜ける」は不自然。"}], "explanations": {"街路": "「石畳の街路を抜ける」は、石畳の道を通ることを表す。文脈に合う。", "手続き": "「手続き」は事務的な手順で、「石畳の手続きを抜ける」は意味をなさない。", "駐車": "「駐車」は車を止めることで、「石畳の駐車を抜ける」は成り立たない。", "配送": "「配送」は荷物を届けることで、「石畳の配送を抜ける」は不自然。"}, "sentence_index": 6, "correct_answer": "街路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地下の街路を歩いて、改札に向かった。", "explanation": "ここは「地下通路」の意味。街路は地上の町の道なので、地下の通路には合わない。"}, {"text": "家に入るとき、街路で靴を脱いで上がった。", "explanation": "ここは「玄関」の意味。玄関は家の入り口で、街路は屋外の道なので合わない。"}, {"text": "水路の街路に魚が泳いでいた。", "explanation": "ここは「川」の意味。街路は人や車が通る町の道なので、魚が泳ぐ水の流れには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52916, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の夜の街路を、虫の声が聞こえていた。", "corrected_sentence": "夏の夜の街路には、虫の声が聞こえていた。", "error_description": "場所を示すには「には」を使う。「を」は目的語の目印で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52916, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "石畳の街路が歩いた。", "corrected_sentence": "石畳の街路を歩いた。", "error_description": "「歩く」は人が主語で、場所は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52917, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52917, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「ゆっくりと」の「と」。歩み出し方の様子を表す。"}, {"text": "に", "is_correct": false, "explanation": "「ゆっくりに歩み出した」は成り立たない。様子は「と」で表す。"}, {"text": "で", "is_correct": false, "explanation": "「ゆっくりで歩み出した」は不自然。「で」は場所や手段を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ゆっくりが歩み出した」は主語にならず、文の主旨が崩れる。"}], "correct_answer": "と", "explanations": {"と": "「ゆっくりと」の「と」。歩み出し方の様子を表す。", "に": "「ゆっくりに歩み出した」は成り立たない。様子は「と」で表す。", "で": "「ゆっくりで歩み出した」は不自然。「で」は場所や手段を示す。", "が": "「ゆっくりが歩み出した」は主語にならず、文の主旨が崩れる。"}, "error_tags": {"に": "direction/time", "で": "location/means", "が": "subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52917, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "歩み出すは、歩き始めることです。", "primary_collocate": null, "pronunciation": "あゆみだす", "ipa": "ajumidasɯ", "syllable_count": 5, "sentences": [{"text": "赤ちゃんは母親の声に誘われて、そろそろと歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは母親[ははおや]の声[こえ]に誘[さそ]われて、そろそろと歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "信号が青になったので、私たちは交差点へと歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "信号[しんごう]が青[あお]になったので、私[わたし]たちは交差点[こうさてん]へと歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "雨がやむと、傘を閉じた人々が再び駅へ向かって歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "雨[あめ]がやむと、傘[かさ]を閉[と]じた人々[ひとびと]が再[ふたた]び駅[えき]へ向[む]かって歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "先生に名前を呼ばれて、緊張した生徒が前へ歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "先生[せんせい]に名前[なまえ]を呼[よ]ばれて、緊張[きんちょう]した生徒[せいと]が前[まえ]へ歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "休憩を終えて、登山隊は山頂を目指して再び歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "休憩[きゅうけい]を終[お]えて、登山隊[とざんたい]は山頂[さんちょう]を目指[めざ]して再[ふたた]び歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "試験が終わったら、次の目標に向かって歩み出すつもりだ。", "target_word": "歩み出す", "complexity_tier": "T3", "furigana": "試験[しけん]が終[お]わったら、次[つぎ]の目標[もくひょう]に向[む]かって歩[あゆ]み出[だ]すつもりだ。", "sentence_source": "generated"}, {"text": "彼は新しい町で、小さなパン屋の主人として歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しい町[まち]で、小[ちい]さなパン屋[や]の主人[しゅじん]として歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "犬は飼い主の合図を待って、ゆっくりと歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "犬[いぬ]は飼[か]い主[ぬし]の合図[あいず]を待[ま]って、ゆっくりと歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "父は退院の日、看護師に礼を言ってから玄関へ歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "父[ちち]は退院[たいいん]の日[ひ]、看護師[かんごし]に礼[れい]を言[い]ってから玄関[げんかん]へ歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "迷いを捨てて歩み出せば、きっと新しい道が見つかる。", "target_word": "歩み出せば", "complexity_tier": "T3", "furigana": "迷[まよ]いを捨[す]てて歩[あゆ]み出[だ]せば、きっと新[あたら]しい道[みち]が見[み]つかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歩み出す", "label": "基本形"}, {"form": "歩み出さない", "label": "ない形"}, {"form": "歩み出します", "label": "ます形"}, {"form": "歩み出した", "label": "た形"}, {"form": "歩み出して", "label": "て形"}, {"form": "歩み出せば", "label": "ば形"}, {"form": "歩み出そう", "label": "意志形"}], "register": "書き言葉", "sense_fingerprint": "歩み出す：それまで止まっていた人や動物が、歩き始める。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52917, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歩み出した", "is_correct": true, "explanation": "過去の出来事を述べる「た形」。「赤ちゃんは…そろそろと歩み出した」と文を言い切れる。"}, {"text": "歩み出して", "is_correct": false, "explanation": "て形は文末に置けず、「そろそろと歩み出して。」は成立しない。"}, {"text": "歩み出せば", "is_correct": false, "explanation": "ば形は条件節で、文の述語にならない。"}, {"text": "歩み出します", "is_correct": false, "explanation": "丁寧な現在形は、母親の声に誘われた出来事を述べる地の文と合わない。"}], "explanations": {"歩み出した": "過去の出来事を述べる「た形」。「赤ちゃんは…そろそろと歩み出した」と文を言い切れる。", "歩み出して": "て形は文末に置けず、「そろそろと歩み出して。」は成立しない。", "歩み出せば": "ば形は条件節で、文の述語にならない。", "歩み出します": "丁寧な現在形は、母親の声に誘われた出来事を述べる地の文と合わない。"}, "sentence_index": 0, "correct_answer": "歩み出した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が上がると、傘が一斉に歩み出した。", "explanation": "ここは〈動き出す〉の意味。歩み出すは人や動物が歩く動作で、傘（物）には使わない。"}, {"text": "休日は朝から晩まで、家の前を歩み出していた。", "explanation": "ここは〈歩き回る〉の意味。歩み出すは歩き始めることで、継続して歩き回る様子には合わない。"}, {"text": "信号が変わると、車の列がゆっくり歩み出した。", "explanation": "ここは〈進む〉の意味。歩み出すは人や動物が歩き始めることで、車には〈進む〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52917, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歩み出した", "is_correct": true, "explanation": "過去の出来事を述べる「た形」。「彼は…主人として歩み出した」と文を言い切れる。"}, {"text": "歩み出し", "is_correct": false, "explanation": "連用形は文を言い切れず、「主人として歩み出し。」は成立しない。"}, {"text": "歩み出せ", "is_correct": false, "explanation": "命令形は命令になり、新しい町での出発を述べる地の文と合わない。"}, {"text": "歩み出される", "is_correct": false, "explanation": "自動詞は受身にならず、「歩み出される」は成り立たない。"}], "explanations": {"歩み出した": "過去の出来事を述べる「た形」。「彼は…主人として歩み出した」と文を言い切れる。", "歩み出し": "連用形は文を言い切れず、「主人として歩み出し。」は成立しない。", "歩み出せ": "命令形は命令になり、新しい町での出発を述べる地の文と合わない。", "歩み出される": "自動詞は受身にならず、「歩み出される」は成り立たない。"}, "sentence_index": 6, "correct_answer": "歩み出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "号砲が鳴ると、短距離の選手たちは一斉に歩み出した。", "explanation": "ここは〈走り出す〉の意味。短距離走は走って競うので、歩き始めることを表す歩み出すは合わない。"}, {"text": "彼は椅子に座ったまま、ゆっくり歩み出した。", "explanation": "ここは〈座る〉の意味。歩き始めることと座った状態が矛盾し、歩み出すは座る動作には使えない。"}, {"text": "その知らせを聞いて、彼女の気持ちが歩み出した。", "explanation": "ここは〈変わる〉の意味。歩み出すは人の動作を指し、気持ちの変化には〈変わる〉が合う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52917, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は勇気を出して、一歩ずつ歩み出しだ。", "corrected_sentence": "彼女は勇気を出して、一歩ずつ歩み出した。", "error_description": "過去形の誤り。「歩み出した」の「た」を「だ」に濁らせている。正しくは「歩み出した」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "歩み出した", "is_correct": true, "explanation": "文中の形そのもの。過去を表す「た形」で、「交差点へと歩み出した」と言い切る。"}, {"text": "歩み出して", "is_correct": false, "explanation": "て形では文を言い切れず、「ので」の後にも続かない。"}, {"text": "歩み出せば", "is_correct": false, "explanation": "ば形は条件節で、文末の述語にならない。"}, {"text": "歩み出し", "is_correct": false, "explanation": "連用形は文を終えられず、「交差点へと歩み出し。」は成立しない。"}], "correct_form": "歩み出した", "base_form": "歩み出す", "form_label": "た形", "sentence_index": 1, "explanations": {"歩み出した": "文中の形そのもの。過去を表す「た形」で、「交差点へと歩み出した」と言い切る。", "歩み出して": "て形では文を言い切れず、「ので」の後にも続かない。", "歩み出せば": "ば形は条件節で、文末の述語にならない。", "歩み出し": "連用形は文を終えられず、「交差点へと歩み出し。」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52917, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "犬は飼い主の合図で、庭が歩み出した。", "corrected_sentence": "犬は飼い主の合図で、庭へ歩み出した。", "error_description": "方向を示す「へ」を「が」に変えた誤り。歩み出すは動作主が移動先へ向かう文で、「庭が」は主語にならない。正しくは「庭へ歩み出した」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "歩み出した", "is_correct": true, "explanation": "文中の形そのもの。過去を表す「た形」で、「犬は…歩み出した」と言い切る。"}, {"text": "歩み出したら", "is_correct": false, "explanation": "たら形は条件節で、「ゆっくりと歩み出したら。」と文を終えられない。"}, {"text": "歩み出さない", "is_correct": false, "explanation": "ない形は否定になり、歩き始めた事実と逆になる。"}, {"text": "歩み出しながら", "is_correct": false, "explanation": "ながら形は同時の動作を表す接続形で、文末には置けず、「ゆっくりと歩み出しながら。」は成立しない。"}], "correct_form": "歩み出した", "base_form": "歩み出す", "form_label": "た形", "sentence_index": 7, "explanations": {"歩み出した": "文中の形そのもの。過去を表す「た形」で、「犬は…歩み出した」と言い切る。", "歩み出したら": "たら形は条件節で、「ゆっくりと歩み出したら。」と文を終えられない。", "歩み出さない": "ない形は否定になり、歩き始めた事実と逆になる。", "歩み出しながら": "ながら形は同時の動作を表す接続形で、文末には置けず、「ゆっくりと歩み出しながら。」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
