INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52918, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "歩き始めること。また、一歩を踏み出して前に進むこと。", "primary_collocate": null, "pronunciation": "あゆみだす", "ipa": "ajumidasɯ", "syllable_count": 5, "sentences": [{"text": "さあ、この退廃的な美しさを纏い、冷徹な街路へ歩み出そうではないか。", "target_word": "歩み出そう", "complexity_tier": "T3", "furigana": "さあ、この退廃的[たいはいてき]な美[うつく]しさを纏[まと]い、冷徹[れいてつ]な街路[がいろ]へ歩[あゆ]み出[だ]そうではないか。", "sentence_source": "mined"}, {"text": "長い沈黙のあと、彼はゆっくりと扉に向かって歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "長[なが]い沈黙[ちんもく]のあと、彼[かれ]はゆっくりと扉[とびら]に向[む]かって歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "卒業式を終えた彼女は、新しい人生へと歩み出す決意を固めた。", "target_word": "歩み出す", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]を終[お]えた彼女[かのじょ]は、新[あたら]しい人生[じんせい]へと歩[あゆ]み出[だ]す決意[けつい]を固[かた]めた。", "sentence_source": "generated"}, {"text": "信号が青に変わると、人々は一斉に横断歩道へ歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "信号[しんごう]が青[あお]に変[か]わると、人々[ひとびと]は一斉[いっせい]に横断歩道[おうだんほどう]へ歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "迷っていても何も変わらない。まずは自分の足で歩み出そう。", "target_word": "歩み出そう", "complexity_tier": "T3", "furigana": "迷[まよ]っていても何[なに]も変[か]わらない。まずは自分[じぶん]の足[あし]で歩[あゆ]み出[だ]そう。", "sentence_source": "generated"}, {"text": "幕が上がると、主役の少女は光の当たる中央へ歩み出して、静かに一礼した。", "target_word": "歩み出して", "complexity_tier": "T3", "furigana": "幕[まく]が上[あ]がると、主役[しゅやく]の少女[しょうじょ]は光[ひかり]の当[あ]たる中央[ちゅうおう]へ歩[あゆ]み出[だ]して、静[しず]かに一礼[いちれい]した。", "sentence_source": "generated"}, {"text": "怪我が治った祖父は、杖を手に、久しぶりに庭へと歩み出した。", "target_word": "歩み出した", "complexity_tier": "T3", "furigana": "怪我[けが]が治[なお]った祖父[そふ]は、杖[つえ]を手[て]に、久[ひさ]しぶりに庭[にわ]へと歩[あゆ]み出[だ]した。", "sentence_source": "generated"}, {"text": "失敗を恐れて歩み出さない人には、新しい景色は見えてこない。", "target_word": "歩み出さない", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を恐[おそ]れて歩[あゆ]み出[だ]さない人[ひと]には、新[あたら]しい景色[けしき]は見[み]えてこない。", "sentence_source": "generated"}, {"text": "会社を辞めた兄は、夢だった店を持つ道へと歩み出している。", "target_word": "歩み出して", "complexity_tier": "T3", "furigana": "会社[かいしゃ]を辞[や]めた兄[あに]は、夢[ゆめ]だった店[みせ]を持[も]つ道[みち]へと歩[あゆ]み出[だ]している。", "sentence_source": "generated"}, {"text": "怖がらずに歩み出せば、道は自然と先へ続いていくものだ。", "target_word": "歩み出せば", "complexity_tier": "T3", "furigana": "怖[こわ]がらずに歩[あゆ]み出[だ]せば、道[みち]は自然[しぜん]と先[さき]へ続[つづ]いていくものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歩み出す", "label": "基本形"}, {"form": "歩み出さない", "label": "ない形"}, {"form": "歩み出します", "label": "ます形"}, {"form": "歩み出した", "label": "た形"}, {"form": "歩み出して", "label": "て形"}, {"form": "歩み出せば", "label": "ば形"}, {"form": "歩み出そう", "label": "意志形"}], "register": "書き言葉", "sense_fingerprint": "歩み出す：歩き始める。また、一歩を踏み出して前へ進む（新しい道へ進むことにも使う）。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 退廃 (Zipf 3.08), 纏い (Zipf 2.78), 冷徹 (Zipf 3.22), 街路 (Zipf 3.15)']::text[], '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52918, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歩み出そう", "is_correct": true, "explanation": "「〜そうではないか」は意志形に接続する。「さあ、…冷徹な街路へ歩み出そうではないか」の呼びかけに合う。"}, {"text": "歩み出して", "is_correct": false, "explanation": "て形は文を言い切れず、「〜ではないか」にも続かない。"}, {"text": "歩み出せば", "is_correct": false, "explanation": "ば形は条件節で、「〜ではないか」の述語にならない。"}, {"text": "歩み出します", "is_correct": false, "explanation": "丁寧語は「〜そうではないか」の呼びかけと接続せず、文が成立しない。"}], "explanations": {"歩み出そう": "「〜そうではないか」は意志形に接続する。「さあ、…冷徹な街路へ歩み出そうではないか」の呼びかけに合う。", "歩み出して": "て形は文を言い切れず、「〜ではないか」にも続かない。", "歩み出せば": "ば形は条件節で、「〜ではないか」の述語にならない。", "歩み出します": "丁寧語は「〜そうではないか」の呼びかけと接続せず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "歩み出そう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渋滞が解けて、車の列がゆっくりと歩み出した。", "explanation": "ここは〈進む〉の意味。歩み出すは人や動物が歩き始める動作で、車の列には使わない。"}, {"text": "休日は一日中、公園を歩み出していた。", "explanation": "ここは〈歩き回る〉の意味。歩み出すは歩き始めることで、継続して歩き回る様子には合わない。"}, {"text": "止まっていた古い時計が、ついに歩み出した。", "explanation": "ここは〈動き出す〉の意味。歩み出すは歩く主体（人・動物）に限られ、時計には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52918, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歩み出した", "is_correct": true, "explanation": "過去の出来事を述べる「た形」。「祖父は…庭へと歩み出した」と文を言い切れる。"}, {"text": "歩み出し", "is_correct": false, "explanation": "連用形は文を言い切れず、「庭へと歩み出し。」は成立しない。"}, {"text": "歩み出せ", "is_correct": false, "explanation": "命令形は命令になり、祖父の久しぶりの外出を述べる地の文と合わない。"}, {"text": "歩み出される", "is_correct": false, "explanation": "自動詞は受身にならず、「歩み出される」は成り立たない。"}], "explanations": {"歩み出した": "過去の出来事を述べる「た形」。「祖父は…庭へと歩み出した」と文を言い切れる。", "歩み出し": "連用形は文を言い切れず、「庭へと歩み出し。」は成立しない。", "歩み出せ": "命令形は命令になり、祖父の久しぶりの外出を述べる地の文と合わない。", "歩み出される": "自動詞は受身にならず、「歩み出される」は成り立たない。"}, "sentence_index": 6, "correct_answer": "歩み出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合図と同時に、ランナーたちは一斉に歩み出した。", "explanation": "ここは〈走り出す〉の意味。ランナーは走る人なので、歩き始めることを表す歩み出すは合わない。"}, {"text": "赤ちゃんは布団の中で、やっと歩み出した。", "explanation": "ここは〈寝返りを打つ〉の意味。布団の中の動きは寝返りで表し、歩み出すは歩く動作なので合わない。"}, {"text": "夕暮れになって、空の色が静かに歩み出した。", "explanation": "ここは〈変わる〉の意味。歩み出すは人や動物の動作を指し、空の色には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52918, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい町へ、今日こそ歩み出そうだと決めた。", "corrected_sentence": "新しい町へ、今日こそ歩み出そうと決めた。", "error_description": "意志形「歩み出そう」に「だ」を付けた誤り。意志形は「と」で続けて「歩み出そうと決めた」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "歩み出した", "is_correct": true, "explanation": "文中の形そのもの。過去を表す「た形」で、「彼はゆっくりと扉に向かって歩み出した」と言い切る。"}, {"text": "歩み出して", "is_correct": false, "explanation": "て形では文を言い切れず、「歩み出して。」で終わらない。"}, {"text": "歩み出せば", "is_correct": false, "explanation": "ば形は条件節で、文末の述語にならない。"}, {"text": "歩み出さない", "is_correct": false, "explanation": "ない形にすると「歩き出さなかった」という否定になり、文の内容と逆になる。"}], "correct_form": "歩み出した", "base_form": "歩み出す", "form_label": "た形", "sentence_index": 1, "explanations": {"歩み出した": "文中の形そのもの。過去を表す「た形」で、「彼はゆっくりと扉に向かって歩み出した」と言い切る。", "歩み出して": "て形では文を言い切れず、「歩み出して。」で終わらない。", "歩み出せば": "ば形は条件節で、文末の述語にならない。", "歩み出さない": "ない形にすると「歩き出さなかった」という否定になり、文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52918, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勇気を出して歩み出すば、道は開ける。", "corrected_sentence": "勇気を出して歩み出せば、道は開ける。", "error_description": "「歩み出す」の仮定形の誤り。「す」で終わる五段動詞の仮定形は「歩み出せば」で、「歩み出すば」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "歩み出さない", "is_correct": true, "explanation": "文中の形そのもの。ない形で「歩み出さない人には」と名詞を修飾する。"}, {"text": "歩み出そう", "is_correct": false, "explanation": "意志形は名詞を直接修飾できず、「歩み出そう人」は成り立たない。"}, {"text": "歩み出せ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、「歩み出せ人」は成り立たない。"}, {"text": "歩み出し", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「歩み出し人」は成り立たない。"}], "correct_form": "歩み出さない", "base_form": "歩み出す", "form_label": "ない形", "sentence_index": 7, "explanations": {"歩み出さない": "文中の形そのもの。ない形で「歩み出さない人には」と名詞を修飾する。", "歩み出そう": "意志形は名詞を直接修飾できず、「歩み出そう人」は成り立たない。", "歩み出せ": "命令形は名詞を修飾できず、「歩み出せ人」は成り立たない。", "歩み出し": "連用形は名詞を直接修飾できず、「歩み出し人」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52925, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置に合う助詞。"}, {"text": "に", "is_correct": false, "explanation": "「に」はここでは文法的に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」はここでは文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」はここでは文法的に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置に合う助詞。", "に": "「に」はここでは文法的に合わない。", "と": "「と」はここでは文法的に合わない。", "へ": "「へ」はここでは文法的に合わない。"}, "error_tags": {"に": "wrong_particle", "と": "wrong_particle", "へ": "wrong_particle"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '055b2145-1f90-4d76-a44b-cd27e88baf3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
