INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52925, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを、もっとよくするために、何度も練習したり、工夫したりすること。", "primary_collocate": null, "pronunciation": "みがきあげる", "ipa": "miɡakiaɡeɾɯ", "syllable_count": 6, "sentences": [{"text": "歌を磨き上げる。", "target_word": "磨き上げる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "劇を磨き上げた。", "target_word": "磨き上げた", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "発表を磨き上げました。", "target_word": "磨き上げました", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼は毎日、泳ぎを磨き上げます。", "target_word": "磨き上げます", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "友達と練習して、ダンスを磨き上げている。", "target_word": "磨き上げている", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "何度も直して、文章を磨き上げた。", "target_word": "磨き上げた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "もっと練習すれば、自分のプレーを磨き上げられる。", "target_word": "磨き上げられる", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "先生に教わって磨き上げた発表は、大成功だった。", "target_word": "磨き上げた", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "チーム全員で工夫を重ねながら、大会に向けて演技を磨き上げていった。", "target_word": "磨き上げて", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "何度も練習や工夫を繰り返して、スピーチを少しずつ磨き上げるのが大切だ。", "target_word": "磨き上げる", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "磨き上げた", "label": "活用"}, {"form": "磨き上げて", "label": "活用"}, {"form": "磨き上げない", "label": "活用"}, {"form": "磨き上げられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 練習や工夫で何かをよりよくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b16e14-36e1-4b2f-ae25-fea49fdf019b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52925, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磨き上げる", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "「食べる」は形は合うが意味が合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "「洗う」は形は合うが意味が合わない。"}, {"text": "切る", "is_correct": false, "explanation": "「切る」は形は合うが意味が合わない。"}], "explanations": {"磨き上げる": "正解。文脈に合う。", "食べる": "「食べる」は形は合うが意味が合わない。", "洗う": "「洗う」は形は合うが意味が合わない。", "切る": "「切る」は形は合うが意味が合わない。"}, "sentence_index": 0, "correct_answer": "磨き上げる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日、泳ぎに磨き上げます。", "explanation": "「泳ぎ」には「を」を使う。「に」を使うのは誤り。"}, {"text": "彼は毎日、お茶を磨き上げます。", "explanation": "「お茶」は練習や工夫で磨く対象ではなく、「磨き上げる」と合わない。"}, {"text": "彼は毎日、泳ぎを磨き上げるます。", "explanation": "「磨き上げる」に「ます」を直接つけるのは誤り。活用の誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '055b2145-1f90-4d76-a44b-cd27e88baf3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52925, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磨き上げられる", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "食べられる", "is_correct": false, "explanation": "「食べられる」は形は合うが意味が合わない。"}, {"text": "洗える", "is_correct": false, "explanation": "「洗える」は形は合うが意味が合わない。"}, {"text": "切れる", "is_correct": false, "explanation": "「切れる」は形は合うが意味が合わない。"}], "explanations": {"磨き上げられる": "正解。文脈に合う。", "食べられる": "「食べられる」は形は合うが意味が合わない。", "洗える": "「洗える」は形は合うが意味が合わない。", "切れる": "「切れる」は形は合うが意味が合わない。"}, "sentence_index": 6, "correct_answer": "磨き上げられる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "何度も練習や工夫を繰り返して、スピーチに少しずつ磨き上げるのが大切だ。", "explanation": "「スピーチ」には「を」を使う。「に」を使うのは誤り。"}, {"text": "何度も練習や工夫を繰り返して、空気を少しずつ磨き上げるのが大切だ。", "explanation": "「空気」は練習や工夫で磨く対象ではなく、「磨き上げる」と合わない。"}, {"text": "何度も練習や工夫を繰り返して、雨を少しずつ磨き上げるのが大切だ。", "explanation": "「雨」は練習や工夫で磨く対象ではなく、「磨き上げる」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '055b2145-1f90-4d76-a44b-cd27e88baf3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52925, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達とダンスで磨き上げている。", "corrected_sentence": "友達とダンスを磨き上げている。", "error_description": "「磨き上げる」の対象は「を」で示す。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "磨き上げた", "is_correct": true, "explanation": "正解。この位置に合う形。"}, {"text": "磨き上げれば", "is_correct": false, "explanation": "この位置では使えない形。"}, {"text": "磨き上げさせ", "is_correct": false, "explanation": "使役の連用形で、文をここで終えることはできない。"}, {"text": "磨き上げず", "is_correct": false, "explanation": "この位置では使えない形。"}], "correct_form": "磨き上げた", "base_form": "磨き上げる", "form_label": "過去形", "sentence_index": 1, "explanations": {"磨き上げた": "正解。この位置に合う形。", "磨き上げれば": "この位置では使えない形。", "磨き上げさせ": "使役の連用形で、文をここで終えることはできない。", "磨き上げず": "この位置では使えない形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '055b2145-1f90-4d76-a44b-cd27e88baf3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
