INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52926, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事をより完全な状態にするために、手を加えて美しくしたり、技術を高めたりすること。", "primary_collocate": null, "pronunciation": "みがきあげる", "ipa": "miɡakiaɡeɾɯ", "syllable_count": 6, "sentences": [{"text": "古来、人類は植物の生命力を繊維に宿す術を磨き上げてきた。", "target_word": "磨き上げて", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "刀を磨き上げる。", "target_word": "磨き上げる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "器を磨き上げる。", "target_word": "磨き上げる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "職人は刀を磨き上げました。", "target_word": "磨き上げました", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毎日、技術を磨き上げます。", "target_word": "磨き上げます", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "時間をかけて、木の器を磨き上げている。", "target_word": "磨き上げている", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手を加えて磨き上げた家具が並ぶ。", "target_word": "磨き上げた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "長い修業で磨き上げられた技に、誰もが驚いた。", "target_word": "磨き上げられた", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "職人が磨き上げた刀は、まるで鏡のように光る。", "target_word": "磨き上げた", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "熟練の職人が長い年月をかけて磨き上げた技術は、今も多くの人に受け継がれている。", "target_word": "磨き上げた", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "磨き上げた", "label": "活用"}, {"form": "磨き上げて", "label": "活用"}, {"form": "磨き上げない", "label": "活用"}, {"form": "磨き上げられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 手を加えて美しく仕上げ技を高める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b16e14-36e1-4b2f-ae25-fea49fdf019b') ON CONFLICT (sens