INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52928, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が次第に変化していくこと。特に、季節の移り変わり。", "primary_collocate": null, "pronunciation": "うつろい", "ipa": "ɯt͡sɯɾoi", "syllable_count": 4, "sentences": [{"text": "まず、季節の移ろいと共に採取された植物は、熱と水によってその奥底に秘められた色素を解放される。", "target_word": "移ろい", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "この一連の作業は、移ろいやすい自然の産物を、人間の手によって恒久の美へと昇華させる、高度な技術と美意識の結晶なのである。", "target_word": "移ろい", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "季節の移ろいだ。", "target_word": "移ろい", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋の移ろいを見る。", "target_word": "移ろい", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "町の移ろいを感じました。", "target_word": "移ろい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "季節の移ろいが好きです。", "target_word": "移ろい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古い通りの移ろいを写真に撮っている。", "target_word": "移ろい", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "時代の移ろいとともに、町の姿も変わった。", "target_word": "移ろい", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "季節の移ろいを感じると、時間の流れを思う。", "target_word": "移ろい", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "心の移ろいは、目に見えにくいものだが、詩人はそれを言葉にしてきた。", "target_word": "移ろい", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "移ろう", "label": "派生"}, {"form": "移ろいやすい", "label": "派生"}, {"form": "移ろいゆく", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事や季節が次第に変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b16e14-36e1-4b2f-ae25-fea49fdf019b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
