INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52929, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "同じだということ。何かと何かが、全く同じくらいだ。", "primary_collocate": null, "pronunciation": "ひとしい", "ipa": "çitoɕiː", "syllable_count": 4, "sentences": [{"text": "人は皆、等しい。", "target_word": "等しい", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "二人の背は等しい。", "target_word": "等しい", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "ケーキを等しく分けました。", "target_word": "等しく", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兄と私のお小遣いは等しいです。", "target_word": "等しい", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全員に等しく配っている。", "target_word": "等しく", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二人の点数が等しくて、引き分けだった。", "target_word": "等しくて", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全員が等しく扱われるべきだ。", "target_word": "等しく", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "もし値段が等しければ、近い店で買うだろう。", "target_word": "等しければ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "子どもたちには、生まれや育ちに関係なく、等しく学ぶ機会が与えられるべきだ。", "target_word": "等しく", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "二つの店の味はほぼ等しく、どちらを選ぶか迷ってしまった。", "target_word": "等しく", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "等しく", "label": "活用"}, {"form": "等しかった", "label": "活用"}, {"form": "等しければ", "label": "活用"}, {"form": "等しさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 同じであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b16e14-36e1-4b2f-ae25-fea49fdf019b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_