INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52929, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "等しい", "is_correct": true, "explanation": "正解。「ひとしい」と読む。"}, {"text": "久しい", "is_correct": false, "explanation": "「ひさしい」。音が一つだけ違う別の語。"}, {"text": "一入", "is_correct": false, "explanation": "「ひとしお」。音が一つだけ違う別の語。"}, {"text": "愛しい", "is_correct": false, "explanation": "「いとしい」。音が一つだけ違う別の語。"}], "explanations": {"等しい": "正解。「ひとしい」と読む。", "久しい": "「ひさしい」。音が一つだけ違う別の語。", "一入": "「ひとしお」。音が一つだけ違う別の語。", "愛しい": "「いとしい」。音が一つだけ違う別の語。"}, "sentence_index": null, "correct_answer": "等しい"}, "level_3": {"options": [{"text": "等しい", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "四角い", "is_correct": false, "explanation": "「四角い」は形は合うが意味が合わない。"}, {"text": "狭い", "is_correct": false, "explanation": "「狭い」は形は合うが意味が合わない。"}, {"text": "酸っぱい", "is_correct": false, "explanation": "「酸っぱい」は形は合うが意味が合わない。"}], "explanations": {"等しい": "正解。文脈に合う。", "四角い": "「四角い」は形は合うが意味が合わない。", "狭い": "「狭い」は形は合うが意味が合わない。", "酸っぱい": "「酸っぱい」は形は合うが意味が合わない。"}, "sentence_index": 0, "correct_answer": "等しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄と私のお小遣いは等しくです。", "explanation": "「です」の前は「等しい」。「等しくです」は活用の誤り。"}, {"text": "お小遣いは一人だけで等しいです。", "explanation": "「等しい」は二つ以上を比べる語。比べる相手がなく語義の誤り。"}, {"text": "兄と私のお小遣いは等しいでした。", "explanation": "「等しい」に「でした」をつけるのは誤り。過去は「等しかった」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '055b2145-1f90-4d76-a44b-cd27e88baf3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
