INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52932, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "布や糸、紙などを染めるために使う色のついた材料。", "primary_collocate": null, "pronunciation": "せんりょう", "ipa": "seɴɾʲoː", "syllable_count": 4, "sentences": [{"text": "天然染料による染色は、単なる化学的操作の連鎖ではなく、素材と対話する儀礼にも等しい。", "target_word": "染料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "染料で布を染める。", "target_word": "染料", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "青い染料を買う。", "target_word": "染料", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "染料を水に溶かしました。", "target_word": "染料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この染料は植物から作ります。", "target_word": "染料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糸を染料に漬けている。", "target_word": "染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草木から取った染料で布を染めた。", "target_word": "染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染料が布に染みこむまで、一晩待った。", "target_word": "染料", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "化学染料と天然染料では、色の出方が違う。", "target_word": "染料", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "藍の葉から作った染料は、時間がたつほど深い青色に変わっていく。", "target_word": "染料", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然染料", "label": "派生"}, {"form": "化学染料", "label": "派生"}, {"form": "植物染料", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 布や糸を染める色つきの材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b16e14-36e1-4b2f-ae25-fea49fdf019b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
