INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52935, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自然にある草や花などを、とって集めること。", "primary_collocate": null, "pronunciation": "さいしゅ", "ipa": "saiɕɯ", "syllable_count": 3, "sentences": [{"text": "山で薬草を採取する。", "target_word": "採取", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "花の採取は禁止されています。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "母は野原で草を採取した。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "この花は採取してはいけません。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "春になると山菜の採取に出かける。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "子どもたちは花の採取を楽しんだ。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "野草を採取して、お茶を作る。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "採取した草を、かごに入れた。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "採取のときは、手袋をつけます。", "target_word": "採取", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "祖父は毎年、山で野草の採取をする。", "target_word": "採取", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "採取する", "label": "活用"}, {"form": "採取した", "label": "活用"}, {"form": "採取される", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 野草や花を摘んで集めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CO