INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52936, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "採取", "is_correct": true, "explanation": "季節とともに自然から集めて取った植物という意味に合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、植物を約束するという意味が合わない。"}, {"text": "反対", "is_correct": false, "explanation": "形は合うが、植物を反対するという意味が合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが、植物を欠席するという意味は成り立たない。"}], "explanations": {"採取": "季節とともに自然から集めて取った植物という意味に合う。", "約束": "形は合うが、植物を約束するという意味が合わない。", "反対": "形は合うが、植物を反対するという意味が合わない。", "欠席": "形は合うが、植物を欠席するという意味は成り立たない。"}, "sentence_index": 0, "correct_answer": "採取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、新しい靴を採取して、家で履いた。", "explanation": "採取は自然のものや試料を集めて取ることで、店で物を買う意味には使えない。"}, {"text": "彼は部屋の電気を採取して、暗くした。", "explanation": "電気を消す動作に採取は使えない。採取は集めて取ることを表す。"}, {"text": "兄は大きな声で歌を採取した。", "explanation": "歌うことを採取とは言わない。採取は試料や産物を集めることだ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52936, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "採取", "is_correct": true, "explanation": "化石を集めて取ることに許可が必要、という意味に合う。"}, {"text": "反対", "is_correct": false, "explanation": "形は合うが、化石の反対という意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、化石の約束という意味が合わない。"}, {"text": "返事", "is_correct": false, "explanation": "形は合うが、化石の返事という意味が合わない。"}], "explanations": {"採取": "化石を集めて取ることに許可が必要、という意味に合う。", "反対": "形は合うが、化石の反対という意味が合わない。", "約束": "形は合うが、化石の約束という意味が合わない。", "返事": "形は合うが、化石の返事という意味が合わない。"}, "sentence_index": 6, "correct_answer": "採取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で友達を採取して、一緒に行った。", "explanation": "人を迎える意味に採取は使えない。採取は物を集めて取ることだ。"}, {"text": "彼は毎日、日記を採取している。", "explanation": "日記を書くことを採取とは言わない。"}, {"text": "雨が採取して、道がぬれた。", "explanation": "雨は採取する主体にならず、降る意味にも使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
