INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52937, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「解放の時間」と名詞をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「解放を時間」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「解放へ時間」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「解放と時間になった」は文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「解放の時間」と名詞をつなぐ。", "を": "「解放を時間」は文法的に成り立たない。", "へ": "「解放へ時間」は文法的に成り立たない。", "と": "「解放と時間になった」は文として成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "accompaniment"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "束縛", "is_correct": true, "explanation": "自由を制限する意味で、解放の反対。"}, {"text": "解除", "is_correct": false, "explanation": "制限をなくす意味で、反対語ではない。"}, {"text": "開放", "is_correct": false, "explanation": "開け放つ意味で、反対語ではない。"}, {"text": "脱出", "is_correct": false, "explanation": "抜け出す意味で、反対語ではない。"}], "correct_answer": "束縛", "explanations": {"束縛": "自由を制限する意味で、解放の反対。", "解除": "制限をなくす意味で、反対語ではない。", "開放": "開け放つ意味で、反対語ではない。", "脱出": "抜け出す意味で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52937, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが自由になること。", "primary_collocate": null, "pronunciation": "かいほう", "ipa": "kaihoː", "syllable_count": 4, "sentences": [{"text": "解放の日がやっと来た。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "試験が終わって、解放された気分だ。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "休みは、仕事からの解放だ。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "解放を待つ人たちが、門の前に集まった。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "彼は長い病気からの解放を喜んだ。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "戦争からの解放を、国民は祝った。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "心の解放が、いちばん大切だ。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "長い会議が終わり、解放の時間になった。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "解放されて、彼は海へ走った。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "捕虜の解放が決まったと、ニュースで知った。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "解放する", "label": "活用"}, {"form": "解放した", "label": "活用"}, {"form": "解放される", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 何かが自由になること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') 