INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52937, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解放", "is_correct": true, "explanation": "かいほう。これが正解。"}, {"text": "解剖", "is_correct": false, "explanation": "かいぼう。ほがぼに変わる清濁の違い。"}, {"text": "裁縫", "is_correct": false, "explanation": "さいほう。かがさに変わる。"}, {"text": "大砲", "is_correct": false, "explanation": "たいほう。かがたに変わる。"}, {"text": "回答", "is_correct": false, "explanation": "かいとう。ほがとに変わる。"}], "explanations": {"解放": "かいほう。これが正解。", "解剖": "かいぼう。ほがぼに変わる清濁の違い。", "裁縫": "さいほう。かがさに変わる。", "大砲": "たいほう。かがたに変わる。", "回答": "かいとう。ほがとに変わる。"}, "sentence_index": null, "correct_answer": "解放"}, "level_3": {"options": [{"text": "解放", "is_correct": true, "explanation": "自由になる日がやっと来たという意味に合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、「鉛筆の日がやっと来た」は意味をなさない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、「砂糖の日がやっと来た」は意味をなさない。"}, {"text": "階段", "is_correct": false, "explanation": "形は合うが、「階段の日がやっと来た」は意味をなさない。"}], "explanations": {"解放": "自由になる日がやっと来たという意味に合う。", "鉛筆": "形は合うが、「鉛筆の日がやっと来た」は意味をなさない。", "砂糖": "形は合うが、「砂糖の日がやっと来た」は意味をなさない。", "階段": "形は合うが、「階段の日がやっと来た」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "解放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "解放を買う人たちが、店の前に集まった。", "explanation": "解放は買えるものではない。買う対象としての使い方が誤り。"}, {"text": "解放を食べる人たちが、机の前に座った。", "explanation": "解放は食べるものではない。食べる対象としての使い方が誤り。"}, {"text": "解放を切る人たちが、門の前に集まった。", "explanation": "解放は切るものではなく、切るという動作と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52937, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "解放", "is_correct": true, "explanation": "かいほう。これが正解。"}, {"text": "回廊", "is_correct": false, "explanation": "かいろう。ほがろに変わる。"}, {"text": "開講", "is_correct": false, "explanation": "かいこう。ほがこに変わる。"}, {"text": "財宝", "is_correct": false, "explanation": "ざいほう。かがざに変わる（一モーラの違い）。"}], "explanations": {"解放": "かいほう。これが正解。", "回廊": "かいろう。ほがろに変わる。", "開講": "かいこう。ほがこに変わる。", "財宝": "ざいほう。かがざに変わる（一モーラの違い）。"}, "sentence_index": null, "correct_answer": "解放"}, "level_3": {"options": [{"text": "解放", "is_correct": true, "explanation": "心が自由になることが大切、という意味に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "形は合うが、心の翻訳が大切という意味が合わない。"}, {"text": "宿泊", "is_correct": false, "explanation": "形は合うが、心の宿泊が大切という意味が合わない。"}, {"text": "注文", "is_correct": false, "explanation": "形は合うが、心の注文が大切という意味が合わない。"}], "explanations": {"解放": "心が自由になることが大切、という意味に合う。", "翻訳": "形は合うが、心の翻訳が大切という意味が合わない。", "宿泊": "形は合うが、心の宿泊が大切という意味が合わない。", "注文": "形は合うが、心の注文が大切という意味が合わない。"}, "sentence_index": 6, "correct_answer": "解放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "果物の解放が決まったと、ニュースで知った。", "explanation": "果物は自由になる対象ではなく、解放の使い方が合わない。"}, {"text": "捕虜の解放を飲んだと、ニュースで知った。", "explanation": "解放は飲めるものではなく、使い方が合わない。"}, {"text": "捕虜の解放が赤いと、ニュースで知った。", "explanation": "解放は色を表さず、赤いとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
