INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52938, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "解放する対象「人質」を示す助詞。"}, {"text": "に", "is_correct": false, "explanation": "「人質に解放した」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「人質へ解放した」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「人質の解放した」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "解放する対象「人質」を示す助詞。", "に": "「人質に解放した」は文法的に成り立たない。", "へ": "「人質へ解放した」は文法的に成り立たない。", "の": "「人質の解放した」は文法的に成り立たない。"}, "error_tags": {"に": "target_or_place", "へ": "direction", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拘束", "is_correct": true, "explanation": "自由を奪う意味で、解放の反対。"}, {"text": "釈放", "is_correct": false, "explanation": "自由にする意味で、解放の類義語。"}, {"text": "解除", "is_correct": false, "explanation": "制限をなくす意味で、反対語ではない。"}, {"text": "開放", "is_correct": false, "explanation": "開け放つ意味で、反対語ではない。"}], "correct_answer": "拘束", "explanations": {"拘束": "自由を奪う意味で、解放の反対。", "釈放": "自由にする意味で、解放の類義語。", "解除": "制限をなくす意味で、反対語ではない。", "開放": "開け放つ意味で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52938, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "解放される元の「恐怖」を示す助詞。"}, {"text": "と", "is_correct": false, "explanation": "「恐怖と解放された」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「恐怖へ解放された」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「恐怖の解放された」は文法的に成り立たない。"}], "correct_answer": "から", "explanations": {"から": "解放される元の「恐怖」を示す助詞。", "と": "「恐怖と解放された」は文法的に成り立たない。", "へ": "「恐怖へ解放された」は文法的に成り立たない。", "の": "「恐怖の解放された」は文法的に成り立たない。"}, "error_tags": {"と": "accompaniment", "へ": "direction", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "束縛", "is_correct": true, "explanation": "自由を制限する意味で、解放の反対。"}, {"text": "自由", "is_correct": false, "explanation": "解放の結果の状態で、反対語ではない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりをやめる意味で、反対語ではない。"}, {"text": "脱出", "is_correct": false, "explanation": "抜け出す意味で、反対語ではない。"}], "correct_answer": "束縛", "explanations": {"束縛": "自由を制限する意味で、解放の反対。", "自由": "解放の結果の状態で、反対語ではない。", "解散": "集まりをやめる意味で、反対語ではない。", "脱出": "抜け出す意味で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52938, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "束縛や制限を取り除いて、自由にすること。", "primary_collocate": null, "pronunciation": "かいほう", "ipa": "kaihoː", "syllable_count": 4, "sentences": [{"text": "まず、季節の移ろいと共に採取された植物は、熱と水によってその奥底に秘められた色素を解放される。", "target_word": "解放", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "警察は人質を解放した。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "犯人は人質の解放を約束した。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "長い仕事から解放されて、ほっとした。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "王は奴隷を解放する。", "target_word": "解放", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "彼女は不安から解放された。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "捕まっていた動物が解放された。", "target_word": "解放", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "戦争が終わり、人々は恐怖から解放された。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "試験が終わって、解放の喜びを味わう。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "自由な時間は、心を解放してくれる。", "target_word": "解放", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "解放する", "label": "活用"}, {"form": "解放した", "label": "活用"}, {"form": "解放される", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 束縛を取り除き自由にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
