INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52939, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水のような、さらさらしたもの。", "primary_collocate": null, "pronunciation": "えき", "ipa": "eki", "syllable_count": 2, "sentences": [{"text": "さらさらした液が、手についた。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "液が服にこぼれてしまった。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "この液は、水のように流れる。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "机の上の液を、布でふき取った。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "透明な液が、ボトルに入っている。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "洗う前に、液を少し薄める。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "液が足りなくなったので、足した。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "白い液が机の上に広がった。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "液をスポンジにつけて、拭く。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "さらさらの液は、すぐに流れ落ちる。", "target_word": "液", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 水のようにさらさらした液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_