INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52939, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "液", "is_correct": true, "explanation": "えき。正解の語。"}, {"text": "息", "is_correct": false, "explanation": "いき。最初の音が違う。"}, {"text": "秋", "is_correct": false, "explanation": "あき。最初の音が違う。"}, {"text": "円", "is_correct": false, "explanation": "えん。最後の音が違う。"}, {"text": "餌", "is_correct": false, "explanation": "えさ。最後の音が違う。"}], "explanations": {"液": "えき。正解の語。", "息": "いき。最初の音が違う。", "秋": "あき。最初の音が違う。", "円": "えん。最後の音が違う。", "餌": "えさ。最後の音が違う。"}, "sentence_index": null, "correct_answer": "液"}, "level_3": {"options": [{"text": "液", "is_correct": true, "explanation": "さらさらした液が手についた、で自然。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、さらさらした机が手につくのは意味が合わない。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが、歌が手につくのは意味が合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "形は合うが、さらさらした椅子が手につくのは意味が合わない。"}], "explanations": {"液": "さらさらした液が手についた、で自然。", "机": "形は合うが、さらさらした机が手につくのは意味が合わない。", "歌": "形は合うが、歌が手につくのは意味が合わない。", "椅子": "形は合うが、さらさらした椅子が手につくのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "液"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上の液を、はさみで切って捨てた。", "explanation": "さらさらした液ははさみで切れないので、使い方が誤り。"}, {"text": "机の上の液を、本棚に立てて並べた。", "explanation": "液は形がなく立てて並べられないので、使い方が誤り。"}, {"text": "机の上の液を、ハンマーでたたいて割った。", "explanation": "液は固体ではなく割れないので、使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
