INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52940, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "液体。流れる性質を持つ、固体でも気体でもない物質。", "primary_collocate": null, "pronunciation": "えき", "ipa": "eki", "syllable_count": 2, "sentences": [{"text": "しかし、抽出された液は未だ不安定な色彩に過ぎず、そのままでは時間と共に退色してしまう。", "target_word": "液", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "容器に入れた液を、ゆっくり混ぜる。", "target_word": "液", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この液は、固体でも気体でもない。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "傷口から透明な液が出てきた。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "液を加熱すると、色が変わる。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "実験では、青い液を試験管に注いだ。", "target_word": "液", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "液の温度を、毎分測った。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "植物の茎を切ると、白い液が出る。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "抽出した液をろ過して、不純物を取り除いた。", "target_word": "液", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この液は、水よりも粘りがある。", "target_word": "液", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 流れる性質を持つ液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content,