INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52940, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "液", "is_correct": true, "explanation": "えき。正解の語。"}, {"text": "息", "is_correct": false, "explanation": "いき。最初の音が違う。"}, {"text": "秋", "is_correct": false, "explanation": "あき。最初の音が違う。"}, {"text": "円", "is_correct": false, "explanation": "えん。最後の音が違う。"}, {"text": "餌", "is_correct": false, "explanation": "えさ。最後の音が違う。"}], "explanations": {"液": "えき。正解の語。", "息": "いき。最初の音が違う。", "秋": "あき。最初の音が違う。", "円": "えん。最後の音が違う。", "餌": "えさ。最後の音が違う。"}, "sentence_index": null, "correct_answer": "液"}, "level_3": {"options": [{"text": "液", "is_correct": true, "explanation": "抽出されたものが液で、文脈に合う。"}, {"text": "石", "is_correct": false, "explanation": "形は合うが、抽出された石は意味が合わない。"}, {"text": "紙", "is_correct": false, "explanation": "形は合うが、抽出された紙は意味が合わない。"}, {"text": "木", "is_correct": false, "explanation": "形は合うが、抽出された木は意味が合わない。"}], "explanations": {"液": "抽出されたものが液で、文脈に合う。", "石": "形は合うが、抽出された石は意味が合わない。", "紙": "形は合うが、抽出された紙は意味が合わない。", "木": "形は合うが、抽出された木は意味が合わない。"}, "sentence_index": 0, "correct_answer": "液"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に、固い液が積まれている。", "explanation": "液は流れる性質を持つので、固くて「積む」ものとして使うのは誤り。"}, {"text": "液を糸でしばって、箱に入れた。", "explanation": "液は形がなく流れるので、糸でしばるという使い方は誤り。"}, {"text": "この液は固体なので、ハンマーで割れる。", "explanation": "液は固体でも気体でもない物質であり、固体とするのは意味が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52940, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "液", "is_correct": true, "explanation": "えき。正解の語。"}, {"text": "襟", "is_correct": false, "explanation": "えり。最後の音が違う。"}, {"text": "沖", "is_correct": false, "explanation": "おき。最初の音が違う。"}, {"text": "海老", "is_correct": false, "explanation": "えび。最後の音が違う。"}, {"text": "浮き", "is_correct": false, "explanation": "うき。最初の音が違う。"}], "explanations": {"液": "えき。正解の語。", "襟": "えり。最後の音が違う。", "沖": "おき。最初の音が違う。", "海老": "えび。最後の音が違う。", "浮き": "うき。最初の音が違う。"}, "sentence_index": null, "correct_answer": "液"}, "level_3": {"options": [{"text": "液", "is_correct": true, "explanation": "液の温度を測るのは自然。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、約束の温度は意味が合わない。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが、歌の温度は意味が合わない。"}, {"text": "絵", "is_correct": false, "explanation": "形は合うが、絵の温度を測るのは意味が合わない。"}], "explanations": {"液": "液の温度を測るのは自然。", "約束": "形は合うが、約束の温度は意味が合わない。", "歌": "形は合うが、歌の温度は意味が合わない。", "絵": "形は合うが、絵の温度を測るのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "液"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この液は気体なので、見えないまま空へ消える。", "explanation": "液は気体ではないので、気体として使うのは意味が誤り。"}, {"text": "液を紙にとめるため、ピンで刺した。", "explanation": "液は形がなく、ピンで刺してとめられないので使い方が誤り。"}, {"text": "この液は、白い花が咲く植物の名前だ。", "explanation": "液は物質の状態を表す語で、植物の名前の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
