INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52941, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "布を染める時に、色が落ちないようにするための特別な薬を使うこと。", "primary_collocate": null, "pronunciation": "ばいせん", "ipa": "baisen", "syllable_count": 4, "sentences": [{"text": "布を染める前に、媒染をする。", "target_word": "媒染", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "媒染をすると、色が落ちにくくなる。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "母は毎回、きちんと媒染をする。", "target_word": "媒染", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "媒染は、色を守るための大切な作業だ。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この布は、媒染してから染めた。", "target_word": "媒染", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "媒染の薬を、水にとかした。", "target_word": "媒染", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "媒染をしないと、洗ったときに色が落ちる。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "先生に、媒染のやり方を教えてもらった。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "草木染めでは、媒染が欠かせない。", "target_word": "媒染", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "媒染のあとで、布を水で洗った。", "target_word": "媒染", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "媒染する", "label": "活用"}, {"form": "媒染した", "label": "活用"}, {"form": "媒染剤", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 色落ちを防ぐ薬を布に使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-