INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52941, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "媒染", "is_correct": true, "explanation": "「ばいせん」で、見出し語と同じ音です。"}, {"text": "配線", "is_correct": false, "explanation": "「はいせん」で、最初の音が「ば」ではなく「は」です。"}, {"text": "改選", "is_correct": false, "explanation": "「かいせん」で、最初の音が「ば」ではなく「か」です。"}, {"text": "売店", "is_correct": false, "explanation": "「ばいてん」で、三つ目の音が「せ」ではなく「て」です。"}, {"text": "陪審", "is_correct": false, "explanation": "「ばいしん」で、三つ目の音が「せ」ではなく「し」です。"}], "explanations": {"媒染": "「ばいせん」で、見出し語と同じ音です。", "配線": "「はいせん」で、最初の音が「ば」ではなく「は」です。", "改選": "「かいせん」で、最初の音が「ば」ではなく「か」です。", "売店": "「ばいてん」で、三つ目の音が「せ」ではなく「て」です。", "陪審": "「ばいしん」で、三つ目の音が「せ」ではなく「し」です。"}, "sentence_index": null, "correct_answer": "媒染"}, "level_3": {"options": [{"text": "媒染", "is_correct": true, "explanation": "布を染める前に色落ちを防ぐ処理をするので、意味に合います。"}, {"text": "退色", "is_correct": false, "explanation": "退色は色がうすくなることで、染める前にする作業ではないので意味が合わない。"}, {"text": "繊維", "is_correct": false, "explanation": "形は合うが、「繊維をします」とは言わず意味が合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "形は合うが、「色彩をします」とは言わず意味が合わない。"}], "explanations": {"媒染": "布を染める前に色落ちを防ぐ処理をするので、意味に合います。", "退色": "退色は色がうすくなることで、染める前にする作業ではないので意味が合わない。", "繊維": "形は合うが、「繊維をします」とは言わず意味が合わない。", "色彩": "形は合うが、「色彩をします」とは言わず意味が合わない。"}, "sentence_index": 0, "correct_answer": "媒染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "媒染をして、部屋の温度を下げた。", "explanation": "媒染は布の色落ちを防ぐ作業で、部屋の温度とは関係がありません。"}, {"text": "毎朝、媒染を飲んで健康を保っている。", "explanation": "媒染は薬を布に使う作業で、飲むものではありません。"}, {"text": "媒染は、布を切るためのはさみだ。", "explanation": "媒染は作業の名前で、道具の名前ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52941, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "媒染", "is_correct": true, "explanation": "「ばいせん」で、見出し語と同じ音です。"}, {"text": "対戦", "is_correct": false, "explanation": "「たいせん」で、最初の音が「ば」ではなく「た」です。"}, {"text": "煤煙", "is_correct": false, "explanation": "「ばいえん」で、三つ目の音が「せ」ではなく「え」です。"}, {"text": "陪席", "is_correct": false, "explanation": "「ばいせき」で、最後の音が「ん」ではなく「き」です。"}, {"text": "開戦", "is_correct": false, "explanation": "「かいせん」で、最初の音が「ば」ではなく「か」です。"}], "explanations": {"媒染": "「ばいせん」で、見出し語と同じ音です。", "対戦": "「たいせん」で、最初の音が「ば」ではなく「た」です。", "煤煙": "「ばいえん」で、三つ目の音が「せ」ではなく「え」です。", "陪席": "「ばいせき」で、最後の音が「ん」ではなく「き」です。", "開戦": "「かいせん」で、最初の音が「ば」ではなく「か」です。"}, "sentence_index": null, "correct_answer": "媒染"}, "level_3": {"options": [{"text": "媒染", "is_correct": true, "explanation": "しないと洗ったときに色が落ちる作業なので、意味に合います。"}, {"text": "退色", "is_correct": false, "explanation": "形は合うが、退色をしないと色が落ちるという意味にならず合わない。"}, {"text": "繊維", "is_correct": false, "explanation": "形は合うが、「繊維をしない」とは言わず意味が合わない。"}, {"text": "見学", "is_correct": false, "explanation": "形は合うが、見学をしなくても色落ちには関係せず意味が合わない。"}], "explanations": {"媒染": "しないと洗ったときに色が落ちる作業なので、意味に合います。", "退色": "形は合うが、退色をしないと色が落ちるという意味にならず合わない。", "繊維": "形は合うが、「繊維をしない」とは言わず意味が合わない。", "見学": "形は合うが、見学をしなくても色落ちには関係せず意味が合わない。"}, "sentence_index": 6, "correct_answer": "媒染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "媒染に乗って、学校へ行った。", "explanation": "媒染は作業の名前で、乗り物ではないので「乗る」とは使えません。"}, {"text": "媒染を読んだら、とても面白かった。", "explanation": "媒染は作業であり、本や読み物ではないので「読む」と使えません。"}, {"text": "媒染で、庭の草を刈った。", "explanation": "媒染は道具ではなく、草を刈る手段にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.promp