INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52942, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "染色の際、染料を繊維に定着させるために媒染剤を用いる工程。またはその処理。", "primary_collocate": null, "pronunciation": "ばいせん", "ipa": "baisen", "syllable_count": 4, "sentences": [{"text": "ここで媒染という重要な工程が介在する。", "target_word": "媒染", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "媒染によって、色は布にしっかり定着する。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この工房では、媒染に鉄の溶液を使う。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "媒染の工程を経て、深い茶色に染まった。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "先に媒染してから、染料につける。", "target_word": "媒染", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "媒染を省くと、色が落ちやすくなる。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "染色家は、媒染の温度に気をつけている。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "アルミを使った媒染で、明るい黄色になる。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "媒染した布を、風通しのよい所で乾かす。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "媒染の方法によって、色合いが大きく違う。", "target_word": "媒染", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "媒染する", "label": "活用"}, {"form": "媒染した", "label": "活用"}, {"form": "媒染剤", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 染料を繊維に定着させる工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52942, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "媒染", "is_correct": true, "explanation": "「ばいせん」で、見出し語と同じ音です。"}, {"text": "配線", "is_correct": false, "explanation": "「はいせん」で、最初の音が「ば」ではなく「は」です。"}, {"text": "改選", "is_correct": false, "explanation": "「かいせん」で、最初の音が「ば」ではなく「か」です。"}, {"text": "売店", "is_correct": false, "explanation": "「ばいてん」で、三つ目の音が「せ」ではなく「て」です。"}, {"text": "陪審", "is_correct": false, "explanation": "「ばいしん」で、三つ目の音が「せ」ではなく「し」です。"}], "explanations": {"媒染": "「ばいせん」で、見出し語と同じ音です。", "配線": "「はいせん」で、最初の音が「ば」ではなく「は」です。", "改選": "「かいせん」で、最初の音が「ば」ではなく「か」です。", "売店": "「ばいてん」で、三つ目の音が「せ」ではなく「て」です。", "陪審": "「ばいしん」で、三つ目の音が「せ」ではなく「し」です。"}, "sentence_index": null, "correct_answer": "媒染"}, "level_3": {"options": [{"text": "媒染", "is_correct": true, "explanation": "染料を繊維に定着させる工程を指し、文の意味に合います。"}, {"text": "退色", "is_correct": false, "explanation": "形は合うが、退色は色があせることで、工程ではないので意味が合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "形は合うが、色彩は色合いのことで、工程ではないので意味が合わない。"}, {"text": "繊維", "is_correct": false, "explanation": "形は合うが、繊維は素材のことで、工程ではないので意味が合わない。"}], "explanations": {"媒染": "染料を繊維に定着させる工程を指し、文の意味に合います。", "退色": "形は合うが、退色は色があせることで、工程ではないので意味が合わない。", "色彩": "形は合うが、色彩は色合いのことで、工程ではないので意味が合わない。", "繊維": "形は合うが、繊維は素材のことで、工程ではないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "媒染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "媒染を食べて、体がとても温まった。", "explanation": "媒染は染色の工程であり、食べ物ではないので「食べる」とは使えません。"}, {"text": "媒染は、布をはさみで切る道具の名前だ。", "explanation": "媒染は工程・処理の名前で、道具の名前として使うのは誤りです。"}, {"text": "媒染という工程で、紙に絵が印刷された。", "explanation": "媒染は染料を繊維に定着させる処理で、印刷の意味では使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e7f52c-280f-4c6b-b3bb-5d30c4ee1874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_