INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52943, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "色がうすくなること。", "primary_collocate": null, "pronunciation": "たいしょく", "ipa": "taiɕokɯ", "syllable_count": 4, "sentences": [{"text": "夏の日差しで、シャツが退色した。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "退色すると、色がうすくなる。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "このTシャツは、もう退色している。", "target_word": "退色", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "青い服は退色しやすい。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "退色したポスターを、はがした。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "カーテンの退色が気になる。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "洗濯を重ねて、ジーンズが退色した。", "target_word": "退色", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "退色の原因は、強い日光だ。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "退色を防ぐために、日かげに干す。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "屋外の看板が、退色してきた。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "退色する", "label": "活用"}, {"form": "退色した", "label": "活用"}, {"form": "退色して", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 色がうすくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706f6503-4810-49ec-aa3e-5da3ec8990bd') ON CONFLICT (se