INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52944, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "色が薄くなったり、消えたりすること。", "primary_collocate": null, "pronunciation": "たいしょく", "ipa": "taiɕokɯ", "syllable_count": 4, "sentences": [{"text": "しかし、抽出された液は未だ不安定な色彩に過ぎず、そのままでは時間と共に退色してしまう。", "target_word": "退色", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "日光に当たると、布は少しずつ退色する。", "target_word": "退色", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "古い写真は、退色してしまった。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "退色を防ぐために、カーテンを替えた。", "target_word": "退色", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "長年の使用で、壁紙の退色が目立つ。", "target_word": "退色", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この染料は、洗うたびに退色する。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "退色した絵は、専門家が修復した。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "紫外線は、退色の原因の一つだ。", "target_word": "退色", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "作品の退色は、展示の仕方で遅らせられる。", "target_word": "退色", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "退色しにくい素材を選ぶことが大切だ。", "target_word": "退色", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "退色する", "label": "活用"}, {"form": "退色した", "label": "活用"}, {"form": "退色して", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 色が薄くなったり消えたりすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL,