, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: みがく (Zipf 1.93)']::text[], '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52945, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輝き", "is_correct": true, "explanation": "星の光るようすを表し、文に合う。"}, {"text": "昼食", "is_correct": false, "explanation": "形は合うが、星のようすとして意味が合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "形は合うが、星のようすとして意味が合わない。"}, {"text": "責任", "is_correct": false, "explanation": "形は合うが、星のようすとして意味が合わない。"}], "explanations": {"輝き": "星の光るようすを表し、文に合う。", "昼食": "形は合うが、星のようすとして意味が合わない。", "靴下": "形は合うが、星のようすとして意味が合わない。", "責任": "形は合うが、星のようすとして意味が合わない。"}, "sentence_index": 0, "correct_answer": "輝き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝日を受けて、雪が強い輝きを食べている。", "explanation": "「輝き」は光るようすで、食べるものではない。"}, {"text": "朝日を受けて、雪が強い輝きを着ている。", "explanation": "「輝き」は服ではないので、「着る」とは結びつかない。"}, {"text": "朝日を受けて、雪が強い輝きを歩いている。", "explanation": "「輝き」は場所ではなく、「歩く」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52945, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輝き", "is_correct": true, "explanation": "宝石の光るようすを確かめる文として自然に合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、ライトで確かめるものとして意味が合わない。"}, {"text": "昼食", "is_correct": false, "explanation": "形は合うが、宝石のものとして意味が合わない。"}, {"text": "返事", "is_correct": false, "explanation": "形は合うが、ライトで確かめるものとして意味が合わない。"}], "explanations": {"輝き": "宝石の光るようすを確かめる文として自然に合う。", "季節": "形は合うが、ライトで確かめるものとして意味が合わない。", "昼食": "形は合うが、宝石のものとして意味が合わない。", "返事": "形は合うが、ライトで確かめるものとして意味が合わない。"}, "sentence_index": 6, "correct_answer": "輝き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨のあとの葉っぱは、輝きが重くなって見えた。", "explanation": "「輝き」は光るようすで、重さの変化を表す語ではない。"}, {"text": "雨のあとの葉っぱは、輝きが冷蔵庫で見えた。", "explanation": "「輝き」は場所を表す語ではなく、「冷蔵庫で」とは結びつかない。"}, {"text": "雨のあとの葉っぱは、輝きが甘くなって見えた。", "explanation": "「輝き」は味ではないので、「甘い」で表すのは不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52945, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖の輝きを美しいです。", "corrected_sentence": "湖の輝きが美しいです。", "error_description": "形容詞「美しい」の主語には「を」ではなく「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
