INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52946, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「輝きに目をうばわれる」で、受け身の原因・対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「輝きを目をうばわれました」は「を」が重なり非文になる。"}, {"text": "が", "is_correct": false, "explanation": "「輝きが目をうばわれました」は受け身の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「輝きへ目をうばわれました」は方向を表し、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「輝きに目をうばわれる」で、受け身の原因・対象を表す。", "を": "「輝きを目をうばわれました」は「を」が重なり非文になる。", "が": "「輝きが目をうばわれました」は受け身の文として成り立たない。", "へ": "「輝きへ目をうばわれました」は方向を表し、文が成り立たない。"}, "error_tags": {"を": "object_marker_clash", "が": "subject_marker_clash", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陰り", "is_correct": true, "explanation": "輝きが失われて暗くなるようすで、反対の意味になる。"}, {"text": "光彩", "is_correct": false, "explanation": "美しい光の意味で、輝きと近く反対ではない。"}, {"text": "煌めき", "is_correct": false, "explanation": "きらきら光ることで、輝きの類義語にあたる。"}, {"text": "栄光", "is_correct": false, "explanation": "輝かしい名誉の意味で、反対の意味ではない。"}], "correct_answer": "陰り", "explanations": {"陰り": "輝きが失われて暗くなるようすで、反対の意味になる。", "光彩": "美しい光の意味で、輝きと近く反対ではない。", "煌めき": "きらきら光ることで、輝きの類義語にあたる。", "栄光": "輝かしい名誉の意味で、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52946, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「輝きを増す」で、「増す」の目的語を表す。"}, {"text": "に", "is_correct": false, "explanation": "「輝きに増していった」は「増す」の目的語を表せず不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「輝きと増していった」は意味がつながらず非文になる。"}, {"text": "から", "is_correct": false, "explanation": "「輝きから増していった」は目的語を表せず不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「輝きを増す」で、「増す」の目的語を表す。", "に": "「輝きに増していった」は「増す」の目的語を表せず不自然になる。", "と": "「輝きと増していった」は意味がつながらず非文になる。", "から": "「輝きから増していった」は目的語を表せず不自然になる。"}, "error_tags": {"に": "target_marker", "と": "conjunction", "から": "origin_marker"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "くすみ", "is_correct": true, "explanation": "輝きが失われて冴えないようすで、反対の意味になる。"}, {"text": "閃光", "is_correct": false, "explanation": "一瞬の強い光で、輝きに近く反対ではない。"}, {"text": "華やぎ", "is_correct": false, "explanation": "明るく華やかなようすで、輝きに近い。"}, {"text": "栄華", "is_correct": false, "explanation": "栄えて華やかなことで、反対の意味ではない。"}], "correct_answer": "くすみ", "explanations": {"くすみ": "輝きが失われて冴えないようすで、反対の意味になる。", "閃光": "一瞬の強い光で、輝きに近く反対ではない。", "華やぎ": "明るく華やかなようすで、輝きに近い。", "栄華": "栄えて華やかなことで、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52946, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "光り輝くこと。また、その美しく印象的なようす。", "primary_collocate": null, "pronunciation": "かがやき", "ipa": "kaɡajaki", "syllable_count": 4, "sentences": [{"text": "金属イオンとの錯体形成を通じて、色は初めてその真の輝きを帯び、生地へと不可逆的に定着するのだ。", "target_word": "輝き", "complexity_tier": "T6", "furigana": "かがやき", "sentence_source": "mined"}, {"text": "宝石の輝きに目をうばわれました。", "target_word": "輝き", "complexity_tier": "T2", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "彼女の瞳には、希望の輝きがあった。", "target_word": "輝き", "complexity_tier": "T3", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "星の輝きがきれいです。", "target_word": "輝き", "complexity_tier": "T2", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "長い年月を経て、古い絵は新しい輝きを取り戻した。", "target_word": "輝き", "complexity_tier": "T4", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "子どもたちの笑顔は、何よりも強い輝きを放っている。", "target_word": "輝き", "complexity_tier": "T4", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "朝日の輝きだ。", "target_word": "輝き", "complexity_tier": "T1", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "磨けば磨くほど、その石は深い輝きを増していった。", "target_word": "輝き", "complexity_tier": "T4", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "夢を追う人の輝きが、私は好きだ。", "target_word": "輝き", "complexity_tier": "T3", "furigana": "かがやき", "sentence_source": "generated"}, {"text": "年をとっても、その人の輝きは失われない。", "target_word": "輝き", "complexity_tier": "T4", "furigana": "かがやき", "sentence_source": "generated"}], "morphological_forms": [{"form": "輝く", "label": "派生"}, {"form": "輝かしい", "label": "派生"}, {"form": "輝かせる", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 光り輝く美しいようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52946, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輝き", "is_correct": true, "explanation": "色が帯びる「美しく印象的なようす」を表し、文脈に合う。"}, {"text": "面積", "is_correct": false, "explanation": "形は合うが、色が帯びるものとして意味が合わない。"}, {"text": "距離", "is_correct": false, "explanation": "形は合うが、色が帯びるものとして意味が合わない。"}, {"text": "人数", "is_correct": false, "explanation": "形は合うが、色が帯びるものとして意味が合わない。"}], "explanations": {"輝き": "色が帯びる「美しく印象的なようす」を表し、文脈に合う。", "面積": "形は合うが、色が帯びるものとして意味が合わない。", "距離": "形は合うが、色が帯びるものとして意味が合わない。", "人数": "形は合うが、色が帯びるものとして意味が合わない。"}, "sentence_index": 0, "correct_answer": "輝き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "輝きを電車に忘れてしまいました。", "explanation": "「輝き」は光るようすであり、持ち物のように電車に忘れることはできない。"}, {"text": "星の輝きを駅前の店で買いました。", "explanation": "「輝き」は抽象的なようすで、店で売り買いする品物ではない。"}, {"text": "星の輝きがとても重いです。", "explanation": "「輝き」の状態を重さで表すのは不自然で、「重い」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52946, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輝き", "is_correct": true, "explanation": "朝日の光り輝くようすを表し、文に合う。"}, {"text": "番号", "is_correct": false, "explanation": "形は合うが、朝日のようすとして意味が合わない。"}, {"text": "予定", "is_correct": false, "explanation": "形は合うが、朝日のようすとして意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、朝日のようすとして意味が合わない。"}], "explanations": {"輝き": "朝日の光り輝くようすを表し、文に合う。", "番号": "形は合うが、朝日のようすとして意味が合わない。", "予定": "形は合うが、朝日のようすとして意味が合わない。", "値段": "形は合うが、朝日のようすとして意味が合わない。"}, "sentence_index": 6, "correct_answer": "輝き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年をとっても、その人の輝きは冷蔵庫に入っている。", "explanation": "「輝き」は人の魅力のようすで、冷蔵庫に入れるような物ではない。"}, {"text": "年をとっても、その人の輝きを毎日食べている。", "explanation": "「輝き」は食べ物ではないので、「食べる」とは結びつかない。"}, {"text": "年をとっても、その人の輝きは寒くない。", "explanation": "「輝き」の状態を「寒い」で表すのは不適切で、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52946, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の目には、希望の輝きがいた。", "corrected_sentence": "彼の目には、希望の輝きがあった。", "error_description": "「輝き」は生き物ではないので、存在を表す動詞は「いた」ではなく「あった」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
