INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52947, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「錯体の絵」で、名詞どうしをつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「錯体を絵を見ました」は「を」が重なり非文になる。"}, {"text": "に", "is_correct": false, "explanation": "「錯体に絵を見ました」は意味がつながらず非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「錯体へ絵を見ました」は方向を表し、文がつながらない。"}], "correct_answer": "の", "explanations": {"の": "「錯体の絵」で、名詞どうしをつなぐ。", "を": "「錯体を絵を見ました」は「を」が重なり非文になる。", "に": "「錯体に絵を見ました」は意味がつながらず非文になる。", "へ": "「錯体へ絵を見ました」は方向を表し、文がつながらない。"}, "error_tags": {"を": "object_marker_clash", "に": "target_marker", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
