INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52947, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いくつかの原子や分子がくっついてできた、ひとまとまりのもの。", "primary_collocate": null, "pronunciation": "さくたい", "ipa": "sakɯtai", "syllable_count": 4, "sentences": [{"text": "これは銅の錯体だ。", "target_word": "錯体", "complexity_tier": "T1", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体の絵を見ました。", "target_word": "錯体", "complexity_tier": "T2", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "先生が錯体を説明しました。", "target_word": "錯体", "complexity_tier": "T2", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体は、いくつかの分子がくっついたものだ。", "target_word": "錯体", "complexity_tier": "T3", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "理科の時間に、青い錯体を作っている。", "target_word": "錯体", "complexity_tier": "T3", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "この錯体は、水に入れると色が変わる。", "target_word": "錯体", "complexity_tier": "T4", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体の名前を覚えました。", "target_word": "錯体", "complexity_tier": "T2", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "兄は、錯体の勉強がおもしろいと言っている。", "target_word": "錯体", "complexity_tier": "T3", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体が壊れないように、そっと混ぜられた。", "target_word": "錯体", "complexity_tier": "T4", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体は、目に見えないほど小さいことが多い。", "target_word": "錯体", "complexity_tier": "T3", "furigana": "さくたい", "sentence_source": "generated"}], "morphological_forms": [{"form": "金属錯体", "label": "派生"}, {"form": "錯体化学", "label": "派生"}, {"form": "錯体形成", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 分子がくっついたひとまとまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52947, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "錯体", "is_correct": true, "explanation": "「さくたい」で、見出し語そのもの。"}, {"text": "臍帯", "is_correct": false, "explanation": "「さいたい」で、「く」が「い」に変わっている。"}, {"text": "三体", "is_correct": false, "explanation": "「さんたい」で、「く」が「ん」に変わっている。"}, {"text": "客体", "is_correct": false, "explanation": "「きゃくたい」で、「さ」が「きゃ」に変わっている。"}], "explanations": {"錯体": "「さくたい」で、見出し語そのもの。", "臍帯": "「さいたい」で、「く」が「い」に変わっている。", "三体": "「さんたい」で、「く」が「ん」に変わっている。", "客体": "「きゃくたい」で、「さ」が「きゃ」に変わっている。"}, "sentence_index": null, "correct_answer": "錯体"}, "level_3": {"options": [{"text": "錯体", "is_correct": true, "explanation": "銅などがくっついてできたひとまとまりを指し、「銅の」に続いて文に合う。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、「銅の」に続くものとして意味が合わない。"}, {"text": "来週", "is_correct": false, "explanation": "形は合うが、「銅の」に続くものとして意味が合わない。"}, {"text": "午前", "is_correct": false, "explanation": "形は合うが、「銅の」に続くものとして意味が合わない。"}], "explanations": {"錯体": "銅などがくっついてできたひとまとまりを指し、「銅の」に続いて文に合う。", "昨日": "形は合うが、「銅の」に続くものとして意味が合わない。", "来週": "形は合うが、「銅の」に続くものとして意味が合わない。", "午前": "形は合うが、「銅の」に続くものとして意味が合わない。"}, "sentence_index": 0, "correct_answer": "錯体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "錯体は、毎晩夕食を作ってくれたものだ。", "explanation": "「錯体」は分子の集まりで、料理を作る主体ではない。"}, {"text": "錯体は、いくつかの町がつながった道だ。", "explanation": "「錯体」は分子の集まりで、町や道を表す語ではない。"}, {"text": "錯体は、いくつかの季節が過ぎたものだ。", "explanation": "「錯体」は物質のまとまりで、季節の経過を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52947, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "錯体", "is_correct": true, "explanation": "「さくたい」で、見出し語そのもの。"}, {"text": "悪態", "is_correct": false, "explanation": "「あくたい」で、「さ」が「あ」に変わっている。"}, {"text": "楽隊", "is_correct": false, "explanation": "「がくたい」で、「さ」が「が」に変わっている。"}, {"text": "策定", "is_correct": false, "explanation": "「さくてい」で、「た」が「て」に変わっている。"}], "explanations": {"錯体": "「さくたい」で、見出し語そのもの。", "悪態": "「あくたい」で、「さ」が「あ」に変わっている。", "楽隊": "「がくたい」で、「さ」が「が」に変わっている。", "策定": "「さくてい」で、「た」が「て」に変わっている。"}, "sentence_index": null, "correct_answer": "錯体"}, "level_3": {"options": [{"text": "錯体", "is_correct": true, "explanation": "名前を覚える対象として、分子のまとまりを表し文に合う。"}, {"text": "明日", "is_correct": false, "explanation": "形は合うが、「名前」を覚える対象として意味が合わない。"}, {"text": "今朝", "is_correct": false, "explanation": "形は合うが、「名前」を覚える対象として意味が合わない。"}, {"text": "夕方", "is_correct": false, "explanation": "形は合うが、「名前」を覚える対象として意味が合わない。"}], "explanations": {"錯体": "名前を覚える対象として、分子のまとまりを表し文に合う。", "明日": "形は合うが、「名前」を覚える対象として意味が合わない。", "今朝": "形は合うが、「名前」を覚える対象として意味が合わない。", "夕方": "形は合うが、「名前」を覚える対象として意味が合わない。"}, "sentence_index": 6, "correct_answer": "錯体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "錯体は、目に見えないほど眠いことが多い。", "explanation": "「錯体」は物質であり、「眠い」という感覚は持たない。"}, {"text": "錯体は、目に見えないほど速く走ることが多い。", "explanation": "「錯体」は走る主体ではなく、意味が合わない。"}, {"text": "錯体は、目に見えないほど親切なことが多い。", "explanation": "「錯体」に人の性格を表す「親切」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id