INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52948, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "金属イオンに分子やイオンが結合してできる、まとまった化学的な構造。", "primary_collocate": null, "pronunciation": "さくたい", "ipa": "sakɯtai", "syllable_count": 4, "sentences": [{"text": "金属イオンとの錯体形成を通じて、色は初めてその真の輝きを帯び、生地へと不可逆的に定着するのだ。", "target_word": "錯体", "complexity_tier": "T6", "furigana": "さくたい", "sentence_source": "mined"}, {"text": "この錯体は、水に溶けると青い色を示す。", "target_word": "錯体", "complexity_tier": "T4", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "金属イオンに配位子が結合すると、安定な錯体が生成される。", "target_word": "錯体", "complexity_tier": "T5", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体は、中心の金属と周りの分子からできている。", "target_word": "錯体", "complexity_tier": "T4", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "その研究室では、新しい錯体の合成に成功した。", "target_word": "錯体", "complexity_tier": "T4", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体の色は、金属の種類によって変わる。", "target_word": "錯体", "complexity_tier": "T3", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "触媒として働く錯体の構造を、X線で詳しく調べた。", "target_word": "錯体", "complexity_tier": "T5", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "錯体について質問しました。", "target_word": "錯体", "complexity_tier": "T2", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "鉄の錯体は、血液の中で酸素を運ぶ役割を担っている。", "target_word": "錯体", "complexity_tier": "T5", "furigana": "さくたい", "sentence_source": "generated"}, {"text": "この錯体は熱に弱いので、冷蔵庫に保管している。", "target_word": "錯体", "complexity_tier": "T4", "furigana": "さくたい", "sentence_source": "generated"}], "morphological_forms": [{"form": "金属錯体", "label": "派生"}, {"form": "錯体化学", "label": "派生"}, {"form": "錯体形成", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 金属に分子が結合した化合物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52948, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "錯体", "is_correct": true, "explanation": "「さくたい」で、見出し語そのもの。"}, {"text": "臍帯", "is_correct": false, "explanation": "「さいたい」で、「く」が「い」に変わっている。"}, {"text": "三体", "is_correct": false, "explanation": "「さんたい」で、「く」が「ん」に変わっている。"}, {"text": "客体", "is_correct": false, "explanation": "「きゃくたい」で、「さ」が「きゃ」に変わっている。"}], "explanations": {"錯体": "「さくたい」で、見出し語そのもの。", "臍帯": "「さいたい」で、「く」が「い」に変わっている。", "三体": "「さんたい」で、「く」が「ん」に変わっている。", "客体": "「きゃくたい」で、「さ」が「きゃ」に変わっている。"}, "sentence_index": null, "correct_answer": "錯体"}, "level_3": {"options": [{"text": "錯体", "is_correct": true, "explanation": "金属イオンとの結合でできる構造で、「形成」に続く。"}, {"text": "歌詞", "is_correct": false, "explanation": "形は合うが、金属イオンとは意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、金属イオンとの形成として意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、金属イオンとの形成として意味が合わない。"}], "explanations": {"錯体": "金属イオンとの結合でできる構造で、「形成」に続く。", "歌詞": "形は合うが、金属イオンとは意味が合わない。", "机": "形は合うが、金属イオンとの形成として意味が合わない。", "天気": "形は合うが、金属イオンとの形成として意味が合わない。"}, "sentence_index": 0, "correct_answer": "錯体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "錯体は、毎朝六時に起きて学校へ行く。", "explanation": "「錯体」は化学的な構造で、人のように起きて通学することはない。"}, {"text": "錯体は、先週の試合で三点を取った。", "explanation": "「錯体」は物質であり、試合で得点する主体ではない。"}, {"text": "錯体は、駅の前で友達を待っている。", "explanation": "「錯体」は友達を待つ主体になれず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
