INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52949, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが時間とともに少しずつ変わっていく。", "primary_collocate": null, "pronunciation": "うつろう", "ipa": "ɯtsɯɾoː", "syllable_count": 4, "sentences": [{"text": "雲が移ろう。", "target_word": "移ろう", "complexity_tier": "T1", "furigana": "うつろう", "sentence_source": "generated"}, {"text": "空の色が移ろいます。", "target_word": "移ろい", "complexity_tier": "T2", "furigana": "うつろい", "sentence_source": "generated"}, {"text": "季節が移ろいました。", "target_word": "移ろい", "complexity_tier": "T2", "furigana": "うつろい", "sentence_source": "generated"}, {"text": "花の色は、少しずつ移ろっていく。", "target_word": "移ろっ", "complexity_tier": "T3", "furigana": "うつろっ", "sentence_source": "generated"}, {"text": "秋になると、山の景色が移ろう。", "target_word": "移ろう", "complexity_tier": "T4", "furigana": "うつろう", "sentence_source": "generated"}, {"text": "移ろう雲を、ずっと見ていた。", "target_word": "移ろう", "complexity_tier": "T3", "furigana": "うつろう", "sentence_source": "generated"}, {"text": "ものは時間とともに移ろうものだ。", "target_word": "移ろう", "complexity_tier": "T3", "furigana": "うつろう", "sentence_source": "generated"}, {"text": "時間が移ろうにつれて、町の様子も変わった。", "target_word": "移ろう", "complexity_tier": "T4", "furigana": "うつろう", "sentence_source": "generated"}, {"text": "季節の移ろいを感じている。", "target_word": "移ろい", "complexity_tier": "T3", "furigana": "うつろい", "sentence_source": "generated"}, {"text": "夕方の色が移ろいました。", "target_word": "移ろい", "complexity_tier": "T2", "furigana": "うつろい", "sentence_source": "generated"}], "morphological_forms": [{"form": "移ろい", "label": "活用"}, {"form": "移ろった", "label": "活用"}, {"form": "移ろって", "label": "活用"}, {"form": "移ろわない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | ものが時とともに変わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed'