INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52949, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移ろう", "is_correct": true, "explanation": "「雲が移ろう」で、雲が少しずつ変わっていくことを表す。"}, {"text": "歌う", "is_correct": false, "explanation": "形は合うが意味が合わない。雲は歌わない。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが意味が合わない。雲が眠るとは言えない。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが意味が合わない。雲は食べる主体ではない。"}], "explanations": {"移ろう": "「雲が移ろう」で、雲が少しずつ変わっていくことを表す。", "歌う": "形は合うが意味が合わない。雲は歌わない。", "眠る": "形は合うが意味が合わない。雲が眠るとは言えない。", "食べる": "形は合うが意味が合わない。雲は食べる主体ではない。"}, "sentence_index": 0, "correct_answer": "移ろう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上のペンが、突然床に移ろった。", "explanation": "「移ろう」は少しずつ変わることで、急に落ちる動きには使えない。"}, {"text": "私は友達に電話を移ろった。", "explanation": "「移ろう」は自動詞で、「電話をかける」意味の他動詞としては使えない。"}, {"text": "三秒前の天気が、今も同じまま移ろっている。", "explanation": "「移ろう」は変化を表すので、同じまま続く状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52949, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移ろう", "is_correct": true, "explanation": "「時間とともに移ろうもの」で、時間で変わっていくという意味に合う。"}, {"text": "笑う", "is_correct": false, "explanation": "形は合うが意味が合わない。ものが時間とともに笑うとは言えない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "形は合うが意味が合わない。ものについての一般論に合わない。"}, {"text": "履く", "is_correct": false, "explanation": "形は合うが意味が合わない。「ものは履くものだ」では文意が通らない。"}], "explanations": {"移ろう": "「時間とともに移ろうもの」で、時間で変わっていくという意味に合う。", "笑う": "形は合うが意味が合わない。ものが時間とともに笑うとは言えない。", "泳ぐ": "形は合うが意味が合わない。ものについての一般論に合わない。", "履く": "形は合うが意味が合わない。「ものは履くものだ」では文意が通らない。"}, "sentence_index": 6, "correct_answer": "移ろう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は荷物を駅まで移ろって運んだ。", "explanation": "「移ろう」は自動詞で、荷物を運ぶ意味の他動詞としては使えない。"}, {"text": "このコップは、割れた瞬間に粉々へと移ろった。", "explanation": "「移ろう」は少しずつの変化で、瞬間的な変化には使えない。"}, {"text": "変わらない山の形が、毎日激しく移ろっている。", "explanation": "「変わらない」と「移ろう」は矛盾し、語の意味と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52949, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の景色を、季節とともに移ろった。", "corrected_sentence": "山の景色が、季節とともに移ろった。", "error_description": "「移ろう」は自動詞なので、変わるものは「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "移ろい", "is_correct": true, "explanation": "「ます」は連用形に付くので「移ろいます」となる。"}, {"text": "移ろう", "is_correct": false, "explanation": "終止形に「ます」は付かない。"}, {"text": "移ろった", "is_correct": false, "explanation": "過去形に「ます」は付かない。"}, {"text": "移ろって", "is_correct": false, "explanation": "て形に「ます」は付かない。"}], "correct_form": "移ろい", "base_form": "移ろう", "form_label": "連用形", "sentence_index": 1, "explanations": {"移ろい": "「ます」は連用形に付くので「移ろいます」となる。", "移ろう": "終止形に「ます」は付かない。", "移ろった": "過去形に「ます」は付かない。", "移ろって": "て形に「ます」は付かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52949, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の様子が時間とともに移ろいた。", "corrected_sentence": "町の様子が時間とともに移ろった。", "error_description": "「移ろう」の過去形は「移ろった」であり、「移ろいた」は誤りである。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "移ろう", "is_correct": true, "explanation": "「につれて」は動詞の辞書形に付くので「移ろうにつれて」となる。"}, {"text": "移ろい", "is_correct": false, "explanation": "「時間が移ろいにつれて」とは言えず、動詞の形として不適切である。"}, {"text": "移ろった", "is_correct": false, "explanation": "「につれて」に過去形は付かない。"}, {"text": "移ろわ", "is_correct": false, "explanation": "未然形に「につれて」は付かない。"}], "correct_form": "移ろう", "base_form": "移ろう", "form_label": "連体形", "sentence_index": 7, "explanations": {"移ろう": "「につれて」は動詞の辞書形に付くので「移ろうにつれて」となる。", "移ろい": "「時間が移ろいにつれて」とは言えず、動詞の形として不適切である。", "移ろった": "「につれて」に過去形は付かない。", "移ろわ": "未然形に「につれて」は付かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52950, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「産物を昇華させる」で、昇華させる対象を示す。"}, {"text": "の", "is_correct": false, "explanation": "「産物の、人間の手によって」では述語につながらない。"}, {"text": "で", "is_correct": false, "explanation": "「産物で」では昇華させる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「産物へ」では「昇華させる」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「産物を昇華させる」で、昇華させる対象を示す。", "の": "「産物の、人間の手によって」では述語につながらない。", "で": "「産物で」では昇華させる対象を示せない。", "へ": "「産物へ」では「昇華させる」の目的語にならない。"}, "error_tags": {"の": "attribution", "で": "means", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留まる", "is_correct": true, "explanation": "移ろう(変わっていく)と反対に、同じ状態や場所にとどまる意味である。"}, {"text": "流れる", "is_correct": false, "explanation": "移ろうと似て、変化や移動を表すので反意ではない。"}, {"text": "広がる", "is_correct": false, "explanation": "状態が変わる点で近く、反意ではない。"}, {"text": "弱まる", "is_correct": false, "explanation": "これも変化を表す語で、反意ではない。"}], "correct_answer": "留まる", "explanations": {"留まる": "移ろう(変わっていく)と反対に、同じ状態や場所にとどまる意味である。", "流れる": "移ろうと似て、変化や移動を表すので反意ではない。", "広がる": "状態が変わる点で近く、反意ではない。", "弱まる": "これも変化を表す語で、反意ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52950, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「色が移ろう」で、変化する主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「移ろう」は自動詞なので、「を」では主語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「色の移ろいました」では述語の主語にならず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「色で移ろいました」では主語がなく不自然である。"}], "correct_answer": "が", "explanations": {"が": "「色が移ろう」で、変化する主体を示す。", "を": "「移ろう」は自動詞なので、「を」では主語を示せない。", "の": "「色の移ろいました」では述語の主語にならず文が成り立たない。", "で": "「色で移ろいました」では主語がなく不自然である。"}, "error_tags": {"を": "object", "の": "attribution", "で": "means"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "定まる", "is_correct": true, "explanation": "移ろう(変わっていく)と反対に、落ち着いて変わらなくなる意味である。"}, {"text": "進む", "is_correct": false, "explanation": "移動や進行を表し、反意ではない。"}, {"text": "薄れる", "is_correct": false, "explanation": "少しずつ変わることを表し、むしろ近い意味である。"}, {"text": "揺れる", "is_correct": false, "explanation": "動きを表す語で、変わらないことの反対ではない。"}], "correct_answer": "定まる", "explanations": {"定まる": "移ろう(変わっていく)と反対に、落ち着いて変わらなくなる意味である。", "進む": "移動や進行を表し、反意ではない。", "薄れる": "少しずつ変わることを表し、むしろ近い意味である。", "揺れる": "動きを表す語で、変わらないことの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52950, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "時間がたつにつれて、物事の状態や場所が少しずつ変わっていく。", "primary_collocate": null, "pronunciation": "うつろう", "ipa": "ɯtsɯɾoː", "syllable_count": 4, "sentences": [{"text": "まず、季節の移ろいと共に採取された植物は、熱と水によってその奥底に秘められた色素を解放される。", "target_word": "移ろい", "complexity_tier": "T6", "furigana": "うつろい", "sentence_source": "mined"}, {"text": "この一連の作業は、移ろいやすい自然の産物を、人間の手によって恒久の美へと昇華させる、高度な技術と美意識の結晶なのである。", "target_word": "移ろい", "complexity_tier": "T6", "furigana": "うつろい", "sentence_source": "mined"}, {"text": "季節は静かに移ろっていく。", "target_word": "移ろっ", "complexity_tier": "T3", "furigana": "うつろっ", "sentence_source": "generated"}, {"text": "人の心は、時とともに移ろうものだ。", "target_word": "移ろう", "complexity_tier": "T3", "furigana": "うつろう", "sentence_source": "generated"}, {"text": "夕焼けの色が、少しずつ移ろった。", "target_word": "移ろっ", "complexity_tier": "T3", "furigana": "うつろっ", "sentence_source": "generated"}, {"text": "移ろう景色を眺めながら、一日を過ごした。", "target_word": "移ろう", "complexity_tier": "T4", "furigana": "うつろう", "sentence_source": "generated"}, {"text": "移ろわない愛など、本当にあるのだろうか。", "target_word": "移ろわ", "complexity_tier": "T4", "furigana": "うつろわ", "sentence_source": "generated"}, {"text": "空の色が移ろいました。", "target_word": "移ろい", "complexity_tier": "T2", "furigana": "うつろい", "sentence_source": "generated"}, {"text": "時代が移ろっても、変わらずに残る言葉がある。", "target_word": "移ろっ", "complexity_tier": "T4", "furigana": "うつろっ", "sentence_source": "generated"}, {"text": "光が移ろうたびに、壁の模様も違って見えた。", "target_word": "移ろう", "complexity_tier": "T4", "furigana": "うつろう", "sentence_source": "generated"}], "morphological_forms": [{"form": "移ろい", "label": "活用"}, {"form": "移ろった", "label": "活用"}, {"form": "移ろって", "label": "活用"}, {"form": "移ろわない", "label": "活用"}, {"form": "移ろいやすい", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | 時とともに状態が変わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52950, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移ろい", "is_correct": true, "explanation": "「季節の移ろい」で、季節が少しずつ変わることを表し、文意に合う。"}, {"text": "争い", "is_correct": false, "explanation": "形は合うが意味が合わない。「季節の争い」では植物の採取と結びつかない。"}, {"text": "戦い", "is_correct": false, "explanation": "形は合うが意味が合わない。季節と共に採取される文脈に戦いは関係しない。"}, {"text": "戸惑い", "is_correct": false, "explanation": "形は合うが意味が合わない。季節の「戸惑い」では不自然である。"}], "explanations": {"移ろい": "「季節の移ろい」で、季節が少しずつ変わることを表し、文意に合う。", "争い": "形は合うが意味が合わない。「季節の争い」では植物の採取と結びつかない。", "戦い": "形は合うが意味が合わない。季節と共に採取される文脈に戦いは関係しない。", "戸惑い": "形は合うが意味が合わない。季節の「戸惑い」では不自然である。"}, "sentence_index": 0, "correct_answer": "移ろい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は電車に乗って、一瞬で駅に移ろった。", "explanation": "「移ろう」は少しずつ変わることで、一瞬の移動には使えない。"}, {"text": "重い箱を二階まで移ろった。", "explanation": "「移ろう」は自動詞で、物を運ぶ意味の他動詞としては使えない。"}, {"text": "三分前に買った牛乳が、冷蔵庫の中で移ろった。", "explanation": "「移ろう」は長い時間をかけた変化を表すので、三分間の状況には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52950, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移ろわ", "is_correct": true, "explanation": "「移ろわない愛」で、時がたっても変わらない愛を表し、文意に合う。"}, {"text": "洗わ", "is_correct": false, "explanation": "形は合うが意味が合わない。「洗わない愛」では意味が通らない。"}, {"text": "歌わ", "is_correct": false, "explanation": "形は合うが意味が合わない。「歌わない愛」では文脈に合わない。"}, {"text": "使わ", "is_correct": false, "explanation": "形は合うが意味が合わない。愛を修飾する語として不自然である。"}], "explanations": {"移ろわ": "「移ろわない愛」で、時がたっても変わらない愛を表し、文意に合う。", "洗わ": "形は合うが意味が合わない。「洗わない愛」では意味が通らない。", "歌わ": "形は合うが意味が合わない。「歌わない愛」では文脈に合わない。", "使わ": "形は合うが意味が合わない。愛を修飾する語として不自然である。"}, "sentence_index": 6, "correct_answer": "移ろわ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が止んだので、傘を玄関に移ろった。", "explanation": "「移ろう」は自動詞で、物を移し置く意味の他動詞としては使えない。"}, {"text": "彼は怒って、机を強く移ろった。", "explanation": "「移ろう」には叩くという意味はなく、物に働きかける動作には使えない。"}, {"text": "試験の点数が、突然ゼロに移ろった。", "explanation": "「移ろう」は少しずつ変わることで、突然の変化には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52950, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋になると、山の景色を移ろう。", "corrected_sentence": "秋になると、山の景色が移ろう。", "error_description": "「移ろう」は自動詞なので、主語は「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "移ろい", "is_correct": true, "explanation": "「やすい」は連用形に付くので「移ろいやすい」となる。"}, {"text": "移ろう", "is_correct": false, "explanation": "終止形には「やすい」が付かない。"}, {"text": "移ろった", "is_correct": false, "explanation": "過去形には「やすい」が付かない。"}, {"text": "移ろわ", "is_correct": false, "explanation": "未然形には「やすい」が付かない。"}], "correct_form": "移ろい", "base_form": "移ろう", "form_label": "連用形", "sentence_index": 1, "explanations": {"移ろい": "「やすい」は連用形に付くので「移ろいやすい」となる。", "移ろう": "終止形には「やすい」が付かない。", "移ろった": "過去形には「やすい」が付かない。", "移ろわ": "未然形には「やすい」が付かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
