INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52952, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「平和は恒久であって」で、話題の「平和」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「平和を恒久であって」では「である」の主題を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「平和の恒久であってほしい」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「平和へ恒久であって」では意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「平和は恒久であって」で、話題の「平和」を示す。", "を": "「平和を恒久であって」では「である」の主題を示せない。", "の": "「平和の恒久であってほしい」では文が成り立たない。", "へ": "「平和へ恒久であって」では意味が通らない。"}, "error_tags": {"を": "object", "の": "attribution", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一時", "is_correct": true, "explanation": "恒久(ずっと変わらない)と反対に、わずかな間だけの意味である。"}, {"text": "永遠", "is_correct": false, "explanation": "恒久と同じく果てしなく続く意味で、類義語である。"}, {"text": "将来", "is_correct": false, "explanation": "これから先を指す語で、恒久の反意ではない。"}, {"text": "平和", "is_correct": false, "explanation": "争いのない状態を表し、恒久とは関係がない。"}], "correct_answer": "一時", "explanations": {"一時": "恒久(ずっと変わらない)と反対に、わずかな間だけの意味である。", "永遠": "恒久と同じく果てしなく続く意味で、類義語である。", "将来": "これから先を指す語で、恒久の反意ではない。", "平和": "争いのない状態を表し、恒久とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52952, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「恒久の愛」で、恒久が愛を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「恒久を愛を誓った」では目的語が重なり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「恒久へ愛を」では名詞を修飾できない。"}, {"text": "か", "is_correct": false, "explanation": "「恒久か愛を誓った」では文意が通らない。"}], "correct_answer": "の", "explanations": {"の": "「恒久の愛」で、恒久が愛を修飾する。", "を": "「恒久を愛を誓った」では目的語が重なり文が成り立たない。", "へ": "「恒久へ愛を」では名詞を修飾できない。", "か": "「恒久か愛を誓った」では文意が通らない。"}, "error_tags": {"を": "object", "へ": "direction", "か": "question"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暫定", "is_correct": true, "explanation": "恒久(ずっと続く)と反対に、とりあえず一時的に定めることである。"}, {"text": "永久", "is_correct": false, "explanation": "恒久と同じくいつまでも続く意味で、類義語である。"}, {"text": "基本", "is_correct": false, "explanation": "物事のもとを表す語で、恒久の反意ではない。"}, {"text": "現在", "is_correct": false, "explanation": "今の時を指す語で、恒久の反意ではない。"}], "correct_answer": "暫定", "explanations": {"暫定": "恒久(ずっと続く)と反対に、とりあえず一時的に定めることである。", "永久": "恒久と同じくいつまでも続く意味で、類義語である。", "基本": "物事のもとを表す語で、恒久の反意ではない。", "現在": "今の時を指す語で、恒久の反意ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52952, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "永久に変わらないこと。永遠であること。", "primary_collocate": null, "pronunciation": "こうきゅう", "ipa": "koːkʲɯː", "syllable_count": 4, "sentences": [{"text": "この一連の作業は、移ろいやすい自然の産物を、人間の手によって恒久の美へと昇華させる、高度な技術と美意識の結晶なのである。", "target_word": "恒久", "complexity_tier": "T6", "furigana": "こうきゅう", "sentence_source": "mined"}, {"text": "平和は恒久であってほしい、と誰もが願う。", "target_word": "恒久", "complexity_tier": "T4", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "恒久の平和を守るために、国々は話し合いを続けた。", "target_word": "恒久", "complexity_tier": "T4", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "恒久を求める人間の願いが、巨大な建築物を生んだ。", "target_word": "恒久", "complexity_tier": "T4", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "恒久の平和が、私たちの願いだ。", "target_word": "恒久", "complexity_tier": "T3", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "石は、恒久の象徴として扱われてきた。", "target_word": "恒久", "complexity_tier": "T4", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "その制度は、恒久であることが求められている。", "target_word": "恒久", "complexity_tier": "T4", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "彼は、恒久の愛を誓った。", "target_word": "恒久", "complexity_tier": "T3", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "恒久であるはずのものも、いつかは形を変える。", "target_word": "恒久", "complexity_tier": "T4", "furigana": "こうきゅう", "sentence_source": "generated"}, {"text": "恒久の価値を持つ芸術は、時代を超えて愛される。", "target_word": "恒久", "complexity_tier": "T5", "furigana": "こうきゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "恒久的", "label": "派生"}, {"form": "恒久性", "label": "派生"}, {"form": "恒久平和", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 永久に変わらないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52952, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恒久", "is_correct": true, "explanation": "こうきゅう。これが聞かせる語である。"}, {"text": "要求", "is_correct": false, "explanation": "ようきゅう。最初の「こ」が「よ」に変わる。"}, {"text": "等級", "is_correct": false, "explanation": "とうきゅう。最初の「こ」が「と」に変わる。"}, {"text": "交流", "is_correct": false, "explanation": "こうりゅう。「き」が「り」に変わる。"}, {"text": "公衆", "is_correct": false, "explanation": "こうしゅう。「きゅ」が「しゅ」に変わる。"}], "explanations": {"恒久": "こうきゅう。これが聞かせる語である。", "要求": "ようきゅう。最初の「こ」が「よ」に変わる。", "等級": "とうきゅう。最初の「こ」が「と」に変わる。", "交流": "こうりゅう。「き」が「り」に変わる。", "公衆": "こうしゅう。「きゅ」が「しゅ」に変わる。"}, "sentence_index": null, "correct_answer": "恒久"}, "level_3": {"options": [{"text": "恒久", "is_correct": true, "explanation": "「恒久の美」で、永遠に変わらない美を表し、移ろいやすいものと対比される。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが意味が合わない。「地図の美」では昇華の文脈に合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "形は合うが意味が合わない。「郵便の美」では意味が通らない。"}, {"text": "野球", "is_correct": false, "explanation": "形は合うが意味が合わない。自然の産物を野球の美へ昇華させるとは言えない。"}], "explanations": {"恒久": "「恒久の美」で、永遠に変わらない美を表し、移ろいやすいものと対比される。", "地図": "形は合うが意味が合わない。「地図の美」では昇華の文脈に合わない。", "郵便": "形は合うが意味が合わない。「郵便の美」では意味が通らない。", "野球": "形は合うが意味が合わない。自然の産物を野球の美へ昇華させるとは言えない。"}, "sentence_index": 0, "correct_answer": "恒久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "恒久の雨が、昼過ぎには止んだ。", "explanation": "「恒久」は永遠に変わらないことで、昼に止む雨とは矛盾する。"}, {"text": "彼は恒久に走って、駅に着いた。", "explanation": "「恒久」は名詞で、走り方を表す副詞としては使えない。"}, {"text": "昨日の夕飯は恒久だった。", "explanation": "「恒久」は変わらない状態を指し、料理や食事の内容には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52952, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恒久", "is_correct": true, "explanation": "こうきゅう。これが聞かせる語である。"}, {"text": "早急", "is_correct": false, "explanation": "そうきゅう。最初の「こ」が「そ」に変わる。"}, {"text": "俸給", "is_correct": false, "explanation": "ほうきゅう。最初の「こ」が「ほ」に変わる。"}, {"text": "公共", "is_correct": false, "explanation": "こうきょう。「きゅ」が「きょ」に変わる。"}, {"text": "甲虫", "is_correct": false, "explanation": "こうちゅう。「きゅ」が「ちゅ」に変わる。"}], "explanations": {"恒久": "こうきゅう。これが聞かせる語である。", "早急": "そうきゅう。最初の「こ」が「そ」に変わる。", "俸給": "ほうきゅう。最初の「こ」が「ほ」に変わる。", "公共": "こうきょう。「きゅ」が「きょ」に変わる。", "甲虫": "こうちゅう。「きゅ」が「ちゅ」に変わる。"}, "sentence_index": null, "correct_answer": "恒久"}, "level_3": {"options": [{"text": "恒久", "is_correct": true, "explanation": "「恒久であること」で、制度がずっと続くことが求められるという意味に合う。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが意味が合わない。制度が「傘であること」では意味が通らない。"}, {"text": "紙", "is_correct": false, "explanation": "形は合うが意味が合わない。制度が「紙であること」では文意に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが意味が合わない。制度が「靴であること」は不自然である。"}], "explanations": {"恒久": "「恒久であること」で、制度がずっと続くことが求められるという意味に合う。", "傘": "形は合うが意味が合わない。制度が「傘であること」では意味が通らない。", "紙": "形は合うが意味が合わない。制度が「紙であること」では文意に合わない。", "靴": "形は合うが意味が合わない。制度が「靴であること」は不自然である。"}, "sentence_index": 6, "correct_answer": "恒久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この氷は恒久なので、五分で溶けた。", "explanation": "「恒久」は永遠に変わらないことで、五分で溶ける氷とは矛盾する。"}, {"text": "私は毎朝、恒久を食べてから学校へ行く。", "explanation": "「恒久」は抽象名詞で、食べ物のように「食べる」対象にならない。"}, {"text": "恒久の風が、窓から一瞬だけ吹いた。", "explanation": "「恒久」は永続を表し、一瞬だけ吹く風とは意味が衝突する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_vers