INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52953, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「美を楽しむ」で、楽しむ対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「美が楽しむ行事」では、美が楽しむ主体になって意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「美へ楽しむ」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「楽しむ」の対象は「を」で表すので、「月の美に楽しむ」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「美を楽しむ」で、楽しむ対象を表す。", "が": "「美が楽しむ行事」では、美が楽しむ主体になって意味が合わない。", "へ": "方向を表すので、「美へ楽しむ」は成り立たない。", "に": "「楽しむ」の対象は「を」で表すので、「月の美に楽しむ」は成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "に": "target_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醜", "is_correct": true, "explanation": "「美」と反対の意味で、みにくさを表す。"}, {"text": "善", "is_correct": false, "explanation": "「真善美」で並ぶ語で、美の反対ではない。"}, {"text": "技", "is_correct": false, "explanation": "技術を表し、美と反対の関係にはない。"}, {"text": "光", "is_correct": false, "explanation": "光は美の反対ではない。"}], "correct_answer": "醜", "explanations": {"醜": "「美」と反対の意味で、みにくさを表す。", "善": "「真善美」で並ぶ語で、美の反対ではない。", "技": "技術を表し、美と反対の関係にはない。", "光": "光は美の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52953, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この庭の美は、変わる」で、話題の主語を表す。"}, {"text": "を", "is_correct": false, "explanation": "「変わる」は自動詞なので、「美を変わる」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「美へ変わる」は文として合わない。"}, {"text": "と", "is_correct": false, "explanation": "「この庭の美と、季節ごとに変わる」では主語がなくなり成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「この庭の美は、変わる」で、話題の主語を表す。", "を": "「変わる」は自動詞なので、「美を変わる」は合わない。", "へ": "方向を表すので、「美へ変わる」は文として合わない。", "と": "「この庭の美と、季節ごとに変わる」では主語がなくなり成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醜", "is_correct": true, "explanation": "「美」と反対の意味で、みにくさを表す。"}, {"text": "力", "is_correct": false, "explanation": "力は美の反対ではない。"}, {"text": "色", "is_correct": false, "explanation": "色は美の反対ではない。"}, {"text": "音", "is_correct": false, "explanation": "音は美の反対ではない。"}], "correct_answer": "醜", "explanations": {"醜": "「美」と反対の意味で、みにくさを表す。", "力": "力は美の反対ではない。", "色": "色は美の反対ではない。", "音": "音は美の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52953, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "きれいなこと。", "primary_collocate": null, "pronunciation": "び", "ipa": "bi", "syllable_count": 1, "sentences": [{"text": "花の美に、子どもたちは足を止めた。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "月の美を楽しむ行事がある。", "target_word": "美", "complexity_tier": "T2", "furigana": "び", "sentence_source": "generated"}, {"text": "美と醜は反対の意味の言葉です。", "target_word": "美", "complexity_tier": "T2", "furigana": "び", "sentence_source": "generated"}, {"text": "彼女は古い建物の美を大切にしている。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "美を感じるものは人によって違う。", "target_word": "美", "complexity_tier": "T2", "furigana": "び", "sentence_source": "generated"}, {"text": "海の美に感動して、写真をたくさん撮った。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "見た目の美だけが、大切なのではない。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "この庭の美は、季節ごとに変わる。", "target_word": "美", "complexity_tier": "T2", "furigana": "び", "sentence_source": "generated"}, {"text": "空の美を見ようと、みんなで山に登った。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "美を愛する心は、誰にでもある。", "target_word": "美", "complexity_tier": "T2", "furigana": "び", "sentence_source": "generated"}], "morphological_forms": [{"form": "美しい", "label": "派生"}, {"form": "美しさ", "label": "派生"}, {"form": "美化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 見た目のきれいさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a797ebe1-5b97-4e78-8db1-e79629926289') ON CONFL