INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52953, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の美を、私たちは一日中飲んでいた。", "corrected_sentence": "山の美を、私たちは一日中眺めていた。", "error_description": "「美」は飲むものではない。「美を眺める」が自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52953, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この絵の美と、見る人は息をのんだ。", "corrected_sentence": "この絵の美に、見る人は息をのんだ。", "error_description": "息をのむきっかけは「美に」で表す。「と」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52954, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「美が息づいている」で、美が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「息づく」は自動詞なので、「美を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「美へ息づいている」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "すでに「庭には」があり、「美に息づいている」では主語がなく成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「美が息づいている」で、美が主語になる。", "を": "「息づく」は自動詞なので、「美を」は合わない。", "へ": "方向を表すので、「美へ息づいている」は成り立たない。", "に": "すでに「庭には」があり、「美に息づいている」では主語がなく成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "に": "target_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醜", "is_correct": true, "explanation": "「美」と反対の意味で、みにくさを表す。"}, {"text": "善", "is_correct": false, "explanation": "「真善美」で並ぶ語で、美の反対ではない。"}, {"text": "技", "is_correct": false, "explanation": "技術を表し、美と反対の関係にはない。"}, {"text": "光", "is_correct": false, "explanation": "光は美の反対ではない。"}], "correct_answer": "醜", "explanations": {"醜": "「美」と反対の意味で、みにくさを表す。", "善": "「真善美」で並ぶ語で、美の反対ではない。", "技": "技術を表し、美と反対の関係にはない。", "光": "光は美の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52954, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「美に言葉を失った」で、きっかけを表す。"}, {"text": "を", "is_correct": false, "explanation": "すでに「言葉を」があり、「美を」では文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「美が人々は言葉を失った」は主語が重なって合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「美へ言葉を失った」は合わない。"}], "correct_answer": "に", "explanations": {"に": "「美に言葉を失った」で、きっかけを表す。", "を": "すでに「言葉を」があり、「美を」では文が成り立たない。", "が": "「美が人々は言葉を失った」は主語が重なって合わない。", "へ": "方向を表すので、「美へ言葉を失った」は合わない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醜", "is_correct": true, "explanation": "「美」と反対の意味で、みにくさを表す。"}, {"text": "力", "is_correct": false, "explanation": "力は美の反対ではない。"}, {"text": "色", "is_correct": false, "explanation": "色は美の反対ではない。"}, {"text": "音", "is_correct": false, "explanation": "音は美の反対ではない。"}], "correct_answer": "醜", "explanations": {"醜": "「美」と反対の意味で、みにくさを表す。", "力": "力は美の反対ではない。", "色": "色は美の反対ではない。", "音": "音は美の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52954, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が持つ、見た目や心をひきつける美しさ、またその性質。", "primary_collocate": null, "pronunciation": "び", "ipa": "bi", "syllable_count": 1, "sentences": [{"text": "この一連の作業は、移ろいやすい自然の産物を、人間の手によって恒久の美へと昇華させる、高度な技術と美意識の結晶なのである。", "target_word": "美", "complexity_tier": "T6", "furigana": "び", "sentence_source": "mined"}, {"text": "この寺の庭には、日本の伝統の美が息づいている。", "target_word": "美", "complexity_tier": "T4", "furigana": "び", "sentence_source": "generated"}, {"text": "芸術家は生涯をかけて美を追い求めた。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "彼は音楽に美を感じて、毎日ピアノを弾く。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "美は見る人の心の中にあるという考え方がある。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "その絵は、自然の美と人間の力を同時に表している。", "target_word": "美", "complexity_tier": "T4", "furigana": "び", "sentence_source": "generated"}, {"text": "美を守るために、古い町並みを残す運動が始まった。", "target_word": "美", "complexity_tier": "T4", "furigana": "び", "sentence_source": "generated"}, {"text": "作品の美に、会場の人々は言葉を失った。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}, {"text": "この映画は、悲しみの中にある美を静かに描いている。", "target_word": "美", "complexity_tier": "T4", "furigana": "び", "sentence_source": "generated"}, {"text": "日本の美について、先生が話してくれた。", "target_word": "美", "complexity_tier": "T3", "furigana": "び", "sentence_source": "generated"}], "morphological_forms": [{"form": "美しい", "label": "派生"}, {"form": "美しさ", "label": "派生"}, {"form": "美的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 芸術や伝統が持つ美しさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 移ろい (Zipf 2.5), 産物 (Zipf 3.5), 恒久 (Zipf 3.13), 昇華 (Zipf 3.35)','sentence 1 above tier T2: contains vocabulary far above tier T2: 息づい (Zipf 2.11)']::text[], 'a797ebe1-5b97-4e78-8db1-e79629926289') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52954, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美", "is_correct": true, "explanation": "「び」で、聞こえた語と一致する。"}, {"text": "日", "is_correct": false, "explanation": "「ひ」で、最初の音が違う。"}, {"text": "実", "is_correct": false, "explanation": "「み」で、最初の音が違う。"}, {"text": "木", "is_correct": false, "explanation": "「き」で、最初の音が違う。"}, {"text": "血", "is_correct": false, "explanation": "「ち」で、最初の音が違う。"}, {"text": "胃", "is_correct": false, "explanation": "「い」で、最初の音が違う。"}], "explanations": {"美": "「び」で、聞こえた語と一致する。", "日": "「ひ」で、最初の音が違う。", "実": "「み」で、最初の音が違う。", "木": "「き」で、最初の音が違う。", "血": "「ち」で、最初の音が違う。", "胃": "「い」で、最初の音が違う。"}, "sentence_index": null, "correct_answer": "美"}, "level_3": {"options": [{"text": "美", "is_correct": true, "explanation": "自然の産物を恒久の美へ昇華させるという意味に合う。"}, {"text": "醜", "is_correct": false, "explanation": "形は合うが、昇華の行き先として意味が合わない。"}, {"text": "悪", "is_correct": false, "explanation": "形は合うが、技術の結晶という文脈に意味が合わない。"}, {"text": "混乱", "is_correct": false, "explanation": "形は合うが、昇華させる先として意味が合わない。"}], "explanations": {"美": "自然の産物を恒久の美へ昇華させるという意味に合う。", "醜": "形は合うが、昇華の行き先として意味が合わない。", "悪": "形は合うが、技術の結晶という文脈に意味が合わない。", "混乱": "形は合うが、昇華させる先として意味が合わない。"}, "sentence_index": 0, "correct_answer": "美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は音楽に美を食べて、毎日ピアノを弾く。", "explanation": "「美」は抽象的な性質で、食べるものではないので「食べる」とは使えない。"}, {"text": "彼は音楽に美を洗って、毎日ピアノを弾く。", "explanation": "「美」は物ではなく、洗う対象にならないので「洗う」とは使えない。"}, {"text": "彼は音楽に美を着て、毎日ピアノを弾く。", "explanation": "「美」は着られるものではないので「着る」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
