INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52954, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕日の美を、私たちはしばらく飲んでいた。", "corrected_sentence": "夕日の美を、私たちはしばらく眺めていた。", "error_description": "「美」は飲むものではない。「美を眺める」が自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52954, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪景色の美と、旅人は心を打たれた。", "corrected_sentence": "雪景色の美に、旅人は心を打たれた。", "error_description": "心を打たれる原因は「美に」で表す。「と」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52955, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「服飾が好き」の主語を示し、好きな対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "方向や対象を表し、「服飾に好きで」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、「服飾で好きで」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「服飾へ好きで」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「服飾が好き」の主語を示し、好きな対象を表す。", "に": "方向や対象を表し、「服飾に好きで」は不自然。", "で": "手段や場所を表し、「服飾で好きで」は成り立たない。", "へ": "方向を表し、「服飾へ好きで」は不自然。"}, "error_tags": {"に": "方向・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52955, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「服飾は着回しのきくものだけに絞った」の主題を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を表し、「服飾と着回しのきくものだけに絞った」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表し、「服飾より着回しのきくものだけに絞った」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「服飾へ着回しのきくものだけに絞った」は不自然。"}], "correct_answer": "は", "explanations": {"は": "「服飾は着回しのきくものだけに絞った」の主題を示す。", "と": "並列や共同を表し、「服飾と着回しのきくものだけに絞った」は成り立たない。", "より": "比較を表し、「服飾より着回しのきくものだけに絞った」は不自然。", "へ": "方向を表すが、「服飾へ着回しのきくものだけに絞った」は不自然。"}, "error_tags": {"と": "並列・共同", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52955, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が着るものや、それに合うもののことです。", "primary_collocate": null, "pronunciation": "ふくしょく", "ipa": "ɸɯkɯɕokɯ", "syllable_count": 4, "sentences": [{"text": "結婚式に出るので、服飾を一式そろえる必要がある。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]に出[で]るので、服飾[ふくしょく]を一式[いっしき]そろえる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "姉は服飾が好きで、毎朝、服と靴と鞄の組み合わせを楽しんでいる。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "姉[あね]は服飾[ふくしょく]が好[す]きで、毎朝[まいあさ]、服[ふく]と靴[くつ]と鞄[かばん]の組[く]み合[あ]わせを楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "夏祭りでは、浴衣に合う服飾を選ぶのが楽しみだ。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "夏祭[なつまつ]りでは、浴衣[ゆかた]に合[あ]う服飾[ふくしょく]を選[えら]ぶのが楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "彼は服飾にお金をかけず、同じ上着を何年も着ている。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "彼[かれ]は服飾[ふくしょく]にお金[かね]をかけず、同[おな]じ上着[うわぎ]を何年[なんねん]も着[き]ている。", "sentence_source": "generated"}, {"text": "雨の日は、服飾を選ぶときに靴や傘も一緒に考える。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、服飾[ふくしょく]を選[えら]ぶときに靴[くつ]や傘[かさ]も一緒[いっしょ]に考[かんが]える。", "sentence_source": "generated"}, {"text": "面接に着ていく服飾は、清潔で落ち着いた色が望ましい。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "面接[めんせつ]に着[き]ていく服飾[ふくしょく]は、清潔[せいけつ]で落[お]ち着[つ]いた色[いろ]が望[のぞ]ましい。", "sentence_source": "generated"}, {"text": "服飾の好みは人によって違い、派手な色を好む人もいれば地味な色を好む人もいる。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "服飾[ふくしょく]の好[この]みは人[ひと]によって違[ちが]い、派手[はで]な色[いろ]を好[この]む人[ひと]もいれば地味[じみ]な色[いろ]を好[この]む人[ひと]もいる。", "sentence_source": "generated"}, {"text": "出張の荷物を減らすため、服飾は着回しのきくものだけに絞った。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "出張[しゅっちょう]の荷物[にもつ]を減[へ]らすため、服飾[ふくしょく]は着回[きまわ]しのきくものだけに絞[しぼ]った。", "sentence_source": "generated"}, {"text": "寒暖差の大きい季節は、服飾の重ね方を工夫すると体温調節がしやすくなる。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "寒暖差[かんだんさ]の大[おお]きい季節[きせつ]は、服飾[ふくしょく]の重[かさ]ね方[かた]を工夫[くふう]すると体温調節[たいおんちょうせつ]がしやすくなる。", "sentence_source": "generated"}, {"text": "寒い地方では、手袋や帽子もふだんの服飾に欠かせない。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "寒[さむ]い地方[ちほう]では、手袋[てぶくろ]や帽子[ぼうし]もふだんの服飾[ふくしょく]に欠[か]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "服飾", "label": "基本形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "人が身につける服と、それに合わせる小物をひとまとめにして指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52955, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服飾", "is_correct": true, "explanation": "身につけるものと小物をまとめて指し、「一式そろえる」対象に合う。"}, {"text": "酵母", "is_correct": false, "explanation": "パンや酒の発酵に使う微生物で、結婚式に必要なものとしては合わない。"}, {"text": "硫黄", "is_correct": false, "explanation": "化学物質で、結婚式の準備として一式そろえる対象ではない。"}, {"text": "石膏", "is_correct": false, "explanation": "建材や彫刻に使う素材で、式の準備の文脈に合わない。"}], "explanations": {"服飾": "身につけるものと小物をまとめて指し、「一式そろえる」対象に合う。", "酵母": "パンや酒の発酵に使う微生物で、結婚式に必要なものとしては合わない。", "硫黄": "化学物質で、結婚式の準備として一式そろえる対象ではない。", "石膏": "建材や彫刻に使う素材で、式の準備の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "服飾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい家の玄関に服飾を取り付けた。", "explanation": "ここは〈建具〉の意味。服飾は身につけるものやそれに合う物を指すので、玄関のドアのような建具には使えない。"}, {"text": "新しいパソコンに服飾を全部つけた。", "explanation": "ここは〈付属品〉の意味。服飾は人が身につける物を指すので、パソコンの付属品には使えない。"}, {"text": "床に服飾を敷いて、足元を暖かくした。", "explanation": "ここは〈敷物〉の意味。服飾は身につける物を指すので、床に敷く物としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52955, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服飾", "is_correct": true, "explanation": "身につけるものを指し、「服飾の好み」が人によって違うという文に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表し、好みの対象にはならない。"}, {"text": "伝票", "is_correct": false, "explanation": "取引の記録用紙で、人の好みの対象として不自然。"}, {"text": "降雪", "is_correct": false, "explanation": "雪が降ることを表し、人の好みの対象にはならない。"}], "explanations": {"服飾": "身につけるものを指し、「服飾の好み」が人によって違うという文に合う。", "体温": "体の温度を表し、好みの対象にはならない。", "伝票": "取引の記録用紙で、人の好みの対象として不自然。", "降雪": "雪が降ることを表し、人の好みの対象にはならない。"}, "sentence_index": 6, "correct_answer": "服飾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服飾が腐って、冷蔵庫が臭くなった。", "explanation": "ここは〈食品〉の意味。服飾は身につけるものなので、腐るものとしては使えない。"}, {"text": "彼は毎日、服飾を演奏して練習している。", "explanation": "ここは〈楽器〉の意味。服飾は身につけるものなので、演奏の対象にはならない。"}, {"text": "コピーをとるために、服飾を一箱買った。", "explanation": "ここは〈用紙〉の意味。服飾は身につけるものやそれに合う物を指すので、コピー用紙の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52955, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "入学式のために、服飾に一式そろえた。", "corrected_sentence": "入学式のために、服飾を一式そろえた。", "error_description": "「そろえる」の目的語は「を」で示す。「に」は誤りで、正しくは「服飾を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52955, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、季節ごとの服飾を箱に焼いた。", "corrected_sentence": "祖母は、季節ごとの服飾を箱にしまった。", "error_description": "「服飾」と結びつく動詞は「しまう」。「焼いた」は食べ物に使う語で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52956, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「服飾のデザイン」の「の」で、服飾とデザインを結ぶ。"}, {"text": "に", "is_correct": false, "explanation": "「服飾にデザインから縫製まで」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、「服飾でデザインから」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「服飾へデザインから」は文として合わない。"}], "correct_answer": "の", "explanations": {"の": "「服飾のデザイン」の「の」で、服飾とデザインを結ぶ。", "に": "「服飾にデザインから縫製まで」は成り立たない。", "で": "手段や場所を表し、「服飾でデザインから」は不自然。", "へ": "方向を表し、「服飾へデザインから」は文として合わない。"}, "error_tags": {"に": "方向・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52956, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「服飾を担当し」の目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を表し、「服飾と担当し」は目的語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表し、「服飾より担当し」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、「服飾から担当し」は目的語として合わない。"}], "correct_answer": "を", "explanations": {"を": "「服飾を担当し」の目的語を示す。", "と": "並列や共同を表し、「服飾と担当し」は目的語として成り立たない。", "より": "比較を表し、「服飾より担当し」は不自然。", "から": "起点を表し、「服飾から担当し」は目的語として合わない。"}, "error_tags": {"と": "並列・共同", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52956, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "衣服や装飾品など、身につけるもの全般を指す言葉です。", "primary_collocate": null, "pronunciation": "ふくしょく", "ipa": "ɸɯkɯɕokɯ", "syllable_count": 4, "sentences": [{"text": "オートクチュールの歴史は、単なる服飾の変遷を超え、人類の美的探究と技術革新の軌跡そのものである。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "オートクチュールの歴史[れきし]は、単[たん]なる服飾[ふくしょく]の変遷[へんせん]を超[こ]え、人類[じんるい]の美的[びてき]探究[たんきゅう]と技術[ぎじゅつ]革新[かくしん]の軌跡[きせき]そのものである。", "sentence_source": "mined"}, {"text": "この専門学校では、服飾のデザインから縫製まで幅広く学べる。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "この専門[せんもん]学校[がっこう]では、服飾[ふくしょく]のデザインから縫製[ほうせい]まで幅広[はばひろ]く学[まな]べる。", "sentence_source": "generated"}, {"text": "服飾の仕事に就くため、彼は専門学校に通っている。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "服飾[ふくしょく]の仕事[しごと]に就[つ]くため、彼[かれ]は専門[せんもん]学校[がっこう]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "展示室には、平安時代の貴族の服飾が復元されて並んでいる。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "展示室[てんじしつ]には、平安[へいあん]時代[じだい]の貴族[きぞく]の服飾[ふくしょく]が復元[ふくげん]されて並[なら]んでいる。", "sentence_source": "generated"}, {"text": "祖母は服飾に詳しく、帯や帽子の組み合わせまで教えてくれる。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "祖母[そぼ]は服飾[ふくしょく]に詳[くわ]しく、帯[おび]や帽子[ぼうし]の組[く]み合[あ]わせまで教[おし]えてくれる。", "sentence_source": "generated"}, {"text": "服飾の流行は毎年変わるので、デザイナーは常に情報を集めている。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "服飾[ふくしょく]の流行[りゅうこう]は毎年[まいとし]変[か]わるので、デザイナーは常[つね]に情報[じょうほう]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "民族ごとの服飾を比べると、気候や宗教の違いが見えてくる。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "民族[みんぞく]ごとの服飾[ふくしょく]を比[くら]べると、気候[きこう]や宗教[しゅうきょう]の違[ちが]いが見[み]えてくる。", "sentence_source": "generated"}, {"text": "彼女は舞台の服飾を担当し、衣装だけでなく帽子や靴も用意した。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は舞台[ぶたい]の服飾[ふくしょく]を担当[たんとう]し、衣装[いしょう]だけでなく帽子[ぼうし]や靴[くつ]も用意[ようい]した。", "sentence_source": "generated"}, {"text": "この博物館は、世界各地の服飾を集めた収蔵品で知られている。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "この博物館[はくぶつかん]は、世界[せかい]各地[かくち]の服飾[ふくしょく]を集[あつ]めた収蔵品[しゅうぞうひん]で知[し]られている。", "sentence_source": "generated"}, {"text": "服飾に使う布の値段が上がったため、新作の価格も高くなった。", "target_word": "服飾", "complexity_tier": "T3", "furigana": "服飾[ふくしょく]に使[つか]う布[ぬの]の値段[ねだん]が上[あ]がったため、新作[しんさく]の価格[かかく]も高[たか]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "服飾", "label": "基本形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "衣服や帽子・靴・装身具など身につけるもの全般を総称する名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52956, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服飾", "is_correct": true, "explanation": "衣服や装飾品を指し、「単なる服飾の変遷」として文脈に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出す行為で、服飾の歴史の文脈に合わない。"}, {"text": "配線", "is_correct": false, "explanation": "電気の線を通す作業を指し、衣服の変遷とは結びつかない。"}, {"text": "誤植", "is_correct": false, "explanation": "印刷の誤りを指し、服飾の歴史の文脈に合わない。"}], "explanations": {"服飾": "衣服や装飾品を指し、「単なる服飾の変遷」として文脈に合う。", "採掘": "地下の資源を掘り出す行為で、服飾の歴史の文脈に合わない。", "配線": "電気の線を通す作業を指し、衣服の変遷とは結びつかない。", "誤植": "印刷の誤りを指し、服飾の歴史の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "服飾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁の服飾を金色に塗って、部屋を明るくした。", "explanation": "ここは〈装飾〉の意味。服飾は身につけるものを指すので、壁の飾りには使えない。"}, {"text": "彼女は服飾を選んで、カーテンを作った。", "explanation": "ここは〈布地〉の意味。服飾は衣服や装身具を指すので、カーテンの材料には使えない。"}, {"text": "リビングに服飾を置いて、部屋を広く見せた。", "explanation": "ここは〈家具〉の意味。服飾は身につけるものなので、置いて部屋を飾る物としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52956, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服飾", "is_correct": true, "explanation": "衣服や装飾品を指し、「民族ごとの服飾を比べる」という文に合う。"}, {"text": "機械", "is_correct": false, "explanation": "動力で動く道具を指し、民族ごとの比較の対象としては不自然。"}, {"text": "誤植", "is_correct": false, "explanation": "印刷の誤りを指し、民族の装いの比較とは結びつかない。"}, {"text": "配管", "is_correct": false, "explanation": "水やガスを通す管のことで、文化の比較には使えない。"}], "explanations": {"服飾": "衣服や装飾品を指し、「民族ごとの服飾を比べる」という文に合う。", "機械": "動力で動く道具を指し、民族ごとの比較の対象としては不自然。", "誤植": "印刷の誤りを指し、民族の装いの比較とは結びつかない。", "配管": "水やガスを通す管のことで、文化の比較には使えない。"}, "sentence_index": 6, "correct_answer": "服飾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日、服飾を演奏して練習している。", "explanation": "ここは〈楽器〉の意味。服飾は身につけるものなので、演奏の対象にはならない。"}, {"text": "冬の寒さをしのぐため、服飾を燃料として燃やした。", "explanation": "ここは〈燃料〉の意味。服飾は身につけるものを指すので、燃やして熱を得る物としては使えない。"}, {"text": "新しい家を建てるため、服飾を建材として選んだ。", "explanation": "ここは〈建材〉の意味。服飾は身につけるものを指すので、家の材料としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52956, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店では、服飾を豊富に焼いている。", "corrected_sentence": "この店では、服飾を豊富にそろえている。", "error_description": "「服飾」と結びつく動詞は「そろえる」。「焼く」は食べ物に使う語で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52956, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、古い服飾へ大事に保管している。", "corrected_sentence": "祖母は、古い服飾を大事に保管している。", "error_description": "「保管する」の対象は「を」で示す。「へ」は方向を表すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
