INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52959, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「表示する」の対象を示す「を」。ロケットの軌跡を画面に表示した、の意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「軌跡が」は主語を示し、「表示する」の対象にならない。"}, {"text": "に", "is_correct": false, "explanation": "「軌跡に」は場所や相手を示し、「表示する」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「軌跡へ」は方向を示し、「表示する」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「表示する」の対象を示す「を」。ロケットの軌跡を画面に表示した、の意味になる。", "が": "「軌跡が」は主語を示し、「表示する」の対象にならない。", "に": "「軌跡に」は場所や相手を示し、「表示する」の対象にはならない。", "へ": "「軌跡へ」は方向を示し、「表示する」の対象にはならない。"}, "error_tags": {"が": "主語（表示の対象にならない）", "に": "場所（対象ではない）", "へ": "方向（対象ではない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52959, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものが動いたあとにできる、道のようなもの。", "primary_collocate": null, "pronunciation": "きせき", "ipa": "kiseki", "syllable_count": 3, "sentences": [{"text": "夜空に流れ星の軌跡が、白い線となって残った。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "夜空[よぞら]に流[なが]れ星[ぼし]の軌跡[きせき]が、白[しろ]い線[せん]となって残[のこ]った。", "sentence_source": "generated"}, {"text": "雪の上に、ソリが通った軌跡がまっすぐ続いている。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "雪[ゆき]の上[うえ]に、ソリが通[とお]った軌跡[きせき]がまっすぐ続[つづ]いている。", "sentence_source": "generated"}, {"text": "飛行機が飛んだ軌跡は、空に長い白い雲となって見えた。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が飛[と]んだ軌跡[きせき]は、空[そら]に長[なが]い白[しろ]い雲[くも]となって見[み]えた。", "sentence_source": "generated"}, {"text": "実験では、ボールが落ちる軌跡をカメラで撮影して調べた。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "実験[じっけん]では、ボールが落[お]ちる軌跡[きせき]をカメラで撮影[さつえい]して調[しら]べた。", "sentence_source": "generated"}, {"text": "彗星の軌跡を計算して、地球に近づく日を予測した。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "彗星[すいせい]の軌跡[きせき]を計算[けいさん]して、地球[ちきゅう]に近[ちか]づく日[ひ]を予測[よそく]した。", "sentence_source": "generated"}, {"text": "長時間露光で撮ると、星の軌跡が円を描いて写る。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "長時間[ちょうじかん]露光[ろこう]で撮[と]ると、星[ほし]の軌跡[きせき]が円[えん]を描[えが]いて写[うつ]る。", "sentence_source": "generated"}, {"text": "砂浜には、カニが歩いた軌跡が細い線になって残っていた。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "砂浜[すなはま]には、カニが歩[ある]いた軌跡[きせき]が細[ほそ]い線[せん]になって残[のこ]っていた。", "sentence_source": "generated"}, {"text": "ロケットの軌跡を画面に表示し、予定との差を確認した。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "ロケットの軌跡[きせき]を画面[がめん]に表示[ひょうじ]し、予定[よてい]との差[さ]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "ペンの軌跡をセンサーが読み取り、手書きの文字を画面に表示する。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "ペンの軌跡[きせき]をセンサーが読[よ]み取[と]り、手書[てが]きの文字[もじ]を画面[がめん]に表示[ひょうじ]する。", "sentence_source": "generated"}, {"text": "打ち上げた花火の軌跡が、暗い空に光の線を引いた。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "打[う]ち上[あ]げた花火[はなび]の軌跡[きせき]が、暗[くら]い空[そら]に光[ひかり]の線[せん]を引[ひ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軌跡", "label": "基本形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "動いたものが通ったあとに線や道のように残る跡を指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52959, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軌跡", "is_correct": true, "explanation": "流れ星が動いたあとに残る道筋として、白い線になるという文と合う。"}, {"text": "電圧", "is_correct": false, "explanation": "「流れ星の電圧」は意味をなさず、白い線の説明にならない。"}, {"text": "座布団", "is_correct": false, "explanation": "「流れ星の座布団」は比喩としても通らず、文が成り立たない。"}, {"text": "寿命", "is_correct": false, "explanation": "「流れ星の寿命」は残る線の主語として不自然で、文の意味が合わない。"}], "explanations": {"軌跡": "流れ星が動いたあとに残る道筋として、白い線になるという文と合う。", "電圧": "「流れ星の電圧」は意味をなさず、白い線の説明にならない。", "座布団": "「流れ星の座布団」は比喩としても通らず、文が成り立たない。", "寿命": "「流れ星の寿命」は残る線の主語として不自然で、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "軌跡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車の屋根に、雹でできた軌跡がついていた。", "explanation": "ここは〈へこみ〉の意味。雹で押されてできた凹みは静止した跡で、動いたものが残す道筋の〈軌跡〉は合わない。"}, {"text": "地震で壁に大きな軌跡が入った。", "explanation": "ここは〈ひび割れ〉の意味。割れ目は動いたあとの道筋ではないので、〈軌跡〉ではなく「ひび」と言う。"}, {"text": "棚に軌跡が積もっていた。", "explanation": "ここは〈積もったほこり〉の意味。〈軌跡〉は動いたものの道筋で、積もって残るほこりには使わない（「ほこり」と言う）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52959, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軌跡", "is_correct": true, "explanation": "カニが歩いて残した跡が細い線になるという文に合う。"}, {"text": "体重", "is_correct": false, "explanation": "「カニが歩いた体重」は細い線の説明にならず、文が成り立たない。"}, {"text": "包丁", "is_correct": false, "explanation": "「カニが歩いた包丁」は意味をなさず、文の主語として通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "「カニが歩いた湿度」は意味をなさず、細い線になるという文と合わない。"}], "explanations": {"軌跡": "カニが歩いて残した跡が細い線になるという文に合う。", "体重": "「カニが歩いた体重」は細い線の説明にならず、文が成り立たない。", "包丁": "「カニが歩いた包丁」は意味をなさず、文の主語として通らない。", "湿度": "「カニが歩いた湿度」は意味をなさず、細い線になるという文と合わない。"}, "sentence_index": 6, "correct_answer": "軌跡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方、木の軌跡が長く地面に伸びていた。", "explanation": "ここは〈光を遮ってできる暗い形〉の意味。〈軌跡〉は動いたものが残す道筋で、静止した影には使わない。"}, {"text": "ピアノの軌跡が、部屋いっぱいに広がった。", "explanation": "ここは〈音や響き〉の意味。〈軌跡〉は動いたあとの線なので、音が広がる文には合わない。"}, {"text": "川の軌跡が、岩を長い年月かけて削った。", "explanation": "ここは〈水が流れて作用する〉の意味。〈軌跡〉は通ったあとの跡で、岩を削る力は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52959, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪原に、そりが通った軌跡を一本まっすぐ伸びている。", "corrected_sentence": "雪原に、そりが通った軌跡が一本まっすぐ伸びている。", "error_description": "「伸びる」は自動詞で、主語は「軌跡が」。「軌跡を」は誤りで、正しくは「軌跡が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52959, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "流星群の軌跡を、夜明け前の空に淡く残っていた。", "corrected_sentence": "流星群の軌跡が、夜明け前の空に淡く残っていた。", "error_description": "「残っていた」の主語は「軌跡が」。「軌跡を」は誤りで、自動詞の文に目的語は付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52960, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「たどる」の対象は目的語の「を」で示す。軌跡を作品でたどる、の意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「軌跡が」は主語を示し、「たどる」の目的語にならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「軌跡に」だと到達点の意味になり、たどる対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「軌跡の」は修飾になり、「たどる」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「たどる」の対象は目的語の「を」で示す。軌跡を作品でたどる、の意味になる。", "が": "「軌跡が」は主語を示し、「たどる」の目的語にならないので合わない。", "に": "「軌跡に」だと到達点の意味になり、たどる対象にはならない。", "の": "「軌跡の」は修飾になり、「たどる」の目的語にならない。"}, "error_tags": {"が": "主語（目的語にならない）", "に": "到達点（対象ではない）", "の": "修飾（目的語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52960, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「まとめる」の対象は「を」で示す。自らの軌跡を本にまとめた、の意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "「軌跡へ」は方向を示し、まとめる対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「軌跡より」は比較になり、まとめる対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「軌跡と」は並列になり、「本にまとめる」の目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「まとめる」の対象は「を」で示す。自らの軌跡を本にまとめた、の意味になる。", "へ": "「軌跡へ」は方向を示し、まとめる対象にはならない。", "より": "「軌跡より」は比較になり、まとめる対象を示せない。", "と": "「軌跡と」は並列になり、「本にまとめる」の目的語を示せない。"}, "error_tags": {"へ": "方向（対象ではない）", "より": "比較（対象ではない）", "と": "並列（対象ではない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52960, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が進んでいくうちに残される道筋や、その過程や歴史のあと。", "primary_collocate": null, "pronunciation": "きせき", "ipa": "kiseki", "syllable_count": 3, "sentences": [{"text": "オートクチュールの歴史は、単なる服飾の変遷を超え、人類の美的探究と技術革新の軌跡そのものである。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "オートクチュールの歴史[れきし]は、単[たん]なる服飾[ふくしょく]の変遷[へんせん]を超[こ]え、人類[じんるい]の美的[びてき]探究[たんきゅう]と技術[ぎじゅつ]革新[かくしん]の軌跡[きせき]そのものである。", "sentence_source": "mined"}, {"text": "この展覧会では、画家が歩んだ軌跡を作品でたどることができる。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "この展覧会[てんらんかい]では、画家[がか]が歩[あゆ]んだ軌跡[きせき]を作品[さくひん]でたどることができる。", "sentence_source": "generated"}, {"text": "会社の成長の軌跡を、社史にまとめて社員に配った。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の成長[せいちょう]の軌跡[きせき]を、社史[しゃし]にまとめて社員[しゃいん]に配[くば]った。", "sentence_source": "generated"}, {"text": "彼女の軌跡を追ったドキュメンタリーが、先月放送された。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の軌跡[きせき]を追[お]ったドキュメンタリーが、先月[せんげつ]放送[ほうそう]された。", "sentence_source": "generated"}, {"text": "発展の軌跡を振り返ると、失敗から学んだ点が数多く見えてくる。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "発展[はってん]の軌跡[きせき]を振[ふ]り返[かえ]ると、失敗[しっぱい]から学[まな]んだ点[てん]が数多[かずおお]く見[み]えてくる。", "sentence_source": "generated"}, {"text": "博物館には、探検家の旅の軌跡を示す地図や日記が残っている。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]には、探検家[たんけんか]の旅[たび]の軌跡[きせき]を示[しめ]す地図[ちず]や日記[にっき]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "研究の軌跡を記録しておけば、後から誤りの原因を調べやすい。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の軌跡[きせき]を記録[きろく]しておけば、後[あと]から誤[あやま]りの原因[げんいん]を調[しら]べやすい。", "sentence_source": "generated"}, {"text": "監督は自らの軌跡を本にまとめ、若い世代に向けて出版した。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "監督[かんとく]は自[みずか]らの軌跡[きせき]を本[ほん]にまとめ、若[わか]い世代[せだい]に向[む]けて出版[しゅっぱん]した。", "sentence_source": "generated"}, {"text": "復興の軌跡を伝える写真が、市役所のロビーに飾られている。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "復興[ふっこう]の軌跡[きせき]を伝[つた]える写真[しゃしん]が、市役所[しやくしょ]のロビーに飾[かざ]られている。", "sentence_source": "generated"}, {"text": "選手の努力の軌跡は、毎日の練習ノートにはっきり残っていた。", "target_word": "軌跡", "complexity_tier": "T3", "furigana": "選手[せんしゅ]の努力[どりょく]の軌跡[きせき]は、毎日[まいにち]の練習[れんしゅう]ノートにはっきり残[のこ]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軌跡", "label": "基本形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "人や物事が歩んできた過程や歴史を、残された道筋として捉える名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): オートクチュール (Zipf 2.47), 服飾 (Zipf 3.2), 美的 (Zipf 3.07), 探究 (Zipf 3.15)']::text[], '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52960, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軌跡", "is_correct": true, "explanation": "「技術革新の〜そのもの」に入り、積み重ねてきた過程の跡という意味で文が成り立つ。"}, {"text": "騒音", "is_correct": false, "explanation": "「技術革新の騒音」では過程の跡という意味にならず、文が成り立たない。"}, {"text": "面積", "is_correct": false, "explanation": "「技術革新の面積」は意味をなさず、「そのもの」でつながらない。"}, {"text": "体重", "is_correct": false, "explanation": "「技術革新の体重」は比喩としても通らず、文の主語（歴史）の説明にならない。"}], "explanations": {"軌跡": "「技術革新の〜そのもの」に入り、積み重ねてきた過程の跡という意味で文が成り立つ。", "騒音": "「技術革新の騒音」では過程の跡という意味にならず、文が成り立たない。", "面積": "「技術革新の面積」は意味をなさず、「そのもの」でつながらない。", "体重": "「技術革新の体重」は比喩としても通らず、文の主語（歴史）の説明にならない。"}, "sentence_index": 0, "correct_answer": "軌跡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日、練習の軌跡をつけてノートに書いた。", "explanation": "ここは〈記録として書き留める〉の意味。〈軌跡〉は過程が残した跡で、書き留める対象は「記録」になるので、「軌跡をつける」とは言わない。"}, {"text": "選手は大会で、自己ベストの軌跡を出した。", "explanation": "ここは〈数値として残る成績〉の意味。〈軌跡〉は過程の跡なので、タイムを「出す」の対象にはならない（記録を使う）。"}, {"text": "来年の軌跡を、チームで話し合って立てた。", "explanation": "ここは〈これから立てる予定〉の意味。〈軌跡〉は過ぎた過程の跡なので、未来の計画には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52960, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軌跡", "is_correct": true, "explanation": "「研究の〜を記録」で、研究の過程の跡を残すという意味が成り立つ。"}, {"text": "寝具", "is_correct": false, "explanation": "「研究の寝具」は記録の対象にならず、文が成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "「研究の座布団」は記録の対象にならず、文の意味が通らない。"}, {"text": "包丁", "is_correct": false, "explanation": "「研究の包丁」は意味をなさず、原因を調べやすいという結果にもつながらない。"}], "explanations": {"軌跡": "「研究の〜を記録」で、研究の過程の跡を残すという意味が成り立つ。", "寝具": "「研究の寝具」は記録の対象にならず、文が成り立たない。", "座布団": "「研究の座布団」は記録の対象にならず、文の意味が通らない。", "包丁": "「研究の包丁」は意味をなさず、原因を調べやすいという結果にもつながらない。"}, "sentence_index": 6, "correct_answer": "軌跡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの夜の軌跡は、今も忘れられない。", "explanation": "ここは〈ある一時点の出来事〉の意味。〈軌跡〉は時間をかけて残る過程の跡なので、一夜の出来事には使わない。"}, {"text": "試験の軌跡が、今朝届いた。", "explanation": "ここは〈結果の通知〉の意味。〈軌跡〉は過程の跡なので、届く通知には合わない。"}, {"text": "その絵は、わずか二時間の軌跡で仕上げた。", "explanation": "ここは〈かかった時間〉の意味。〈軌跡〉は過程の跡で、所要時間は「時間」で表すので、長さを示す言葉としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52960, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は歩んできた軌跡に、本にまとめた。", "corrected_sentence": "彼は歩んできた軌跡を、本にまとめた。", "error_description": "「まとめる」の対象は「を」で示す。「軌跡に」は誤った格助詞で、正しくは「軌跡を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52960, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の発展の軌跡で、写真展で紹介した。", "corrected_sentence": "町の発展の軌跡を、写真展で紹介した。", "error_description": "「紹介する」の対象は「を」で示す。「軌跡で」は誤った助詞で、正しくは「軌跡を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
