INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52963, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「エポックと呼べる」の助詞「と」。呼べる出来事、の意味になる。"}, {"text": "の", "is_correct": false, "explanation": "「エポックの呼べる出来事」は連体修飾になり、「呼べる」の対象にならない。"}, {"text": "が", "is_correct": false, "explanation": "「エポックが呼べる」は主語の形で、「呼ぶ」の対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「エポックへ呼べる」は方向を示し、「呼ぶ」の対象にならない。"}], "correct_answer": "と", "explanations": {"と": "「エポックと呼べる」の助詞「と」。呼べる出来事、の意味になる。", "の": "「エポックの呼べる出来事」は連体修飾になり、「呼べる」の対象にならない。", "が": "「エポックが呼べる」は主語の形で、「呼ぶ」の対象にならない。", "へ": "「エポックへ呼べる」は方向を示し、「呼ぶ」の対象にならない。"}, "error_tags": {"の": "修飾（呼ぶ対象にならない）", "が": "主語（呼ぶ対象にならない）", "へ": "方向（呼ぶ対象にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52963, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある特別な時（とき）のこと。", "primary_collocate": null, "pronunciation": "えぽっく", "ipa": "epokkɯ", "syllable_count": 4, "sentences": [{"text": "初めて海外へ行った夏は、私の人生のエポックでした。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "初[はじ]めて海外[かいがい]へ行[い]った夏[なつ]は、私[わたし]の人生[じんせい]のエポックでした。", "sentence_source": "generated"}, {"text": "子どもが生まれた日は、わが家にとって大きなエポックだった。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "子[こ]どもが生[う]まれた日[ひ]は、わが家[や]にとって大[おお]きなエポックだった。", "sentence_source": "generated"}, {"text": "留学したことが、彼の考え方を変えたエポックだと思う。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "留学[りゅうがく]したことが、彼[かれ]の考[かんが]え方[かた]を変[か]えたエポックだと思[おも]う。", "sentence_source": "generated"}, {"text": "卒業は、一つのエポックとして心に残っている。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]は、一[ひと]つのエポックとして心[こころ]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "あの試合は、私にとって忘れられないエポックになった。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "あの試合[しあい]は、私[わたし]にとって忘[わす]れられないエポックになった。", "sentence_source": "generated"}, {"text": "引っ越しをしたこの年は、家族の生活を変えたエポックだった。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しをしたこの年[とし]は、家族[かぞく]の生活[せいかつ]を変[か]えたエポックだった。", "sentence_source": "generated"}, {"text": "転職は大きなエポックだったので、日記に詳しく書いた。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "転職[てんしょく]は大[おお]きなエポックだったので、日記[にっき]に詳[くわ]しく書[か]いた。", "sentence_source": "generated"}, {"text": "彼にとって、初めて作った曲はエポックと呼べる出来事だった。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "彼[かれ]にとって、初[はじ]めて作[つく]った曲[きょく]はエポックと呼[よ]べる出来事[できごと]だった。", "sentence_source": "generated"}, {"text": "祖母は、戦争が終わった日をエポックとして今も覚えている。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、戦争[せんそう]が終[お]わった日[ひ]をエポックとして今[いま]も覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "新しい仕事を始めた春は、自分にとってのエポックだった。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]を始[はじ]めた春[はる]は、自分[じぶん]にとってのエポックだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エポック", "label": "基本形"}], "register": "中立（話し言葉・書き言葉どちらも可）", "sense_fingerprint": "自分や家族にとって意味のある、ある特別な時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52963, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エポック", "is_correct": true, "explanation": "「初めて海外へ行った夏は、私の人生の〜でした」で、人生の中の特別な時点を指すので合う。"}, {"text": "電圧", "is_correct": false, "explanation": "「私の人生の電圧」は意味をなさず、文の内容と合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "「私の人生の座布団」は比喩としても通らず、文が成り立たない。"}, {"text": "包丁", "is_correct": false, "explanation": "「私の人生の包丁」は意味をなさず、夏の思い出の文と合わない。"}], "explanations": {"エポック": "「初めて海外へ行った夏は、私の人生の〜でした」で、人生の中の特別な時点を指すので合う。", "電圧": "「私の人生の電圧」は意味をなさず、文の内容と合わない。", "座布団": "「私の人生の座布団」は比喩としても通らず、文が成り立たない。", "包丁": "「私の人生の包丁」は意味をなさず、夏の思い出の文と合わない。"}, "sentence_index": 0, "correct_answer": "エポック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週のエポックが、すでに一件入っている。", "explanation": "ここは〈予定の一件〉の意味。エポックは特別な時点で、予定の項目を指さないので入れられない。"}, {"text": "卒業のエポックを、大切に飾っている。", "explanation": "ここは〈記念に残す品〉の意味。エポックは時点を表すので、飾れるものにはならない。"}, {"text": "うちのエポックは、家族の一員だ。", "explanation": "ここは〈生き物〉の意味。エポックは時点で、家族の一員にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52963, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エポック", "is_correct": true, "explanation": "「転職は大きな〜だったので、日記に詳しく書いた」で、人生の画期となる出来事の時期を指すので合う。"}, {"text": "騒音", "is_correct": false, "explanation": "「転職は大きな騒音だったので」は意味をなさず、日記に書く理由にならない。"}, {"text": "体重", "is_correct": false, "explanation": "「転職は大きな体重だったので」は比喩としても通らず、文が成り立たない。"}, {"text": "面積", "is_correct": false, "explanation": "「転職は大きな面積だったので」は意味をなさず、理由の説明にならない。"}], "explanations": {"エポック": "「転職は大きな〜だったので、日記に詳しく書いた」で、人生の画期となる出来事の時期を指すので合う。", "騒音": "「転職は大きな騒音だったので」は意味をなさず、日記に書く理由にならない。", "体重": "「転職は大きな体重だったので」は比喩としても通らず、文が成り立たない。", "面積": "「転職は大きな面積だったので」は意味をなさず、理由の説明にならない。"}, "sentence_index": 6, "correct_answer": "エポック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どものエポックが高く、ぐったりしている。", "explanation": "ここは〈体温〉の意味。エポックは時点を表すので、体の熱の高さは表さない。"}, {"text": "このスープはエポックが濃い。", "explanation": "ここは〈味〉の意味。エポックは特別な時点で、味の濃さは表さない。"}, {"text": "彼はエポックが若く見える。", "explanation": "ここは〈年齢〉の意味。エポックは時点を表すので、年齢の若さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52963, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引っ越した年は、家族の生活に一つのエポックもたらした。", "corrected_sentence": "引っ越した年は、家族の生活に一つのエポックをもたらした。", "error_description": "「もたらす」の目的語は「を」で示す。「を」がないと文が成り立たず、「エポック」に付く助詞が抜けている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52963, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの夏の出会いは、私にとって大切なエポックを心に刻まれている。", "corrected_sentence": "あの夏の出会いは、私にとって大切なエポックとして心に刻まれている。", "error_description": "「として心に刻まれる」の助詞は「として」。「を」は誤りで、エポックの資格を示す「として」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52964, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「〜となる」の助詞「と」。エポックとなった、の意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「エポックを」は目的語で、「なる」とは組めない。"}, {"text": "が", "is_correct": false, "explanation": "「エポックが」は主語で、「なった」の補語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「エポックで」は手段や場所を示し、「なった」の補語にならない。"}], "correct_answer": "と", "explanations": {"と": "「〜となる」の助詞「と」。エポックとなった、の意味になる。", "を": "「エポックを」は目的語で、「なる」とは組めない。", "が": "「エポックが」は主語で、「なった」の補語にならない。", "で": "「エポックで」は手段や場所を示し、「なった」の補語にならない。"}, "error_tags": {"を": "目的語（なるとは組めない）", "が": "主語（補語にならない）", "で": "手段（補語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52964, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52964, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "歴史や物事の流れの中で、特徴的な出来事や変化が起こった、特別な時期や時代。", "primary_collocate": null, "pronunciation": "えぽっく", "ipa": "epokkɯ", "syllable_count": 4, "sentences": [{"text": "十九世紀末のエポックには、アトリエの職人の手による精緻な刺繍とドレープが、身体を包み込む芸術として確立された。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "十九世紀末[じゅうきゅうせいきまつ]のエポックには、アトリエの職人[しょくにん]の手[て]による精緻[せいち]な刺繍[ししゅう]とドレープが、身体[しんたい]を包[つつ]み込[こ]む芸術[げいじゅつ]として確立[かくりつ]された。", "sentence_source": "generated"}, {"text": "蒸気機関の発明は、人類の歴史にとって大きなエポックとなった。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "蒸気機関[じょうききかん]の発明[はつめい]は、人類[じんるい]の歴史[れきし]にとって大[おお]きなエポックとなった。", "sentence_source": "generated"}, {"text": "彼女の優勝は、日本の女子スポーツにとって一つのエポックだった。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の優勝[ゆうしょう]は、日本[にほん]の女子[じょし]スポーツにとって一[ひと]つのエポックだった。", "sentence_source": "generated"}, {"text": "印刷技術が広まった十五世紀は、文化の面でも新しいエポックだと言われる。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "印刷技術[いんさつぎじゅつ]が広[ひろ]まった十五世紀[じゅうごせいき]は、文化[ぶんか]の面[めん]でも新[あたら]しいエポックだと言[い]われる。", "sentence_source": "generated"}, {"text": "インターネットの普及を機に、私たちの暮らしは新しいエポックに入った。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "インターネットの普及[ふきゅう]を機[き]に、私[わたし]たちの暮[く]らしは新[あたら]しいエポックに入[はい]った。", "sentence_source": "generated"}, {"text": "この小説は、戦後文学のエポックを画した作品として評価されている。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、戦後文学[せんごぶんがく]のエポックを画[かく]した作品[さくひん]として評価[ひょうか]されている。", "sentence_source": "generated"}, {"text": "戦後の高度経済成長は、日本の社会史の大きなエポックだが、それだけで社会の姿が決まるわけではない。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "戦後[せんご]の高度[こうど]経済成長[けいざいせいちょう]は、日本[にほん]の社会史[しゃかいし]の大[おお]きなエポックだが、それだけで社会[しゃかい]の姿[すがた]が決[き]まるわけではない。", "sentence_source": "generated"}, {"text": "月面着陸に成功した一九六九年は、宇宙開発の歴史におけるエポックである。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "月面着陸[げつめんちゃくりく]に成功[せいこう]した一九六九年[せんきゅうひゃくろくじゅうきゅうねん]は、宇宙開発[うちゅうかいはつ]の歴史[れきし]におけるエポックである。", "sentence_source": "generated"}, {"text": "展覧会では、画家の作風が変わったエポックを境に、作品が二つの部屋に分けて並べられていた。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]では、画家[がか]の作風[さくふう]が変[か]わったエポックを境[さかい]に、作品[さくひん]が二[ふた]つの部屋[へや]に分[わ]けて並[なら]べられていた。", "sentence_source": "generated"}, {"text": "先生は、明治維新を日本の近代化の最初のエポックと位置づけた。", "target_word": "エポック", "complexity_tier": "T3", "furigana": "先生[せんせい]は、明治維新[めいじいしん]を日本[にほん]の近代化[きんだいか]の最初[さいしょ]のエポックと位置[いち]づけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エポック", "label": "基本形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "歴史や人生の流れを区切る、画期的な出来事のあった時期・時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52964, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エポック", "is_correct": true, "explanation": "「十九世紀末のエポックには」で、ある時代の区切りを指すので合う。"}, {"text": "寝具", "is_correct": false, "explanation": "「十九世紀末の寝具には」は時代の区切りとして成り立たず、文が通らない。"}, {"text": "包丁", "is_correct": false, "explanation": "「十九世紀末の包丁には」は時代の区切りとして意味をなさない。"}, {"text": "湿度", "is_correct": false, "explanation": "「十九世紀末の湿度には」は時代の区切りとして意味をなさない。"}], "explanations": {"エポック": "「十九世紀末のエポックには」で、ある時代の区切りを指すので合う。", "寝具": "「十九世紀末の寝具には」は時代の区切りとして成り立たず、文が通らない。", "包丁": "「十九世紀末の包丁には」は時代の区切りとして意味をなさない。", "湿度": "「十九世紀末の湿度には」は時代の区切りとして意味をなさない。"}, "sentence_index": 0, "correct_answer": "エポック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街は秋のエポックを迎え、木々が色づいた。", "explanation": "ここは〈季節の移り変わり〉の意味。エポックは歴史上の画期的な時期で、季節には使わない。"}, {"text": "チームは来年のエポックを掲げた。", "explanation": "ここは〈目標・目的〉の意味。エポックは区切りの時期を指し、掲げる目標にはならない。"}, {"text": "古い車のエポックを交換した。", "explanation": "ここは〈部品〉の意味。エポックは時代の区切りで、物の部品を指さないので交換の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52964, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エポック", "is_correct": true, "explanation": "「戦後の高度経済成長は日本の社会史の大きな〜だが」で、歴史の画期となる時期を指すので合う。"}, {"text": "騒音", "is_correct": false, "explanation": "「大きな騒音だが」は意味をなさず、社会の姿の説明にならない。"}, {"text": "体重", "is_correct": false, "explanation": "「大きな体重だが」は比喩としても通らず、文が成り立たない。"}, {"text": "面積", "is_correct": false, "explanation": "「大きな面積だが」は意味をなさず、文の意味が合わない。"}], "explanations": {"エポック": "「戦後の高度経済成長は日本の社会史の大きな〜だが」で、歴史の画期となる時期を指すので合う。", "騒音": "「大きな騒音だが」は意味をなさず、社会の姿の説明にならない。", "体重": "「大きな体重だが」は比喩としても通らず、文が成り立たない。", "面積": "「大きな面積だが」は意味をなさず、文の意味が合わない。"}, "sentence_index": 6, "correct_answer": "エポック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日のエポックは晴れになるらしい。", "explanation": "ここは〈天気〉の意味。エポックは時代の区切りで、天候は表さないので晴れにはならない。"}, {"text": "この店のエポックは、学生は半額だ。", "explanation": "ここは〈料金〉の意味。エポックは時期を指し、値段の説明には使わない。"}, {"text": "彼女はエポックが明るく、誰とでもすぐ仲良くなる。", "explanation": "ここは〈人の性格〉の意味。エポックは時代の区切りで、人の性格は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52964, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉄道の開通は、この町にとって大きなエポックをなった。", "corrected_sentence": "鉄道の開通は、この町にとって大きなエポックとなった。", "error_description": "「なる」と組むのは「と」。「を」は誤りで、正しくは「エポックと」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52964, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その発見は、医学の歴史において大きなエポックを語り継がれている。", "corrected_sentence": "その発見は、医学の歴史において大きなエポックとして語り継がれている。", "error_description": "「として語り継がれる」の助詞は「として」。「を」は誤りで、語り継がれる対象の資格を示す「として」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52965, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の対象として手指を直接つなぐ〈を〉が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「手指が使って」は主語として成り立たず、〈が〉は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「手指に使って」は成り立たず、〈に〉は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「手指と使って」は相手を示す〈と〉で、使う対象の文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「使う」の対象として手指を直接つなぐ〈を〉が正しい。", "が": "「手指が使って」は主語として成り立たず、〈が〉は合わない。", "に": "「手指に使って」は成り立たず、〈に〉は合わない。", "と": "「手指と使って」は相手を示す〈と〉で、使う対象の文脈に合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "着点・相手", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52965, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「手指の汚れ」として手指と汚れを結ぶ〈の〉が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「手指を汚れを」は目的語が重なり、〈を〉は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「手指に汚れ」は意味が通らず、〈に〉は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「手指と汚れ」は並列になり、所有関係の〈の〉の代わりにはならない。"}], "correct_answer": "の", "explanations": {"の": "「手指の汚れ」として手指と汚れを結ぶ〈の〉が正しい。", "を": "「手指を汚れを」は目的語が重なり、〈を〉は合わない。", "に": "「手指に汚れ」は意味が通らず、〈に〉は合わない。", "と": "「手指と汚れ」は並列になり、所有関係の〈の〉の代わりにはならない。"}, "error_tags": {"の": "連体・所有", "を": "目的語", "に": "着点・相手", "と": "共同・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52965, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "手の指のこと。", "primary_collocate": null, "pronunciation": "しゅし", "ipa": "ɕɯɕi", "syllable_count": 2, "sentences": [{"text": "手を洗うときは、手指のあいだもきれいに洗います。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手[て]を洗[あら]うときは、手指[しゅし]のあいだもきれいに洗[あら]います。", "sentence_source": "generated"}, {"text": "手指を使って、小さなビーズを糸に通した。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手指[しゅし]を使[つか]って、小[ちい]さなビーズを糸[いと]に通[とお]した。", "sentence_source": "generated"}, {"text": "雪の中で遊んだので、手指が冷たくなった。", "target_word": "手指", "complexity_tier": "T3", "furigana": "雪[ゆき]の中[なか]で遊[あそ]んだので、手指[しゅし]が冷[つめ]たくなった。", "sentence_source": "generated"}, {"text": "手指を一本ずつ曲げて、数を数えた。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手指[しゅし]を一本[いっぽん]ずつ曲[ま]げて、数[かず]を数[かぞ]えた。", "sentence_source": "generated"}, {"text": "彼女は手指が長く、ピアノを弾くのに向いている。", "target_word": "手指", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は手指[しゅし]が長[なが]く、ピアノを弾[ひ]くのに向[む]いている。", "sentence_source": "generated"}, {"text": "作業中に手指を切ってしまい、絆創膏をはった。", "target_word": "手指", "complexity_tier": "T3", "furigana": "作業中[さぎょうちゅう]に手指[しゅし]を切[き]ってしまい、絆創膏[ばんそうこう]をはった。", "sentence_source": "generated"}, {"text": "手指に力が入らなくなったので、病院で診てもらった。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手指[しゅし]に力[ちから]が入[はい]らなくなったので、病院[びょういん]で診[み]てもらった。", "sentence_source": "generated"}, {"text": "手指の汚れを落とすために、ブラシを使った。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手指[しゅし]の汚[よご]れを落[お]とすために、ブラシを使[つか]った。", "sentence_source": "generated"}, {"text": "祖父の手指は節くれ立っていて、長年の仕事を物語っていた。", "target_word": "手指", "complexity_tier": "T3", "furigana": "祖父[そふ]の手指[しゅし]は節[ふし]くれ立[だ]っていて、長年[ながねん]の仕事[しごと]を物語[ものがた]っていた。", "sentence_source": "generated"}, {"text": "赤ちゃんは自分の手指を口に入れて遊んでいる。", "target_word": "手指", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは自分[じぶん]の手指[しゅし]を口[くち]に入[い]れて遊[あそ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手指", "label": "基本形"}], "register": "やや硬い書き言葉（医療・衛生・技術の場面）", "sense_fingerprint": "手についている指そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52965, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手指", "is_correct": true, "explanation": "「手を洗うときは、＿のあいだも洗う」の対象は指で、手指が入る。"}, {"text": "石けん", "is_correct": false, "explanation": "石けんは洗うための道具で、「石けんのあいだ」は文の意味が通らない。"}, {"text": "洗面所", "is_correct": false, "explanation": "洗面所は場所で、洗われる部位のあいだを指せないので合わない。"}, {"text": "水道", "is_correct": false, "explanation": "水道は設備で、「水道のあいだもきれいに洗う」は成り立たない。"}], "explanations": {"手指": "「手を洗うときは、＿のあいだも洗う」の対象は指で、手指が入る。", "石けん": "石けんは洗うための道具で、「石けんのあいだ」は文の意味が通らない。", "洗面所": "洗面所は場所で、洗われる部位のあいだを指せないので合わない。", "水道": "水道は設備で、「水道のあいだもきれいに洗う」は成り立たない。"}, "sentence_index": 0, "correct_answer": "手指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裸足で歩いたので、手指のすきまに砂が入った。", "explanation": "ここは〈足指〉の意味。足の指のすきまに入る砂で、手指とは言わないので合わない。"}, {"text": "腕時計は手指にはめて使う。", "explanation": "ここは〈手首〉の意味。腕時計は手首につけるもので、手指にははめないので合わない。"}, {"text": "重い箱を両手指で抱えて運んだ。", "explanation": "ここは〈手〉の意味。箱を抱えるのは手全体で、指だけでは抱えられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52965, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手指", "is_correct": true, "explanation": "「＿に力が入らなくなった」の主語は手指で、力が入らなくなるのは手指なので正しい。"}, {"text": "病院", "is_correct": false, "explanation": "病院は場所で、「病院に力が入らない」は成り立たない。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪は身につける物で、力が入らなくなる部位にはならないので合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は感覚で、「眠気に力が入らない」は文の意味が通らない。"}], "explanations": {"手指": "「＿に力が入らなくなった」の主語は手指で、力が入らなくなるのは手指なので正しい。", "病院": "病院は場所で、「病院に力が入らない」は成り立たない。", "指輪": "指輪は身につける物で、力が入らなくなる部位にはならないので合わない。", "眠気": "眠気は感覚で、「眠気に力が入らない」は文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "手指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "伸びた手指をやすりで削って丸めた。", "explanation": "ここは〈爪〉の意味。やすりで削って整えるのは爪で、手指とは言わないので合わない。"}, {"text": "式場で、二人は手指を交換した。", "explanation": "ここは〈指輪〉の意味。交換するのは指輪で、手指とは言わないので合わない。"}, {"text": "寒い朝、外に出るとき手指をはめて指先まで覆った。", "explanation": "ここは〈手袋〉の意味。指先まで覆うのは手袋で、手指をはめるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52965, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凍えた手指に、息で温めた。", "corrected_sentence": "凍えた手指を、息で温めた。", "error_description": "「温める」は〈を〉で目的語をとる。手指の直後は〈に〉ではなく〈を〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52965, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ピアノの練習のあとで、手指が軽くマッサージした。", "corrected_sentence": "ピアノの練習のあとで、手指を軽くマッサージした。", "error_description": "「マッサージする」は〈を〉で目的語をとる。手指の直後は〈が〉ではなく〈を〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52966, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「洗う」の目的語として手指を直接つなぐ〈を〉が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「手指に洗う」は成り立たず、〈に〉は「洗う」の助詞として合わない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すが、ここで手指は洗われる対象なので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「手指と洗う」は相手を示す〈と〉で、洗う対象の文脈には合わない。"}], "correct_answer": "を", "explanations": {"を": "「洗う」の目的語として手指を直接つなぐ〈を〉が正しい。", "に": "「手指に洗う」は成り立たず、〈に〉は「洗う」の助詞として合わない。", "が": "〈が〉は主語を示すが、ここで手指は洗われる対象なので合わない。", "と": "「手指と洗う」は相手を示す〈と〉で、洗う対象の文脈には合わない。"}, "error_tags": {"を": "目的語", "に": "着点・相手", "が": "主語", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52966, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「動かす」の目的語として手指を直接つなぐ〈を〉が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示し、「手指へ動かす」では動かす対象にならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示し、「手指より動かす」では動かす対象にならず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「手指の」は修飾になり、「動かす」の目的語として手指を直接つなぐ形にはならない。"}], "correct_answer": "を", "explanations": {"を": "「動かす」の目的語として手指を直接つなぐ〈を〉が正しい。", "へ": "〈へ〉は方向を示し、「手指へ動かす」では動かす対象にならず不自然。", "より": "〈より〉は比較を示し、「手指より動かす」では動かす対象にならず文が成り立たない。", "の": "「手指の」は修飾になり、「動かす」の目的語として手指を直接つなぐ形にはならない。"}, "error_tags": {"を": "目的語", "へ": "方向（目的語にならない）", "より": "比較（目的語にならない）", "の": "修飾（目的語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52966, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "手の指。手の先にある、物をつかんだり触ったりする部分。", "primary_collocate": null, "pronunciation": "しゅし", "ipa": "ɕɯɕi", "syllable_count": 2, "sentences": [{"text": "職人の手指による刺繍は、とても細かく美しい。", "target_word": "手指", "complexity_tier": "T3", "furigana": "職人[しょくにん]の手指[しゅし]による刺繍[ししゅう]は、とても細[こま]かく美[うつく]しい。", "sentence_source": "generated"}, {"text": "食事の前には、石けんで手指をよく洗ってください。", "target_word": "手指", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]には、石[せっ]けんで手指[しゅし]をよく洗[あら]ってください。", "sentence_source": "generated"}, {"text": "ピアニストは、毎日の練習で手指の動きをなめらかにしている。", "target_word": "手指", "complexity_tier": "T3", "furigana": "ピアニストは、毎日[まいにち]の練習[れんしゅう]で手指[しゅし]の動[うご]きをなめらかにしている。", "sentence_source": "generated"}, {"text": "寒い朝は、手指がかじかんでうまくペンが持てない。", "target_word": "手指", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は、手指[しゅし]がかじかんでうまくペンが持[も]てない。", "sentence_source": "generated"}, {"text": "手指に怪我をした彼は、しばらく楽器を弾けなかった。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手指[しゅし]に怪我[けが]をした彼[かれ]は、しばらく楽器[がっき]を弾[ひ]けなかった。", "sentence_source": "generated"}, {"text": "赤ちゃんは、小さな手指でお母さんの服をぎゅっとつかんだ。", "target_word": "手指", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、小[ちい]さな手指[しゅし]でお母[かあ]さんの服[ふく]をぎゅっとつかんだ。", "sentence_source": "generated"}, {"text": "外から帰ったら、アルコールで手指を消毒する習慣をつけている。", "target_word": "手指", "complexity_tier": "T3", "furigana": "外[そと]から帰[かえ]ったら、アルコールで手指[しゅし]を消毒[しょうどく]する習慣[しゅうかん]をつけている。", "sentence_source": "generated"}, {"text": "手術のあと、リハビリで手指を動かす訓練を続けた。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]のあと、リハビリで手指[しゅし]を動[うご]かす訓練[くんれん]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "手指の細かい作業が得意な彼は、時計の修理職人になった。", "target_word": "手指", "complexity_tier": "T3", "furigana": "手指[しゅし]の細[こま]かい作業[さぎょう]が得意[とくい]な彼[かれ]は、時計[とけい]の修理職人[しゅうりしょくにん]になった。", "sentence_source": "generated"}, {"text": "冬になると、手指が乾燥してひび割れができやすい。", "target_word": "手指", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、手指[しゅし]が乾燥[かんそう]してひび割[わ]れができやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手指", "label": "基本形"}], "register": "やや硬い書き言葉（医療・衛生・技術の場面）", "sense_fingerprint": "物をつかんだり触ったりする、手の先の指の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: かじかん (Zipf 1.97)']::text[], '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52966, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手指", "is_correct": true, "explanation": "「職人の＿による刺繍」の主体は手の指なので、手指が入る。"}, {"text": "素材", "is_correct": false, "explanation": "素材は材料を指し、作業の主体にはならないので「職人の素材による刺繍」は不自然。"}, {"text": "休日", "is_correct": false, "explanation": "休日は作業の主体になれず、文の意味が通らない。"}, {"text": "時間", "is_correct": false, "explanation": "時間は作業をする主体にならず、「職人の時間による刺繍」は成り立たない。"}], "explanations": {"手指": "「職人の＿による刺繍」の主体は手の指なので、手指が入る。", "素材": "素材は材料を指し、作業の主体にはならないので「職人の素材による刺繍」は不自然。", "休日": "休日は作業の主体になれず、文の意味が通らない。", "時間": "時間は作業をする主体にならず、「職人の時間による刺繍」は成り立たない。"}, "sentence_index": 0, "correct_answer": "手指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裸足で砂浜を歩いたら、手指の間に砂が入った。", "explanation": "ここは〈足指〉の意味。手指は手の指のことで、足の指には使わないので合わない。"}, {"text": "腕時計は手指にはめて使う。", "explanation": "ここは〈手首〉の意味。腕時計は手首につけるもので、手指にははめないので合わない。"}, {"text": "重い箱を両手指で抱えて運んだ。", "explanation": "ここは〈手〉の意味。箱を抱えるのは手全体で、指だけでは抱えられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52966, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手指", "is_correct": true, "explanation": "「アルコールで＿を消毒する」の対象は手指なので正しい。"}, {"text": "天気", "is_correct": false, "explanation": "天気は消毒の対象にならず、「天気を消毒する」は成り立たない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は消毒できるものではなく、文の意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は消毒の対象にならず、「眠気を消毒する」は不自然。"}], "explanations": {"手指": "「アルコールで＿を消毒する」の対象は手指なので正しい。", "天気": "天気は消毒の対象にならず、「天気を消毒する」は成り立たない。", "時刻": "時刻は消毒できるものではなく、文の意味が通らない。", "眠気": "眠気は消毒の対象にならず、「眠気を消毒する」は不自然。"}, "sentence_index": 6, "correct_answer": "手指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爪切りで、伸びた手指をきれいに整えた。", "explanation": "ここは〈爪〉の意味。伸びて整えるのは爪なので、手指とは言わず合わない。"}, {"text": "結婚式で、二人は手指を交換した。", "explanation": "ここは〈指輪〉の意味。交換するのは指輪で、手指とは言わないので合わない。"}, {"text": "寒い日は、外に出る前に手指をはめて出かける。", "explanation": "ここは〈手袋〉の意味。はめるのは手袋で、手指にはめるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52966, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の冷え込みで、手指にかじかんで字が書けなかった。", "corrected_sentence": "朝の冷え込みで、手指がかじかんで字が書けなかった。", "error_description": "「かじかむ」は〈が〉で主語をとる。手指の直後の助詞は〈に〉ではなく〈が〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52966, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長時間の入力で疲れた手指に休めるため、少し横になった。", "corrected_sentence": "長時間の入力で疲れた手指を休めるため、少し横になった。", "error_description": "「休める」は〈を〉で目的語をとる。手指の直後は〈に〉ではなく〈を〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
