INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52969, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間のからだ。頭・手・足などの部位をそなえる。", "primary_collocate": null, "pronunciation": "しんたい", "ipa": "ɕiɴtai", "syllable_count": 4, "sentences": [{"text": "人間の身体には、頭、手、足などがある。", "target_word": "身体", "complexity_tier": "T3", "furigana": "人間[にんげん]の身体[しんたい]には、頭[あたま]、手[て]、足[あし]などがある。", "sentence_source": "generated"}, {"text": "身体の柔らかさを保つため、私は毎朝ストレッチをしている。", "target_word": "身体", "complexity_tier": "T3", "furigana": "身体[しんたい]の柔[やわ]らかさを保[たも]つため、私[わたし]は毎朝[まいあさ]ストレッチをしている。", "sentence_source": "generated"}, {"text": "身体の発育を確かめるために、毎月赤ちゃんの大きさを測る。", "target_word": "身体", "complexity_tier": "T3", "furigana": "身体[しんたい]の発育[はついく]を確[たし]かめるために、毎月[まいつき]赤[あか]ちゃんの大[おお]きさを測[はか]る。", "sentence_source": "generated"}, {"text": "年をとると、身体の機能が少しずつ衰える。", "target_word": "身体", "complexity_tier": "T3", "furigana": "年[とし]をとると、身体[しんたい]の機能[きのう]が少[すこ]しずつ衰[おとろ]える。", "sentence_source": "generated"}, {"text": "身体と心は深くつながっていると、先生は話した。", "target_word": "身体", "complexity_tier": "T3", "furigana": "身体[しんたい]と心[こころ]は深[ふか]くつながっていると、先生[せんせい]は話[はな]した。", "sentence_source": "generated"}, {"text": "身体の疲れをとるには、十分な睡眠が必要です。", "target_word": "身体", "complexity_tier": "T3", "furigana": "身体[しんたい]の疲[つか]れをとるには、十分[じゅうぶん]な睡眠[すいみん]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "この彫刻は、人間の身体の美しさを表している。", "target_word": "身体", "complexity_tier": "T3", "furigana": "この彫刻[ちょうこく]は、人間[にんげん]の身体[しんたい]の美[うつく]しさを表[あらわ]している。", "sentence_source": "generated"}, {"text": "人の身体は、骨や筋肉や皮膚などでできている。", "target_word": "身体", "complexity_tier": "T3", "furigana": "人[ひと]の身体[しんたい]は、骨[ほね]や筋肉[きんにく]や皮膚[ひふ]などでできている。", "sentence_source": "generated"}, {"text": "事故で身体に傷を負ったが、命に別状はなかった。", "target_word": "身体", "complexity_tier": "T3", "furigana": "事故[じこ]で身体[しんたい]に傷[きず]を負[お]ったが、命[いのち]に別状[べつじょう]はなかった。", "sentence_source": "generated"}, {"text": "身体の左右で、手の大きさが少し違う人もいる。", "target_word": "身体", "complexity_tier": "T3", "furigana": "身体[しんたい]の左右[さゆう]で、手[て]の大[おお]きさが少[すこ]し違[ちが]う人[ひと]もいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "身体", "label": "基本形"}], "register": "硬い書き言葉（医学・学術の場面）", "sense_fingerprint": "手・足・頭などをもつ、人のからだ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52969, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身体", "is_correct": true, "explanation": "「人間の＿には、頭、手、足などがある」の主語は人のからだで、身体が入る。"}, {"text": "天気", "is_correct": false, "explanation": "天気には頭や手足がないので、文の意味が通らない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻には頭や手足がないので、文の意味が通らない。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪には頭や手足がないので、文の意味が通らない。"}], "explanations": {"身体": "「人間の＿には、頭、手、足などがある」の主語は人のからだで、身体が入る。", "天気": "天気には頭や手足がないので、文の意味が通らない。", "時刻": "時刻には頭や手足がないので、文の意味が通らない。", "指輪": "指輪には頭や手足がないので、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "身体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木は身体が高く、枝が大きく広がっている。", "explanation": "ここは〈木〉の意味。身体は生き物のからだを指すので、木の本体には使わないので合わない。"}, {"text": "この石は身体が重く、持ち上げられない。", "explanation": "ここは〈石〉の意味。石の重さは形や大きさで言い、身体とは言わないので合わない。"}, {"text": "この机は身体が丈夫で、長く使える。", "explanation": "ここは〈机〉の意味。物の本体には身体を使わないので、机の丈夫さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52969, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身体", "is_correct": true, "explanation": "「人間の＿の美しさ」の対象は人のからだで、身体が入る。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は人間の身体の美しさを表す対象にならず、文の意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は美しさの対象にならず、「人間の眠気の美しさ」は成り立たない。"}, {"text": "予定", "is_correct": false, "explanation": "予定は美しさの対象にならず、「人間の予定の美しさ」は不自然。"}], "explanations": {"身体": "「人間の＿の美しさ」の対象は人のからだで、身体が入る。", "郵便": "郵便は人間の身体の美しさを表す対象にならず、文の意味が通らない。", "眠気": "眠気は美しさの対象にならず、「人間の眠気の美しさ」は成り立たない。", "予定": "予定は美しさの対象にならず、「人間の予定の美しさ」は不自然。"}, "sentence_index": 6, "correct_answer": "身体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は身体がさびて、塗り直した。", "explanation": "ここは〈車体〉の意味。車の外側は車体で、身体とは言わないので合わない。"}, {"text": "パソコンの身体が熱くなったので、ファンを掃除した。", "explanation": "ここは〈本体〉の意味。機器の中心部は本体で、身体とは言わないので合わない。"}, {"text": "この船は身体が大きく、港に入れない。", "explanation": "ここは〈船体〉の意味。船の本体は船体で、身体とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52969, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は身体が温めてから外出する。", "corrected_sentence": "寒い日は身体を温めてから外出する。", "error_description": "「温める」は〈を〉で目的語をとる。身体の直後は〈が〉ではなく〈を〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52969, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この体操は、身体が鍛える。", "corrected_sentence": "この体操は、身体を鍛える。", "error_description": "「鍛える」は〈を〉で目的語をとる。身体の直後は〈が〉ではなく〈を〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
