INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52970, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「身体の構造」として身体と構造を結ぶ〈の〉が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「身体を構造を」は目的語が重なり、〈を〉は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「身体に構造を」は成り立たず、〈に〉は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「身体が構造を」は主語と目的語が噛み合わず、〈が〉は合わない。"}], "correct_answer": "の", "explanations": {"の": "「身体の構造」として身体と構造を結ぶ〈の〉が正しい。", "を": "「身体を構造を」は目的語が重なり、〈を〉は合わない。", "に": "「身体に構造を」は成り立たず、〈に〉は合わない。", "が": "「身体が構造を」は主語と目的語が噛み合わず、〈が〉は合わない。"}, "error_tags": {"の": "連体・所有", "を": "目的語", "に": "着点・相手", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52970, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間や動物の、頭から足までの全体。特に、生きている人のからだ。", "primary_collocate": null, "pronunciation": "しんたい", "ipa": "ɕiɴtai", "syllable_count": 4, "sentences": [{"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "身体", "complexity_tier": "T3", "furigana": "ベル・エポック期[き]、アトリエにおける職人[しょくにん]の手指[しゅし]による精緻[せいち]な刺繍[ししゅう]とドレープは、身体[しんたい]を包[つつ]み込[こ]む芸術[げいじゅつ]として確立[かくりつ]された。", "sentence_source": "mined"}, {"text": "人間の身体は、約六十パーセントが水分でできている。", "target_word": "身体", "complexity_tier": "T3", "furigana": "人間[にんげん]の身体[しんたい]は、約[やく]六十[ろくじゅう]パーセントが水分[すいぶん]でできている。", "sentence_source": "generated"}, {"text": "成長期には、身体と心の両方が大きく変化する。", "target_word": "身体", "complexity_tier": "T3", "furigana": "成長期[せいちょうき]には、身体[しんたい]と心[こころ]の両方[りょうほう]が大[おお]きく変化[へんか]する。", "sentence_source": "generated"}, {"text": "子どもの身体の発達に合わせて、運動の内容を変えた。", "target_word": "身体", "complexity_tier": "T3", "furigana": "子[こ]どもの身体[しんたい]の発達[はったつ]に合[あ]わせて、運動[うんどう]の内容[ないよう]を変[か]えた。", "sentence_source": "generated"}, {"text": "ダンサーは、身体の動きだけで感情を表現する。", "target_word": "身体", "complexity_tier": "T3", "furigana": "ダンサーは、身体[しんたい]の動[うご]きだけで感情[かんじょう]を表現[ひょうげん]する。", "sentence_source": "generated"}, {"text": "医師は、患者の身体の状態を詳しく調べた。", "target_word": "身体", "complexity_tier": "T3", "furigana": "医師[いし]は、患者[かんじゃ]の身体[しんたい]の状態[じょうたい]を詳[くわ]しく調[しら]べた。", "sentence_source": "generated"}, {"text": "長時間の緊張は、身体に負担をかけてしまう。", "target_word": "身体", "complexity_tier": "T3", "furigana": "長時間[ちょうじかん]の緊張[きんちょう]は、身体[しんたい]に負担[ふたん]をかけてしまう。", "sentence_source": "generated"}, {"text": "解剖学では、身体の構造を部位ごとに学ぶ。", "target_word": "身体", "complexity_tier": "T3", "furigana": "解剖学[かいぼうがく]では、身体[しんたい]の構造[こうぞう]を部位[ぶい]ごとに学[まな]ぶ。", "sentence_source": "generated"}, {"text": "憲法は、人が不当に身体を拘束されない権利を保障している。", "target_word": "身体", "complexity_tier": "T3", "furigana": "憲法[けんぽう]は、人[ひと]が不当[ふとう]に身体[しんたい]を拘束[こうそく]されない権利[けんり]を保障[ほしょう]している。", "sentence_source": "generated"}, {"text": "彼女は、身体の柔らかさを生かして新体操の選手になった。", "target_word": "身体", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、身体[しんたい]の柔[やわ]らかさを生[い]かして新体操[しんたいそう]の選手[せんしゅ]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "身体", "label": "基本形"}], "register": "硬い書き言葉（医学・法律・学術の場面）", "sense_fingerprint": "頭から足までを含む、生きた人間のからだ全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ドレープ (Zipf 1.9)']::text[], '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52970, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身体", "is_correct": true, "explanation": "「＿を包み込む芸術」は人のからだ全体を指すので、身体が入る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は包み込む対象にならず、「天気を包み込む芸術」は成り立たない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は包み込む対象にならず、文の意味が通らない。"}, {"text": "原稿", "is_correct": false, "explanation": "原稿は包み込む対象として不自然で、ここでは合わない。"}], "explanations": {"身体": "「＿を包み込む芸術」は人のからだ全体を指すので、身体が入る。", "天気": "天気は包み込む対象にならず、「天気を包み込む芸術」は成り立たない。", "時刻": "時刻は包み込む対象にならず、文の意味が通らない。", "原稿": "原稿は包み込む対象として不自然で、ここでは合わない。"}, "sentence_index": 0, "correct_answer": "身体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポットの身体が割れたので、新しく買った。", "explanation": "ここは〈本体〉の意味。ポットの本体は身体とは言わないので合わない。"}, {"text": "この壁の身体にひびが入ったので、補修した。", "explanation": "ここは〈壁〉の意味。壁の表面は身体とは言わないので合わない。"}, {"text": "ほつれた身体を縫い直した。", "explanation": "ここは〈服〉の意味。縫い直すのは服で、身体とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52970, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身体", "is_correct": true, "explanation": "「＿に負担をかけてしまう」の対象はからだ全体で、身体が入る。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は負担をかける対象にならず、「郵便に負担をかける」は成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は負担をかける対象にならず、文の意味が通らない。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪は身につける物で、負担をかける対象としては合わない。"}], "explanations": {"身体": "「＿に負担をかけてしまう」の対象はからだ全体で、身体が入る。", "郵便": "郵便は負担をかける対象にならず、「郵便に負担をかける」は成り立たない。", "眠気": "眠気は負担をかける対象にならず、文の意味が通らない。", "指輪": "指輪は身につける物で、負担をかける対象としては合わない。"}, "sentence_index": 6, "correct_answer": "身体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故で身体が折れたので、ギプスで固定した。", "explanation": "ここは〈骨〉の意味。折れるのは骨で、身体全体が折れるとは言わないので合わない。"}, {"text": "この車は身体にへこみができたので、板金に出した。", "explanation": "ここは〈車体〉の意味。車の外側は車体で、身体にへこみができるとは言わないので合わない。"}, {"text": "ラジオの身体が割れたので、修理に出した。", "explanation": "ここは〈本体〉の意味。機器の中心部は本体で、身体とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52970, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マラソンのあと身体に疲れを取るため、湯船につかった。", "corrected_sentence": "マラソンのあと身体の疲れを取るため、湯船につかった。", "error_description": "「身体の疲れ」の〈の〉は身体と疲れを結ぶ助詞。〈に〉にすると「身体に疲れを取る」となり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52970, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ストレッチで身体が動かすと、気分が晴れる。", "corrected_sentence": "ストレッチで身体を動かすと、気分が晴れる。", "error_description": "「動かす」は〈を〉で目的語をとる。身体の直後は〈が〉ではなく〈を〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52971, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ドレープの技術」と、技術の内容を所属として示す。"}, {"text": "に", "is_correct": false, "explanation": "「ドレープに技術」は成り立たず、位置を表す『に』は名詞同士を結べない。"}, {"text": "を", "is_correct": false, "explanation": "「ドレープを技術を学ぶ」は目的語が二つ並び、不自然で文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』では「ドレープへ技術を学ぶ」となり、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「ドレープの技術」と、技術の内容を所属として示す。", "に": "「ドレープに技術」は成り立たず、位置を表す『に』は名詞同士を結べない。", "を": "「ドレープを技術を学ぶ」は目的語が二つ並び、不自然で文法的に成り立たない。", "へ": "方向を表す『へ』では「ドレープへ技術を学ぶ」となり、意味が通らない。"}, "error_tags": {"に": "位置", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52971, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ドレープでは」と、ここでの範囲や対象を示す。『は』と続けて主題を立てる。"}, {"text": "を", "is_correct": false, "explanation": "『ドレープを』は『は』と続けても主題にならず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の『から』では「ドレープから、布の重さ〜」となり、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』では「ドレープより、布の重さ〜」となり、比べる文脈がない。"}], "correct_answer": "で", "explanations": {"で": "「ドレープでは」と、ここでの範囲や対象を示す。『は』と続けて主題を立てる。", "を": "『ドレープを』は『は』と続けても主題にならず、不自然。", "から": "起点の『から』では「ドレープから、布の重さ〜」となり、意味が通らない。", "より": "比較の『より』では「ドレープより、布の重さ〜」となり、比べる文脈がない。"}, "error_tags": {"から": "起点", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52971, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "布をゆるく、きれいに垂らしてひだを作ること。", "primary_collocate": null, "pronunciation": "どれーぷ", "ipa": "doɾeːpɯ", "syllable_count": 4, "sentences": [{"text": "デザイナーはマネキンに布を当てて、ドレープを作りながら形を決めていく。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "デザイナーはマネキンに布[ぬの]を当[あ]てて、ドレープを作[つく]りながら形[かたち]を決[き]めていく。", "sentence_source": "generated"}, {"text": "ドレープの技術を学ぶために、服飾学校に通っている。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "ドレープの技術[ぎじゅつ]を学[まな]ぶために、服飾学校[ふくしょくがっこう]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "舞台の幕は、ドレープをきれいにつけるのに時間がかかった。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の幕[まく]は、ドレープをきれいにつけるのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "このドレスは、ドレープを何度もやり直して、ようやく納得のいく形になった。", "target_word": "ドレープ", "complexity_tier": "T4", "furigana": "このドレスは、ドレープを何度[なんど]もやり直[なお]して、ようやく納得[なっとく]のいく形[かたち]になった。", "sentence_source": "generated"}, {"text": "ドレープの手順は、まず布を肩に置き、次に流れを見ながらピンで留める。", "target_word": "ドレープ", "complexity_tier": "T4", "furigana": "ドレープの手順[てじゅん]は、まず布[ぬの]を肩[かた]に置[お]き、次[つぎ]に流[なが]れを見[み]ながらピンで留[と]める。", "sentence_source": "generated"}, {"text": "先生はドレープの練習に、やわらかいシフォンの布を使わせた。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "先生[せんせい]はドレープの練習[れんしゅう]に、やわらかいシフォンの布[ぬの]を使[つか]わせた。", "sentence_source": "generated"}, {"text": "窓辺のカーテンに、ドレープを一つずつ手で作っていった。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "窓辺[まどべ]のカーテンに、ドレープを一[ひと]つずつ手[て]で作[つく]っていった。", "sentence_source": "generated"}, {"text": "ドレープでは、布の重さを生かして自然に垂らすことがいちばん大切だ。", "target_word": "ドレープ", "complexity_tier": "T4", "furigana": "ドレープでは、布[ぬの]の重[おも]さを生[い]かして自然[しぜん]に垂[た]らすことがいちばん大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "立体裁断とは、ドレープによってデザインを形にする方法だ。", "target_word": "ドレープ", "complexity_tier": "T4", "furigana": "立体裁断[りったいさいだん]とは、ドレープによってデザインを形[かたち]にする方法[ほうほう]だ。", "sentence_source": "generated"}, {"text": "ドレープを作ることに慣れていない人は、布をすぐに引っ張ってしまう。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "ドレープを作[つく]ることに慣[な]れていない人[ひと]は、布[ぬの]をすぐに引[ひ]っ張[ぱ]ってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドレープ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "布を垂らしてひだを作る作業・技法(服作り・装飾)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52971, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドレープ", "is_correct": true, "explanation": "布を垂らしてひだを作る作業を指す。「ドレープを作りながら形を決める」の目的語として正しく入る。"}, {"text": "感想", "is_correct": false, "explanation": "心の中の受け止めを表す語で、布を作る作業の対象にはならない。"}, {"text": "雨粒", "is_correct": false, "explanation": "空から落ちる水滴で、布の形を作る作業の対象にはならない。"}, {"text": "方言", "is_correct": false, "explanation": "地域の話し言葉で、布の作業の対象として文に入らない。"}], "explanations": {"ドレープ": "布を垂らしてひだを作る作業を指す。「ドレープを作りながら形を決める」の目的語として正しく入る。", "感想": "心の中の受け止めを表す語で、布を作る作業の対象にはならない。", "雨粒": "空から落ちる水滴で、布の形を作る作業の対象にはならない。", "方言": "地域の話し言葉で、布の作業の対象として文に入らない。"}, "sentence_index": 0, "correct_answer": "ドレープ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "布の端を、ドレープで留めた。", "explanation": "ドレープは布を垂らして作る作業で、布を留める道具や動作ではない。"}, {"text": "赤ちゃんにドレープを着せて、写真を撮った。", "explanation": "ドレープは布の垂れた形や作業で、衣服そのものは指さない。"}, {"text": "洗濯物のタオルを、ドレープでたたんだ。", "explanation": "ドレープは布を垂らして作るもので、たたむ動作とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52971, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドレープ", "is_correct": true, "explanation": "布を垂らしてひだを作る作業を指す。「一つずつ手で作っていった」の目的語として正しく入る。"}, {"text": "渋滞", "is_correct": false, "explanation": "車が詰まる状態を指し、カーテンを手で作る作業の対象にはならない。"}, {"text": "雨季", "is_correct": false, "explanation": "雨の多い季節を指し、手作業の対象として文に入らない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸を指し、布を作る動作の対象にはならない。"}], "explanations": {"ドレープ": "布を垂らしてひだを作る作業を指す。「一つずつ手で作っていった」の目的語として正しく入る。", "渋滞": "車が詰まる状態を指し、カーテンを手で作る作業の対象にはならない。", "雨季": "雨の多い季節を指し、手作業の対象として文に入らない。", "寝息": "眠っている人の呼吸を指し、布を作る動作の対象にはならない。"}, "sentence_index": 6, "correct_answer": "ドレープ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スカートの丈を、ドレープで一本ずつ測っていった。", "explanation": "ドレープは垂らして作る作業で、長さを測る道具ではない。"}, {"text": "ぬれた髪を、ドレープで乾かした。", "explanation": "ドレープは布を垂らして形を作る作業で、髪を乾かす道具ではない。"}, {"text": "ドレープを飲むことに慣れていない人は、布をすぐに引っ張ってしまう。", "explanation": "『飲む』とは合わず、布を垂らす作業としては読めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52971, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "まず布を肩からゆるく垂らして、ドレープが作る。", "corrected_sentence": "まず布を肩からゆるく垂らして、ドレープを作る。", "error_description": "『作る』の目的語はドレープなので『を』が正しい。『が』にすると『ドレープ』が作る主体になり、目的語がなくて意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52971, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "布を肩に掛けて、ゆっくりドレープを作るた。", "corrected_sentence": "布を肩に掛けて、ゆっくりドレープを作った。", "error_description": "過去の活用が誤っている。『作るた』は成立せず、正しくは『作った』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52972, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ドレープが美しい」と、ドレープを主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「ドレープを美しい」は成り立たない。目的語の『を』は形容詞の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「ドレープに美しい」は成り立たない。位置を表す『に』は述語と結べない。"}, {"text": "の", "is_correct": false, "explanation": "『の』なら名詞修飾になり、『美しい。』で文が終わらない。"}], "correct_answer": "が", "explanations": {"が": "「ドレープが美しい」と、ドレープを主語として示す。", "を": "「ドレープを美しい」は成り立たない。目的語の『を』は形容詞の主語にはならない。", "に": "「ドレープに美しい」は成り立たない。位置を表す『に』は述語と結べない。", "の": "『の』なら名詞修飾になり、『美しい。』で文が終わらない。"}, "error_tags": {"を": "目的語", "に": "位置", "の": "名詞修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52972, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52972, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "布がゆるやかに垂れてできる、ひだのある形。", "primary_collocate": null, "pronunciation": "どれーぷ", "ipa": "doɾeːpɯ", "syllable_count": 4, "sentences": [{"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "ドレープ", "complexity_tier": "T5", "furigana": "ベル・エポック期[き]、アトリエにおける職人[しょくにん]の手指[てゆび]による精緻[せいち]な刺繍[ししゅう]とドレープは、身体[からだ]を包[つつ]み込[こ]む芸術[げいじゅつ]として確立[かくりつ]された。", "sentence_source": "mined"}, {"text": "このドレスは、胸元から流れるドレープが美しい。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "このドレスは、胸元[むなもと]から流[なが]れるドレープが美[うつく]しい。", "sentence_source": "generated"}, {"text": "薄い絹は風に揺れて、深いドレープを描いた。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "薄[うす]い絹[きぬ]は風[かぜ]に揺[ゆ]れて、深[ふか]いドレープを描[えが]いた。", "sentence_source": "generated"}, {"text": "彫刻の女神像は、衣のドレープまで細かく彫られている。", "target_word": "ドレープ", "complexity_tier": "T4", "furigana": "彫刻[ちょうこく]の女神像[めがみぞう]は、衣[ころも]のドレープまで細[こま]かく彫[ほ]られている。", "sentence_source": "generated"}, {"text": "ドレープが多すぎると、ワンピースは重たく見えてしまう。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "ドレープが多[おお]すぎると、ワンピースは重[おも]たく見[み]えてしまう。", "sentence_source": "generated"}, {"text": "光が当たると、ドレープの影が布の上にくっきりと浮かぶ。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "光[ひかり]が当[あ]たると、ドレープの影[かげ]が布[ぬの]の上[うえ]にくっきりと浮[う]かぶ。", "sentence_source": "generated"}, {"text": "彼女は肩にかけたショールのドレープを、鏡の前で整えた。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は肩[かた]にかけたショールのドレープを、鏡[かがみ]の前[まえ]で整[ととの]えた。", "sentence_source": "generated"}, {"text": "生地がかたいので、思ったようなドレープが出なかった。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "生地[きじ]がかたいので、思[おも]ったようなドレープが出[で]なかった。", "sentence_source": "generated"}, {"text": "絵の勉強では、服のドレープをよく観察することが大切だ。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "絵[え]の勉強[べんきょう]では、服[ふく]のドレープをよく観察[かんさつ]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "腰のあたりのドレープのおかげで、体型がきれいに見える。", "target_word": "ドレープ", "complexity_tier": "T3", "furigana": "腰[こし]のあたりのドレープのおかげで、体型[たいけい]がきれいに見[み]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドレープ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "布が垂れてできるゆるやかなひだ・その形(服飾・彫刻・絵)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52972, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドレープ", "is_correct": true, "explanation": "布が垂れてできるひだの形を指す。「精緻な刺繍と〜は、身体を包み込む芸術」の文脈で、布の美的な形として自然に入る。"}, {"text": "ファスナー", "is_correct": false, "explanation": "衣服の開閉具で、布の垂れ方を表す語ではない。身体を包み込む芸術として確立されたという文の主語には立たない。"}, {"text": "方言", "is_correct": false, "explanation": "地域の話し言葉を指し、刺繍と並べて身体を包み込む芸術の要素にはならない。"}, {"text": "氷河", "is_correct": false, "explanation": "陸上の大きな氷の塊で、布の装飾技法の文脈には入らない。"}], "explanations": {"ドレープ": "布が垂れてできるひだの形を指す。「精緻な刺繍と〜は、身体を包み込む芸術」の文脈で、布の美的な形として自然に入る。", "ファスナー": "衣服の開閉具で、布の垂れ方を表す語ではない。身体を包み込む芸術として確立されたという文の主語には立たない。", "方言": "地域の話し言葉を指し、刺繍と並べて身体を包み込む芸術の要素にはならない。", "氷河": "陸上の大きな氷の塊で、布の装飾技法の文脈には入らない。"}, "sentence_index": 0, "correct_answer": "ドレープ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツは、ドレープを真っ赤に染めた。", "explanation": "ドレープは布の垂れた形で、色を染める対象ではない。"}, {"text": "このスカートは、ドレープを一本ずつ数えて売った。", "explanation": "ドレープは布の垂れた形で、数えて売る品物ではない。"}, {"text": "彼女は結婚式のためにドレープを一着選んだ。", "explanation": "ドレープは布の垂れた形で、衣服そのものを指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52972, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドレープ", "is_correct": true, "explanation": "肩にかけた布の垂れひだを指す。整える対象として、布の形を表す語が正しく入る。"}, {"text": "鉄橋", "is_correct": false, "explanation": "金属製の橋で、布の形を整える対象にはならない。"}, {"text": "水量", "is_correct": false, "explanation": "水の多さを表す語で、布のひだを整える文脈には入らない。"}, {"text": "化石", "is_correct": false, "explanation": "過去の生物の痕跡で、衣服を整える動作の対象にはならない。"}], "explanations": {"ドレープ": "肩にかけた布の垂れひだを指す。整える対象として、布の形を表す語が正しく入る。", "鉄橋": "金属製の橋で、布の形を整える対象にはならない。", "水量": "水の多さを表す語で、布のひだを整える文脈には入らない。", "化石": "過去の生物の痕跡で、衣服を整える動作の対象にはならない。"}, "sentence_index": 6, "correct_answer": "ドレープ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ダイエットで体重が減り、ドレープを一着新しく買った。", "explanation": "ドレープは布の垂れた形で、買う品物の名前ではない。"}, {"text": "このワンピースは、ドレープを一本のひもに変えて縫った。", "explanation": "ドレープは布の形で、ひもという物ではない。"}, {"text": "湿った布を乾かすため、ドレープを強く絞った。", "explanation": "ドレープは布の垂れた形で、絞って水を切る対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52972, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このショールは、ドレープを柔らかくて肩に心地よい。", "corrected_sentence": "このショールは、ドレープが柔らかくて肩に心地よい。", "error_description": "主語を示す『が』が『を』になっている。『柔らかい』の主語はドレープなので『が』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52972, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この生地は軽いので、ドレープが自然に流れて。", "corrected_sentence": "この生地は軽いので、ドレープが自然に流れる。", "error_description": "主語『ドレープ』に対する述語が『流れて』で文が途中で切れている。終止形『流れる』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52973, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「刺繍をするときは」と、する動作の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』では「刺繍がするとき」となり、動作の対象が立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』では「刺繍へするとき」となり、動作の対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』では「刺繍よりするとき」となり、比べる文脈がない。"}], "correct_answer": "を", "explanations": {"を": "「刺繍をするときは」と、する動作の目的語を示す。", "が": "主語の『が』では「刺繍がするとき」となり、動作の対象が立たない。", "へ": "方向を表す『へ』では「刺繍へするとき」となり、動作の対象を示せない。", "より": "比較の『より』では「刺繍よりするとき」となり、比べる文脈がない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52973, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「刺繍を習った」と、習う内容を目的語として示す。"}, {"text": "で", "is_correct": false, "explanation": "手段の『で』では「刺繍で習った」となり、習う対象として意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の『から』では「刺繍から習った」となり、人から教わる形として合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』では「刺繍と習った」となり、習う対象が立たない。"}], "correct_answer": "を", "explanations": {"を": "「刺繍を習った」と、習う内容を目的語として示す。", "で": "手段の『で』では「刺繍で習った」となり、習う対象として意味が通らない。", "から": "起点の『から』では「刺繍から習った」となり、人から教わる形として合わない。", "と": "並列の『と』では「刺繍と習った」となり、習う対象が立たない。"}, "error_tags": {"で": "手段", "から": "起点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52973, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "糸で布に絵や模様を縫うこと。", "primary_collocate": null, "pronunciation": "ししゅう", "ipa": "ɕiɕɯː", "syllable_count": 3, "sentences": [{"text": "母はクッションカバーに小さな鳥の刺繍をした。", "target_word": "刺繍", "complexity_tier": "T2", "furigana": "母[はは]はクッションカバーに小[ちい]さな鳥[とり]の刺繍[ししゅう]をした。", "sentence_source": "generated"}, {"text": "刺繍をするときは、針に糸を通してから布をぴんと張る。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "刺繍[ししゅう]をするときは、針[はり]に糸[いと]を通[とお]してから布[ぬの]をぴんと張[は]る。", "sentence_source": "generated"}, {"text": "ハンカチに自分の名前の刺繍を入れてもらった。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "ハンカチに自分[じぶん]の名前[なまえ]の刺繍[ししゅう]を入[い]れてもらった。", "sentence_source": "generated"}, {"text": "この刺繍には、三日もかかった。", "target_word": "刺繍", "complexity_tier": "T2", "furigana": "この刺繍[ししゅう]には、三日[みっか]もかかった。", "sentence_source": "generated"}, {"text": "刺繍が苦手な私でも、簡単な模様ならできる。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "刺繍[ししゅう]が苦手[にがて]な私[わたし]でも、簡単[かんたん]な模様[もよう]ならできる。", "sentence_source": "generated"}, {"text": "先生に教わって、初めて刺繍に挑戦した。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "先生[せんせい]に教[おそ]わって、初[はじ]めて刺繍[ししゅう]に挑戦[ちょうせん]した。", "sentence_source": "generated"}, {"text": "刺繍の途中で糸がからまり、何度もやり直した。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "刺繍[ししゅう]の途中[とちゅう]で糸[いと]がからまり、何度[なんど]もやり直[なお]した。", "sentence_source": "generated"}, {"text": "小学生のころ、家庭科の時間に刺繍を習った。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "小学生[しょうがくせい]のころ、家庭科[かていか]の時間[じかん]に刺繍[ししゅう]を習[なら]った。", "sentence_source": "generated"}, {"text": "目が疲れるので、長時間の刺繍は休みながら進めている。", "target_word": "刺繍", "complexity_tier": "T4", "furigana": "目[め]が疲[つか]れるので、長時間[ちょうじかん]の刺繍[ししゅう]は休[やす]みながら進[すす]めている。", "sentence_source": "generated"}, {"text": "祖母は刺繍のとき、いつも窓の近くの明るい席に座る。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "祖母[そぼ]は刺繍[ししゅう]のとき、いつも窓[まど]の近[ちか]くの明[あか]るい席[せき]に座[すわ]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "刺繍", "label": "基本形"}, {"form": "刺繍する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "糸で布に絵や模様を縫う作業・行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52973, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刺繍", "is_correct": true, "explanation": "糸で布に絵や模様を縫う作業を指す。「鳥の刺繍をした」の目的語として正しく入る。"}, {"text": "渋滞", "is_correct": false, "explanation": "車などが詰まる状態を指し、「した」の目的語として成立しない。"}, {"text": "献立", "is_correct": false, "explanation": "食事の予定表を指し、鳥の模様を作る動作の対象にはならない。"}, {"text": "信号", "is_correct": false, "explanation": "交通の合図を指し、布に模様を作る動作の目的語にはならない。"}], "explanations": {"刺繍": "糸で布に絵や模様を縫う作業を指す。「鳥の刺繍をした」の目的語として正しく入る。", "渋滞": "車などが詰まる状態を指し、「した」の目的語として成立しない。", "献立": "食事の予定表を指し、鳥の模様を作る動作の対象にはならない。", "信号": "交通の合図を指し、布に模様を作る動作の目的語にはならない。"}, "sentence_index": 0, "correct_answer": "刺繍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏、友達と腕に刺繍を入れた。", "explanation": "ここは〈刺青〉の意味。刺繍は布に糸で絵や模様を縫う作業で、皮膚に墨で彫るものには使わない。"}, {"text": "木の板に、花の刺繍を彫った。", "explanation": "ここは〈彫刻〉の意味。刺繍は布に糸で縫う作業で、木の板に刃物で彫る技法とは違う。"}, {"text": "ボタンが取れたので、糸で刺繍した。", "explanation": "ここは〈縫う〉の意味。刺繍は模様や絵を縫い表す作業で、ボタン付けのような補修には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52973, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刺繍", "is_correct": true, "explanation": "糸で布に模様を縫う作業を指す。「刺繍の途中で糸がからまり」の主語として正しく入る。"}, {"text": "点滴", "is_correct": false, "explanation": "薬液を体に入れる医療行為を指し、糸がからまる作業の対象にはならない。"}, {"text": "朝食", "is_correct": false, "explanation": "朝の食事を指し、糸がからまる作業の途中として文に入らない。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面を指し、糸がからまる作業の途中としては成立しない。"}], "explanations": {"刺繍": "糸で布に模様を縫う作業を指す。「刺繍の途中で糸がからまり」の主語として正しく入る。", "点滴": "薬液を体に入れる医療行為を指し、糸がからまる作業の対象にはならない。", "朝食": "朝の食事を指し、糸がからまる作業の途中として文に入らない。", "天井": "部屋の上の面を指し、糸がからまる作業の途中としては成立しない。"}, "sentence_index": 6, "correct_answer": "刺繍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は壁に白いペンキで、刺繍を塗っていた。", "explanation": "ここは〈描画〉の意味。刺繍は布に糸で縫う作業で、壁に色を重ねて描く描画とは違う。"}, {"text": "ほつれた裾を白い糸で、刺繍して留めた。", "explanation": "ここは〈かがる〉の意味。刺繍は模様や絵を縫い表す作業で、ほつれを縫い留める補修とは違う。"}, {"text": "ナイフで腕を刺繍した。", "explanation": "ここは〈刺す〉の意味。刺繍は布に糸で模様を縫う作業で、刃物で突くことは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52973, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "シャツの袖に、名前の刺繍に入れる。", "corrected_sentence": "シャツの袖に、名前の刺繍を入れる。", "error_description": "目的語の刺繍には『を』が必要。『入れる』は『を』で目的語を取るので、『に』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52973, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、友達のために刺繍をする。", "corrected_sentence": "昨日、友達のために刺繍をした。", "error_description": "『昨日』と合うのは過去の『した』。『する』は非過去で、時制が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52974, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「刺繍を額に入れて飾る」と、額に入れる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』では「刺繍が額に入れて飾っている」となり、入れる対象が立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置の『に』では「刺繍に額に入れて」となり、何を入れるのかが示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』では「刺繍へ額に入れて」となり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「刺繍を額に入れて飾る」と、額に入れる対象を示す。", "が": "主語の『が』では「刺繍が額に入れて飾っている」となり、入れる対象が立たない。", "に": "位置の『に』では「刺繍に額に入れて」となり、何を入れるのかが示せない。", "へ": "方向を表す『へ』では「刺繍へ額に入れて」となり、対象を示せない。"}, "error_tags": {"が": "主語", "に": "位置・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52974, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「刺繍の図案」と、図案の所属先として刺繍を示す。"}, {"text": "を", "is_correct": false, "explanation": "「刺繍を図案を」と目的語が二つ並び、文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』では「刺繍が図案を選ぶ」となり、人が図案を選ぶ文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』では「刺繍へ図案を選ぶ」となり、選ぶ対象を示せない。"}], "correct_answer": "の", "explanations": {"の": "「刺繍の図案」と、図案の所属先として刺繍を示す。", "を": "「刺繍を図案を」と目的語が二つ並び、文として成り立たない。", "が": "主語の『が』では「刺繍が図案を選ぶ」となり、人が図案を選ぶ文として不自然。", "へ": "方向を表す『へ』では「刺繍へ図案を選ぶ」となり、選ぶ対象を示せない。"}, "error_tags": {"を": "目的語の重複", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52974, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "布などに針と糸で模様や絵を縫い付けて表した作品。装飾的な手芸の一種。", "primary_collocate": null, "pronunciation": "ししゅう", "ipa": "ɕiɕɯː", "syllable_count": 3, "sentences": [{"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "刺繍", "complexity_tier": "T5", "furigana": "ベル・エポック期[き]、アトリエにおける職人[しょくにん]の手指[てゆび]による精緻[せいち]な刺繍[ししゅう]とドレープは、身体[からだ]を包[つつ]み込[こ]む芸術[げいじゅつ]として確立[かくりつ]された。", "sentence_source": "mined"}, {"text": "祖母が毎晩縫った花の刺繍を、額に入れて飾っている。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "祖母[そぼ]が毎晩[まいばん]縫[ぬ]った花[はな]の刺繍[ししゅう]を、額[がく]に入[い]れて飾[かざ]っている。", "sentence_source": "generated"}, {"text": "この民族衣装は、袖の刺繍がとても華やかだ。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "この民族衣装[みんぞくいしょう]は、袖[そで]の刺繍[ししゅう]がとても華[はな]やかだ。", "sentence_source": "generated"}, {"text": "刺繍は、日本でも古くから着物を飾る手芸として親しまれてきた。", "target_word": "刺繍", "complexity_tier": "T4", "furigana": "刺繍[ししゅう]は、日本[にほん]でも古[ふる]くから着物[きもの]を飾[かざ]る手芸[しゅげい]として親[した]しまれてきた。", "sentence_source": "generated"}, {"text": "手芸店で、初心者向けの刺繍のキットを買った。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "手芸店[しゅげいてん]で、初心者[しょしんしゃ]向[む]けの刺繍[ししゅう]のキットを買[か]った。", "sentence_source": "generated"}, {"text": "金糸を使った刺繍は、光を受けると美しく輝く。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "金糸[きんし]を使[つか]った刺繍[ししゅう]は、光[ひかり]を受[う]けると美[うつく]しく輝[かがや]く。", "sentence_source": "generated"}, {"text": "彼女の刺繍は細かくて、まるで絵のように見える。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の刺繍[ししゅう]は細[こま]かくて、まるで絵[え]のように見[み]える。", "sentence_source": "generated"}, {"text": "刺繍の図案を選ぶとき、まず布の色との相性を考える。", "target_word": "刺繍", "complexity_tier": "T4", "furigana": "刺繍[ししゅう]の図案[ずあん]を選[えら]ぶとき、まず布[ぬの]の色[いろ]との相性[あいしょう]を考[かんが]える。", "sentence_source": "generated"}, {"text": "制服の胸に、学校の名前が刺繍で入っている。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "制服[せいふく]の胸[むね]に、学校[がっこう]の名前[なまえ]が刺繍[ししゅう]で入[はい]っている。", "sentence_source": "generated"}, {"text": "展覧会に出品した刺繍が、大きな賞を取った。", "target_word": "刺繍", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]に出品[しゅっぴん]した刺繍[ししゅう]が、大[おお]きな賞[しょう]を取[と]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "刺繍", "label": "基本形"}, {"form": "刺繍する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "針と糸で布に模様や絵を縫い表した装飾・手芸(その作品)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52974, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刺繍", "is_correct": true, "explanation": "針と糸で布に模様を縫い表した作品や技法を指す。精緻な刺繍と〜の文脈に合う。"}, {"text": "家計", "is_correct": false, "explanation": "家庭の収入と支出を指し、布を飾る芸術の要素にはならない。"}, {"text": "氷河", "is_correct": false, "explanation": "陸上の大きな氷の塊で、布の装飾や芸術の文脈には入らない。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指し、身体を包み込む芸術の要素として文に入らない。"}], "explanations": {"刺繍": "針と糸で布に模様を縫い表した作品や技法を指す。精緻な刺繍と〜の文脈に合う。", "家計": "家庭の収入と支出を指し、布を飾る芸術の要素にはならない。", "氷河": "陸上の大きな氷の塊で、布の装飾や芸術の文脈には入らない。", "天候": "天気の状態を指し、身体を包み込む芸術の要素として文に入らない。"}, "sentence_index": 0, "correct_answer": "刺繍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は毎晩、セーターの刺繍を編んでいる。", "explanation": "ここは〈編み物〉の意味。刺繍は布の上に糸で模様を縫い付ける作業で、糸を編んで作るものではない。"}, {"text": "食卓に刺繍を並べた。", "explanation": "ここは〈刺身〉の意味。刺繍は布に糸で模様を縫い付ける手芸で、料理は指さない。"}, {"text": "袖口の汚れを、消しゴムで刺繍して落とした。", "explanation": "ここは〈こすり取る〉の意味。刺繍は布に糸で模様を縫い付ける手芸で、汚れを擦って取る動作は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52974, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刺繍", "is_correct": true, "explanation": "布に糸で模様や絵を縫い表したものを指す。「細かくて、絵のように見える」と評する対象として正しい。"}, {"text": "日没", "is_correct": false, "explanation": "太陽が沈むことを指し、細かさや絵のような見え方を評する対象にならない。"}, {"text": "寝坊", "is_correct": false, "explanation": "朝に起きるのが遅れることを指し、見た目を評する主語にはならない。"}, {"text": "遠足", "is_correct": false, "explanation": "行事として出かけることを指し、細かさや絵のような見え方の対象にはならない。"}], "explanations": {"刺繍": "布に糸で模様や絵を縫い表したものを指す。「細かくて、絵のように見える」と評する対象として正しい。", "日没": "太陽が沈むことを指し、細かさや絵のような見え方を評する対象にならない。", "寝坊": "朝に起きるのが遅れることを指し、見た目を評する主語にはならない。", "遠足": "行事として出かけることを指し、細かさや絵のような見え方の対象にはならない。"}, "sentence_index": 6, "correct_answer": "刺繍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は毎晩、ボタン付けの刺繍をしている。", "explanation": "ここは〈縫い物〉の意味。刺繍は模様や絵を縫い表す手芸で、ボタン付けのような実用の縫い物は指さない。"}, {"text": "この織物は、経糸と緯糸で作った刺繍が美しい。", "explanation": "ここは〈織り技法〉の意味。刺繍は布に糸で模様を縫い付けるもので、糸を交差させて織ることは指さない。"}, {"text": "夏の夜、腕を蚊に刺繍された。", "explanation": "ここは〈刺す〉の意味。刺繍は針と糸で模様を作る手芸で、虫に刺されることは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52974, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母の刺繍を、ていねいな仕上がりで評判だ。", "corrected_sentence": "母の刺繍は、ていねいな仕上がりで評判だ。", "error_description": "主題を示す『は』が『を』になっている。『評判だ』の主語は刺繍なので『は』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52974, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この刺繍は、ていねいに仕上がっているた。", "corrected_sentence": "この刺繍は、ていねいに仕上がっている。", "error_description": "述語『仕上がっている』の後に余分な『た』が付き、活用として成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52975, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「始める」の対象は「を」で示す。「モデリングを始めたばかり」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示す。「始める」の対象には使わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「モデリングと始めた」では対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「始める」の対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「始める」の対象は「を」で示す。「モデリングを始めたばかり」が正しい。", "に": "「に」は相手や場所を示す。「始める」の対象には使わない。", "と": "「と」は相手や並列を示す。「モデリングと始めた」では対象にならない。", "へ": "「へ」は方向を示す。「始める」の対象には使えない。"}, "error_tags": {"に": "相手・場所", "と": "相手・並列", "へ": "方向・帰着点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52975, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は名詞をつなぐ。「モデリングのやり方」として意味が通る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「モデリングがやり方」では名詞同士がつながらない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示す。「やり方を」と続くと対象が二つになり不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「モデリングよりやり方」では意味がつながらない。"}], "correct_answer": "の", "explanations": {"の": "「の」は名詞をつなぐ。「モデリングのやり方」として意味が通る。", "が": "「が」は主語を示す。「モデリングがやり方」では名詞同士がつながらない。", "を": "「を」は対象を示す。「やり方を」と続くと対象が二つになり不自然。", "より": "「より」は比較を示す。「モデリングよりやり方」では意味がつながらない。"}, "error_tags": {"が": "主語", "を": "対象の重複", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52975, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "コンピューターで、ものの形を立体的に作ること。", "primary_collocate": null, "pronunciation": "もでりんぐ", "ipa": "modeɾiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "兄はパソコンで車のモデリングを練習している。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "兄[あに]はパソコンで車[くるま]のモデリングを練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "モデリングを始めたばかりで、まだ丸い形しか作れない。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "モデリングを始[はじ]めたばかりで、まだ丸[まる]い形[かたち]しか作[つく]れない。", "sentence_source": "generated"}, {"text": "この授業では、モデリングの基本を学ぶ。", "target_word": "モデリング", "complexity_tier": "T2", "furigana": "この授業[じゅぎょう]では、モデリングの基本[きほん]を学[まな]ぶ。", "sentence_source": "generated"}, {"text": "立体のモデリングは、平らな絵を描くより時間がかかる。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "立体[りったい]のモデリングは、平[たい]らな絵[え]を描[か]くより時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "専用のソフトを使えば、初心者でもモデリングを楽しめる。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "専用[せんよう]のソフトを使[つか]えば、初心者[しょしんしゃ]でもモデリングを楽[たの]しめる。", "sentence_source": "generated"}, {"text": "彼女は猫のモデリングに一週間かけた。", "target_word": "モデリング", "complexity_tier": "T2", "furigana": "彼女[かのじょ]は猫[ねこ]のモデリングに一週間[いっしゅうかん]かけた。", "sentence_source": "generated"}, {"text": "モデリングを終えた人形を、3Dプリンターで出力した。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "モデリングを終[お]えた人形[にんぎょう]を、3Dプリンターで出力[しゅつりょく]した。", "sentence_source": "generated"}, {"text": "モデリングのやり方を動画で見て、同じ形を作ってみた。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "モデリングのやり方[かた]を動画[どうが]で見[み]て、同[おな]じ形[かたち]を作[つく]ってみた。", "sentence_source": "generated"}, {"text": "モデリングが得意な友達に、ゲームのキャラを作ってもらった。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "モデリングが得意[とくい]な友達[ともだち]に、ゲームのキャラを作[つく]ってもらった。", "sentence_source": "generated"}, {"text": "新しいパソコンのおかげで、大きなモデリングも止まらずに進む。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "新[あたら]しいパソコンのおかげで、大[おお]きなモデリングも止[と]まらずに進[すす]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モデリング", "label": "基本形"}, {"form": "モデリングする", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "パソコンのソフトで立体の形を作る作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52975, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モデリング", "is_correct": true, "explanation": "パソコンでソフトを使い、車の形を作る練習として文が成り立つ。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言語を別の言語に訳す作業で、車の形を作る練習の対象にはならない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲を作ることで、車の形を作る練習の文脈には合わない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作ることで、パソコンで車を作る練習とは結びつかない。"}], "explanations": {"モデリング": "パソコンでソフトを使い、車の形を作る練習として文が成り立つ。", "翻訳": "翻訳は言語を別の言語に訳す作業で、車の形を作る練習の対象にはならない。", "作曲": "作曲は曲を作ることで、車の形を作る練習の文脈には合わない。", "料理": "料理は食べ物を作ることで、パソコンで車を作る練習とは結びつかない。"}, "sentence_index": 0, "correct_answer": "モデリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "白い紙に鉛筆で線を引いて、人物の絵をモデリングした。", "explanation": "ここは〈作画〉の意味。紙に線で絵を描く作業で、立体の形を作るモデリングとは合わない。"}, {"text": "毎朝、祖父は新聞の記事を声に出してモデリングした。", "explanation": "ここは〈音読〉の意味。新聞を声に出して読む行為で、形を作るモデリングとは違う。"}, {"text": "夏休みの日記を、毎日モデリングして書いた。", "explanation": "ここは〈作文〉の意味。文章を組み立てる行為で、形を作るモデリングとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52975, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モデリング", "is_correct": true, "explanation": "人形の形を作る作業を終えた、という意味で文が成り立つ。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点数をつける作業で、人形の形作りには合わない。"}, {"text": "会計", "is_correct": false, "explanation": "会計は支払いの計算を指し、人形を作る作業を終えた状態とは言えない。"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は微生物による変化を指し、人形を作る工程としては不自然。"}], "explanations": {"モデリング": "人形の形を作る作業を終えた、という意味で文が成り立つ。", "採点": "採点は答案に点数をつける作業で、人形の形作りには合わない。", "会計": "会計は支払いの計算を指し、人形を作る作業を終えた状態とは言えない。", "発酵": "発酵は微生物による変化を指し、人形を作る工程としては不自然。"}, "sentence_index": 6, "correct_answer": "モデリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎晩、本をモデリングしてから寝る。", "explanation": "ここは〈読書〉の意味。本を読む行為で、コンピューター上で形を作るモデリングとは違う。"}, {"text": "ノコギリで板を切って、本棚をモデリングで作った。", "explanation": "ここは〈木工〉の意味。板を切って組み立てる作業で、コンピューター上で形を作るモデリングには合わない。"}, {"text": "机の上の書類をモデリングして、きれいに並べた。", "explanation": "ここは〈整理〉の意味。書類を片づける作業で、形を作るモデリングとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52975, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "モデリングを進むと、画面に形が見えてくる。", "corrected_sentence": "モデリングが進むと、画面に形が見えてくる。", "error_description": "「進む」は自動詞で、作業が主語になるので「が」を使う。「モデリングを進む」は誤りで、「モデリングが進む」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52975, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "モデリングを終わったら、次は色をつける。", "corrected_sentence": "モデリングを終えたら、次は色をつける。", "error_description": "「終える」は他動詞で「〜を終える」と言う。「終わる」は自動詞なので「モデリングを終わった」は誤りで、「モデリングを終えた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52976, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「担当する」は担当する対象を「を」で示す。「モデリングを担当している」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を示す。担当の対象は「を」で示すので、「モデリングに担当」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。担当する対象を表すには「を」が必要で、ここでは合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「モデリングと担当している」では担当の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「担当する」は担当する対象を「を」で示す。「モデリングを担当している」が正しい。", "に": "「に」は相手や帰着点を示す。担当の対象は「を」で示すので、「モデリングに担当」は成り立たない。", "で": "「で」は場所や手段を示す。担当する対象を表すには「を」が必要で、ここでは合わない。", "と": "「と」は相手や並列を示す。「モデリングと担当している」では担当の対象にならない。"}, "error_tags": {"に": "相手・帰着点", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52976, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「する」の対象は「を」で示す。「モデリングをする彫刻家」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「モデリングがする」では「する」の対象が立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「する」の対象には使えない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「モデリングからする」では対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「する」の対象は「を」で示す。「モデリングをする彫刻家」が正しい。", "が": "「が」は主語を示す。「モデリングがする」では「する」の対象が立たない。", "へ": "「へ」は方向を示す。「する」の対象には使えない。", "から": "「から」は起点を示す。「モデリングからする」では対象にならない。"}, "error_tags": {"が": "主語", "へ": "方向・帰着点", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52976, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "コンピューター上で物体の形状を立体的に作り出す技術。", "primary_collocate": null, "pronunciation": "もでりんぐ", "ipa": "modeɾiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "モデリングは、コンピューター上で物体の形を立体的に作る技術だ。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "モデリングは、コンピューター上[じょう]で物体[ぶったい]の形[かたち]を立体的[りったいてき]に作[つく]る技術[ぎじゅつ]だ。", "sentence_source": "generated"}, {"text": "ゲーム会社で、キャラクターのモデリングを担当している。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "ゲーム会社[かいしゃ]で、キャラクターのモデリングを担当[たんとう]している。", "sentence_source": "generated"}, {"text": "モデリングが終わったら、次は表面に色や質感をつける。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "モデリングが終[お]わったら、次[つぎ]は表面[ひょうめん]に色[いろ]や質感[しつかん]をつける。", "sentence_source": "generated"}, {"text": "この建築ソフトは、複雑な建物のモデリングが短時間でできる。", "target_word": "モデリング", "complexity_tier": "T4", "furigana": "この建築[けんちく]ソフトは、複雑[ふくざつ]な建物[たてもの]のモデリングが短時間[たんじかん]でできる。", "sentence_source": "generated"}, {"text": "モデリングの精度が高いほど、画面上の物体は本物に近く見える。", "target_word": "モデリング", "complexity_tier": "T4", "furigana": "モデリングの精度[せいど]が高[たか]いほど、画面上[がめんじょう]の物体[ぶったい]は本物[ほんもの]に近[ちか]く見[み]える。", "sentence_source": "generated"}, {"text": "彼は独学でモデリングを学び、自分の作品をインターネットで公開した。", "target_word": "モデリング", "complexity_tier": "T4", "furigana": "彼[かれ]は独学[どくがく]でモデリングを学[まな]び、自分[じぶん]の作品[さくひん]をインターネットで公開[こうかい]した。", "sentence_source": "generated"}, {"text": "映画の制作現場では、モデリングの担当者が背景の街を一から作る。", "target_word": "モデリング", "complexity_tier": "T4", "furigana": "映画[えいが]の制作現場[せいさくげんば]では、モデリングの担当者[たんとうしゃ]が背景[はいけい]の街[まち]を一[いち]から作[つく]る。", "sentence_source": "generated"}, {"text": "粘土の代わりに、パソコンでモデリングをする彫刻家もいる。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "粘土[ねんど]の代[か]わりに、パソコンでモデリングをする彫刻家[ちょうこくか]もいる。", "sentence_source": "generated"}, {"text": "モデリングの途中でデータが重くなり、パソコンが止まってしまった。", "target_word": "モデリング", "complexity_tier": "T3", "furigana": "モデリングの途中[とちゅう]でデータが重[おも]くなり、パソコンが止[と]まってしまった。", "sentence_source": "generated"}, {"text": "質感の表現には、モデリングだけでなく光の設定も重要だ。", "target_word": "モデリング", "complexity_tier": "T4", "furigana": "質感[しつかん]の表現[ひょうげん]には、モデリングだけでなく光[ひかり]の設定[せってい]も重要[じゅうよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モデリング", "label": "基本形"}, {"form": "モデリングする", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "CG・3Dソフトで立体物の形を作り出す技術", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52976, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モデリング", "is_correct": true, "explanation": "コンピューター上で物体の形を立体的に作る技術を指し、文の主語として自然に入る。"}, {"text": "ドライバ", "is_correct": false, "explanation": "ドライバは機器やソフトを動かすプログラムのことで、立体を構築する作業名としては入らない。"}, {"text": "キャッシュ", "is_correct": false, "explanation": "キャッシュは一時保存されたデータを指し、「3Dキャッシュ」は立体を作る作業の名詞として成り立たない。"}, {"text": "ハッシュ", "is_correct": false, "explanation": "ハッシュはデータを一定の値に変換する計算方法で、3Dの形を作る作業としては当てはまらない。"}], "explanations": {"モデリング": "コンピューター上で物体の形を立体的に作る技術を指し、文の主語として自然に入る。", "ドライバ": "ドライバは機器やソフトを動かすプログラムのことで、立体を構築する作業名としては入らない。", "キャッシュ": "キャッシュは一時保存されたデータを指し、「3Dキャッシュ」は立体を作る作業の名詞として成り立たない。", "ハッシュ": "ハッシュはデータを一定の値に変換する計算方法で、3Dの形を作る作業としては当てはまらない。"}, "sentence_index": 0, "correct_answer": "モデリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この建築ソフトは、光の反射を計算するモデリングが一瞬で終わる。", "explanation": "ここは〈レンダリング〉の意味。光や影を計算して画像を仕上げる工程で、形を作るモデリングとは合わない。"}, {"text": "キャラクターの走る動きを、モデリングで毎秒二十四コマ作る。", "explanation": "ここは〈アニメーション〉の意味。動きを時間の流れに沿って作る工程で、形そのものを作るモデリングとは違う。"}, {"text": "彼は新しい曲をモデリングして、ピアノで弾いた。", "explanation": "ここは〈作曲〉の意味。音を組み立てて曲を作る行為で、形を作るモデリングとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52976, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モデリング", "is_correct": true, "explanation": "背景の街を一から作る3D制作の担当者を指し、「モデリングの担当者」として文が成り立つ。"}, {"text": "経理", "is_correct": false, "explanation": "経理は会社のお金の管理を指し、背景の街を作る担当者の文脈には合わない。"}, {"text": "税務", "is_correct": false, "explanation": "税務は税金の手続きに関わる仕事で、街を一から作る担当とは結びつかない。"}, {"text": "採用", "is_correct": false, "explanation": "採用は人材を選ぶ仕事で、背景の街を作る担当者の文脈には入らない。"}], "explanations": {"モデリング": "背景の街を一から作る3D制作の担当者を指し、「モデリングの担当者」として文が成り立つ。", "経理": "経理は会社のお金の管理を指し、背景の街を作る担当者の文脈には合わない。", "税務": "税務は税金の手続きに関わる仕事で、街を一から作る担当とは結びつかない。", "採用": "採用は人材を選ぶ仕事で、背景の街を作る担当者の文脈には入らない。"}, "sentence_index": 6, "correct_answer": "モデリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コピー機で原稿をモデリングして、三部印刷した。", "explanation": "ここは〈複写〉の意味。原稿を写し取る作業で、コンピューター上で形を作るモデリングとは合わない。"}, {"text": "試験の前に公式をモデリングして、ひたすら覚えた。", "explanation": "ここは〈暗記〉の意味。繰り返して頭に入れる行為で、形を作るモデリングとは違う。"}, {"text": "表面の模様を貼るモデリングを作り直したら、質感が良くなった。", "explanation": "ここは〈テクスチャ〉の意味。模様や画像を表面に貼る工程で、形を作るモデリングとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52976, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はモデリングを詳しい。", "corrected_sentence": "彼女はモデリングに詳しい。", "error_description": "「詳しい」は「〜に詳しい」の形を取り、対象は「に」で示す。「モデリングを詳しい」は誤りで、「モデリングに詳しい」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52976, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日はモデリングしする予定だ。", "corrected_sentence": "明日はモデリングをする予定だ。", "error_description": "「モデリング」は名詞なので「モデリングをする」と「を」で目的語を示す。「しする」と「し」を挿入するのは誤りで、「モデリングをする」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52977, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "包み込む対象の荷物を示す目的語の『を』で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "『荷物に包み込み』では対象を示せず、目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す『で』で、荷物を包む対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す『と』で、荷物の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "包み込む対象の荷物を示す目的語の『を』で、文に合う。", "に": "『荷物に包み込み』では対象を示せず、目的語にならない。", "で": "手段を示す『で』で、荷物を包む対象を示せない。", "と": "並列や相手を示す『と』で、荷物の対象にはならない。"}, "error_tags": {"を": "対象", "に": "位置・方向", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52977, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "布を使って包んだという手段を示す『で』で、文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』で、手段としての布は示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す『から』で、道具としての布は示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す『より』で、布を示す格にならない。"}], "correct_answer": "で", "explanations": {"で": "布を使って包んだという手段を示す『で』で、文に合う。", "へ": "方向を示す『へ』で、手段としての布は示せない。", "から": "起点を示す『から』で、道具としての布は示せない。", "より": "比較を示す『より』で、布を示す格にならない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52977, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを、すっぽりと中に入れて、外から見えなくすること。", "primary_collocate": null, "pronunciation": "つつみこむ", "ipa": "tsɯtsɯmikomɯ", "syllable_count": 5, "sentences": [{"text": "割れやすい皿を新聞紙で包み込んで、箱に入れた。", "target_word": "包み込んで", "complexity_tier": "T3", "furigana": "割[わ]れやすい皿[さら]を新聞紙[しんぶんし]で包[つつ]み込[こ]んで、箱[はこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "大きな布が荷物をすっぽり包み込み、中身は見えなかった。", "target_word": "包み込み", "complexity_tier": "T3", "furigana": "大[おお]きな布[ぬの]が荷物[にもつ]をすっぽり包[つつ]み込[こ]み、中身[なかみ]は見[み]えなかった。", "sentence_source": "generated"}, {"text": "彼女はプレゼントを包装紙で包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はプレゼントを包装紙[ほうそうし]で包[つつ]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "寒いので、全身をマントで包み込んで外に出た。", "target_word": "包み込んで", "complexity_tier": "T3", "furigana": "寒[さむ]いので、全身[ぜんしん]をマントで包[つつ]み込[こ]んで外[そと]に出[で]た。", "sentence_source": "generated"}, {"text": "肉をラップで包み込んで、冷凍庫に入れた。", "target_word": "包み込んで", "complexity_tier": "T3", "furigana": "肉[にく]をラップで包[つつ]み込[こ]んで、冷凍庫[れいとうこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "魚をアルミホイルで包み込んで焼くと、身が柔らかくなる。", "target_word": "包み込んで", "complexity_tier": "T4", "furigana": "魚[さかな]をアルミホイルで包[つつ]み込[こ]んで焼[や]くと、身[み]が柔[やわ]らかくなる。", "sentence_source": "generated"}, {"text": "犯人は盗んだ宝石をハンカチで包み込み、ポケットに隠した。", "target_word": "包み込み", "complexity_tier": "T4", "furigana": "犯人[はんにん]は盗[ぬす]んだ宝石[ほうせき]をハンカチで包[つつ]み込[こ]み、ポケットに隠[かく]した。", "sentence_source": "generated"}, {"text": "彼は手紙を封筒に入れ、さらに布で包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T3", "furigana": "彼[かれ]は手紙[てがみ]を封筒[ふうとう]に入[い]れ、さらに布[ぬの]で包[つつ]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "ご飯で具をすっぽり包み込むと、おにぎりになる。", "target_word": "包み込む", "complexity_tier": "T3", "furigana": "ご飯[はん]で具[ぐ]をすっぽり包[つつ]み込[こ]むと、おにぎりになる。", "sentence_source": "generated"}, {"text": "引っ越しの荷造りで、グラスを一つずつ紙で包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの荷造[にづく]りで、グラスを一[ひと]つずつ紙[かみ]で包[つつ]み込[こ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "包み込む", "label": "辞書形"}, {"form": "包み込んだ", "label": "過去形"}, {"form": "包み込まない", "label": "否定形"}, {"form": "包み込んで", "label": "て形"}, {"form": "包み込み", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "紙・布などですっぽり中に入れて見えなくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52977, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包み込んで", "is_correct": true, "explanation": "紙で中にすっぽり入れる意味で、皿を新聞紙で包んで箱に入れる文に合う。"}, {"text": "叩き割って", "is_correct": false, "explanation": "叩いて壊す意味で、包んで箱に入れる流れと合わない。"}, {"text": "数えて", "is_correct": false, "explanation": "数量を数える意味で、新聞紙で皿を包む動作には合わない。"}, {"text": "測って", "is_correct": false, "explanation": "長さや量をはかる意味で、新聞紙の使い方と合わない。"}], "explanations": {"包み込んで": "紙で中にすっぽり入れる意味で、皿を新聞紙で包んで箱に入れる文に合う。", "叩き割って": "叩いて壊す意味で、包んで箱に入れる流れと合わない。", "数えて": "数量を数える意味で、新聞紙で皿を包む動作には合わない。", "測って": "長さや量をはかる意味で、新聞紙の使い方と合わない。"}, "sentence_index": 0, "correct_answer": "包み込んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ロープを柱に包み込んだ。", "explanation": "ここは〈巻きつける〉の意味。包み込むは中にすっぽり入れて見えなくする意味で、柱に巻きつける場面には合わない。"}, {"text": "強風が洗濯物を包み込み、庭いっぱいに吹き飛ばした。", "explanation": "ここは〈巻き上げる〉の意味。包み込むは中に入れて見えなくする意味で、風が物を舞い上げる場面には使わない。"}, {"text": "事件が無関係の市民を包み込んだ。", "explanation": "ここは〈巻き込む〉の意味。包み込むは紙や布で中に入れて見えなくする意味で、人を事件に引きずり込む場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52977, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包み込み", "is_correct": true, "explanation": "ハンカチで宝石を中に入れて隠す意味で、続くポケットに隠したの流れに合う。"}, {"text": "掘り出し", "is_correct": false, "explanation": "地中から取り出す意味で、ハンカチで宝石を掘り出す文は成り立たない。"}, {"text": "撃ち落とし", "is_correct": false, "explanation": "撃って落とす意味で、宝石の扱いとしてハンカチの文脈に合わない。"}, {"text": "踏みつぶし", "is_correct": false, "explanation": "踏んで潰す意味で、ハンカチで宝石を包む描写にはならない。"}], "explanations": {"包み込み": "ハンカチで宝石を中に入れて隠す意味で、続くポケットに隠したの流れに合う。", "掘り出し": "地中から取り出す意味で、ハンカチで宝石を掘り出す文は成り立たない。", "撃ち落とし": "撃って落とす意味で、宝石の扱いとしてハンカチの文脈に合わない。", "踏みつぶし": "踏んで潰す意味で、ハンカチで宝石を包む描写にはならない。"}, "sentence_index": 6, "correct_answer": "包み込み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警官隊が店の入り口を包み込んだ。", "explanation": "ここは〈取り囲む〉の意味。包み込むは中に入れて見えなくする意味で、店を取り囲んで封鎖する場面には使わない。"}, {"text": "包丁で野菜を包み込んだ。", "explanation": "ここは〈切り刻む〉の意味。包み込むは中に入れて外から見えなくする意味で、刃物で切る動作には合わない。"}, {"text": "ふたを閉めた箱を、中身が外からよく見えるように紙で包み込んだ。", "explanation": "ここは〈見せる〉の意味。包み込むは外から見えなくする意味なので、中身がよく見える状態を作る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52977, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ケーキに白い紙で包み込んだ。", "corrected_sentence": "ケーキを白い紙で包み込んだ。", "error_description": "助詞の誤り。包み込む対象のケーキには『を』が必要で、『に』は誤り。正しくは『ケーキを包み込んだ』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "包み込み", "is_correct": true, "explanation": "連用中止形で、ここでは『包み込み、〜』と文を続けている。"}, {"text": "包み込もう", "is_correct": false, "explanation": "意志を表す形で、布の動作の描写には合わない。"}, {"text": "包み込める", "is_correct": false, "explanation": "可能形で、布ができるという意味になり文とずれる。"}, {"text": "包み込まない", "is_correct": false, "explanation": "否定形で、布が包んだという肯定の描写と合わない。"}], "correct_form": "包み込み", "base_form": "包み込む", "form_label": "連用形", "sentence_index": 1, "explanations": {"包み込み": "連用中止形で、ここでは『包み込み、〜』と文を続けている。", "包み込もう": "意志を表す形で、布の動作の描写には合わない。", "包み込める": "可能形で、布ができるという意味になり文とずれる。", "包み込まない": "否定形で、布が包んだという肯定の描写と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52977, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はカップを新聞紙で包み込んて、箱にしまった。", "corrected_sentence": "彼はカップを新聞紙で包み込んで、箱にしまった。", "error_description": "て形の誤り。正しくは『包み込んで』で、『包み込んて』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "包み込んだ", "is_correct": true, "explanation": "過去形で、布で包むという完了した動作に合う。"}, {"text": "包み込まれた", "is_correct": false, "explanation": "受身の過去形で、彼が包まれたという意味になり主語の動作と合わない。"}, {"text": "包み込ませた", "is_correct": false, "explanation": "使役の過去形で、誰かに包ませたという意味になり文と合わない。"}, {"text": "包み込んで", "is_correct": false, "explanation": "て形で、文を言い切る過去形の位置には入らない。"}], "correct_form": "包み込んだ", "base_form": "包み込む", "form_label": "過去形", "sentence_index": 7, "explanations": {"包み込んだ": "過去形で、布で包むという完了した動作に合う。", "包み込まれた": "受身の過去形で、彼が包まれたという意味になり主語の動作と合わない。", "包み込ませた": "使役の過去形で、誰かに包ませたという意味になり文と合わない。", "包み込んで": "て形で、文を言い切る過去形の位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52978, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "包み込む対象の子どもを示す目的語の『を』で、文の骨組みに合う。"}, {"text": "に", "is_correct": false, "explanation": "『子どもに包み込んだ』は対象を示せず、目的語には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』で、包み込む対象は示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す『で』で、包み込む対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "包み込む対象の子どもを示す目的語の『を』で、文の骨組みに合う。", "に": "『子どもに包み込んだ』は対象を示せず、目的語には使えない。", "へ": "方向を示す『へ』で、包み込む対象は示せない。", "で": "手段や場所を示す『で』で、包み込む対象を示せない。"}, "error_tags": {"を": "対象", "に": "位置・方向", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52978, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "人を包み込むの目的語を示す『を』で、文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』で、包み込む対象は示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す『から』で、対象の表示にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す『より』で、目的語の格にはならない。"}], "correct_answer": "を", "explanations": {"を": "人を包み込むの目的語を示す『を』で、文に合う。", "へ": "方向を示す『へ』で、包み込む対象は示せない。", "から": "起点を示す『から』で、対象の表示にはならない。", "より": "比較を示す『より』で、目的語の格にはならない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52978, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や人の周りをすっかり覆って、内側に含むこと。特に、優しく包むようにして囲むこと。", "primary_collocate": null, "pronunciation": "つつみこむ", "ipa": "tsɯtsɯmikomɯ", "syllable_count": 5, "sentences": [{"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "包み込む", "complexity_tier": "T4", "furigana": "ベル・エポック期[き]、アトリエにおける職人[しょくにん]の手指[てゆび]による精緻[せいち]な刺繍[ししゅう]とドレープは、身体[しんたい]を包[つつ]み込[こ]む芸術[げいじゅつ]として確立[かくりつ]された。", "sentence_source": "mined"}, {"text": "母は泣いている子どもをやさしく包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T3", "furigana": "母[はは]は泣[な]いている子[こ]どもをやさしく包[つつ]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "夕焼けの光が、町全体を包み込んでいた。", "target_word": "包み込んでいた", "complexity_tier": "T3", "furigana": "夕焼[ゆうや]けの光[ひかり]が、町全体[まちぜんたい]を包[つつ]み込[こ]んでいた。", "sentence_source": "generated"}, {"text": "彼の穏やかな声は、聞く人の不安を包み込むようだ。", "target_word": "包み込む", "complexity_tier": "T4", "furigana": "彼[かれ]の穏[おだ]やかな声[こえ]は、聞[き]く人[ひと]の不安[ふあん]を包[つつ]み込[こ]むようだ。", "sentence_source": "generated"}, {"text": "毛布が冷えた体を温かく包み込んでくれた。", "target_word": "包み込んで", "complexity_tier": "T3", "furigana": "毛布[もうふ]が冷[ひ]えた体[からだ]を温[あたた]かく包[つつ]み込[こ]んでくれた。", "sentence_source": "generated"}, {"text": "先生は失敗した生徒を責めず、大きな心で包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T4", "furigana": "先生[せんせい]は失敗[しっぱい]した生徒[せいと]を責[せ]めず、大[おお]きな心[こころ]で包[つつ]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "霧が山あいの村をふんわりと包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T3", "furigana": "霧[きり]が山[やま]あいの村[むら]をふんわりと包[つつ]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "祖母の笑顔には、周りの人を包み込む温かさがある。", "target_word": "包み込む", "complexity_tier": "T4", "furigana": "祖母[そぼ]の笑顔[えがお]には、周[まわ]りの人[ひと]を包[つつ]み込[こ]む温[あたた]かさがある。", "sentence_source": "generated"}, {"text": "柔らかな音楽が、静かな部屋を包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T3", "furigana": "柔[やわ]らかな音楽[おんがく]が、静[しず]かな部屋[へや]を包[つつ]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "彼は大きな手で、小さなひな鳥を包み込んだ。", "target_word": "包み込んだ", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな手[て]で、小[ちい]さなひな鳥[どり]を包[つつ]み込[こ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "包み込む", "label": "辞書形"}, {"form": "包み込んだ", "label": "過去形"}, {"form": "包み込まない", "label": "否定形"}, {"form": "包み込んで", "label": "て形"}, {"form": "包み込み", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "優しく覆って内に含む(光・声・人など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52978, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包み込む", "is_correct": true, "explanation": "身体を優しく覆って囲む意味で、「身体を包み込む芸術」に合う。"}, {"text": "取り外す", "is_correct": false, "explanation": "身体から離して外す意味になり、「身体を取り外す芸術」は内容が成り立たない。"}, {"text": "押し流す", "is_correct": false, "explanation": "水などが力で運び去る意味で、芸術が身体を押し流すという文脈は合わない。"}, {"text": "追い払う", "is_correct": false, "explanation": "人や虫を遠ざける意味で、身体を覆う芸術の描写には使えない。"}], "explanations": {"包み込む": "身体を優しく覆って囲む意味で、「身体を包み込む芸術」に合う。", "取り外す": "身体から離して外す意味になり、「身体を取り外す芸術」は内容が成り立たない。", "押し流す": "水などが力で運び去る意味で、芸術が身体を押し流すという文脈は合わない。", "追い払う": "人や虫を遠ざける意味で、身体を覆う芸術の描写には使えない。"}, "sentence_index": 0, "correct_answer": "包み込む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は言葉巧みに相手を包み込み、契約を取りつけた。", "explanation": "ここは〈丸め込む〉の意味。包み込むは優しく内に含むことで、言葉で相手をだまして従わせる場面には使わない。"}, {"text": "猛スピードのトラックが店の壁を包み込んだ。", "explanation": "ここは〈突っ込む〉の意味。包み込むは優しく覆って内に含むことで、衝突して壊す場面には使わない。"}, {"text": "政府は事故の真相を包み込み、公表しなかった。", "explanation": "ここは〈隠蔽する〉の意味。包み込むは優しく内に含む感じで、事実を隠して明かさない場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52978, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包み込んだ", "is_correct": true, "explanation": "霧が村を優しく覆った意味で、ふんわりと、の修飾に合う。"}, {"text": "引き裂いた", "is_correct": false, "explanation": "布などを力で裂く意味で、霧が村を引き裂くのは文として成り立たない。"}, {"text": "叩き壊した", "is_correct": false, "explanation": "物を叩いて壊す意味で、霧の穏やかな描写には合わない。"}, {"text": "放り投げた", "is_correct": false, "explanation": "物を勢いよく投げる意味で、霧が村を投げるという内容は文脈に合わない。"}], "explanations": {"包み込んだ": "霧が村を優しく覆った意味で、ふんわりと、の修飾に合う。", "引き裂いた": "布などを力で裂く意味で、霧が村を引き裂くのは文として成り立たない。", "叩き壊した": "物を叩いて壊す意味で、霧の穏やかな描写には合わない。", "放り投げた": "物を勢いよく投げる意味で、霧が村を投げるという内容は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "包み込んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重い岩が小さな箱を包み込んだ。", "explanation": "ここは〈押しつぶす〉の意味。包み込むは優しく囲む感じで、力で潰す場面には使わない。"}, {"text": "嵐が古い家屋を包み込み、屋根を吹き飛ばした。", "explanation": "ここは〈破壊する〉の意味。包み込むは優しく内に含むことで、屋根を吹き飛ばす破壊の場面には使わない。"}, {"text": "彼は不正の証拠を包み込み、誰にも見せなかった。", "explanation": "ここは〈隠す〉の意味。包み込むは優しく内に含む感じで、証拠を隠して見せない場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52978, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は子どもに両腕で包み込んだ。", "corrected_sentence": "母は子どもを両腕で包み込んだ。", "error_description": "助詞の誤り。包み込む対象の子どもには『を』が必要で、『に』は誤り。正しくは『子どもを包み込んだ』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "包み込んだ", "is_correct": true, "explanation": "過去の出来事を述べる過去形で、文の時制に合う。"}, {"text": "包み込んで", "is_correct": false, "explanation": "て形で、文を言い切る過去形の位置には入らない。"}, {"text": "包み込まない", "is_correct": false, "explanation": "否定形で、母が包んだという肯定の内容と合わない。"}, {"text": "包み込み", "is_correct": false, "explanation": "連用形で、文を言い切る形としては使えない。"}], "correct_form": "包み込んだ", "base_form": "包み込む", "form_label": "過去形", "sentence_index": 1, "explanations": {"包み込んだ": "過去の出来事を述べる過去形で、文の時制に合う。", "包み込んで": "て形で、文を言い切る過去形の位置には入らない。", "包み込まない": "否定形で、母が包んだという肯定の内容と合わない。", "包み込み": "連用形で、文を言い切る形としては使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52978, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪が町全体を静かに包み込でいた。", "corrected_sentence": "雪が町全体を静かに包み込んでいた。", "error_description": "活用の誤り。て形は『包み込んで』が正しく、『包み込で』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "包み込む", "is_correct": true, "explanation": "名詞の温かさを修飾する辞書形で、連体修飾の位置に合う。"}, {"text": "包み込んで", "is_correct": false, "explanation": "て形で、名詞の温かさを修飾できない。"}, {"text": "包み込もう", "is_correct": false, "explanation": "意志を表す形で、温かさの説明にはならない。"}, {"text": "包み込まれる", "is_correct": false, "explanation": "受身形で、人を目的語に取る文に入ると不文法になる。"}], "correct_form": "包み込む", "base_form": "包み込む", "form_label": "辞書形", "sentence_index": 7, "explanations": {"包み込む": "名詞の温かさを修飾する辞書形で、連体修飾の位置に合う。", "包み込んで": "て形で、名詞の温かさを修飾できない。", "包み込もう": "意志を表す形で、温かさの説明にはならない。", "包み込まれる": "受身形で、人を目的語に取る文に入ると不文法になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52981, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「仕立て屋の店」の「の」で、店が仕立て屋のものであることを示し、文に自然に合う。"}, {"text": "が", "is_correct": false, "explanation": "「仕立て屋が店には」は「店」を修飾できず、文の流れが成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「仕立て屋を店には」と仕立て屋を目的語にする形になり、文の構造が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「仕立て屋で店には」は場所の「で」が「店には」と自然に続かず、店の所属を示せないため合わない。"}], "correct_answer": "の", "explanations": {"の": "「仕立て屋の店」の「の」で、店が仕立て屋のものであることを示し、文に自然に合う。", "が": "「仕立て屋が店には」は「店」を修飾できず、文の流れが成り立たない。", "を": "「仕立て屋を店には」と仕立て屋を目的語にする形になり、文の構造が合わない。", "で": "「仕立て屋で店には」は場所の「で」が「店には」と自然に続かず、店の所属を示せないため合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52981, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52981, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "服を作ったり直したりする人、またはその店。", "primary_collocate": null, "pronunciation": "したてや", "ipa": "ɕitateja", "syllable_count": 4, "sentences": [{"text": "私の叔父は仕立て屋で、毎日きれいな服を作っている。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "私[わたし]の叔父[おじ]は仕立[した]て屋[や]で、毎日[まいにち]きれいな服[ふく]を作[つく]っている。", "sentence_source": "generated"}, {"text": "仕立て屋の店には、色とりどりの布が並んでいる。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "仕立[した]て屋[や]の店[みせ]には、色[いろ]とりどりの布[ぬの]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "仕立て屋は針と糸を使って、ズボンの長さを直した。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "仕立[した]て屋[や]は針[はり]と糸[いと]を使[つか]って、ズボンの長[なが]さを直[なお]した。", "sentence_source": "generated"}, {"text": "母は仕立て屋に、娘のドレスを作ってほしいと頼んだ。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "母[はは]は仕立[した]て屋[や]に、娘[むすめ]のドレスを作[つく]ってほしいと頼[たの]んだ。", "sentence_source": "generated"}, {"text": "あの仕立て屋は仕事が丁寧なので、いつも予約でいっぱいだ。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "あの仕立[した]て屋[や]は仕事[しごと]が丁寧[ていねい]なので、いつも予約[よやく]でいっぱいだ。", "sentence_source": "generated"}, {"text": "弟は大きくなったら、仕立て屋になりたいと言っている。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "弟[おとうと]は大[おお]きくなったら、仕立[した]て屋[や]になりたいと言[い]っている。", "sentence_source": "generated"}, {"text": "仕立て屋のおじさんが、私に新しい制服を作ってくれた。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "仕立[した]て屋[や]のおじさんが、私[わたし]に新[あたら]しい制服[せいふく]を作[つく]ってくれた。", "sentence_source": "generated"}, {"text": "服の袖が長すぎたので、近所の仕立て屋で短くしてもらった。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "服[ふく]の袖[そで]が長[なが]すぎたので、近所[きんじょ]の仕立[した]て屋[や]で短[みじか]くしてもらった。", "sentence_source": "generated"}, {"text": "仕立て屋の窓から、ミシンの音が聞こえてくる。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "仕立[した]て屋[や]の窓[まど]から、ミシンの音[おと]が聞[き]こえてくる。", "sentence_source": "generated"}, {"text": "劇の衣装は、町の仕立て屋が一週間で仕上げてくれた。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "劇[げき]の衣装[いしょう]は、町[まち]の仕立[した]て屋[や]が一週間[いっしゅうかん]で仕上[しあ]げてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕立て屋", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "服を作ったり直したりする人、またはその店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52981, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕立て屋", "is_correct": true, "explanation": "服を作る仕事をする人を指し、叔父の職業として文に合う。"}, {"text": "医者", "is_correct": false, "explanation": "患者を診る職業で、服を作る文脈には合わない。"}, {"text": "教師", "is_correct": false, "explanation": "授業をする職業で、服を作るという文の内容と合わない。"}, {"text": "画家", "is_correct": false, "explanation": "絵を描く職業で、服を作るという文の内容と合わない。"}], "explanations": {"仕立て屋": "服を作る仕事をする人を指し、叔父の職業として文に合う。", "医者": "患者を診る職業で、服を作る文脈には合わない。", "教師": "授業をする職業で、服を作るという文の内容と合わない。", "画家": "絵を描く職業で、服を作るという文の内容と合わない。"}, "sentence_index": 0, "correct_answer": "仕立て屋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕立て屋で虫歯を削ってもらった。", "explanation": "ここは〈歯医者〉の意味。虫歯の治療は歯医者の仕事で、服を作ったり直したりする仕立て屋には合わない。"}, {"text": "仕立て屋に頼んで、庭木の枝を切ってもらった。", "explanation": "ここは〈庭師〉の意味。庭木の剪定は庭師の仕事で、服を作る仕立て屋には合わない。"}, {"text": "仕立て屋に、家の電気配線を直してもらった。", "explanation": "ここは〈電気屋〉の意味。配線の修理は電気屋の仕事で、服の仕立て直しをする仕立て屋には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52981, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕立て屋", "is_correct": true, "explanation": "新しい制服を作ってくれたおじさんとして、服を作る職人の意味で文に合う。"}, {"text": "八百屋", "is_correct": false, "explanation": "野菜や果物を売る店で、制服を作る文脈には合わない。"}, {"text": "花屋", "is_correct": false, "explanation": "花を売る店で、制服を作るという内容と合わない。"}, {"text": "鍛冶屋", "is_correct": false, "explanation": "金属の道具を作る職人で、制服を作るという内容と合わない。"}], "explanations": {"仕立て屋": "新しい制服を作ってくれたおじさんとして、服を作る職人の意味で文に合う。", "八百屋": "野菜や果物を売る店で、制服を作る文脈には合わない。", "花屋": "花を売る店で、制服を作るという内容と合わない。", "鍛冶屋": "金属の道具を作る職人で、制服を作るという内容と合わない。"}, "sentence_index": 6, "correct_answer": "仕立て屋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仕立て屋に名刺を注文して、百枚刷ってもらった。", "explanation": "ここは〈印刷所〉の意味。名刺を刷るのは印刷所の仕事で、服を仕立てる仕立て屋には合わない。"}, {"text": "仕立て屋でパーマをかけてもらい、髪が軽くなった。", "explanation": "ここは〈美容院〉の意味。パーマをかけるのは美容院の仕事で、仕立て屋には合わない。"}, {"text": "仕立て屋で新しいレンズを入れてもらった。", "explanation": "ここは〈眼鏡屋〉の意味。レンズの入れ替えは眼鏡屋の仕事で、服を作る仕立て屋には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52981, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は仕立て屋を、結婚式用の羽織を作ってもらった。", "corrected_sentence": "祖父は仕立て屋に、結婚式用の羽織を作ってもらった。", "error_description": "「作ってもらう」の相手は「に」で示すため、「仕立て屋を」は誤り。正しくは「仕立て屋に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52981, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、仕立て屋に袖丈を直しもらった。", "corrected_sentence": "先週、仕立て屋に袖丈を直してもらった。", "error_description": "誤りは動詞の活用。「直してもらった」の「て」が抜けており、「直しもらった」は誤り。正しくは「直してもらった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52982, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「頼む」の依頼先を示す「に」で、「仕立て屋に頼んで」として自然。"}, {"text": "を", "is_correct": false, "explanation": "「頼む」は人を目的語に取らないため、「仕立て屋を頼んで」は不自然で合わない。"}, {"text": "と", "is_correct": false, "explanation": "「仕立て屋と頼んで」は共同で頼む意味になり、依頼先を示さないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、依頼の相手を示す文脈には合わない。"}], "correct_answer": "に", "explanations": {"に": "「頼む」の依頼先を示す「に」で、「仕立て屋に頼んで」として自然。", "を": "「頼む」は人を目的語に取らないため、「仕立て屋を頼んで」は不自然で合わない。", "と": "「仕立て屋と頼んで」は共同で頼む意味になり、依頼先を示さないので合わない。", "より": "「より」は比較を表すため、依頼の相手を示す文脈には合わない。"}, "error_tags": {"を": "目的語", "と": "並列・共同", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52982, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52982, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "注文に応じて、布を切って縫い、服を作る人。", "primary_collocate": null, "pronunciation": "したてや", "ipa": "ɕitateja", "syllable_count": 4, "sentences": [{"text": "かつての仕立て屋は、職人としての矜持を大切にしていた。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "かつての仕立[した]て屋[や]は、職人[しょくにん]としての矜持[きょうじ]を大切[たいせつ]にしていた。", "sentence_source": "generated"}, {"text": "父は仕立て屋に頼んで、結婚式用のスーツを作ってもらった。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "父[ちち]は仕立[した]て屋[や]に頼[たの]んで、結婚式[けっこんしき]用[よう]のスーツを作[つく]ってもらった。", "sentence_source": "generated"}, {"text": "この町には、三代続く仕立て屋が一軒だけ残っている。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "この町[まち]には、三代[さんだい]続[つづ]く仕立[した]て屋[や]が一軒[いっけん]だけ残[のこ]っている。", "sentence_source": "generated"}, {"text": "仕立て屋は私の肩幅を測り、布に印をつけた。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "仕立[した]て屋[や]は私[わたし]の肩幅[かたはば]を測[はか]り、布[ぬの]に印[しるし]をつけた。", "sentence_source": "generated"}, {"text": "既製品は合わなかったので、仕立て屋に注文することにした。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "既製品[きせいひん]は合[あ]わなかったので、仕立[した]て屋[や]に注文[ちゅうもん]することにした。", "sentence_source": "generated"}, {"text": "祖父は若いころ、仕立て屋として働いていた。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "祖父[そふ]は若[わか]いころ、仕立[した]て屋[や]として働[はたら]いていた。", "sentence_source": "generated"}, {"text": "腕のいい仕立て屋が縫った上着は、着るたびに体になじむ。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "腕[うで]のいい仕立[した]て屋[や]が縫[ぬ]った上着[うわぎ]は、着[き]るたびに体[からだ]になじむ。", "sentence_source": "generated"}, {"text": "仕立て屋に出したコートが、来週の火曜日にできあがる。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "仕立[した]て屋[や]に出[だ]したコートが、来週[らいしゅう]の火曜日[かようび]にできあがる。", "sentence_source": "generated"}, {"text": "彼女は仕立て屋になるために、毎日ミシンの練習をしている。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仕立[した]て屋[や]になるために、毎日[まいにち]ミシンの練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "仕立て屋が客の好みを聞きながら、布の色を一緒に選んでくれた。", "target_word": "仕立て屋", "complexity_tier": "T3", "furigana": "仕立[した]て屋[や]が客[きゃく]の好[この]みを聞[き]きながら、布[ぬの]の色[いろ]を一緒[いっしょ]に選[えら]んでくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕立て屋", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "注文を受けて布から服を仕立てる職人(オーダーメイドの洋服屋)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52982, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕立て屋", "is_correct": true, "explanation": "注文を受けて布から服を仕立てる職人で、かつての職人としての矜持を持つ主体として文意に合う。"}, {"text": "ミシン", "is_correct": false, "explanation": "服を縫う道具であり、矜持を持つ主体にはならないので「かつてのミシンの矜持」は成り立たない。"}, {"text": "針", "is_correct": false, "explanation": "手縫いの道具で、矜持を持つ主体とはならないので文脈に合わない。"}, {"text": "布", "is_correct": false, "explanation": "服の材料であり、矜持を持つ主体にはならないので「かつての布の矜持」は不自然で合わない。"}], "explanations": {"仕立て屋": "注文を受けて布から服を仕立てる職人で、かつての職人としての矜持を持つ主体として文意に合う。", "ミシン": "服を縫う道具であり、矜持を持つ主体にはならないので「かつてのミシンの矜持」は成り立たない。", "針": "手縫いの道具で、矜持を持つ主体とはならないので文脈に合わない。", "布": "服の材料であり、矜持を持つ主体にはならないので「かつての布の矜持」は不自然で合わない。"}, "sentence_index": 0, "correct_answer": "仕立て屋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕立て屋に頼んで、古いピアノを調律してもらった。", "explanation": "ここは〈調律師〉の意味。ピアノの調律は調律師の仕事で、服を縫う仕立て屋には合わない。"}, {"text": "仕立て屋に頼んで、この部屋の壁紙を張り替えてもらった。", "explanation": "ここは〈大工〉の意味。壁紙の張り替えは大工や内装の仕事で、服を縫う仕立て屋の仕事ではない。"}, {"text": "仕立て屋で髪を切ってもらい、さっぱりした。", "explanation": "ここは〈床屋〉の意味。髪を切るのは床屋の仕事で、服を仕立てる仕立て屋には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52982, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕立て屋", "is_correct": true, "explanation": "腕のいい職人として上着を縫う人を指し、文の主語として自然。"}, {"text": "糸", "is_correct": false, "explanation": "縫う際の材料であり、腕がいいと評価される人ではないので「腕のいい糸が縫った」は成り立たない。"}, {"text": "ボタン", "is_correct": false, "explanation": "上着の部品であり、縫う主体にならないので文に合わない。"}, {"text": "ハサミ", "is_correct": false, "explanation": "布を切る道具で、縫う主体ではないため「腕のいいハサミが縫った」は合わない。"}], "explanations": {"仕立て屋": "腕のいい職人として上着を縫う人を指し、文の主語として自然。", "糸": "縫う際の材料であり、腕がいいと評価される人ではないので「腕のいい糸が縫った」は成り立たない。", "ボタン": "上着の部品であり、縫う主体にならないので文に合わない。", "ハサミ": "布を切る道具で、縫う主体ではないため「腕のいいハサミが縫った」は合わない。"}, "sentence_index": 6, "correct_answer": "仕立て屋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仕立て屋で家族の写真を撮ってもらった。", "explanation": "ここは〈写真館〉の意味。写真を撮るのは写真館の仕事で、服を作る仕立て屋には合わない。"}, {"text": "仕立て屋が人物画を描いた。", "explanation": "ここは〈画家〉の意味。人物画を描くのは画家で、服を仕立てる仕立て屋には合わない。"}, {"text": "仕立て屋にカギを作り直してもらった。", "explanation": "ここは〈鍵屋〉の意味。カギの作り直しは鍵屋の仕事で、仕立て屋は服を作る人なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52982, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は仕立て屋を、娘の浴衣を縫ってもらうよう頼んだ。", "corrected_sentence": "祖母は仕立て屋に、娘の浴衣を縫ってもらうよう頼んだ。", "error_description": "「頼む」は依頼先に「に」を取るため、「仕立て屋を」は誤り。正しくは「仕立て屋に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52982, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は仕立て屋を注文して、夏用のワンピースを作ってもらった。", "corrected_sentence": "彼女は仕立て屋に注文して、夏用のワンピースを作ってもらった。", "error_description": "「注文する」の相手は「に」で示すため、「仕立て屋を」は誤り。正しくは「仕立て屋に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
