INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52983, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『先生の矜持』で、所有・修飾の関係を示す。"}, {"text": "で", "is_correct": false, "explanation": "『先生で矜持』は格が合わず、名詞同士を結ばない。"}, {"text": "から", "is_correct": false, "explanation": "『先生から矜持』は起点を表し、修飾関係にならない。"}, {"text": "より", "is_correct": false, "explanation": "『先生より矜持』は比較を表し、名詞を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "『先生の矜持』で、所有・修飾の関係を示す。", "で": "『先生で矜持』は格が合わず、名詞同士を結ばない。", "から": "『先生から矜持』は起点を表し、修飾関係にならない。", "より": "『先生より矜持』は比較を表し、名詞を修飾する形にならない。"}, "error_tags": {"で": "手段・場所", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52983, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "じぶんのしごとや ちからに もつ ほこり。", "primary_collocate": null, "pronunciation": "きょうじ", "ipa": "kʲoːdʑi", "syllable_count": 3, "sentences": [{"text": "彼は料理人としての矜持を持って、毎日店に立っている。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "彼[かれ]は料理人[りょうりにん]としての矜持[きょうじ]を持[も]って、毎日[まいにち]店[みせ]に立[た]っている。", "sentence_source": "generated"}, {"text": "私の祖父は大工の矜持を大切にしていた。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "私[わたし]の祖父[そふ]は大工[だいく]の矜持[きょうじ]を大切[たいせつ]にしていた。", "sentence_source": "generated"}, {"text": "矜持があるから、彼は手を抜かずに仕事をする。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "矜持[きょうじ]があるから、彼[かれ]は手[て]を抜[ぬ]かずに仕事[しごと]をする。", "sentence_source": "generated"}, {"text": "試合に負けても、全力を出したという矜持は残った。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けても、全力[ぜんりょく]を出[だ]したという矜持[きょうじ]は残[のこ]った。", "sentence_source": "generated"}, {"text": "医者の矜持にかけて、この患者を必ず助ける。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "医者[いしゃ]の矜持[きょうじ]にかけて、この患者[かんじゃ]を必[かなら]ず助[たす]ける。", "sentence_source": "generated"}, {"text": "彼女は歌手の矜持を忘れず、毎日練習を続けた。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は歌手[かしゅ]の矜持[きょうじ]を忘[わす]れず、毎日[まいにち]練習[れんしゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "安い仕事でも、職人は矜持を持って作る。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "安[やす]い仕事[しごと]でも、職人[しょくにん]は矜持[きょうじ]を持[も]って作[つく]る。", "sentence_source": "generated"}, {"text": "先生の矜持は、生徒に正しく教えることだった。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "先生[せんせい]の矜持[きょうじ]は、生徒[せいと]に正[ただ]しく教[おし]えることだった。", "sentence_source": "generated"}, {"text": "矜持を傷つけられて、彼はしばらく黙っていた。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "矜持[きょうじ]を傷[きず]つけられて、彼[かれ]はしばらく黙[だま]っていた。", "sentence_source": "generated"}, {"text": "店主の矜持が、あの店の味を守っている。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "店主[てんしゅ]の矜持[きょうじ]が、あの店[みせ]の味[あじ]を守[まも]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "矜持", "label": "基本形"}, {"form": "矜持の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "自分の仕事や力に対して持つ誇り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52983, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矜持", "is_correct": true, "explanation": "『料理人としての矜持を持って』は、料理人が仕事に持つ誇りを表し、文に合う。"}, {"text": "寝不足", "is_correct": false, "explanation": "睡眠不足を表す語で、料理人としての心構えを述べる文には入らない。"}, {"text": "体重", "is_correct": false, "explanation": "身体の重さを指す語で、仕事への姿勢とは関係がない。"}, {"text": "騒音", "is_correct": false, "explanation": "店の周囲の音を指す語で、仕事への誇りを表す文脈には合わない。"}], "explanations": {"矜持": "『料理人としての矜持を持って』は、料理人が仕事に持つ誇りを表し、文に合う。", "寝不足": "睡眠不足を表す語で、料理人としての心構えを述べる文には入らない。", "体重": "身体の重さを指す語で、仕事への姿勢とは関係がない。", "騒音": "店の周囲の音を指す語で、仕事への誇りを表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "矜持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事の報酬として、彼は高い矜持を三つ数えた。", "explanation": "ここは〈数量〉の意味。矜持は心の自負なので、三つと数えて勘定するものではない。"}, {"text": "彼は矜持を引っ越し荷物にまとめた。", "explanation": "矜持は目に見えない自負心なので、箱に詰めて運ぶ物として扱うのは不自然。"}, {"text": "彼は店長の矜持を、店の棚に一列に並べた。", "explanation": "ここは〈陳列品〉の意味。矜持は形のない自負心なので、棚に並べて飾る品物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52983, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矜持", "is_correct": true, "explanation": "『安い仕事でも、職人は矜持を持って作る』で、仕事への誇りを表し文脈に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい状態を指し、職人の仕事への心の持ち方を表すには合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の状態を表す語で、仕事の取り組み方を述べる文には入らない。"}, {"text": "体温", "is_correct": false, "explanation": "身体の温度を指す語で、仕事に持つ誇りとは関係がない。"}], "explanations": {"矜持": "『安い仕事でも、職人は矜持を持って作る』で、仕事への誇りを表し文脈に合う。", "眠気": "眠たい状態を指し、職人の仕事への心の持ち方を表すには合わない。", "湿度": "空気の状態を表す語で、仕事の取り組み方を述べる文には入らない。", "体温": "身体の温度を指す語で、仕事に持つ誇りとは関係がない。"}, "sentence_index": 6, "correct_answer": "矜持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主の矜持が、あの店の味を見分けている。", "explanation": "ここは〈感じ分ける力〉の意味。矜持は仕事への自負なので、味を感じ分ける能力とは関係しない。"}, {"text": "大雨で店が浸水し、店主の矜持が看板を塗り替えた。", "explanation": "ここは〈物体〉の意味。矜持は形のない自負なので、塗り替えられる物としては使わない。"}, {"text": "店主の矜持が、来月の天候を読んでいる。", "explanation": "ここは〈予測〉の意味。矜持は仕事への自負なので、天候を読んで先を予想する働きはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52983, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は矜持が大切にしていた。", "corrected_sentence": "祖父は矜持を大切にしていた。", "error_description": "『大切にする』の目的語は『を』で示す。『矜持が』は誤りで、正しくは『矜持を』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52983, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店主は矜持に守って、店を閉めなかった。", "corrected_sentence": "店主は矜持を守って、店を閉めなかった。", "error_description": "『守る』の目的語は『を』で示す。『矜持に』は誤りで、正しくは『矜持を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52984, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『守る』の目的語なので『矜持を守る』となる。"}, {"text": "が", "is_correct": false, "explanation": "『矜持が守る』では主語と動詞の関係が成り立たず、目的語の役割にならない。"}, {"text": "に", "is_correct": false, "explanation": "『矜持に守る』は目的語の格が合わない。"}, {"text": "の", "is_correct": false, "explanation": "『矜持の守る』と続かず、名詞を修飾する形にもならない。"}], "correct_answer": "を", "explanations": {"を": "『守る』の目的語なので『矜持を守る』となる。", "が": "『矜持が守る』では主語と動詞の関係が成り立たず、目的語の役割にならない。", "に": "『矜持に守る』は目的語の格が合わない。", "の": "『矜持の守る』と続かず、名詞を修飾する形にもならない。"}, "error_tags": {"が": "主格（主語）", "に": "対象・方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52984, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『記者の矜持』で、所有・修飾の関係を示す。"}, {"text": "で", "is_correct": false, "explanation": "『記者で矜持』は格が合わず、名詞同士を結ぶ形にならない。"}, {"text": "から", "is_correct": false, "explanation": "『記者から矜持』は起点を表すため、修飾の関係にならない。"}, {"text": "へ", "is_correct": false, "explanation": "『記者へ矜持』は方向を表すため、名詞を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "『記者の矜持』で、所有・修飾の関係を示す。", "で": "『記者で矜持』は格が合わず、名詞同士を結ぶ形にならない。", "から": "『記者から矜持』は起点を表すため、修飾の関係にならない。", "へ": "『記者へ矜持』は方向を表すため、名詞を修飾する形にならない。"}, "error_tags": {"で": "手段・場所", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52984, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の能力や立場に対して持つ誇り。特に、専門的な技術や職業に対する自負心。", "primary_collocate": null, "pronunciation": "きょうじ", "ipa": "kʲoːdʑi", "syllable_count": 3, "sentences": [{"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "矜持", "complexity_tier": "T4", "furigana": "仮想[かそう]空間[くうかん]上[じょう]で構築[こうちく]される3Dモデリングやアルゴリズムによる生成物[せいせいぶつ]は、かつての「仕立[した]て屋[や]」の矜持[きょうじ]をどう書[か]き換[か]えているのか。そこには、アナログな温[ぬく]もりとデジタルな冷徹[れいてつ]さの間[あいだ]の絶[た]え間[ま]ない緊張[きんちょう]関係[かんけい]が見[み]て取[と]れ、それは創造性[そうぞうせい]の本質[ほんしつ]を問[と]うている。", "sentence_source": "mined"}, {"text": "職人としての矜持を守るため、彼は安い材料を決して使わなかった。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "職人[しょくにん]としての矜持[きょうじ]を守[まも]るため、彼[かれ]は安[やす]い材料[ざいりょう]を決[けっ]して使[つか]わなかった。", "sentence_source": "generated"}, {"text": "長年医師を務めた父は、患者を最後まで診る矜持を持っていた。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "長年[ながねん]医師[いし]を務[つと]めた父[ちち]は、患者[かんじゃ]を最後[さいご]まで診[み]る矜持[きょうじ]を持[も]っていた。", "sentence_source": "generated"}, {"text": "彼女は料理人の矜持にかけて、手抜きの料理は出さないと決めている。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は料理人[りょうりにん]の矜持[きょうじ]にかけて、手抜[てぬ]きの料理[りょうり]は出[だ]さないと決[き]めている。", "sentence_source": "generated"}, {"text": "締め切りに追われても、プロの矜持が品質を落とすことを許さなかった。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "締[し]め切[き]りに追[お]われても、プロの矜持[きょうじ]が品質[ひんしつ]を落[お]とすことを許[ゆる]さなかった。", "sentence_source": "generated"}, {"text": "無理な値下げを断ったのは、技術者としての矜持があったからだ。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "無理[むり]な値下[ねさ]げを断[ことわ]ったのは、技術者[ぎじゅつしゃ]としての矜持[きょうじ]があったからだ。", "sentence_source": "generated"}, {"text": "老いた大工は、自分の仕事に矜持を抱き、最後まで道具を手放さなかった。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "老[お]いた大工[だいく]は、自分[じぶん]の仕事[しごと]に矜持[きょうじ]を抱[いだ]き、最後[さいご]まで道具[どうぐ]を手放[てばな]さなかった。", "sentence_source": "generated"}, {"text": "記者の矜持とは、権力に屈せず事実を伝えることだと先輩は言った。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "記者[きしゃ]の矜持[きょうじ]とは、権力[けんりょく]に屈[くっ]せず事実[じじつ]を伝[つた]えることだと先輩[せんぱい]は言[い]った。", "sentence_source": "generated"}, {"text": "負けはしたが、最高の演奏をしたという矜持が彼の胸に残っていた。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "負[ま]けはしたが、最高[さいこう]の演奏[えんそう]をしたという矜持[きょうじ]が彼[かれ]の胸[むね]に残[のこ]っていた。", "sentence_source": "generated"}, {"text": "若手の職人にも、一流の矜持を持って仕事に向き合ってほしい。", "target_word": "矜持", "complexity_tier": "T3", "furigana": "若手[わかて]の職人[しょくにん]にも、一流[いちりゅう]の矜持[きょうじ]を持[も]って仕事[しごと]に向[む]き合[あ]ってほしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "矜持", "label": "基本形"}, {"form": "矜持の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "専門的な技術や職業に対する、揺るがない自負心としての誇り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52984, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矜持", "is_correct": true, "explanation": "「仕立て屋の矜持」は、職人が自分の仕事に持つ誇りを指し、文脈の「どう書き換えているのか」に合う。"}, {"text": "怠惰", "is_correct": false, "explanation": "仕事に対する怠け心を表し、職人の誇りを問う文脈とは逆の意味になるので合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "睡眠不足の状態を表す語で、仕立て屋の仕事観を述べる文の対象にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の状態を表す語で、仕立て屋の仕事の姿勢を指すには当てはまらない。"}], "explanations": {"矜持": "「仕立て屋の矜持」は、職人が自分の仕事に持つ誇りを指し、文脈の「どう書き換えているのか」に合う。", "怠惰": "仕事に対する怠け心を表し、職人の誇りを問う文脈とは逆の意味になるので合わない。", "寝不足": "睡眠不足の状態を表す語で、仕立て屋の仕事観を述べる文の対象にならない。", "湿度": "空気の状態を表す語で、仕立て屋の仕事の姿勢を指すには当てはまらない。"}, "sentence_index": 0, "correct_answer": "矜持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この村の矜持は、毎年夏に広場で開かれる。", "explanation": "ここは〈行事〉の意味。矜持は心に持つ自負なので、広場で開かれる行事として扱うのは誤り。"}, {"text": "生活費のため、彼は古い矜持を一箱分まとめて運んだ。", "explanation": "ここは〈持ち運ぶ物〉の意味。矜持は形のない自負心なので、箱にまとめて運べる物としては使えない。"}, {"text": "彼は矜持を毎朝七時に鳴らした。", "explanation": "ここは〈音を出す〉の意味。矜持は心の自負なので、目覚ましのように鳴らして知らせるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52984, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矜持", "is_correct": true, "explanation": "「仕事に矜持を抱き」は、大工が自分の仕事に持つ誇りを表し、文の流れに合う。"}, {"text": "体重", "is_correct": false, "explanation": "身体の重さを表す語で、仕事に対して抱く心情とは結びつかない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい状態を指し、仕事への心の持ち方を述べる文には合わない。"}, {"text": "騒音", "is_correct": false, "explanation": "周囲の大きな音を指す語で、大工が仕事に抱く感情とは関係がない。"}], "explanations": {"矜持": "「仕事に矜持を抱き」は、大工が自分の仕事に持つ誇りを表し、文の流れに合う。", "体重": "身体の重さを表す語で、仕事に対して抱く心情とは結びつかない。", "眠気": "眠たい状態を指し、仕事への心の持ち方を述べる文には合わない。", "騒音": "周囲の大きな音を指す語で、大工が仕事に抱く感情とは関係がない。"}, "sentence_index": 6, "correct_answer": "矜持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "失敗を笑われて、彼は矜持を赤くして部屋にこもった。", "explanation": "ここは〈顔色〉の意味。矜持は心の自負なので、顔が赤くなるような身体の様子としては使えない。"}, {"text": "大会で、彼女の矜持は三位に終わった。", "explanation": "ここは競技の順位の意味。矜持は自負心なので、成績の結果を表す語にはならない。"}, {"text": "祖父は古い矜持を、役所の許可証として子に渡した。", "explanation": "ここは〈証明書〉の意味。矜持は心の自負なので、役所が発行する許可証のような書類とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52984, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は職人としての矜持に大切にしている。", "corrected_sentence": "彼は職人としての矜持を大切にしている。", "error_description": "『大切にする』は目的語に『を』を取る。『矜持に』は誤りで、正しくは『矜持を』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52984, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "職人は矜持に持って仕事をする。", "corrected_sentence": "職人は矜持を持って仕事をする。", "error_description": "『持つ』の目的語は『を』で示す。『矜持に』は誤りで、正しくは『矜持を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52985, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「新しい店の名前に」で、書き替えの結果として変わる先を示す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「名前が書き替えます」では名前が動作する主語になり、看板を書き替える文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や共同を示す。「店の名前と書き替えます」では何と何を書き替えるのか意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。「店の名前の書き替えます」では動詞に続かず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「新しい店の名前に」で、書き替えの結果として変わる先を示す。正しい。", "が": "主語を示す。「名前が書き替えます」では名前が動作する主語になり、看板を書き替える文に合わない。", "と": "相手や共同を示す。「店の名前と書き替えます」では何と何を書き替えるのか意味が通らない。", "の": "連体修飾を示す。「店の名前の書き替えます」では動詞に続かず、文が成り立たない。"}, "error_tags": {"が": "主語", "と": "相手・共同", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52985, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「数字を」で、書き替える対象を示す。正しい。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。「数字の書き替えました」では動詞に続かず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「数字より書き替えました」では何かと比べる文になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向や到達点を示す。「数字へ書き替えました」は変わる先を示すことになり、書き替える対象は「を」で示すのが自然。"}], "correct_answer": "を", "explanations": {"を": "「数字を」で、書き替える対象を示す。正しい。", "の": "連体修飾を示す。「数字の書き替えました」では動詞に続かず、文が成り立たない。", "より": "比較を示す。「数字より書き替えました」では何かと比べる文になり、文が成り立たない。", "へ": "方向や到達点を示す。「数字へ書き替えました」は変わる先を示すことになり、書き替える対象は「を」で示すのが自然。"}, "error_tags": {"の": "連体修飾", "より": "比較", "へ": "方向・到達点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52985, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かいたものを、ちがうものに かえること。", "primary_collocate": null, "pronunciation": "かきかえる", "ipa": "kakikaeɾɯ", "syllable_count": 5, "sentences": [{"text": "名前を間違えたので、新しい名前に書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "名前[なまえ]を間違[まちが]えたので、新[あたら]しい名前[なまえ]に書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "古い看板を、新しい店の名前に書き替えます。", "target_word": "書き替えます", "complexity_tier": "T3", "furigana": "古[ふる]い看板[かんばん]を、新[あたら]しい店[みせ]の名前[なまえ]に書[か]き替[か]えます。", "sentence_source": "generated"}, {"text": "黒板の問題を消して、別の問題に書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "黒板[こくばん]の問題[もんだい]を消[け]して、別[べつ]の問題[もんだい]に書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "住所が変わったので、カードの住所を書き替えてください。", "target_word": "書き替えて", "complexity_tier": "T3", "furigana": "住所[じゅうしょ]が変[か]わったので、カードの住所[じゅうしょ]を書[か]き替[か]えてください。", "sentence_source": "generated"}, {"text": "予定が変わり、カレンダーの日付を書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "予定[よてい]が変[か]わり、カレンダーの日付[ひづけ]を書き替[かきか]えました。", "sentence_source": "generated"}, {"text": "先生は、私の答えを正しい答えに書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "先生[せんせい]は、私[わたし]の答[こた]えを正[ただ]しい答[こた]えに書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "ホワイトボードの時間を、午後三時に書き替えます。", "target_word": "書き替えます", "complexity_tier": "T3", "furigana": "ホワイトボードの時間[じかん]を、午後三時[ごごさんじ]に書[か]き替[か]えます。", "sentence_source": "generated"}, {"text": "値段が上がったので、メニューの数字を書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "値段[ねだん]が上[あ]がったので、メニューの数字[すうじ]を書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "雨で中止になったから、お知らせの日付を書き替えます。", "target_word": "書き替えます", "complexity_tier": "T3", "furigana": "雨[あめ]で中止[ちゅうし]になったから、お知[し]らせの日付[ひづけ]を書[か]き替[か]えます。", "sentence_source": "generated"}, {"text": "ポスターの日にちを消して、新しい日にちに書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "ポスターの日[ひ]にちを消[け]して、新[あたら]しい日[ひ]にちに書[か]き替[か]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書き替える", "label": "基本形"}, {"form": "書き替えます", "label": "丁寧形"}, {"form": "書き替えて", "label": "て形"}, {"form": "書き替えた", "label": "過去形"}, {"form": "書き替えない", "label": "否定形"}], "register": "丁寧", "sense_fingerprint": "書いてあった字や名前を別のものに替えて書く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52985, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書き替えました", "is_correct": true, "explanation": "「書き替える」の丁寧な過去形。名前を書き直して別の名前に替えた、という文に合う。"}, {"text": "破りました", "is_correct": false, "explanation": "「破る」の過去形。紙を破る動作で、新しい名前に続けると文が成り立たない。"}, {"text": "消しました", "is_correct": false, "explanation": "「消す」の過去形。消す対象は名前だが、「新しい名前に消しました」は不自然で書き替えの代わりにならない。"}, {"text": "切りました", "is_correct": false, "explanation": "「切る」の過去形。名前に切るという動作は成り立たず、文の意味が通らない。"}], "explanations": {"書き替えました": "「書き替える」の丁寧な過去形。名前を書き直して別の名前に替えた、という文に合う。", "破りました": "「破る」の過去形。紙を破る動作で、新しい名前に続けると文が成り立たない。", "消しました": "「消す」の過去形。消す対象は名前だが、「新しい名前に消しました」は不自然で書き替えの代わりにならない。", "切りました": "「切る」の過去形。名前に切るという動作は成り立たず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "書き替えました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "メモの文字の色を、書き替えました。", "explanation": "ここは〈書式を変える〉の意味。文字の色は書いた内容ではないので、書き替えるは合わない。"}, {"text": "古い写真を、新しい写真に書き替えました。", "explanation": "ここは〈差し替える〉の意味。写真は字や名前を書いたものではないので、書き替えるは使えない。"}, {"text": "白紙の申込書に、名前を書き替えました。", "explanation": "ここは〈書き込む〉の意味。白紙には替える前の字がないので、書き替えるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52985, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書き替えます", "is_correct": true, "explanation": "「書き替える」の丁寧形。時間を別の時刻に替えて書き直す意味で文に合う。"}, {"text": "洗います", "is_correct": false, "explanation": "「洗う」の丁寧形。ボードの時間を洗うことはできず、文が成り立たない。"}, {"text": "読みます", "is_correct": false, "explanation": "「読む」の丁寧形。時間を読むという動作は、文の意味に合わない。"}, {"text": "寝ます", "is_correct": false, "explanation": "「寝る」の丁寧形。午後三時に寝るという行為は、時間を替える話と結びつかない。"}], "explanations": {"書き替えます": "「書き替える」の丁寧形。時間を別の時刻に替えて書き直す意味で文に合う。", "洗います": "「洗う」の丁寧形。ボードの時間を洗うことはできず、文が成り立たない。", "読みます": "「読む」の丁寧形。時間を読むという動作は、文の意味に合わない。", "寝ます": "「寝る」の丁寧形。午後三時に寝るという行為は、時間を替える話と結びつかない。"}, "sentence_index": 6, "correct_answer": "書き替えます"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お手本を見ながら、ノートに漢字を書き替えました。", "explanation": "ここは〈書き写す〉の意味。同じ内容を写しただけで変えていないので、内容を別のものに替える書き替えるは合わない。"}, {"text": "入学願書の空いている欄に、住所を書き替えました。", "explanation": "ここは〈記入する〉の意味。空いている欄には前の字がなく、替える内容がないので、書き替えるは使えない。"}, {"text": "壊れた時計の電池を、新しいものに書き替えました。", "explanation": "ここは〈取り替える〉の意味。電池は字や名前を書いたものではないので、書き替えるは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52985, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "住所を間違えたので、新しい住所に書き替えるました。", "corrected_sentence": "住所を間違えたので、新しい住所に書き替えました。", "error_description": "「書き替えました」の「る」が余分。動詞の連用形「書き替え」に「ました」を付けるので、「書き替えるました」は誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "書き替えます", "is_correct": true, "explanation": "丁寧な現在形（ます形）。文全体の丁寧な言い方に合う。"}, {"text": "書き替え", "is_correct": false, "explanation": "連用形（ます形の語幹）。文末に置くと文が終わらないので使えない。"}, {"text": "書き替えれば", "is_correct": false, "explanation": "仮定形。「れば」の後に続く文がないので、ここで文を終えることはできない。"}, {"text": "書き替えて", "is_correct": false, "explanation": "て形。ここで文を終えることはできないので、文末の形として使えない。"}], "correct_form": "書き替えます", "base_form": "書き替える", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"書き替えます": "丁寧な現在形（ます形）。文全体の丁寧な言い方に合う。", "書き替え": "連用形（ます形の語幹）。文末に置くと文が終わらないので使えない。", "書き替えれば": "仮定形。「れば」の後に続く文がないので、ここで文を終えることはできない。", "書き替えて": "て形。ここで文を終えることはできないので、文末の形として使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52985, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ホワイトボードの予定が、午後四時に書き替えます。", "corrected_sentence": "ホワイトボードの予定を、午後四時に書き替えます。", "error_description": "「書き替えます」の対象には「を」を付ける。「予定が」では予定が主語になり、書き替える対象を示せない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "書き替えました", "is_correct": true, "explanation": "丁寧な過去形（ました形）。数字を替えて書き直したという完了した動作に合う。"}, {"text": "書き替えさせ", "is_correct": false, "explanation": "使役の語幹で、文末に置くと文が終わらないので使えない。"}, {"text": "書き替えたり", "is_correct": false, "explanation": "並列を表す形で、後ろに別の動作が続かなければ文を終えられない。"}, {"text": "書き替えず", "is_correct": false, "explanation": "連用形の否定で、文末に置くと文が終わらないので使えない。"}], "correct_form": "書き替えました", "base_form": "書き替える", "form_label": "丁寧過去形", "sentence_index": 7, "explanations": {"書き替えました": "丁寧な過去形（ました形）。数字を替えて書き直したという完了した動作に合う。", "書き替えさせ": "使役の語幹で、文末に置くと文が終わらないので使えない。", "書き替えたり": "並列を表す形で、後ろに別の動作が続かなければ文を終えられない。", "書き替えず": "連用形の否定で、文末に置くと文が終わらないので使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52986, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「最初から」で、書き替えを始める起点を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「報告書を最初を書き替えます」では「を」が二つになり、書き替えの対象が定まらない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「最初より書き替えます」では比べる文になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。「最初の書き替えます」では動詞に続かず、文が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「最初から」で、書き替えを始める起点を示す。正しい。", "を": "目的語を示す。「報告書を最初を書き替えます」では「を」が二つになり、書き替えの対象が定まらない。", "より": "比較を示す。「最初より書き替えます」では比べる文になり、文が成り立たない。", "の": "連体修飾を示す。「最初の書き替えます」では動詞に続かず、文が成り立たない。"}, "error_tags": {"を": "目的語の重複", "より": "比較", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52986, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「明るい内容に」で、書き替えの結果として変わる先を示す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「明るい内容が書き替えました」では内容が動作の主体になり、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や共同を示す。「明るい内容と書き替えました」では何と何を書き替えるのか意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「明るい内容へ書き替えました」は変わる先を『へ』で示すことになり、ここでは『に』が自然。"}], "correct_answer": "に", "explanations": {"に": "「明るい内容に」で、書き替えの結果として変わる先を示す。正しい。", "が": "主語を示す。「明るい内容が書き替えました」では内容が動作の主体になり、文の意味が通らない。", "と": "相手や共同を示す。「明るい内容と書き替えました」では何と何を書き替えるのか意味が通らない。", "へ": "方向を示す。「明るい内容へ書き替えました」は変わる先を『へ』で示すことになり、ここでは『に』が自然。"}, "error_tags": {"が": "主語", "と": "相手・共同", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52986, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "前に書いた内容を、新しい内容に書き直すこと。", "primary_collocate": null, "pronunciation": "かきかえる", "ipa": "kakikaeɾɯ", "syllable_count": 5, "sentences": [{"text": "古い資料の内容を、新しい情報に書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "古[ふる]い資料[しりょう]の内容[ないよう]を、新[あたら]しい情報[じょうほう]に書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "計画が変わったので、報告書を最初から書き替えます。", "target_word": "書き替えます", "complexity_tier": "T3", "furigana": "計画[けいかく]が変[か]わったので、報告書[ほうこくしょ]を最初[さいしょ]から書[か]き替[か]えます。", "sentence_source": "generated"}, {"text": "設定ファイルの内容を書き替えて、保存しました。", "target_word": "書き替えて", "complexity_tier": "T3", "furigana": "設定[せってい]ファイルの内容[ないよう]を書[か]き替[か]えて、保存[ほぞん]しました。", "sentence_source": "generated"}, {"text": "前の文章を書き替えたら、読みやすくなりました。", "target_word": "書き替えたら", "complexity_tier": "T3", "furigana": "前[まえ]の文章[ぶんしょう]を書[か]き替[か]えたら、読[よ]みやすくなりました。", "sentence_source": "generated"}, {"text": "規則が新しくなったので、説明書の内容を書き替えます。", "target_word": "書き替えます", "complexity_tier": "T3", "furigana": "規則[きそく]が新[あたら]しくなったので、説明書[せつめいしょ]の内容[ないよう]を書[か]き替[か]えます。", "sentence_source": "generated"}, {"text": "間違いが多い記事を、正しい内容に書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "間違[まちが]いが多[おお]い記事[きじ]を、正[ただ]しい内容[ないよう]に書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "ホームページの案内を、新しい情報に書き替えてください。", "target_word": "書き替えて", "complexity_tier": "T3", "furigana": "ホームページの案内[あんない]を、新[あたら]しい情報[じょうほう]に書[か]き替[か]えてください。", "sentence_source": "generated"}, {"text": "彼は前の日記の終わりを、明るい内容に書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "彼[かれ]は前[まえ]の日記[にっき]の終[お]わりを、明[あか]るい内容[ないよう]に書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "契約の条件が変わり、書類の文を書き替えました。", "target_word": "書き替えました", "complexity_tier": "T3", "furigana": "契約[けいやく]の条件[じょうけん]が変[か]わり、書類[しょるい]の文[ぶん]を書[か]き替[か]えました。", "sentence_source": "generated"}, {"text": "古い説明を残さず、すべて新しい文に書き替えます。", "target_word": "書き替えます", "complexity_tier": "T3", "furigana": "古[ふる]い説明[せつめい]を残[のこ]さず、すべて新[あたら]しい文[ぶん]に書[か]き替[か]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書き替える", "label": "基本形"}, {"form": "書き替えます", "label": "丁寧形"}, {"form": "書き替えて", "label": "て形"}, {"form": "書き替えた", "label": "過去形"}, {"form": "書き替えない", "label": "否定形"}], "register": "丁寧", "sense_fingerprint": "前の文章や資料の内容を新しい内容に直して書く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52986, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書き替えました", "is_correct": true, "explanation": "「書き替える」の丁寧な過去形。古い資料の内容を新しい情報に替えて書いた、という文に合う。"}, {"text": "読みました", "is_correct": false, "explanation": "「読む」の丁寧な過去形。情報を読むことは内容を替える動作にならず、文の意味に合わない。"}, {"text": "削りました", "is_correct": false, "explanation": "「削る」の丁寧な過去形。資料を削ることは新しい情報を書く文に続かない。"}, {"text": "破りました", "is_correct": false, "explanation": "「破る」の丁寧な過去形。資料を破るのは新しい情報に替える動作ではないので、文が成り立たない。"}], "explanations": {"書き替えました": "「書き替える」の丁寧な過去形。古い資料の内容を新しい情報に替えて書いた、という文に合う。", "読みました": "「読む」の丁寧な過去形。情報を読むことは内容を替える動作にならず、文の意味に合わない。", "削りました": "「削る」の丁寧な過去形。資料を削ることは新しい情報を書く文に続かない。", "破りました": "「破る」の丁寧な過去形。資料を破るのは新しい情報に替える動作ではないので、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "書き替えました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前の文章の文字の色を、書き替えました。", "explanation": "ここは〈書式を変える〉の意味。文字の色は書いた内容ではないので、書き替えるは合わない。"}, {"text": "前の文章を一字も変えずに、ノートへ書き替えました。", "explanation": "ここは〈書き写す〉の意味。一字も変えないのに内容を替えたとは言えず、書き替えるは合わない。"}, {"text": "白紙の余白に、一文を書き替えました。", "explanation": "ここは〈書き込む〉の意味。白紙には替える前の内容がないので、書き替えるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52986, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書き替えて", "is_correct": true, "explanation": "「書き替える」のて形。ホームページの案内を新しい情報に替えて書いてほしい、という依頼文に合う。"}, {"text": "洗って", "is_correct": false, "explanation": "「洗う」のて形。情報に洗うという動作は成り立たず、依頼の意味に合わない。"}, {"text": "寝て", "is_correct": false, "explanation": "「寝る」のて形。情報に寝るという動作は文の意味に合わない。"}, {"text": "歩いて", "is_correct": false, "explanation": "「歩く」のて形。情報に対して歩くという動作は、依頼文の意味が通らない。"}], "explanations": {"書き替えて": "「書き替える」のて形。ホームページの案内を新しい情報に替えて書いてほしい、という依頼文に合う。", "洗って": "「洗う」のて形。情報に洗うという動作は成り立たず、依頼の意味に合わない。", "寝て": "「寝る」のて形。情報に寝るという動作は文の意味に合わない。", "歩いて": "「歩く」のて形。情報に対して歩くという動作は、依頼文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "書き替えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "名簿の住所を、台帳にそのまま書き替えました。", "explanation": "ここは〈転記する〉の意味。そのまま写すだけで内容は替えていないので、書き替えるは合わない。"}, {"text": "ノートに写真を書き替えました。", "explanation": "ここは〈貼る〉の意味。写真は字を書いたものではないので、書き替えるは使えない。"}, {"text": "ファイルを別のフォルダに書き替えました。", "explanation": "ここは〈移す〉の意味。場所を替えるだけで内容は変わらないので、書き替えるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52986, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前の文章が、新しい内容に書き替えました。", "corrected_sentence": "前の文章を、新しい内容に書き替えました。", "error_description": "「書き替える」は書き替える対象に「を」を付ける。「前の文章が」では文章が主語になり、対象を示せない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "書き替えます", "is_correct": true, "explanation": "丁寧な現在形。計画変更を受けて、これから報告書を書き直すという丁寧な文に合う。"}, {"text": "書き替え", "is_correct": false, "explanation": "連用形（ます形の語幹）。文末に置くと文が終わらないので使えない。"}, {"text": "書き替えれば", "is_correct": false, "explanation": "仮定形。「れば」の後に続く文がないので、ここで文を終えることはできない。"}, {"text": "書き替えて", "is_correct": false, "explanation": "て形。ここで文を終えることはできないので、文末の形として使えない。"}], "correct_form": "書き替えます", "base_form": "書き替える", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"書き替えます": "丁寧な現在形。計画変更を受けて、これから報告書を書き直すという丁寧な文に合う。", "書き替え": "連用形（ます形の語幹）。文末に置くと文が終わらないので使えない。", "書き替えれば": "仮定形。「れば」の後に続く文がないので、ここで文を終えることはできない。", "書き替えて": "て形。ここで文を終えることはできないので、文末の形として使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52986, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は昨日の日記の結末を、明るい内容に書き替えたました。", "corrected_sentence": "彼は昨日の日記の結末を、明るい内容に書き替えました。", "error_description": "「書き替えました」の「た」が余分。丁寧な過去は「書き替え」＋「ました」で、「書き替えたました」は誤った形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "書き替えさせ", "is_correct": false, "explanation": "使役の語幹で、文末に置くと文が終わらないので使えない。"}, {"text": "書き替えたり", "is_correct": false, "explanation": "並列を表す形で、後ろに別の動作が続かなければ文を終えられない。"}, {"text": "書き替えました", "is_correct": true, "explanation": "丁寧な過去形。前の日記の結末を明るい内容に書き替えた、という完了した出来事を丁寧に述べる文に合う。"}, {"text": "書き替えず", "is_correct": false, "explanation": "連用形の否定で、文末に置くと文が終わらないので使えない。"}], "correct_form": "書き替えました", "base_form": "書き替える", "form_label": "丁寧過去形", "sentence_index": 7, "explanations": {"書き替えさせ": "使役の語幹で、文末に置くと文が終わらないので使えない。", "書き替えたり": "並列を表す形で、後ろに別の動作が続かなければ文を終えられない。", "書き替えました": "丁寧な過去形。前の日記の結末を明るい内容に書き替えた、という完了した出来事を丁寧に述べる文に合う。", "書き替えず": "連用形の否定で、文末に置くと文が終わらないので使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
