INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52987, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "あたたかさ。心がほっとする感じ。", "primary_collocate": null, "pronunciation": "ぬくもり", "ipa": "nɯkɯmoɾi", "syllable_count": 4, "sentences": [{"text": "布団に入ると、ほんのりとした温もりに包まれた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "布団[ふとん]に入[はい]ると、ほんのりとした温[ぬく]もりに包[つつ]まれた。", "sentence_source": "generated"}, {"text": "母が作ったお粥の温もりで、体も心もほっとした。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "母[はは]が作[つく]ったお粥[かゆ]の温[ぬく]もりで、体[からだ]も心[こころ]もほっとした。", "sentence_source": "generated"}, {"text": "犬のそばに座ると、体の温もりが伝わってきた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "犬[いぬ]のそばに座[すわ]ると、体[からだ]の温[ぬく]もりが伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "朝、ベッドを出ても、まだ温もりが残っていた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "朝[あさ]、ベッドを出[で]ても、まだ温[ぬく]もりが残[のこ]っていた。", "sentence_source": "generated"}, {"text": "冬の夜、湯たんぽの温もりのおかげで、ぐっすり眠れた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜[よる]、湯[ゆ]たんぽの温[ぬく]もりのおかげで、ぐっすり眠[ねむ]れた。", "sentence_source": "generated"}, {"text": "友だちの「おかえり」という声に、家の温もりを感じた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "友[とも]だちの「おかえり」という声[こえ]に、家[いえ]の温[ぬく]もりを感[かん]じた。", "sentence_source": "generated"}, {"text": "彼の手は大きくて、握ると温もりが伝わった。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "彼[かれ]の手[て]は大[おお]きくて、握[にぎ]ると温[ぬく]もりが伝[つた]わった。", "sentence_source": "generated"}, {"text": "暖炉の火の温もりが、冷えた部屋をやわらかく包んだ。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "暖炉[だんろ]の火[ひ]の温[ぬく]もりが、冷[ひ]えた部屋[へや]をやわらかく包[つつ]んだ。", "sentence_source": "generated"}, {"text": "祖父の背中の温もりを、今でもよく覚えている。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "祖父[そふ]の背中[せなか]の温[ぬく]もりを、今[いま]でもよく覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "コーヒーカップを両手で持つと、温もりが指先に広がった。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "コーヒーカップを両手[りょうて]で持[も]つと、温[ぬく]もりが指先[ゆびさき]に広[ひろ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温もり", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "体や物から伝わる、ほっとするやわらかなあたたかさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52987, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温もり", "is_correct": true, "explanation": "あたたかさを表し、布団の中でほんのりとした感じに包まれるという文に合う。"}, {"text": "音", "is_correct": false, "explanation": "耳で聞くものであり、ほんのりとした感じに包まれるという文には合わない。"}, {"text": "速さ", "is_correct": false, "explanation": "物事の進む度合いを表し、布団に包まれる感じとは合わない。"}, {"text": "味", "is_correct": false, "explanation": "舌で感じるものであり、布団に包まれる感じとは合わない。"}], "explanations": {"温もり": "あたたかさを表し、布団の中でほんのりとした感じに包まれるという文に合う。", "音": "耳で聞くものであり、ほんのりとした感じに包まれるという文には合わない。", "速さ": "物事の進む度合いを表し、布団に包まれる感じとは合わない。", "味": "舌で感じるものであり、布団に包まれる感じとは合わない。"}, "sentence_index": 0, "correct_answer": "温もり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "口座の温もりはゼロだ。", "explanation": "ここは〈残高〉の意味。金額として数えられるものであり、温もりは数量では表せないので合わない。"}, {"text": "体重計で温もりを量ったら五十キロだった。", "explanation": "ここは〈体重〉の意味。重さとして量れるのは体重で、あたたかさの感じは量れないので合わない。"}, {"text": "駅までの温もりは二キロだ。", "explanation": "ここは〈距離〉の意味。道のりとして測れるのは距離で、温もりは距離を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52987, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温もり", "is_correct": true, "explanation": "彼の大きな手から伝わるあたたかさを表し、握ると伝わるという文に合う。"}, {"text": "色", "is_correct": false, "explanation": "目で見るものであり、握って伝わるものとしては文に合わない。"}, {"text": "速さ", "is_correct": false, "explanation": "物事の進む度合いを表し、握って伝わるという文には合わない。"}, {"text": "光", "is_correct": false, "explanation": "目で感じるものであり、手を握って伝わるという文には合わない。"}], "explanations": {"温もり": "彼の大きな手から伝わるあたたかさを表し、握ると伝わるという文に合う。", "色": "目で見るものであり、握って伝わるものとしては文に合わない。", "速さ": "物事の進む度合いを表し、握って伝わるという文には合わない。", "光": "目で感じるものであり、手を握って伝わるという文には合わない。"}, "sentence_index": 6, "correct_answer": "温もり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪をひいて、一晩中、温もりを出して寝込んだ。", "explanation": "ここは〈熱〉の意味。風邪で体から出るのは熱で、あたたかく優しい感じの温もりは出せないので合わない。"}, {"text": "この料理の温もりは塩辛い。", "explanation": "ここは〈味〉の意味。塩辛いのは料理の味で、あたたかく優しい感じを表す温もりには合わない。"}, {"text": "温もりが家族全員に背負わされた。", "explanation": "ここは〈借金〉の意味。背負わされるのは借金であり、温もりは背負うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52987, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜、ストーブの前で温もりに感じた。", "corrected_sentence": "寒い夜、ストーブの前で温もりを感じた。", "error_description": "「感じる」は感じる対象を「を」で示すため、「温もりに」は誤り。正しくは「温もりを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52987, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い夜、友だちの手の温もりを指先に伝わってきた。", "corrected_sentence": "寒い夜、友だちの手の温もりが指先に伝わってきた。", "error_description": "「伝わる」は主語を「が」で示すため、「温もりを」は誤り。正しくは「温もりが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
