INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52988, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物や人の持つ、あたたかくて優しい感じ。心が落ち着くような、親しみのあるぬくもり。", "primary_collocate": null, "pronunciation": "ぬくもり", "ipa": "nɯkɯmoɾi", "syllable_count": 4, "sentences": [{"text": "夕方の台所には、お母さんの料理の温もりが満ちていた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "夕[ゆう]方[がた]の台所[だいどころ]には、お母[かあ]さんの料理[りょうり]の温[ぬく]もりが満[み]ちていた。", "sentence_source": "generated"}, {"text": "手編みのマフラーには、買ったものにはない温もりがある。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "手編[てあ]みのマフラーには、買[か]ったものにはない温[ぬく]もりがある。", "sentence_source": "generated"}, {"text": "祖母の手を握ると、優しい温もりが伝わってきた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "祖母[そぼ]の手[て]を握[にぎ]ると、優[やさ]しい温[ぬく]もりが伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "木の机に触れると、やわらかな温もりを感じる。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "木[き]の机[つくえ]に触[ふ]れると、やわらかな温[ぬく]もりを感[かん]じる。", "sentence_source": "generated"}, {"text": "この店は古い家具が多く、どこか温もりのある雰囲気だ。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "この店[みせ]は古[ふる]い家具[かぐ]が多[おお]く、どこか温[ぬく]もりのある雰囲気[ふんいき]だ。", "sentence_source": "generated"}, {"text": "手紙の文字から、書いた人の温もりが伝わってくる。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "手紙[てがみ]の文字[もじ]から、書[か]いた人[ひと]の温[ぬく]もりが伝[つた]わってくる。", "sentence_source": "generated"}, {"text": "冷たい雨の日に、母のスープの温もりが心にしみた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "冷[つめ]たい雨[あめ]の日[ひ]に、母[はは]のスープの温[ぬく]もりが心[こころ]にしみた。", "sentence_source": "generated"}, {"text": "機械で作った箱より、職人が削った箱のほうが温もりを感じる。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "機械[きかい]で作[つく]った箱[はこ]より、職人[しょくにん]が削[けず]った箱[はこ]のほうが温[ぬく]もりを感[かん]じる。", "sentence_source": "generated"}, {"text": "小さな子犬を抱いていると、その温もりに心が落ち着いた。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "小[ちい]さな子犬[こいぬ]を抱[だ]いていると、その温[ぬく]もりに心[こころ]が落[お]ち着[つ]いた。", "sentence_source": "generated"}, {"text": "古い木の家には、住む人を包むような温もりがある。", "target_word": "温もり", "complexity_tier": "T3", "furigana": "古[ふる]い木[き]の家[いえ]には、住[す]む人[ひと]を包[つつ]むような温[ぬく]もりがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温もり", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物や人から感じる、優しく親しみのあるあたたかさ(心理的な温かみ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52988, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温もり", "is_correct": true, "explanation": "あたたかく優しい感じを表し、夕方の台所に料理の温もりが満ちているという文に合う。"}, {"text": "速さ", "is_correct": false, "explanation": "物事の進む度合いを表し、温かみと対比される感じにならないので文に合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "物の固さを表し、料理の温もりが満ちるという文には合わない。"}, {"text": "鋭さ", "is_correct": false, "explanation": "鋭い感覚や性質を表し、温もりが満ちるという文には合わない。"}], "explanations": {"温もり": "あたたかく優しい感じを表し、夕方の台所に料理の温もりが満ちているという文に合う。", "速さ": "物事の進む度合いを表し、温かみと対比される感じにならないので文に合わない。", "硬さ": "物の固さを表し、料理の温もりが満ちるという文には合わない。", "鋭さ": "鋭い感覚や性質を表し、温もりが満ちるという文には合わない。"}, "sentence_index": 0, "correct_answer": "温もり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋の温もりは二十二度だ。", "explanation": "ここは〈温度〉の意味。温もりは数値で測れる温度ではなく、心に伝わる感じなので合わない。"}, {"text": "やかんの口から温もりが立ち上がった。", "explanation": "ここは〈湯気〉の意味。湯気のように立ち上る様子を表す言葉ではないので合わない。"}, {"text": "冬の朝は温もりが厳しい。", "explanation": "ここは〈寒さ〉の意味。厳しさを表せるのは寒さで、やさしい感じの温もりには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52988, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温もり", "is_correct": true, "explanation": "冷たい雨の日にスープから伝わる、心にしみるあたたかさを表し文に合う。"}, {"text": "重さ", "is_correct": false, "explanation": "重さを表す名詞で、心にしみるあたたかさの感じとは合わない。"}, {"text": "明るさ", "is_correct": false, "explanation": "光の強さを表し、スープの感じとしては文に合わない。"}, {"text": "長さ", "is_correct": false, "explanation": "長さを表す名詞で、スープの感じが心にしみる文には合わない。"}], "explanations": {"温もり": "冷たい雨の日にスープから伝わる、心にしみるあたたかさを表し文に合う。", "重さ": "重さを表す名詞で、心にしみるあたたかさの感じとは合わない。", "明るさ": "光の強さを表し、スープの感じとしては文に合わない。", "長さ": "長さを表す名詞で、スープの感じが心にしみる文には合わない。"}, "sentence_index": 6, "correct_answer": "温もり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドアノブの温もりは銀色だ。", "explanation": "ここは〈色〉の意味。銀色は見た目の色で、あたたかく優しい感じの温もりとは違うので合わない。"}, {"text": "外は温もりが降っている。", "explanation": "ここは〈雨〉の意味。降るものは雨で、温もりは降るものではないので合わない。"}, {"text": "布の温もりがざらざらしている。", "explanation": "ここは〈手触り〉の意味。ざらざらした感触を表すのは手触りで、温もりでは表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52988, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い町並みに、どこか懐かしい温もりに感じた。", "corrected_sentence": "古い町並みに、どこか懐かしい温もりを感じた。", "error_description": "「感じる」は感じる対象を「を」で示すため、「温もりに」は誤り。正しくは「温もりを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52988, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝、祖母の温もりを包まれて眠った。", "corrected_sentence": "寒い朝、祖母の温もりに包まれて眠った。", "error_description": "「包まれる」は包むものを「に」で示すため、「温もりを」は誤り。正しくは「温もりに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52989, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "デジタル", "is_correct": true, "explanation": "〈アナログ〉の対義語。機械や電子で処理する方式を指す"}, {"text": "食卓", "is_correct": false, "explanation": "家具や場所を表す名詞で、方式の対義語ではない"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電を表す名詞で、アナログの対義語にはならない"}, {"text": "雑誌", "is_correct": false, "explanation": "印刷物を表す名詞で、方式・性質の対義語ではない"}], "correct_answer": "デジタル", "explanations": {"デジタル": "〈アナログ〉の対義語。機械や電子で処理する方式を指す", "食卓": "家具や場所を表す名詞で、方式の対義語ではない", "冷蔵庫": "家電を表す名詞で、アナログの対義語にはならない", "雑誌": "印刷物を表す名詞で、方式・性質の対義語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
