INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52989, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "コンピューターや機械を使わない、手で触ったり感じたりできるやり方のことです。", "primary_collocate": null, "pronunciation": "あなろぐ", "ipa": "anaɾoɡɯ", "syllable_count": 4, "sentences": [{"text": "パソコンが壊れたので、今日はアナログで紙に書いて計画を立てた。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "パソコンが壊[こわ]れたので、今日[きょう]はアナログで紙[かみ]に書[か]いて計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "手で触って確かめるアナログなやり方のほうが、安心できる。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "手[て]で触[さわ]って確[たし]かめるアナログなやり方[かた]のほうが、安心[あんしん]できる。", "sentence_source": "generated"}, {"text": "母は電子辞書を使わず、アナログなやり方で辞書を引いている。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "母[はは]は電子辞書[でんしじしょ]を使[つか]わず、アナログなやり方[やりかた]で辞書[じしょ]を引[ひ]いている。", "sentence_source": "generated"}, {"text": "停電のとき、アナログなやり方で家族と連絡を取り合った。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "停電[ていでん]のとき、アナログなやり方[やりかた]で家族[かぞく]と連絡[れんらく]を取[と]り合[あ]った。", "sentence_source": "generated"}, {"text": "うちの祖父はアナログ派で、電卓よりそろばんを使う。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "うちの祖父[そふ]はアナログ派[は]で、電卓[でんたく]よりそろばんを使[つか]う。", "sentence_source": "generated"}, {"text": "機械が止まったので、みんなでアナログのやり方に戻して作業した。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "機械[きかい]が止[と]まったので、みんなでアナログのやり方[かた]に戻[もど]して作業[さぎょう]した。", "sentence_source": "generated"}, {"text": "ゲーム機がなかったので、子どものころはアナログな遊びばかりしていた。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "ゲーム機[き]がなかったので、子[こ]どものころはアナログな遊[あそ]びばかりしていた。", "sentence_source": "generated"}, {"text": "地図アプリより、アナログな地図のほうが全体が見やすい。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "地図[ちず]アプリより、アナログな地図[ちず]のほうが全体[ぜんたい]が見[み]やすい。", "sentence_source": "generated"}, {"text": "先生は黒板にチョークで書く、アナログな授業をしている。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]にチョークで書[か]く、アナログな授業[じゅぎょう]をしている。", "sentence_source": "generated"}, {"text": "彼女はスマホを使わず、アナログな日記帳に毎晩書いている。", "target_word": "アナログ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はスマホを使[つか]わず、アナログな日記帳[にっきちょう]に毎晩[まいばん]書[か]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アナログ", "label": "基本形"}, {"form": "アナログな", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "パソコンや機械に頼らず、手や紙など実物で行うやり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52989, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アナログ", "is_correct": true, "explanation": "「今日はアナログで紙に書いて」は、パソコンに頼らない方法を表すので文脈に合う"}, {"text": "夜景", "is_correct": false, "explanation": "「夜景で紙に書いて」は手段として成り立たず、この空欄には入らない"}, {"text": "吹雪", "is_correct": false, "explanation": "「吹雪で紙に書いて」は不自然で、計画を立てる手段にならない"}, {"text": "紙幣", "is_correct": false, "explanation": "「紙幣で紙に書いて」は文として意味をなさない"}], "explanations": {"アナログ": "「今日はアナログで紙に書いて」は、パソコンに頼らない方法を表すので文脈に合う", "夜景": "「夜景で紙に書いて」は手段として成り立たず、この空欄には入らない", "吹雪": "「吹雪で紙に書いて」は不自然で、計画を立てる手段にならない", "紙幣": "「紙幣で紙に書いて」は文として意味をなさない"}, "sentence_index": 0, "correct_answer": "アナログ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の主張はアナログで、規則を一切認めない。", "explanation": "ここは〈アナーキー（無秩序）〉の意味。アナログは方式を指すので、主張の性質には使えない"}, {"text": "このアナログは電池で動くので、外でも使える。", "explanation": "ここは〈機器〉の意味。アナログは方式で、電池で動く道具そのものを指さない"}, {"text": "データをパソコンで保存する、アナログなやり方だ。", "explanation": "ここは〈デジタル〉の意味。パソコンで保存するのは電子的な処理で、紙や手作業を表すアナログとは逆"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52989, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アナログ", "is_correct": true, "explanation": "「子どものころはアナログな遊び」は、ゲーム機に頼らない遊びを表すので文脈に合う"}, {"text": "天候", "is_correct": false, "explanation": "「天候な遊び」は成り立たず、ゲーム機がない時代の遊びの意味にならない"}, {"text": "機関", "is_correct": false, "explanation": "「機関な遊び」は不自然で、遊びの性質を表さない"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気な遊び」は文として意味をなさず、この空欄には入らない"}], "explanations": {"アナログ": "「子どものころはアナログな遊び」は、ゲーム機に頼らない遊びを表すので文脈に合う", "天候": "「天候な遊び」は成り立たず、ゲーム機がない時代の遊びの意味にならない", "機関": "「機関な遊び」は不自然で、遊びの性質を表さない", "湿気": "「湿気な遊び」は文として意味をなさず、この空欄には入らない"}, "sentence_index": 6, "correct_answer": "アナログ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この遊びは単語の文字を並べ替えるアナログだ。", "explanation": "ここは〈アナグラム〉の意味。アナログは方式を指し、文字を並べ替える言葉遊びの名称ではない"}, {"text": "木のアナログがあって、家が落ち着く。", "explanation": "ここは〈ぬくもり〉の意味。アナログは方式の性質で、家の中に存在する物質的なものを指さない"}, {"text": "このお店は値段がアナログで、いつも大人気だ。", "explanation": "ここは〈格安〉の意味。アナログは方式で、値段の安さを表す語ではない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52989, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電池が切れたので、アナログを紙に書いて記録した。", "corrected_sentence": "電池が切れたので、アナログで紙に書いて記録した。", "error_description": "「で」は手段を表す。「を」は目的語を示すので、「書く」の対象ではないアナログに付けるのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52989, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は電卓を使わず、アナログい方法で家計を計算する。", "corrected_sentence": "祖母は電卓を使わず、アナログな方法で家計を計算する。", "error_description": "「アナログ」の連体修飾は「な」を使う。「い」は形容詞の語尾で、ここでは誤った語形になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52991, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈逆説を口にして〉の「を」は「口にする」の目的語で、文の意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "〈逆説に口にして〉は成り立たず、「口にする」は目的語に「を」を取る。"}, {"text": "より", "is_correct": false, "explanation": "〈逆説より口にして〉は比較の形になり、「口にする」の目的語として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "〈逆説が口にして〉は主格になり、「口にする」の目的語として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "〈逆説を口にして〉の「を」は「口にする」の目的語で、文の意味に合う。", "に": "〈逆説に口にして〉は成り立たず、「口にする」は目的語に「を」を取る。", "より": "〈逆説より口にして〉は比較の形になり、「口にする」の目的語として成り立たない。", "が": "〈逆説が口にして〉は主格になり、「口にする」の目的語として成り立たない。"}, "error_tags": {"に": "位格の誤り", "が": "主格の誤り", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52991, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "〈逆説は、〉の「は」は主題を示し、後の「残りやすい」の主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "〈逆説へ、〉は方向を示し、「残りやすい」の主語として不自然。"}, {"text": "を", "is_correct": false, "explanation": "〈逆説を、…残りやすい〉は「残る」が目的語を取らないため、「を」は文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "〈逆説の、〉は連体修飾となり、文の主題にならない。"}], "correct_answer": "は", "explanations": {"は": "〈逆説は、〉の「は」は主題を示し、後の「残りやすい」の主語になる。", "へ": "〈逆説へ、〉は方向を示し、「残りやすい」の主語として不自然。", "を": "〈逆説を、…残りやすい〉は「残る」が目的語を取らないため、「を」は文に合わない。", "の": "〈逆説の、〉は連体修飾となり、文の主題にならない。"}, "error_tags": {"へ": "方向の誤り", "の": "連体修飾の誤り", "を": "目的格の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52991, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「逆説」は、ふつうと反対のことを言うことです。", "primary_collocate": null, "pronunciation": "ぎゃくせつ", "ipa": "ɡʲakɯsetsɯ", "syllable_count": 4, "sentences": [{"text": "「負けるが勝ち」は、よく知られた逆説だ。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "「負[ま]けるが勝[か]ち」は、よく知[し]られた逆説[ぎゃくせつ]だ。", "sentence_source": "generated"}, {"text": "彼はいつも逆説を口にして、みんなを笑わせる。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "彼[かれ]はいつも逆説[ぎゃくせつ]を口[くち]にして、みんなを笑[わら]わせる。", "sentence_source": "generated"}, {"text": "「急がば回れ」は、逆説のようで実は正しい教えだ。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "「急[いそ]がば回[まわ]れ」は、逆説[ぎゃくせつ]のようで実[じつ]は正[ただ]しい教[おし]えだ。", "sentence_source": "generated"}, {"text": "先生は逆説を使って、生徒に考えさせた。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "先生[せんせい]は逆説[ぎゃくせつ]を使[つか]って、生徒[せいと]に考[かんが]えさせた。", "sentence_source": "generated"}, {"text": "逆説に聞こえるかもしれないが、少し休んだほうが仕事は早く終わる。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "逆説[ぎゃくせつ]に聞[き]こえるかもしれないが、少[すこ]し休[やす]んだほうが仕事[しごと]は早[はや]く終[お]わる。", "sentence_source": "generated"}, {"text": "この本には、おもしろい逆説がたくさん出てくる。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "この本[ほん]には、おもしろい逆説[ぎゃくせつ]がたくさん出[で]てくる。", "sentence_source": "generated"}, {"text": "「安いものは高い」という逆説を、父はよく話していた。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "「安[やす]いものは高[たか]い」という逆説[ぎゃくせつ]を、父[ちち]はよく話[はな]していた。", "sentence_source": "generated"}, {"text": "逆説は、ふつうの考えと反対だから、人の印象に残りやすい。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "逆説[ぎゃくせつ]は、ふつうの考[かんが]えと反対[はんたい]だから、人[ひと]の印象[いんしょう]に残[のこ]りやすい。", "sentence_source": "generated"}, {"text": "兄は逆説が好きで、わざと反対のことを言う。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "兄[あに]は逆説[ぎゃくせつ]が好[す]きで、わざと反対[はんたい]のことを言[い]う。", "sentence_source": "generated"}, {"text": "逆説のおもしろさは、聞いたあとでなるほどと思えるところにある。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "逆説[ぎゃくせつ]のおもしろさは、聞[き]いたあとでなるほどと思[おも]えるところにある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "逆説", "label": "基本形"}, {"form": "逆説的", "label": "派生形（的）"}], "register": "中立・日常的な文体（常体）", "sense_fingerprint": "逆説=ふつうの考えと反対のことを言うこと、またその言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52991, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逆説", "is_correct": true, "explanation": "〈よく知られた逆説〉は、ふつうと反対のことを言う主張を指し、「負けるが勝ち」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "〈よく知られた天気〉は意味をなさず、言葉の型を指さない。"}, {"text": "距離", "is_correct": false, "explanation": "〈よく知られた距離〉は成り立たず、説明している言い回しとは無関係。"}, {"text": "面積", "is_correct": false, "explanation": "〈よく知られた面積〉は意味をなさず、言葉の性質を表さない。"}], "explanations": {"逆説": "〈よく知られた逆説〉は、ふつうと反対のことを言う主張を指し、「負けるが勝ち」に合う。", "天気": "〈よく知られた天気〉は意味をなさず、言葉の型を指さない。", "距離": "〈よく知られた距離〉は成り立たず、説明している言い回しとは無関係。", "面積": "〈よく知られた面積〉は意味をなさず、言葉の性質を表さない。"}, "sentence_index": 0, "correct_answer": "逆説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その計算式は逆説で、答えが必ず一つに決まる。", "explanation": "ここは〈数学の公式〉の意味。逆説はふつうと反対のことを言う言葉なので、数式には使わない。"}, {"text": "ふつうの考えと同じことを言うのを、逆説と呼ぶ。", "explanation": "〈常識どおりの発言〉の意味。逆説はふつうと反対のことを言うことが定義なので合わない。"}, {"text": "チームは後半に逆説を果たして、試合をひっくり返した。", "explanation": "ここは〈逆転〉の意味。逆説は言葉の主張を指し、試合の展開には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52991, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逆説", "is_correct": true, "explanation": "〈という逆説〉はふつうと反対のことを言う主張を指し、父が話していた内容に合う。"}, {"text": "体重", "is_correct": false, "explanation": "〈という体重〉は言葉の型を指さず、「安いものは高い」の話とは結びつかない。"}, {"text": "季節", "is_correct": false, "explanation": "〈という季節〉は主張を指さず、話題として成り立たない。"}, {"text": "予算", "is_correct": false, "explanation": "〈という予算〉は意味をなさず、「安いものは高い」という内容とは無関係。"}], "explanations": {"逆説": "〈という逆説〉はふつうと反対のことを言う主張を指し、父が話していた内容に合う。", "体重": "〈という体重〉は言葉の型を指さず、「安いものは高い」の話とは結びつかない。", "季節": "〈という季節〉は主張を指さず、話題として成り立たない。", "予算": "〈という予算〉は意味をなさず、「安いものは高い」という内容とは無関係。"}, "sentence_index": 6, "correct_answer": "逆説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は逆説を売っていて、毎朝たくさんの客が買いに来る。", "explanation": "ここは〈商品〉の意味。逆説は言葉の主張を指し、売買の対象にはならない。"}, {"text": "ロケットは噴射の逆説で飛ぶ。", "explanation": "ここは〈反作用〉の意味。逆説はふつうと反対の言い方を指し、物理の力には使わない。"}, {"text": "彼は会議の議題を逆説に決め、すぐに全員で採用した。", "explanation": "ここは〈政策案〉の意味。逆説は言葉の主張を指し、議論の対象となる案には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52991, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は、ふつうの考えと反対の逆説によく口にする。", "corrected_sentence": "彼女は、ふつうの考えと反対の逆説をよく口にする。", "error_description": "〈口にする〉の目的語は「を」で示す。「逆説に」とすると、動詞との関係が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52991, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その学者は逆説に述べて、人々の常識を静かに揺さぶった。", "corrected_sentence": "その学者は逆説を述べて、人々の常識を静かに揺さぶった。", "error_description": "〈逆説を述べる〉の「を」が正しい。「に」にすると、目的語を示す「述べる」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52992, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "〈逆説のようだ〉の「の」は、比喩の「ようだ」に続く連体修飾として必要。"}, {"text": "を", "is_correct": false, "explanation": "〈逆説をようだ〉は成り立たず、目的語の「を」は「ようだ」の前に来ない。"}, {"text": "に", "is_correct": false, "explanation": "〈逆説にようだ〉は続かず、位置の「に」は文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "〈逆説でようだ〉は手段を示す形になり、「ようだ」と続かない。"}], "correct_answer": "の", "explanations": {"の": "〈逆説のようだ〉の「の」は、比喩の「ようだ」に続く連体修飾として必要。", "を": "〈逆説をようだ〉は成り立たず、目的語の「を」は「ようだ」の前に来ない。", "に": "〈逆説にようだ〉は続かず、位置の「に」は文脈に合わない。", "で": "〈逆説でようだ〉は手段を示す形になり、「ようだ」と続かない。"}, "error_tags": {"を": "目的格の誤り", "に": "位格の誤り", "で": "手段の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52992, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈逆説に、私は〉の「に」は「考えさせられた」の対象を示し、文の流れに合う。"}, {"text": "が", "is_correct": false, "explanation": "〈逆説が、私は〉は主語が二つ並ぶ形になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "〈逆説の、私は〉では逆説が連体修飾になり、後の文と繋がらない。"}, {"text": "へ", "is_correct": false, "explanation": "〈考えさせられる〉の対象は「に」で示す。「へ」は方向を表すので合わない。"}], "correct_answer": "に", "explanations": {"に": "〈逆説に、私は〉の「に」は「考えさせられた」の対象を示し、文の流れに合う。", "が": "〈逆説が、私は〉は主語が二つ並ぶ形になり、文が成り立たない。", "の": "〈逆説の、私は〉では逆説が連体修飾になり、後の文と繋がらない。", "へ": "〈考えさせられる〉の対象は「に」で示す。「へ」は方向を表すので合わない。"}, "error_tags": {"が": "主格の誤り", "の": "連体修飾の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52992, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「逆説」とは、一見矛盾しているように思えるが、実は深い真理を含んでいる主張や状況を指します。", "primary_collocate": null, "pronunciation": "ぎゃくせつ", "ipa": "ɡʲakɯsetsɯ", "syllable_count": 4, "sentences": [{"text": "オートクチュールの希少性は、一見すると逆説だが、マス市場におけるトレンドの源泉として機能している。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "オートクチュールの希少性[きしょうせい]は、一見[いっけん]すると逆説[ぎゃくせつ]だが、マス市場[しじょう]におけるトレンドの源泉[げんせん]として機能[きのう]している。", "sentence_source": "generated"}, {"text": "「急がば回れ」は、一見すると逆説のようだが、実際には確かな経験に基づいている。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "「急[いそ]がば回[まわ]れ」は、一見[いっけん]すると逆説[ぎゃくせつ]のようだが、実際[じっさい]には確[たし]かな経験[けいけん]に基[もと]づいている。", "sentence_source": "generated"}, {"text": "「負けるが勝ち」という逆説には、争わないことで得をする知恵が込められている。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "「負[ま]けるが勝[か]ち」という逆説[ぎゃくせつ]には、争[あらそ]わないことで得[とく]をする知恵[ちえ]が込[こ]められている。", "sentence_source": "generated"}, {"text": "彼の「知れば知るほど無知を自覚する」という逆説は、学問の本質を突いている。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "彼[かれ]の「知[し]れば知[し]るほど無知[むち]を自覚[じかく]する」という逆説[ぎゃくせつ]は、学問[がくもん]の本質[ほんしつ]を突[つ]いている。", "sentence_source": "generated"}, {"text": "逆説に聞こえるかもしれないが、適度に休むことが仕事の効率を高めるという研究もある。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "逆説[ぎゃくせつ]に聞[き]こえるかもしれないが、適度[てきど]に休[やす]むことが仕事[しごと]の効率[こうりつ]を高[たか]めるという研究[けんきゅう]もある。", "sentence_source": "generated"}, {"text": "この小説は、貧しさの中でこそ人は豊かになれるという逆説を描いている。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、貧[まず]しさの中[なか]でこそ人[ひと]は豊[ゆた]かになれるという逆説[ぎゃくせつ]を描[えが]いている。", "sentence_source": "generated"}, {"text": "講師は「自由には制約が必要だ」という逆説を、具体例を挙げて説明した。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "講師[こうし]は「自由[じゆう]には制約[せいやく]が必要[ひつよう]だ」という逆説[ぎゃくせつ]を、具体例[ぐたいれい]を挙[あ]げて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "「強い者ほど弱さを見せられる」という逆説に、私は深く考えさせられた。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "「強[つよ]い者[もの]ほど弱[よわ]さを見[み]せられる」という逆説[ぎゃくせつ]に、私[わたし]は深[ふか]く考[かんが]えさせられた。", "sentence_source": "generated"}, {"text": "逆説は矛盾した言葉に見えて、よく考えると真理を含んでいることが多い。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "逆説[ぎゃくせつ]は矛盾[むじゅん]した言葉[ことば]に見[み]えて、よく考[かんが]えると真理[しんり]を含[ふく]んでいることが多[おお]い。", "sentence_source": "generated"}, {"text": "その詩人は、逆説を巧みに使って人間の孤独を表現した。", "target_word": "逆説", "complexity_tier": "T3", "furigana": "その詩人[しじん]は、逆説[ぎゃくせつ]を巧[たく]みに使[つか]って人間[にんげん]の孤独[こどく]を表現[ひょうげん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "逆説", "label": "基本形"}, {"form": "逆説的", "label": "派生形（的）"}], "register": "書き言葉・硬い文体（常体）", "sense_fingerprint": "逆説=一見矛盾するが深い真理を含む主張や状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52992, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逆説", "is_correct": true, "explanation": "〈一見すると逆説だ〉は、一見矛盾するが真理を含む主張を指し、この文の内容に合う。"}, {"text": "天気", "is_correct": false, "explanation": "〈一見すると天気だ〉は意味をなさず、希少性の話とも結びつかない。"}, {"text": "体重", "is_correct": false, "explanation": "〈一見すると体重だ〉は成り立たず、主張の性質を表さない。"}, {"text": "面積", "is_correct": false, "explanation": "〈一見すると面積だ〉は言葉の性質を表さず、この文に合わない。"}], "explanations": {"逆説": "〈一見すると逆説だ〉は、一見矛盾するが真理を含む主張を指し、この文の内容に合う。", "天気": "〈一見すると天気だ〉は意味をなさず、希少性の話とも結びつかない。", "体重": "〈一見すると体重だ〉は成り立たず、主張の性質を表さない。", "面積": "〈一見すると面積だ〉は言葉の性質を表さず、この文に合わない。"}, "sentence_index": 0, "correct_answer": "逆説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水は高い所から低い所へ流れるという事実も、逆説として教科書に載っている。", "explanation": "ここは〈自明な理〉の意味。逆説は一見矛盾する主張を指すので、当たり前の理には使わない。"}, {"text": "彼の答えは単なる計算ミスだったが、それを逆説と呼んで周りを驚かせた。", "explanation": "ここは〈失敗の指摘〉の意味。逆説は深い真理を含む主張なので、計算ミスには合わない。"}, {"text": "矛盾のない答えを逆説と呼ぶのは、この言葉の本来の使い方だ。", "explanation": "ここは〈筋の通った答え〉の意味。逆説は一見食い違う主張を指すので、筋の通った答えには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52992, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逆説", "is_correct": true, "explanation": "〈という逆説〉は一見矛盾する主張を指す名詞で、具体例を挙げて説明する対象として合う。"}, {"text": "体重", "is_correct": false, "explanation": "〈という体重〉は主張を指さず、説明の対象にならない。"}, {"text": "距離", "is_correct": false, "explanation": "〈という距離〉は意味をなさず、「自由には制約が必要だ」という内容と結びつかない。"}, {"text": "季節", "is_correct": false, "explanation": "〈という季節〉は主張を指さず、「必要だ」という命題の説明には合わない。"}], "explanations": {"逆説": "〈という逆説〉は一見矛盾する主張を指す名詞で、具体例を挙げて説明する対象として合う。", "体重": "〈という体重〉は主張を指さず、説明の対象にならない。", "距離": "〈という距離〉は意味をなさず、「自由には制約が必要だ」という内容と結びつかない。", "季節": "〈という季節〉は主張を指さず、「必要だ」という命題の説明には合わない。"}, "sentence_index": 6, "correct_answer": "逆説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の褒め言葉は逆説に満ちていて、本当は怒っていた。", "explanation": "ここは〈皮肉〉の意味。相手を嘲る言い方であり、深い真理を含む主張の意味には合わない。"}, {"text": "文の語順を逆にした逆説を、そのまま試験に出した。", "explanation": "ここは〈倒置〉の意味。逆説は言葉の並びではなく主張の性質なので、語順には合わない。"}, {"text": "会議で新しい提案をしたところ、その逆説が採用された。", "explanation": "ここは〈方針〉の意味。逆説は主張の性質を指し、取り上げられる方策には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52992, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はその主張を逆説に紹介した。", "corrected_sentence": "彼はその主張を逆説として紹介した。", "error_description": "〈AをBとして紹介する〉が正しい。「に」では役割が示せず、「紹介する」と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52992, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その学者は、逆説が用いて常識を問い直した。", "corrected_sentence": "その学者は、逆説を用いて常識を問い直した。", "error_description": "〈用いる〉は目的語に「を」を取る。「逆説が」とすると、主語が二つになり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52993, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開放", "is_correct": true, "explanation": "〈排他〉の対義語で、人を中に入れる態度を表す。"}, {"text": "誠実", "is_correct": false, "explanation": "真心の性質を表し、入れない態度とは対になっていない。"}, {"text": "従順", "is_correct": false, "explanation": "言うことを聞く性質で、閉じた態度の反対語ではない。"}, {"text": "忍耐", "is_correct": false, "explanation": "我慢する力を表し、入会の可否を表す語の反対概念ではない。"}], "correct_answer": "開放", "explanations": {"開放": "〈排他〉の対義語で、人を中に入れる態度を表す。", "誠実": "真心の性質を表し、入れない態度とは対になっていない。", "従順": "言うことを聞く性質で、閉じた態度の反対語ではない。", "忍耐": "我慢する力を表し、入会の可否を表す語の反対概念ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52993, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開放", "is_correct": true, "explanation": "〈排他〉の対義語で、人を中に入れる態度を表す。"}, {"text": "節約", "is_correct": false, "explanation": "お金や物を無駄にしない行為で、入れない態度とは対立しない。"}, {"text": "規律", "is_correct": false, "explanation": "決まりを守る秩序を指し、排他の反対概念ではない。"}, {"text": "勤勉", "is_correct": false, "explanation": "まじめに働く性質で、排他の対義語にはならない。"}], "correct_answer": "開放", "explanations": {"開放": "〈排他〉の対義語で、人を中に入れる態度を表す。", "節約": "お金や物を無駄にしない行為で、入れない態度とは対立しない。", "規律": "決まりを守る秩序を指し、排他の反対概念ではない。", "勤勉": "まじめに働く性質で、排他の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52993, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "他の人を中に入れないこと。", "primary_collocate": null, "pronunciation": "はいた", "ipa": "haita", "syllable_count": 3, "sentences": [{"text": "この店は会員だけを入れる排他を貫いていて、初めての客は入れない。", "target_word": "排他", "complexity_tier": "T3", "furigana": "この店は会員だけを入れる排他[はいた]を貫いていて、初めての客は入れない。", "sentence_source": "generated"}, {"text": "排他が強い店では、一見の客は入りにくい。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]が強い店では、一見の客は入りにくい。", "sentence_source": "generated"}, {"text": "その集まりは排他に傾いていて、友人の紹介がなければ参加できない。", "target_word": "排他", "complexity_tier": "T3", "furigana": "その集まりは排他[はいた]に傾いていて、友人の紹介がなければ参加できない。", "sentence_source": "generated"}, {"text": "彼女は排他に徹して、新入りを輪に入れようとしなかった。", "target_word": "排他", "complexity_tier": "T3", "furigana": "彼女は排他[はいた]に徹して、新入りを輪に入れようとしなかった。", "sentence_source": "generated"}, {"text": "排他が強い部活は、新入部員が増えにくい。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]が強い部活は、新入部員が増えにくい。", "sentence_source": "generated"}, {"text": "町内会の排他が、引っ越してきた家族を戸惑わせた。", "target_word": "排他", "complexity_tier": "T3", "furigana": "町内会の排他[はいた]が、引っ越してきた家族を戸惑わせた。", "sentence_source": "generated"}, {"text": "排他をやめて、誰でも入れる場所にしよう。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]をやめて、誰[だれ]でも入[はい]れる場所[ばしょ]にしよう。", "sentence_source": "generated"}, {"text": "排他を捨てたら、クラブに新しい人が集まるようになった。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]を捨てたら、クラブに新しい人が集まるようになった。", "sentence_source": "generated"}, {"text": "古い商店街には排他が残っていたが、今は観光客も歓迎している。", "target_word": "排他", "complexity_tier": "T3", "furigana": "古い商店街には排他[はいた]が残っていたが、今は観光客も歓迎している。", "sentence_source": "generated"}, {"text": "内輪だけで固まって排他に走ると、組織は閉じたものになってしまう。", "target_word": "排他", "complexity_tier": "T3", "furigana": "内輪だけで固まって排他[はいた]に走ると、組織は閉じたものになってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排他", "label": "基本形"}, {"form": "排他的", "label": "派生形（的）"}, {"form": "排他性", "label": "派生形（性）"}], "register": "中立・日常的な文体（常体）", "sense_fingerprint": "排他=仲間以外の人を集まりや場所に入れないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52993, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排他", "is_correct": true, "explanation": "〈排他を貫く〉は、仲間以外を入れない態度を続ける意味で文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "〈天気を貫く〉は成り立たず、会員制の店の話とも無関係。"}, {"text": "距離", "is_correct": false, "explanation": "〈距離を貫く〉は意味をなさず、入店を断る方針を表さない。"}, {"text": "面積", "is_correct": false, "explanation": "〈面積を貫く〉は言わず、店の方針を述べる文に合わない。"}], "explanations": {"排他": "〈排他を貫く〉は、仲間以外を入れない態度を続ける意味で文脈に合う。", "天気": "〈天気を貫く〉は成り立たず、会員制の店の話とも無関係。", "距離": "〈距離を貫く〉は意味をなさず、入店を断る方針を表さない。", "面積": "〈面積を貫く〉は言わず、店の方針を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "排他"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨天の排他で、運動会は来週に延期になった。", "explanation": "ここは〈天候〉の原因の意味。排他は人の集まりが他者を入れない性質で、天候には使わない。"}, {"text": "この機械は部品の排他を自動で行うので、作業が速い。", "explanation": "ここは〈排除〉の意味。排他は人を入れない性質で、部品の取り除きには使わない。"}, {"text": "工場の煙は、排他されて空に広がった。", "explanation": "ここは〈排出〉の意味。排他は人を入れない態度で、煙を外へ出す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52993, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排他", "is_correct": true, "explanation": "〈排他をやめて〉は、仲間以外を入れない態度を改める意味で、文脈に合う。"}, {"text": "体重", "is_correct": false, "explanation": "〈体重をやめて〉は言わず、態度の話題に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "〈季節をやめて〉は意味をなさず、入れる場所の話と結びつかない。"}, {"text": "予算", "is_correct": false, "explanation": "〈予算をやめて〉は不自然で、誰でも入れる場所を作る文脈に合わない。"}], "explanations": {"排他": "〈排他をやめて〉は、仲間以外を入れない態度を改める意味で、文脈に合う。", "体重": "〈体重をやめて〉は言わず、態度の話題に合わない。", "季節": "〈季節をやめて〉は意味をなさず、入れる場所の話と結びつかない。", "予算": "〈予算をやめて〉は不自然で、誰でも入れる場所を作る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "排他"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新薬は細菌の排他に効果がある。", "explanation": "ここは〈殺菌〉の意味。排他は人の集まりの性質で、細菌には使わない。"}, {"text": "学校の排他の日は、生徒が自由に遊べる日だ。", "explanation": "ここは〈記念日〉の意味。排他は態度を表す語で、日付の名称にはならない。"}, {"text": "この製品の排他は、長く使うほど性能が上がる仕組みだ。", "explanation": "ここは〈機能〉の意味。排他は人を入れない態度で、物の働きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
