INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52994, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "自分以外のものを排除しようとする性質や態度。", "primary_collocate": null, "pronunciation": "はいた", "ipa": "haita", "syllable_count": 3, "sentences": [{"text": "この高級ブランドは、排他を強めることで、かえって大衆の憧れを集めている。", "target_word": "排他", "complexity_tier": "T3", "furigana": "この高級[こうきゅう]ブランドは、排他[はいた]を強[つよ]めることで、かえって大衆[たいしゅう]の憧[あこが]れを集[あつ]めている。", "sentence_source": "generated"}, {"text": "排他へと傾く組織では、新しい意見が育ちにくい。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]へと傾く組織では、新しい意見が育ちにくい。", "sentence_source": "generated"}, {"text": "異なる文化を拒み、排他に徹する国は孤立しやすい。", "target_word": "排他", "complexity_tier": "T3", "furigana": "異なる文化を拒み、排他[はいた]に徹する国は孤立しやすい。", "sentence_source": "generated"}, {"text": "彼のグループは排他が強く、外部の人間は意見を言えなかった。", "target_word": "排他", "complexity_tier": "T3", "furigana": "彼のグループは排他[はいた]が強く、外部の人間は意見を言えなかった。", "sentence_source": "generated"}, {"text": "排他へ傾く政治家が、不安を抱く人々の支持を集めた。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]へ傾く政治家が、不安を抱く人々の支持を集めた。", "sentence_source": "generated"}, {"text": "村の排他は、外から来た人に冷たく当たる形で表れていた。", "target_word": "排他", "complexity_tier": "T3", "furigana": "村の排他[はいた]は、外から来た人に冷たく当たる形で表れていた。", "sentence_source": "generated"}, {"text": "排他を広める発言は、社会の分断を深めてしまう。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]を広める発言は、社会の分断を深めてしまう。", "sentence_source": "generated"}, {"text": "排他ではなく対話を選ぶことが、問題解決の第一歩となる。", "target_word": "排他", "complexity_tier": "T3", "furigana": "排他[はいた]ではなく対話[たいわ]を選[えら]ぶことが、問題[もんだい]解決[かいけつ]の第一歩[だいいっぽ]となる。", "sentence_source": "generated"}, {"text": "長年続いた排他が、若い世代の移住によって少しずつ変わった。", "target_word": "排他", "complexity_tier": "T3", "furigana": "長年続いた排他[はいた]が、若い世代の移住によって少しずつ変わった。", "sentence_source": "generated"}, {"text": "自国の利益だけを優先し、排他に走る考え方は、国際協力を妨げる。", "target_word": "排他", "complexity_tier": "T3", "furigana": "自国の利益だけを優先し、排他[はいた]に走る考え方は、国際協力を妨げる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排他", "label": "基本形"}, {"form": "排他的", "label": "派生形（的）"}, {"form": "排他性", "label": "派生形（性）"}], "register": "書き言葉・硬い文体（常体）", "sense_fingerprint": "排他=自分や自分たち以外のものを退けようとする性質・態度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52994, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排他", "is_correct": true, "explanation": "〈排他を強める〉は、自分以外を退ける態度を募らせる意味で、この文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "〈天気を強める〉は成り立たず、ブランドの話とも無関係。"}, {"text": "距離", "is_correct": false, "explanation": "〈距離を強める〉は意味をなさず、態度を表さない。"}, {"text": "面積", "is_correct": false, "explanation": "〈面積を強める〉は言わず、この文の内容に合わない。"}], "explanations": {"排他": "〈排他を強める〉は、自分以外を退ける態度を募らせる意味で、この文に合う。", "天気": "〈天気を強める〉は成り立たず、ブランドの話とも無関係。", "距離": "〈距離を強める〉は意味をなさず、態度を表さない。", "面積": "〈面積を強める〉は言わず、この文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "排他"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場では、不良品の排他を徹底して出荷を止めた。", "explanation": "ここは〈排除〉の意味。排他は人の集まりが他者を締め出す性質で、物の除去には使わない。"}, {"text": "台風の影響で、港は一時的に排他された。", "explanation": "ここは〈閉鎖〉の意味。排他は人を締め出す態度や性質で、施設を閉じる意味では使わない。"}, {"text": "この地域には、協力し合う排他が根づいている。", "explanation": "ここは〈助け合い〉の意味。排他は仲間以外を退ける性質なので、助け合いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52994, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排他", "is_correct": true, "explanation": "〈排他を広める〉は、自分以外を退ける態度を広げる意味で成り立つ。"}, {"text": "体重", "is_correct": false, "explanation": "〈体重を広める〉は成り立たず、発言の対象にならない。"}, {"text": "季節", "is_correct": false, "explanation": "〈季節を広める〉は言わず、態度を指す語として合わない。"}, {"text": "予算", "is_correct": false, "explanation": "〈予算を広める〉は意味をなさず、社会の分断という内容と結びつかない。"}], "explanations": {"排他": "〈排他を広める〉は、自分以外を退ける態度を広げる意味で成り立つ。", "体重": "〈体重を広める〉は成り立たず、発言の対象にならない。", "季節": "〈季節を広める〉は言わず、態度を指す語として合わない。", "予算": "〈予算を広める〉は意味をなさず、社会の分断という内容と結びつかない。"}, "sentence_index": 6, "correct_answer": "排他"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この橋は歩行者用の排他として設計され、自由に渡れる。", "explanation": "ここは〈通行区分〉の意味。排他は人を締め出す態度で、道の区分には使わない。"}, {"text": "試合の排他で、チームは一点差の勝利を収めた。", "explanation": "ここは〈競技の流れ〉の意味。排他は態度や性質を指し、競技の流れには使わない。"}, {"text": "両社は値段を排他し、長い時間をかけて合意にこぎつけた。", "explanation": "ここは〈交渉〉の意味。排他は人を締め出す態度で、話を進める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52994, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "そのクラブは排他を強く、新しい会員が入りにくい。", "corrected_sentence": "そのクラブは排他が強く、新しい会員が入りにくい。", "error_description": "〈排他が強い〉の「が」が正しい。「を」にすると、形容詞「強い」の主語が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52994, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その団体は排他に強めて、外部の意見を退けた。", "corrected_sentence": "その団体は排他を強めて、外部の意見を退けた。", "error_description": "〈排他を強める〉の「を」が正しい。「に」にすると、「強める」の目的語が示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
