INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52995, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても少なくて、めったにないこと。", "primary_collocate": null, "pronunciation": "きしょう", "ipa": "kiɕoː", "syllable_count": 3, "sentences": [{"text": "このカードは世界に数十枚しかなく、とても希少だ。", "target_word": "希少", "complexity_tier": "T3", "furigana": "このカードは世界に数十枚しかなく、とても{希少|きしょう}だ。", "sentence_source": "generated"}, {"text": "希少な切手を見つけて、兄は大喜びした。", "target_word": "希少", "complexity_tier": "T3", "furigana": "希少[きしょう]な切手[きって]を見[み]つけて、兄[あに]は大喜[おおよろこ]びした。", "sentence_source": "generated"}, {"text": "祖父は希少な本を大切に棚にしまっている。", "target_word": "希少", "complexity_tier": "T3", "furigana": "祖父[そふ]は希少[きしょう]な本[ほん]を大切[たいせつ]に棚[たな]にしまっている。", "sentence_source": "generated"}, {"text": "昔の写真は残っていないので、とても希少だ。", "target_word": "希少", "complexity_tier": "T3", "furigana": "昔[むかし]の写真[しゃしん]は残[のこ]っていないので、とても希少[きしょう]だ。", "sentence_source": "generated"}, {"text": "希少な魚だから、値段が高いのは当然だ。", "target_word": "希少", "complexity_tier": "T3", "furigana": "希少[きしょう]な魚[さかな]だから、値段[ねだん]が高[たか]いのは当然[とうぜん]だ。", "sentence_source": "generated"}, {"text": "動物園で、希少な鳥を見ることができた。", "target_word": "希少", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]で、希少[きしょう]な鳥[とり]を見[み]ることができた。", "sentence_source": "generated"}, {"text": "この色のペンは希少で、どの店にも置いていない。", "target_word": "希少", "complexity_tier": "T3", "furigana": "この色[いろ]のペンは希少[きしょう]で、どの店[みせ]にも置[お]いていない。", "sentence_source": "generated"}, {"text": "希少な石を拾って、先生に見せた。", "target_word": "希少", "complexity_tier": "T3", "furigana": "希少[きしょう]な石[いし]を拾[ひろ]って、先生[せんせい]に見[み]せた。", "sentence_source": "generated"}, {"text": "数が少ないからこそ、希少な品は人気がある。", "target_word": "希少", "complexity_tier": "T3", "furigana": "数[かず]が少[すく]ないからこそ、希少[きしょう]な品[しな]は人気[にんき]がある。", "sentence_source": "generated"}, {"text": "希少な花が咲いたと聞いて、山へ見に行った。", "target_word": "希少", "complexity_tier": "T3", "furigana": "希少[きしょう]な花[はな]が咲[さ]いたと聞[き]いて、山[やま]へ見[み]に行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "希少", "label": "基本形"}, {"form": "希少な", "label": "連体形"}, {"form": "希少だ", "label": "終止形"}, {"form": "希少で", "label": "連用形"}], "register": "中立・日常的な文体（常体）", "sense_fingerprint": "希少=とても少なくてなかなか手に入らない・見られないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52995, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "希少", "is_correct": true, "explanation": "「数十枚しかなく」という前半に合い、めったにない意味で文がつながる。"}, {"text": "豊富", "is_correct": false, "explanation": "たくさんあるという意味で、「数十枚しかなく」と矛盾する。"}, {"text": "無数", "is_correct": false, "explanation": "数えきれないほど多い意味で、「数十枚しかなく」と正面から矛盾する。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫さを表す語で、カードの数の少なさを述べる文脈には合わない。"}], "explanations": {"希少": "「数十枚しかなく」という前半に合い、めったにない意味で文がつながる。", "豊富": "たくさんあるという意味で、「数十枚しかなく」と矛盾する。", "無数": "数えきれないほど多い意味で、「数十枚しかなく」と正面から矛盾する。", "頑丈": "丈夫さを表す語で、カードの数の少なさを述べる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "希少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先輩は希少に助言をくれるので、いつも頼りにしている。", "explanation": "希少は〈しばしば〉の意味を持たず、副詞の「希少に」は使えない。助言の回数を言う文脈では不自然で、数がめったにないという意味の形状詞。"}, {"text": "最近は、家族で食卓を囲む機会が希少に増えてきた。", "explanation": "希少は〈頻繁〉の意味を持たない。機会が増える様子には使えず、数がめったにないという意味に限られる。"}, {"text": "今月の売上の差は希少で、ほとんど変わらない。", "explanation": "ここは〈僅少〉の意味。わずかな差を表す僅少と混同している。希少は数がめったにないことを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52995, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "希少", "is_correct": true, "explanation": "数が少なく、どの店にも置いていないという内容に自然につながる。"}, {"text": "陽気", "is_correct": false, "explanation": "明るい性格を表す語で、ペンの話には合わない。"}, {"text": "不器用", "is_correct": false, "explanation": "手先が器用でない意味で、物の性質には使わない。"}, {"text": "豪快", "is_correct": false, "explanation": "大胆で勢いのあるさまを表す語で、ペンには使わない。置いていない理由にもならない。"}], "explanations": {"希少": "数が少なく、どの店にも置いていないという内容に自然につながる。", "陽気": "明るい性格を表す語で、ペンの話には合わない。", "不器用": "手先が器用でない意味で、物の性質には使わない。", "豪快": "大胆で勢いのあるさまを表す語で、ペンには使わない。置いていない理由にもならない。"}, "sentence_index": 6, "correct_answer": "希少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "希少なルールを守って、毎日練習を続けた。", "explanation": "希少は〈厳格〉の意味を持たない。ルールの厳しさを表す文脈では使えず、数が少ないという意味に限られる。"}, {"text": "大事な約束を、希少に忘れてしまった。", "explanation": "希少は〈すっかり〉の意味を持たない。忘れる程度を言う副詞としては使えない。"}, {"text": "希少な心配りで説明して、客は納得して帰った。", "explanation": "希少は〈丁寧〉の意味を持たない。説明の手間のかけ方を言う文脈では使えず、数の少なさを表す語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52995, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "希少の絵画を見つけて、祖母は大喜びした。", "corrected_sentence": "希少な絵画を見つけて、祖母は大喜びした。", "error_description": "「希少」は形状詞なので、名詞を修飾するときは「な」を付ける。「の」は誤りで、正しくは「希少な」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "希少", "is_correct": true, "explanation": "基本形。文中の「希少な」はこの形から連体形に活用したもの。"}, {"text": "希少だ", "is_correct": false, "explanation": "終止形。文を言い切る形で、名詞「切手」の前には入らない。"}, {"text": "希少で", "is_correct": false, "explanation": "連用形。後ろに続けて文をつなぐ形で、「切手」を直接修飾しない。"}, {"text": "希少性", "is_correct": false, "explanation": "「性」を付けた派生の名詞。「切手」を修飾する形ではなく、別の語になる。"}], "correct_form": "希少", "base_form": "希少", "form_label": "基本形", "sentence_index": 1, "explanations": {"希少": "基本形。文中の「希少な」はこの形から連体形に活用したもの。", "希少だ": "終止形。文を言い切る形で、名詞「切手」の前には入らない。", "希少で": "連用形。後ろに続けて文をつなぐ形で、「切手」を直接修飾しない。", "希少性": "「性」を付けた派生の名詞。「切手」を修飾する形ではなく、別の語になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52995, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この紙は希少くて、どの店にも置いていない。", "corrected_sentence": "この紙は希少で、どの店にも置いていない。", "error_description": "「希少」は形状詞なので、後ろに続けるときは「で」にする。形容詞の活用の「くて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "希少", "is_correct": true, "explanation": "基本形。文中の「希少な」はこの形から連体形に活用したもの。"}, {"text": "希少に", "is_correct": false, "explanation": "連用形。「に」で状態を表す形で、名詞「石」を修飾する位置には入らない。"}, {"text": "希少さ", "is_correct": false, "explanation": "「さ」を付けた派生の名詞。「石」を修飾する形ではなく、別の語になる。"}, {"text": "希少である", "is_correct": false, "explanation": "「である」を付けた断定の形。名詞「石」の前に置くと文の形が崩れる。"}], "correct_form": "希少", "base_form": "希少", "form_label": "基本形", "sentence_index": 7, "explanations": {"希少": "基本形。文中の「希少な」はこの形から連体形に活用したもの。", "希少に": "連用形。「に」で状態を表す形で、名詞「石」を修飾する位置には入らない。", "希少さ": "「さ」を付けた派生の名詞。「石」を修飾する形ではなく、別の語になる。", "希少である": "「である」を付けた断定の形。名詞「石」の前に置くと文の形が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
