INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52997, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人に向けた、大きな市場のこと。", "primary_collocate": null, "pronunciation": "ます", "ipa": "masɯ", "syllable_count": 2, "sentences": [{"text": "新しい飲料は、マス市場を狙って全国で売り出された。", "target_word": "マス", "complexity_tier": "T3", "furigana": "新[あたら]しい飲料[いんりょう]は、マス市場[しじょう]を狙[ねら]って全国[ぜんこく]で売[う]り出[だ]された。", "sentence_source": "generated"}, {"text": "小さな店は、マスではなく、少数の客を大事にしている。", "target_word": "マス", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]は、マスではなく、少数[しょうすう]の客[きゃく]を大事[だいじ]にしている。", "sentence_source": "generated"}, {"text": "マス市場では、安くて分かりやすい商品が売れやすい。", "target_word": "マス", "complexity_tier": "T3", "furigana": "マス市場[しじょう]では、安[やす]くて分[わ]かりやすい商品[しょうひん]が売[う]れやすい。", "sentence_source": "generated"}, {"text": "その会社は、マス市場に向けてテレビ広告を大量に流している。", "target_word": "マス", "complexity_tier": "T3", "furigana": "その会社は、{マス|ます}市場に向けてテレビ広告を大量に流している。", "sentence_source": "generated"}, {"text": "マス市場に出すには、たくさんの商品を作らなければならない。", "target_word": "マス", "complexity_tier": "T3", "furigana": "マス市場[しじょう]に出[だ]すには、たくさんの商品[しょうひん]を作[つく]らなければならない。", "sentence_source": "generated"}, {"text": "彼はマス市場より、専門家向けの市場で成功した。", "target_word": "マス", "complexity_tier": "T3", "furigana": "彼[かれ]はマス市場[しじょう]より、専門家向[せんもんかむ]けの市場[しじょう]で成功[せいこう]した。", "sentence_source": "generated"}, {"text": "スマホは、いまやマス市場の商品になった。", "target_word": "マス", "complexity_tier": "T3", "furigana": "スマホは、いまやマス市場[しじょう]の商品[しょうひん]になった。", "sentence_source": "generated"}, {"text": "この雑誌は、マスではなく趣味の人に向けて作られている。", "target_word": "マス", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は、マスではなく趣味[しゅみ]の人[ひと]に向[む]けて作[つく]られている。", "sentence_source": "generated"}, {"text": "マス市場は大きいが、競争も激しい。", "target_word": "マス", "complexity_tier": "T3", "furigana": "マス市場[しじょう]は大[おお]きいが、競争[きょうそう]も激[はげ]しい。", "sentence_source": "generated"}, {"text": "電気自動車がマス市場に広がるには、値段が下がる必要がある。", "target_word": "マス", "complexity_tier": "T3", "furigana": "電気自動車[でんきじどうしゃ]がマス市場[しじょう]に広[ひろ]がるには、値段[ねだん]が下[さ]がる必要[ひつよう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "多数の人を対象とする大きな市場・客層", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52997, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マス", "is_correct": true, "explanation": "大きな市場や客層を指し、「マス市場を狙って全国で売り出された」として自然。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを表す語で、「感情市場」とは言わない。飲料の売り出しにも合わない。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "日暮れ時を指す語で、市場には使えない。"}, {"text": "挨拶", "is_correct": false, "explanation": "礼儀として交わす言葉の意味で、市場を狙う文脈とは合わない。"}], "explanations": {"マス": "大きな市場や客層を指し、「マス市場を狙って全国で売り出された」として自然。", "感情": "心の動きを表す語で、「感情市場」とは言わない。飲料の売り出しにも合わない。", "夕暮れ": "日暮れ時を指す語で、市場には使えない。", "挨拶": "礼儀として交わす言葉の意味で、市場を狙う文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "マス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔の農家は、米をマスの数で数えて納めた。", "explanation": "ここは〈升（ます）〉の意味。計量単位の升は同形の別語で、市場を指すマスではない。"}, {"text": "マスの人が会場に集まり、列は外まで続いた。", "explanation": "ここは〈大勢〉の意味。マスは人数の多さではなく市場や客層を指す名詞なので、人数を言う文脈には合わない。"}, {"text": "政府はマスの時期を決めて調査を行い、結果を公表した。", "explanation": "ここは〈時期〉の意味。マスは市場や客層を指す語で、調査の時期を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52997, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マス", "is_correct": true, "explanation": "「マス市場の商品」として、多くの人向けの大きな市場を指し自然に成り立つ。"}, {"text": "空気", "is_correct": false, "explanation": "場の雰囲気を表す語で、「空気市場」は文が意味をなさない。"}, {"text": "理論", "is_correct": false, "explanation": "考えの体系を表す語で、「理論市場の商品」とは言わない。"}, {"text": "大砲", "is_correct": false, "explanation": "大きな火器を指す語で、スマホの話には合わない。"}], "explanations": {"マス": "「マス市場の商品」として、多くの人向けの大きな市場を指し自然に成り立つ。", "空気": "場の雰囲気を表す語で、「空気市場」は文が意味をなさない。", "理論": "考えの体系を表す語で、「理論市場の商品」とは言わない。", "大砲": "大きな火器を指す語で、スマホの話には合わない。"}, "sentence_index": 6, "correct_answer": "マス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この制度はマスな支持を集めている。", "explanation": "ここは〈広範〉の意味。支持が広い範囲に及ぶことを表す語で、市場や客層を指すマスは形容詞的には使えない。"}, {"text": "店舗をマスに広げて、同じ商品を全国で売った。", "explanation": "ここは〈チェーン展開〉の意味。店舗網の広がりを言う文脈で、マスは客層を指す語なので「マスに広げる」とは言わない。"}, {"text": "湖でマスを釣って、夕食に出した。", "explanation": "ここは〈魚のマス（鱒）〉の意味。市場を指すマスとは別の名詞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52997, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この商品はマスの売れないので、少数の店だけで扱う。", "corrected_sentence": "この商品はマスでは売れないので、少数の店だけで扱う。", "error_description": "「マスでは売れない」の「では」を「の」に変えると、マスを修飾する形になって文が成り立たない。「マスの売れない」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52997, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マスで訴える広告を、テレビで流す。", "corrected_sentence": "マスに訴える広告を、テレビで流す。", "error_description": "「訴える」の相手は「に」で示す。「マスで訴える」は「で」で手段を表すことになり、マスを道具のように扱う誤った文になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
