INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52998, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "大衆向けの市場や商品のこと。特に、高級品ではなく、多くの人が買えるように作られたものを指す。", "primary_collocate": null, "pronunciation": "ます", "ipa": "masɯ", "syllable_count": 2, "sentences": [{"text": "オートクチュールの持つ絶対的な希少性と排他性は、逆説的にマス市場におけるトレンドの源泉として機能している。", "target_word": "マス", "complexity_tier": "T4", "furigana": "オートクチュールの持[も]つ絶対的[ぜったいてき]な希少性[きしょうせい]と排他性[はいたせい]は、逆説的[ぎゃくせつてき]にマス市場[しじょう]におけるトレンドの源泉[げんせん]として機能[きのう]している。", "sentence_source": "mined"}, {"text": "この会社は高級路線をやめて、マス向けの商品に力を入れ始めた。", "target_word": "マス", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は高級路線[こうきゅうろせん]をやめて、マス向[む]けの商品[しょうひん]に力[ちから]を入[い]れ始[はじ]めた。", "sentence_source": "generated"}, {"text": "マス商品は大量に作るので、一つあたりの値段を安くできる。", "target_word": "マス", "complexity_tier": "T3", "furigana": "マス商品[しょうひん]は大量[たいりょう]に作[つく]るので、一[ひと]つあたりの値段[ねだん]を安[やす]くできる。", "sentence_source": "generated"}, {"text": "高級ブランドのバッグより、マス向けのバッグのほうが街でよく見かける。", "target_word": "マス", "complexity_tier": "T3", "furigana": "高級[こうきゅう]ブランドのバッグより、マス向[む]けのバッグのほうが街[まち]でよく見[み]かける。", "sentence_source": "generated"}, {"text": "彼女は高級店ではなく、マス向けの店で服を買うことが多い。", "target_word": "マス", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は高級店[こうきゅうてん]ではなく、マス向[む]けの店[みせ]で服[ふく]を買[か]うことが多[おお]い。", "sentence_source": "generated"}, {"text": "マス向けの製品は、だれでも買える値段でなければ売れない。", "target_word": "マス", "complexity_tier": "T3", "furigana": "{マス|ます}向けの製品は、だれでも買える値段でなければ売れない。", "sentence_source": "generated"}, {"text": "その店は高級品とマス商品の両方を並べている。", "target_word": "マス", "complexity_tier": "T3", "furigana": "その店[みせ]は高級品[こうきゅうひん]とマス商品[しょうひん]の両方[りょうほう]を並[なら]べている。", "sentence_source": "generated"}, {"text": "新しい靴は、マス向けに作られたので、手頃な価格だ。", "target_word": "マス", "complexity_tier": "T3", "furigana": "新[あたら]しい靴[くつ]は、マス向[む]けに作[つく]られたので、手頃[てごろ]な価格[かかく]だ。", "sentence_source": "generated"}, {"text": "マス向けの商品は、品質より値段が重視されることが多い。", "target_word": "マス", "complexity_tier": "T3", "furigana": "マス向[む]けの商品[しょうひん]は、品質[ひんしつ]より値段[ねだん]が重視[じゅうし]されることが多[おお]い。", "sentence_source": "generated"}, {"text": "あのブランドは人気が出たあと、マス向けの安い服も売り出した。", "target_word": "マス", "complexity_tier": "T3", "furigana": "あのブランドは人気[にんき]が出[で]たあと、マス向[む]けの安[やす]い服[ふく]も売[う]り出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "大衆向けの安価な商品・市場(高級品の反対)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: オートクチュール (Zipf 2.47)']::text[], '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52998, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マス", "is_correct": true, "explanation": "大衆向けの市場を指し、「逆説的にマス市場におけるトレンド」という文として自然。"}, {"text": "理論", "is_correct": false, "explanation": "考えの体系を指す語で、「理論市場」は成り立たず文が意味をなさない。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを指す語で、「感情市場」とは言わない。"}, {"text": "空気", "is_correct": false, "explanation": "場の雰囲気を指す語で、「空気市場」は文脈に合わない。"}], "explanations": {"マス": "大衆向けの市場を指し、「逆説的にマス市場におけるトレンド」という文として自然。", "理論": "考えの体系を指す語で、「理論市場」は成り立たず文が意味をなさない。", "感情": "心の動きを指す語で、「感情市場」とは言わない。", "空気": "場の雰囲気を指す語で、「空気市場」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "マス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で、マスの意見が一つにまとまった。", "explanation": "ここは〈全員〉の意味。マスは市場や客層を指す名詞で、意見をまとめる人数や一致を言う文脈には使えない。"}, {"text": "同じ部品を、マスとして一つずつ作っている。", "explanation": "ここは〈丁寧に〉の意味。マスは市場を指す名詞で、一つずつ手をかける様子は表せない。"}, {"text": "川で釣ったマスを、家族で塩焼きにして食べた。", "explanation": "ここは〈魚のマス（鱒）〉の意味。大衆向けの市場とは別の名詞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52998, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マス", "is_correct": true, "explanation": "大衆向けの商品を指し、「高級品とマス商品の両方」と対になって自然。"}, {"text": "挨拶", "is_correct": false, "explanation": "礼儀として交わす言葉の意味で、「挨拶商品」とは言わない。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "日暮れ時を指す語で、商品の種類には使えない。"}, {"text": "大砲", "is_correct": false, "explanation": "大きな火器を指す語で、「大砲商品」は文脈に合わない。"}], "explanations": {"マス": "大衆向けの商品を指し、「高級品とマス商品の両方」と対になって自然。", "挨拶": "礼儀として交わす言葉の意味で、「挨拶商品」とは言わない。", "夕暮れ": "日暮れ時を指す語で、商品の種類には使えない。", "大砲": "大きな火器を指す語で、「大砲商品」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "マス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その作家は、作品をマスに書き直して出版した。", "explanation": "ここは〈全面的に〉の意味。マスは市場を指す名詞で、書き直す程度を表す副詞としては使えない。"}, {"text": "店はマスな値段で靴を売った。", "explanation": "ここは〈手頃〉の意味。マスは大衆向けの市場を指す名詞で、値段の安さを表す形容詞のように「な」で修飾することはできない。"}, {"text": "彼は服をマスで仕立て、一着ずつ丁寧に縫った。", "explanation": "ここは〈一点もの〉の意味。マスは市場を指す語で、仕立ての手段や方法を表す言い方としては不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52998, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は高級路線を捨て、マス向ける安い商品を売り出した。", "corrected_sentence": "この会社は高級路線を捨て、マス向けの安い商品を売り出した。", "error_description": "「マス向け」は名詞を修飾する形なので「向けの」と続ける。「向ける」は動詞で、「マス向ける」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52998, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マス向けを安い服は、どこの店でも手に入る。", "corrected_sentence": "マス向けの安い服は、どこの店でも手に入る。", "error_description": "「マス向け」は名詞を修飾する形なので、後ろに「の」を付ける。「を」を付けると修飾の形にならず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52999, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『あのメゾン』の服として、所属を示す。"}, {"text": "を", "is_correct": false, "explanation": "『を』では『メゾン』が目的語になり、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や相手を示し、名詞を結ぶ用法がないため不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は、名詞を結ぶ用法がなく不自然。"}], "correct_answer": "の", "explanations": {"の": "『あのメゾン』の服として、所属を示す。", "を": "『を』では『メゾン』が目的語になり、文が崩れる。", "に": "『に』は位置や相手を示し、名詞を結ぶ用法がないため不自然。", "へ": "方向を示す『へ』は、名詞を結ぶ用法がなく不自然。"}, "error_tags": {"を": "対象", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52999, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『あのメゾン』と『財布』をつなぎ、所属を示す。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示すが、財布の所属は表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は、名詞を結ぶ用法がなく不自然。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すが、財布の所属は示せない。"}], "correct_answer": "の", "explanations": {"の": "『あのメゾン』と『財布』をつなぎ、所属を示す。", "で": "『で』は場所や手段を示すが、財布の所属は表せない。", "へ": "方向を示す『へ』は、名詞を結ぶ用法がなく不自然。", "から": "『から』は起点を示すが、財布の所属は示せない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52999, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おしゃれな服やかばんをつくる、とても有名な会社。", "primary_collocate": null, "pronunciation": "めぞん", "ipa": "mezoɴ", "syllable_count": 3, "sentences": [{"text": "あのメゾンのかばんは、とても高いけれど人気がある。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "あのメゾンのかばんは、とても高[たか]いけれど人気[にんき]がある。", "sentence_source": "generated"}, {"text": "姉は有名なメゾンの服が好きで、毎年一着だけ買う。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "姉[あね]は有名[ゆうめい]なメゾンの服[ふく]が好[す]きで、毎年一着[まいとしいっちゃく]だけ買[か]う。", "sentence_source": "generated"}, {"text": "このメゾンは、フランスで生まれた古い会社だ。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "このメゾンは、フランスで生[う]まれた古[ふる]い会社[かいしゃ]だ。", "sentence_source": "generated"}, {"text": "大きなメゾンの店は、駅の近くのビルにある。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "大[おお]きなメゾンの店[みせ]は、駅[えき]の近[ちか]くのビルにある。", "sentence_source": "generated"}, {"text": "そのメゾンは、毎年春に新しい服を発表する。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "そのメゾンは、毎年春[まいとしはる]に新[あたら]しい服[ふく]を発表[はっぴょう]する。", "sentence_source": "generated"}, {"text": "有名なメゾンで働くのが、彼の夢だった。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "有名[ゆうめい]なメゾンで働[はたら]くのが、彼[かれ]の夢[ゆめ]だった。", "sentence_source": "generated"}, {"text": "このメゾンのかばんは、一つ作るのに何日もかかる。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "このメゾンのかばんは、一[ひと]つ作[つく]るのに何日[なんにち]もかかる。", "sentence_source": "generated"}, {"text": "母は、あのメゾンの財布をずっと大切に使っている。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "母[はは]は、あのメゾンの財布[さいふ]をずっと大切[たいせつ]に使[つか]っている。", "sentence_source": "generated"}, {"text": "世界的に有名なメゾンが、日本の布を使った服を作った。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "世界的[せかいてき]に有名[ゆうめい]なメゾンが、日本[にほん]の布[ぬの]を使[つか]った服[ふく]を作[つく]った。", "sentence_source": "generated"}, {"text": "あのメゾンの名前は、おしゃれな人ならだれでも知っている。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "あのメゾンの名前[なまえ]は、おしゃれな人[ひと]ならだれでも知[し]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メゾン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "服やかばんを作る有名な高級ブランド会社", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52999, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メゾン", "is_correct": true, "explanation": "服やかばんを作る有名な会社を指し、文脈に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "『砂糖のかばん』は不自然で、かばんを作る会社を表せない。"}, {"text": "雨", "is_correct": false, "explanation": "『雨のかばん』は意味が通らず、会社を表せない。"}, {"text": "駅", "is_correct": false, "explanation": "『駅のかばん』は不自然で、かばんを作る会社を表せない。"}], "explanations": {"メゾン": "服やかばんを作る有名な会社を指し、文脈に合う。", "砂糖": "『砂糖のかばん』は不自然で、かばんを作る会社を表せない。", "雨": "『雨のかばん』は意味が通らず、会社を表せない。", "駅": "『駅のかばん』は不自然で、かばんを作る会社を表せない。"}, "sentence_index": 0, "correct_answer": "メゾン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はメゾンを深くかぶって出かけた。", "explanation": "ここは〈帽子〉の意味。〈メゾン〉は服やかばんの会社なので、頭にかぶるものには使わない。"}, {"text": "夏の果物で、メゾンを切って皆で食べた。", "explanation": "ここは〈メロン〉の意味。〈メゾン〉は会社を指すので、果物には使えない。"}, {"text": "彼は囲碁の名人で、メゾンと呼ばれている。", "explanation": "ここは〈名人〉の意味。〈メゾン〉は会社なので、人を指すのには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52999, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メゾン", "is_correct": true, "explanation": "かばんを作る有名な会社を指し、文脈に合う。"}, {"text": "花火", "is_correct": false, "explanation": "『花火のかばん』は不自然で、かばんを作る会社を表せない。"}, {"text": "布団", "is_correct": false, "explanation": "『布団のかばん』は意味が通らず、会社を表せない。"}, {"text": "天井", "is_correct": false, "explanation": "『天井のかばん』は不自然で、会社を表せない。"}], "explanations": {"メゾン": "かばんを作る有名な会社を指し、文脈に合う。", "花火": "『花火のかばん』は不自然で、かばんを作る会社を表せない。", "布団": "『布団のかばん』は意味が通らず、会社を表せない。", "天井": "『天井のかばん』は不自然で、会社を表せない。"}, "sentence_index": 6, "correct_answer": "メゾン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このメゾンが割れてしまった。", "explanation": "ここは〈窓ガラス〉の意味。〈メゾン〉は会社を指すので、割れるガラスの名前には使わない。"}, {"text": "このメゾンは、よく削れて書きやすい。", "explanation": "ここは〈鉛筆〉の意味。〈メゾン〉は会社を指し、削ったり書いたりする道具には使えない。"}, {"text": "風邪のとき、メゾンを三回飲んだ。", "explanation": "ここは〈薬〉の意味。〈メゾン〉は服やかばんの会社なので、飲む薬の名前にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52999, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この有名なメゾンをかばんを買った。", "corrected_sentence": "この有名なメゾンでかばんを買った。", "error_description": "『買う』の場所は『で』で示す。『を』は目的語を示すもので、ここでは誤り。正しくは『で』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52999, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このメゾンにかばんは、一つ一つ職人が手で縫い上げる。", "corrected_sentence": "このメゾンのかばんは、一つ一つ職人が手で縫い上げる。", "error_description": "『メゾンのかばん』は所属を示す『の』が正しい。『に』だと『メゾンにかばん』となり、関係が成り立たず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53000, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "メゾンを文の主題として示す助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は、ここでは『始まった』と結びつかず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す『より』は、ここでは文の主題を示せない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すが、ここでは主題を示せず不自然。"}], "correct_answer": "は", "explanations": {"は": "メゾンを文の主題として示す助詞。", "へ": "方向を示す『へ』は、ここでは『始まった』と結びつかず不自然。", "より": "比較を示す『より』は、ここでは文の主題を示せない。", "と": "『と』は並列や相手を示すが、ここでは主題を示せず不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53000, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "メゾンを主語として示し、『発表した』と結びつける助詞。"}, {"text": "を", "is_correct": false, "explanation": "『メゾンを』では主語が示せず、『発表した』の目的語も重なって文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示すが、ここでは主語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞を修飾するもので、文の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "メゾンを主語として示し、『発表した』と結びつける助詞。", "を": "『メゾンを』では主語が示せず、『発表した』の目的語も重なって文が崩れる。", "で": "『で』は場所や手段を示すが、ここでは主語を示せない。", "の": "『の』は名詞を修飾するもので、文の主語にはならない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53000, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "高級ブランドやデザイン会社。特にファッション業界で、独自のスタイルを持つ一流の工房や企業を指す。", "primary_collocate": null, "pronunciation": "めぞん", "ipa": "mezoɴ", "syllable_count": 3, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "メゾン", "complexity_tier": "T4", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "そのメゾンは百年以上前にパリで小さな工房として始まった。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "そのメゾンは百年以上前[ひゃくねんいじょうまえ]にパリで小[ちい]さな工房[こうぼう]として始[はじ]まった。", "sentence_source": "generated"}, {"text": "有名なメゾンの新作バッグは、発売の日に売り切れた。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "有名[ゆうめい]なメゾンの新作[しんさく]バッグは、発売[はつばい]の日[ひ]に売[う]り切[き]れた。", "sentence_source": "generated"}, {"text": "彼女は夢だったメゾンで、デザイナーとして働いている。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は夢[ゆめ]だったメゾンで、デザイナーとして働[はたら]いている。", "sentence_source": "generated"}, {"text": "老舗のメゾンは、職人の技を大切にして服を作り続けている。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "老舗[しにせ]のメゾンは、職人[しょくにん]の技[わざ]を大切[たいせつ]にして服[ふく]を作[つく]り続[つづ]けている。", "sentence_source": "generated"}, {"text": "そのメゾンの服は独自のスタイルがあり、すぐに見分けがつく。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "そのメゾンの服[ふく]は独自[どくじ]のスタイルがあり、すぐに見分[みわ]けがつく。", "sentence_source": "generated"}, {"text": "若いデザイナーが、新しいメゾンを立ち上げた。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "若[わか]いデザイナーが、新[あたら]しいメゾンを立[た]ち上[あ]げた。", "sentence_source": "generated"}, {"text": "イタリアのメゾンが、東京で新しいコレクションを発表した。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "イタリアのメゾンが、東京[とうきょう]で新[あたら]しいコレクションを発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "このメゾンは高級な素材だけを使うことで知られている。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "このメゾンは高級[こうきゅう]な素材[そざい]だけを使[つか]うことで知[し]られている。", "sentence_source": "generated"}, {"text": "メゾンのショーには、世界中から記者が集まる。", "target_word": "メゾン", "complexity_tier": "T3", "furigana": "メゾンのショーには、世界中[せかいじゅう]から記者[きしゃ]が集[あつ]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メゾン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ファッション業界の一流ブランド・工房(フランス語maison)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53000, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メゾン", "is_correct": true, "explanation": "一流の工房やブランドを指す語で、ファッション業界の文脈に合う。"}, {"text": "病院", "is_correct": false, "explanation": "病院がファッションウィークで造形を提示するのは意味が通らない。"}, {"text": "空港", "is_correct": false, "explanation": "空港はファッションの造形や素材使いを提示する主体にならず、文が成り立たない。"}, {"text": "銀行", "is_correct": false, "explanation": "銀行が服の造形や素材使いを提示するのは文脈に合わない。"}], "explanations": {"メゾン": "一流の工房やブランドを指す語で、ファッション業界の文脈に合う。", "病院": "病院がファッションウィークで造形を提示するのは意味が通らない。", "空港": "空港はファッションの造形や素材使いを提示する主体にならず、文が成り立たない。", "銀行": "銀行が服の造形や素材使いを提示するのは文脈に合わない。"}, "sentence_index": 0, "correct_answer": "メゾン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このメゾンは、一日に二万トンの鉄を生産している。", "explanation": "ここは〈製鉄所〉の意味。〈メゾン〉はファッション業界のブランドや工房を指すので、鉄を作る会社には使わない。"}, {"text": "彼は三十年この道に生きて、毎朝メゾンを磨いている。", "explanation": "ここは〈床〉の意味。〈メゾン〉はブランドや工房を指すので、磨く床の名前には使わない。"}, {"text": "このメゾンは、肌触りがよく丈夫で、夏に着やすい素材だ。", "explanation": "ここは〈生地〉の意味。〈メゾン〉はブランドや工房を指し、布地の名前としては使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53000, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メゾン", "is_correct": true, "explanation": "新しい工房やブランドを立ち上げる意味で、ファッション業界の文脈に合う。"}, {"text": "朝食", "is_correct": false, "explanation": "『新しい朝食を立ち上げた』とは言わず、文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気を立ち上げるという言い方は意味が通らない。"}, {"text": "空", "is_correct": false, "explanation": "空を立ち上げるのは不自然で、この文脈では成り立たない。"}], "explanations": {"メゾン": "新しい工房やブランドを立ち上げる意味で、ファッション業界の文脈に合う。", "朝食": "『新しい朝食を立ち上げた』とは言わず、文が成り立たない。", "天気": "天気を立ち上げるという言い方は意味が通らない。", "空": "空を立ち上げるのは不自然で、この文脈では成り立たない。"}, "sentence_index": 6, "correct_answer": "メゾン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "メゾンは、明日の雨を予測して人々に知らせている。", "explanation": "ここは〈天気予報〉の意味。〈メゾン〉は天気を予測する機関ではないので、この言葉はこう使わない。"}, {"text": "夏のおやつに、メゾンを切って皆で食べた。", "explanation": "ここは〈メロン〉の意味。〈メゾン〉はブランドを指すので、果物には使えない。"}, {"text": "子どもがメゾンを蹴って遊んでいる。", "explanation": "ここは〈ボール〉の意味。〈メゾン〉は蹴るものではないので、この言葉はこう使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53000, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "そのメゾンを新作のコートが届いた。", "corrected_sentence": "そのメゾンから新作のコートが届いた。", "error_description": "『届く』は届け元を『から』で示す。『を』は目的語の印で、届くは自動詞なので誤り。正しくは『から』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53000, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このメゾンに服は、毎シーズン少量しか作られない。", "corrected_sentence": "このメゾンの服は、毎シーズン少量しか作られない。", "error_description": "『メゾンの服』は所属を示す『の』が正しい。『に』だと『メゾンに服』となり、関係が成り立たず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53001, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す『は』で、源泉を文の話題にしている。"}, {"text": "を", "is_correct": false, "explanation": "『を』では文の主題が示せず、『朝の散歩だ』と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は、ここでは文の主題を示せない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞修飾で、文の主題にはならない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す『は』で、源泉を文の話題にしている。", "を": "『を』では文の主題が示せず、『朝の散歩だ』と続かない。", "へ": "方向を示す『へ』は、ここでは文の主題を示せない。", "の": "『の』は名詞修飾で、文の主題にはならない。"}, "error_tags": {"を": "対象", "へ": "方向", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53001, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『となる』の『と』で、変化の結果を示す。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示し、『なった』と結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す『から』は、変化の結果とは結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』は、ここでは『なった』と結びつかない。"}], "correct_answer": "と", "explanations": {"と": "『となる』の『と』で、変化の結果を示す。", "で": "『で』は場所や手段を示し、『なった』と結びつかない。", "から": "起点を示す『から』は、変化の結果とは結びつかない。", "より": "比較の『より』は、ここでは『なった』と結びつかない。"}, "error_tags": {"で": "場所・手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53001, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが始まるもとになるもの。", "primary_collocate": null, "pronunciation": "げんせん", "ipa": "ɡeɴseɴ", "syllable_count": 4, "sentences": [{"text": "母の愛情が、私の勇気の源泉です。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "母[はは]の愛情[あいじょう]が、私[わたし]の勇気[ゆうき]の源泉[げんせん]です。", "sentence_source": "generated"}, {"text": "彼女の元気の源泉は、朝の散歩だ。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の元気[げんき]の源泉[げんせん]は、朝[あさ]の散歩[さんぽ]だ。", "sentence_source": "generated"}, {"text": "この地域の力の源泉は、人々の助け合いだ。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "この地域[ちいき]の力[ちから]の源泉[げんせん]は、人々[ひとびと]の助[たす]け合[あ]いだ。", "sentence_source": "generated"}, {"text": "アイデアの源泉を探すために、一人で旅に出た。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "アイデアの源泉[げんせん]を探[さが]すために、一人[ひとり]で旅[たび]に出[で]た。", "sentence_source": "generated"}, {"text": "読書は知識の源泉であり、毎日続けたい。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "読書[どくしょ]は知識[ちしき]の源泉[げんせん]であり、毎日続[まいにちつづ]けたい。", "sentence_source": "generated"}, {"text": "家族の笑顔が、父にとって働く意欲の源泉だ。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "家族[かぞく]の笑顔[えがお]が、父[ちち]にとって働[はたら]く意欲[いよく]の源泉[げんせん]だ。", "sentence_source": "generated"}, {"text": "彼の強さの源泉は、小さいころの苦労にある。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "彼[かれ]の強[つよ]さの源泉[げんせん]は、小[ちい]さいころの苦労[くろう]にある。", "sentence_source": "generated"}, {"text": "工場の高い技術が、会社の成功の源泉となった。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "工場[こうじょう]の高[たか]い技術[ぎじゅつ]が、会社[かいしゃ]の成功[せいこう]の源泉[げんせん]となった。", "sentence_source": "generated"}, {"text": "好きなことを学ぶ時間が、喜びの源泉になる。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "好[す]きなことを学[まな]ぶ時間[じかん]が、喜[よろこ]びの源泉[げんせん]になる。", "sentence_source": "generated"}, {"text": "この町の祭りは、人々の誇りの源泉だ。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "この町[まち]の祭[まつ]りは、人々[ひとびと]の誇[ほこ]りの源泉[げんせん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "源泉", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "気持ち・力・考えなどが生まれるもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53001, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "源泉", "is_correct": true, "explanation": "気持ちや力が生まれるもとを指し、勇気の元になる文脈に合う。"}, {"text": "不安", "is_correct": false, "explanation": "『私の勇気の不安』は意味が通らず、勇気の元とは合わない。"}, {"text": "税金", "is_correct": false, "explanation": "『勇気の税金』は意味が通らず、文が成り立たない。"}, {"text": "冬", "is_correct": false, "explanation": "『勇気の冬』は不自然で、文脈に合わない。"}], "explanations": {"源泉": "気持ちや力が生まれるもとを指し、勇気の元になる文脈に合う。", "不安": "『私の勇気の不安』は意味が通らず、勇気の元とは合わない。", "税金": "『勇気の税金』は意味が通らず、文が成り立たない。", "冬": "『勇気の冬』は不自然で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "源泉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は、この源泉で毎朝、髪を結う。", "explanation": "ここは〈髪留め〉の意味。〈源泉〉は物事のもとを指し、髪を留める道具の名前には使わないので合わない。"}, {"text": "この引き出しの源泉を強く引いて開けた。", "explanation": "ここは〈取っ手〉の意味。〈源泉〉は物事のもとを指し、引く取っ手の名前には使わない。"}, {"text": "私の源泉は、三十七です。", "explanation": "ここは〈番号〉の意味。〈源泉〉は番号を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53001, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源泉", "is_correct": true, "explanation": "強さを生むもとを指し、『強さの源泉は苦労にある』という文脈に合う。"}, {"text": "名前", "is_correct": false, "explanation": "『強さの名前』は意味が通らず、もとを表せない。"}, {"text": "天候", "is_correct": false, "explanation": "『強さの天候』は不自然で、文が成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "『強さの財布』は意味が通らず、文脈に合わない。"}], "explanations": {"源泉": "強さを生むもとを指し、『強さの源泉は苦労にある』という文脈に合う。", "名前": "『強さの名前』は意味が通らず、もとを表せない。", "天候": "『強さの天候』は不自然で、文が成り立たない。", "財布": "『強さの財布』は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "源泉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は毎朝、この源泉を三回打ち鳴らす。", "explanation": "ここは〈鐘〉の意味。〈源泉〉は物事のもとを指し、打ち鳴らすものではないので合わない。"}, {"text": "この源泉を西側から押して開けて入った。", "explanation": "ここは〈扉〉の意味。〈源泉〉は物事のもとを指し、押して開ける扉の名前には使わない。"}, {"text": "祖母は、この源泉に腰かけて新聞を読む。", "explanation": "ここは〈椅子〉の意味。〈源泉〉は物事のもとを指し、座れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53001, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この趣味が、彼女の毎日の楽しみの源泉をなっている。", "corrected_sentence": "この趣味が、彼女の毎日の楽しみの源泉になっている。", "error_description": "『なっている』は『に』を取る。『を』は誤りで、正しくは『に』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53001, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この旅が、彼の創作の源泉をとなった。", "corrected_sentence": "この旅が、彼の創作の源泉となった。", "error_description": "『となる』は『と』を取る。『を』は誤りで、正しくは『と』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53002, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『源泉になる』の結びつきを示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "『が』では『なっている』と結びつかず、『になる』の形が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "『を』では『なっている』の結びつきが成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示し、ここでは『なっている』と結びつかない。"}], "correct_answer": "に", "explanations": {"に": "『源泉になる』の結びつきを示す助詞。", "が": "『が』では『なっている』と結びつかず、『になる』の形が崩れる。", "を": "『を』では『なっている』の結びつきが成り立たない。", "より": "『より』は比較を示し、ここでは『なっている』と結びつかない。"}, "error_tags": {"が": "主語", "を": "対象", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53002, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す『は』で、『源泉』を文の話題にしている。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は、『源泉』を主題にできない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞修飾なので、文の主題を示せない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示し、主題を示せない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す『は』で、『源泉』を文の話題にしている。", "へ": "方向を示す『へ』は、『源泉』を主題にできない。", "の": "『の』は名詞修飾なので、文の主題を示せない。", "で": "『で』は場所や手段を示し、主題を示せない。"}, "error_tags": {"へ": "方向", "の": "修飾", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53002, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の起こりや供給源。特に、ある現象や流れの発生源となるもの。", "primary_collocate": null, "pronunciation": "げんせん", "ipa": "ɡeɴseɴ", "syllable_count": 4, "sentences": [{"text": "オートクチュールの持つ絶対的な希少性と排他性は、逆説的にマス市場におけるトレンドの源泉として機能している。", "target_word": "源泉", "complexity_tier": "T4", "furigana": "オートクチュールの持[も]つ絶対的[ぜったいてき]な希少性[きしょうせい]と排他性[はいたせい]は、逆説的[ぎゃくせつてき]にマス市場[しじょう]におけるトレンドの源泉[げんせん]として機能[きのう]している。", "sentence_source": "mined"}, {"text": "この町の豊かな文化は、昔からの交易が源泉になっている。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "この町[まち]の豊[ゆた]かな文化[ぶんか]は、昔[むかし]からの交易[こうえき]が源泉[げんせん]になっている。", "sentence_source": "generated"}, {"text": "彼の自信の源泉は、毎日続けてきた努力だ。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "彼[かれ]の自信[じしん]の源泉[げんせん]は、毎日続[まいにちつづ]けてきた努力[どりょく]だ。", "sentence_source": "generated"}, {"text": "古い神話は、多くの物語の源泉と考えられている。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "古[ふる]い神話[しんわ]は、多[おお]くの物語[ものがたり]の源泉[げんせん]と考[かんが]えられている。", "sentence_source": "generated"}, {"text": "この会社の利益の源泉は、独自の技術にある。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の利益[りえき]の源泉[げんせん]は、独自[どくじ]の技術[ぎじゅつ]にある。", "sentence_source": "generated"}, {"text": "失敗から学ぶことが、成長の源泉になる。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "失敗[しっぱい]から学[まな]ぶことが、成長[せいちょう]の源泉[げんせん]になる。", "sentence_source": "generated"}, {"text": "笑いは、人間関係をよくする力の源泉だと言われる。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "笑[わら]いは、人間関係[にんげんかんけい]をよくする力[ちから]の源泉[げんせん]だと言[い]われる。", "sentence_source": "generated"}, {"text": "創造力の源泉は、好奇心だと言われている。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "創造力[そうぞうりょく]の源泉[げんせん]は、好奇心[こうきしん]だと言[い]われている。", "sentence_source": "generated"}, {"text": "この国の経済力の源泉は、豊かな人材である。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "この国[くに]の経済力[けいざいりょく]の源泉[げんせん]は、豊[ゆた]かな人材[じんざい]である。", "sentence_source": "generated"}, {"text": "その歌手は、悲しい経験を作品の源泉にしている。", "target_word": "源泉", "complexity_tier": "T3", "furigana": "その歌手[かしゅ]は、悲[かな]しい経験[けいけん]を作品[さくひん]の源泉[げんせん]にしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "源泉", "label": "基本形"}], "register": "written", "sense_fingerprint": "物事・現象を生み出し支える根本の供給源(抽象的)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107ea05-5203-40e2-90c5-9121c167bf86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53002, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "源泉", "is_correct": true, "explanation": "物事を生み出す供給源を指し、トレンドの元として機能する文脈に合う。"}, {"text": "財布", "is_correct": false, "explanation": "『トレンドの財布』は意味が通らず、トレンドを生む元とは合わない。"}, {"text": "期限", "is_correct": false, "explanation": "期限はトレンドを生み出す元ではないので、文の意味が成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙がトレンドの元として機能するのは文脈に合わない。"}], "explanations": {"源泉": "物事を生み出す供給源を指し、トレンドの元として機能する文脈に合う。", "財布": "『トレンドの財布』は意味が通らず、トレンドを生む元とは合わない。", "期限": "期限はトレンドを生み出す元ではないので、文の意味が成り立たない。", "手紙": "手紙がトレンドの元として機能するのは文脈に合わない。"}, "sentence_index": 0, "correct_answer": "源泉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三階へ行くには、この源泉を上る。", "explanation": "ここは〈階段〉の意味。〈源泉〉は物事の起こりを指し、建物の階段には使わないので合わない。"}, {"text": "このケーキの源泉を、フォークで刺して食べた。", "explanation": "ここは〈菓子〉の意味。〈源泉〉は物事のもとを指し、フォークで刺して食べるものではない。"}, {"text": "私の源泉を、郵便で送った。", "explanation": "ここは〈小包〉の意味。〈源泉〉は物事のもとを指し、郵便で送る荷物の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
